export const SOLVERS_SRC = "# -*- coding: utf-8 -*-\n\"\"\"算法分类的运行时副本——AUTO-GENERATED，请勿手改。\n来源：data/families.json（家族 short 标签）+ data/algos.json（每个算法的 family）；\n生成：python tools/gen_taxonomy.py（build_pages.py 每次构建自动执行）。\n\n算法下拉框的分组标签一律经 category_of() 得出，TSP 页与各问题域页因此永远与站点家族一致。\n\"\"\"\n\nFAMILY_SHORT = {\n    \"F1\": \"进化计算\",\n    \"F2\": \"群体智能\",\n    \"F3\": \"物理·化学·数学启发\",\n    \"F4\": \"人类与社会启发\",\n    \"F5\": \"免疫与其他生物\",\n    \"F10\": \"局部搜索与轨迹法\",\n    \"F6\": \"混合与框架\",\n    \"F7\": \"多目标\",\n    \"F8\": \"新范式\",\n    \"F9\": \"隐喻批评\",\n    \"F0\": \"专用求解（对照）\"\n}\n\nALGO_CATEGORY = {\n    \"abc\": \"群体智能\",\n    \"aco\": \"群体智能\",\n    \"afsa\": \"群体智能\",\n    \"ais\": \"免疫与其他生物\",\n    \"alo\": \"群体智能\",\n    \"ao\": \"群体智能\",\n    \"ba\": \"群体智能\",\n    \"bbo\": \"进化计算\",\n    \"bfo\": \"群体智能\",\n    \"boa\": \"群体智能\",\n    \"cem\": \"进化计算\",\n    \"cma-es\": \"进化计算\",\n    \"cs\": \"群体智能\",\n    \"cscrow\": \"群体智能\",\n    \"da\": \"群体智能\",\n    \"de\": \"进化计算\",\n    \"eo\": \"物理·化学·数学启发\",\n    \"fa\": \"群体智能\",\n    \"fpa\": \"群体智能\",\n    \"fwa\": \"群体智能\",\n    \"ga\": \"进化计算\",\n    \"grasp\": \"局部搜索与轨迹法\",\n    \"gsa\": \"物理·化学·数学启发\",\n    \"gwo\": \"群体智能\",\n    \"hho\": \"群体智能\",\n    \"hs\": \"人类与社会启发\",\n    \"ica\": \"人类与社会启发\",\n    \"ils\": \"局部搜索与轨迹法\",\n    \"jaya\": \"物理·化学·数学启发\",\n    \"kh\": \"群体智能\",\n    \"lk\": \"专用求解（对照）\",\n    \"mfo\": \"群体智能\",\n    \"mpa\": \"群体智能\",\n    \"pso\": \"群体智能\",\n    \"sa\": \"物理·化学·数学启发\",\n    \"salp\": \"群体智能\",\n    \"sca\": \"物理·化学·数学启发\",\n    \"sfla\": \"群体智能\",\n    \"sma\": \"群体智能\",\n    \"sos\": \"群体智能\",\n    \"ssa\": \"群体智能\",\n    \"tlbo\": \"人类与社会启发\",\n    \"ts\": \"局部搜索与轨迹法\",\n    \"vns\": \"局部搜索与轨迹法\",\n    \"woa\": \"群体智能\"\n}\n\n\n# 分组标签 → 展示顺序（= families.json 里的家族顺序）；不在家族体系里的标签排在最前（基线/构造件）\nCATEGORY_RANK = {\"进化计算\": 0, \"群体智能\": 1, \"物理·化学·数学启发\": 2, \"人类与社会启发\": 3, \"免疫与其他生物\": 4, \"局部搜索与轨迹法\": 5, \"混合与框架\": 6, \"多目标\": 7, \"新范式\": 8, \"隐喻批评\": 9, \"专用求解（对照）\": 10}\n\n\ndef category_rank(category):\n    return CATEGORY_RANK.get(category, -1)\n\n\n# 域内核的后缀与 algos.json 里的算法键不一致的少数几个\n_KERNEL_ALIAS = {\"cmaes\": \"cma-es\"}\n\n\ndef category_of(key, default=None):\n    \"\"\"算法键 → 分组标签。问题域里的变种内核（bv_pso / pk_sma / as_eo）取其基础算法的分类；\n    不在家族体系里的（random/hc/贪心基线等）返回 default。\"\"\"\n    base = key.split(\"_\", 1)[1] if key[:3] in (\"bv_\", \"pk_\", \"as_\") else key\n    base = _KERNEL_ALIAS.get(base, base)\n    return ALGO_CATEGORY.get(base, default)\n\n\n# -*- coding: utf-8 -*-\n\"\"\"\nP1 组件库 —— 可复用算子目录（v1.2 组件化重构，蓝图 R6/R8）\n==========================================================\n单一事实来源：solvers.py 的通用算子全部搬到这里，新算法（P1.3+）直接用组件装配。\n- 本地 / pytest：solvers.py 通过受保护 import 正常导入本模块\n- Pyodide 构建期：build_pages.py 把本文件与 solvers.py 拼接进同一名字空间执行，\n  此时 solvers.py 里的 `from components import ...` 会 ImportError → except 分支\n  跳过（所有名字已在空间内），两种环境行为完全一致\n分组按蓝图 R8：构造器 / 局部搜索 / 扰动 / 交叉与序列 / 编码。\n\"\"\"\n\nimport math\nimport random\nfrom typing import Any, Dict, List, Optional, Tuple\n\n# ============================ 构造器 ============================\n\ndef _nint(x: float) -> int:\n    return int(x + 0.5)  # TSPLIB 的 nint：四舍五入（距离非负）\n\n\ndef _tsplib_geo_rad(v: float) -> float:\n    deg = int(v)\n    return 3.141592 * (deg + 5.0 * (v - deg) / 3.0) / 180.0  # TSPLIB 把 DDD.MM 当作度.分\n\n\ndef _tsplib_dist(metric: str, a: List[float], b: List[float]) -> float:\n    \"\"\"TSPLIB 95 规定的距离函数（EUC_2D 等是整数化距离，这样才能和公开的最优值对得上）\"\"\"\n    dx, dy = a[0] - b[0], a[1] - b[1]\n    if metric == \"EUC_2D\":\n        return float(_nint(math.hypot(dx, dy)))\n    if metric == \"CEIL_2D\":\n        return float(math.ceil(math.hypot(dx, dy)))\n    if metric == \"MAN_2D\":\n        return float(_nint(abs(dx) + abs(dy)))\n    if metric == \"MAX_2D\":\n        return float(max(_nint(abs(dx)), _nint(abs(dy))))\n    if metric == \"ATT\":\n        r = math.sqrt((dx * dx + dy * dy) / 10.0)\n        t = _nint(r)\n        return float(t + 1 if t < r else t)\n    if metric == \"GEO\":\n        la1, lo1 = _tsplib_geo_rad(a[0]), _tsplib_geo_rad(a[1])\n        la2, lo2 = _tsplib_geo_rad(b[0]), _tsplib_geo_rad(b[1])\n        q1 = math.cos(lo1 - lo2)\n        q2 = math.cos(la1 - la2)\n        q3 = math.cos(la1 + la2)\n        return float(int(6378.388 * math.acos(max(-1.0, min(1.0, 0.5 * ((1.0 + q1) * q2 - (1.0 - q1) * q3)))) + 1.0))\n    raise ValueError(f\"未知距离类型 {metric!r}\")\n\n\nTSP_METRICS = (\"EUC_2D\", \"CEIL_2D\", \"ATT\", \"GEO\", \"MAN_2D\", \"MAX_2D\")\n\n\ndef build_problem(cities: List[List[float]], metric: Optional[str] = None,\n                  matrix: Optional[List[List[float]]] = None) -> Dict[str, Any]:\n    \"\"\"把城市坐标打包成 problem（含距离矩阵）。n<=150 时 O(n^2) 建矩阵完全够用。\n    metric=None：欧氏距离（浮点）；metric 取 TSP_METRICS 之一：按 TSPLIB 规定的整数化距离；\n    matrix：直接给定的对称距离矩阵（此时 cities 只用于画图）。\"\"\"\n    n = len(cities)\n    if matrix is not None:\n        return {\"cities\": cities, \"D\": [[float(v) for v in row] for row in matrix], \"n\": len(matrix)}\n    D = [[0.0] * n for _ in range(n)]\n    for i in range(n):\n        xi, yi = cities[i]\n        for j in range(i + 1, n):\n            xj, yj = cities[j]\n            d = math.hypot(xi - xj, yi - yj) if metric is None else _tsplib_dist(metric, cities[i], cities[j])\n            D[i][j] = d\n            D[j][i] = d\n    return {\"cities\": cities, \"D\": D, \"n\": n}\n\n\ndef problem_from_spec(spec: Any) -> Dict[str, Any]:\n    \"\"\"前端 / 命令行传来的实例：裸坐标列表，或校验器规整后的 {\"cities\", \"metric\"?, \"matrix\"?}\"\"\"\n    if isinstance(spec, dict):\n        return build_problem(spec[\"cities\"], spec.get(\"metric\") if spec.get(\"metric\") in TSP_METRICS else None,\n                             spec.get(\"matrix\"))\n    return build_problem(spec)\n\n\n\ndef tour_length(tour: List[int], D: List[List[float]]) -> float:\n    s = 0.0\n    n = len(tour)\n    for i in range(n):\n        s += D[tour[i]][tour[(i + 1) % n]]\n    return s\n\n\n\ndef nearest_neighbor(D: List[List[float]], start: int = 0) -> List[int]:\n    \"\"\"最近邻构造初始解：简单、快，是所有改进型算法的合格起点\"\"\"\n    n = len(D)\n    unvisited = set(range(n))\n    tour = [start]\n    unvisited.remove(start)\n    cur = start\n    while unvisited:\n        nxt = min(unvisited, key=lambda j: D[cur][j])\n        tour.append(nxt)\n        unvisited.remove(nxt)\n        cur = nxt\n    return tour\n\n\ndef _grasp_construct(D: List[List[float]], rng: random.Random, k: int = 2) -> List[int]:\n    \"\"\"GRASP 半贪心构造（RCL 限制候选列表，数量式）。\n\n    每步把未访问城市按到当前城市的距离排序，从最近的 k 个里随机选一个。\n    k=1 就是纯最近邻；k 越大随机性越强、构造越差。实测（n=60 均匀散点）：\n    k=2 构造 raw ~1060、2-opt 打磨后 ~621-746；k=5 直接劣化到 1524/806——\n    TSP 距离强聚集，RCL 宽度必须小（k=2~3 是甜区），这不是实现取舍，\n    是本站两次假跑教训换来的实测结论（区间式 RCL 在均匀散点上会膨胀失效）。\n    \"\"\"\n    n = len(D)\n    start = rng.randrange(n)\n    unvisited = set(range(n))\n    unvisited.remove(start)\n    tour = [start]\n    cur = start\n    while unvisited:\n        cand = sorted(unvisited, key=lambda j: D[cur][j])[: max(2, k)]\n        nxt = rng.choice(cand)\n        tour.append(nxt)\n        unvisited.remove(nxt)\n        cur = nxt\n    return tour\n\n\n\n# ============================ 局部搜索 ============================\n\ndef _first_improving_move(tour: List[int], D: List[List[float]]) -> Optional[Tuple[int, int, float]]:\n    \"\"\"找到第一个能改进的 2-opt 移动（i, k, delta），没有则返回 None\"\"\"\n    n = len(tour)\n    for i in range(1, n - 1):\n        for k in range(i + 1, n):\n            a, b = tour[i - 1], tour[i]\n            c, d = tour[k], tour[(k + 1) % n]\n            delta = D[a][c] + D[b][d] - D[a][b] - D[c][d]\n            if delta < -1e-12:\n                return i, k, delta\n    return None\n\n\n\ndef two_opt_improve(tour: List[int], D: List[List[float]], max_moves: int = 500) -> List[int]:\n    \"\"\"一次性 2-opt 改进（不产生中间状态，用于算法内部加速）\"\"\"\n    best = list(tour)\n    moves = 0\n    while moves < max_moves:\n        m = _first_improving_move(best, D)\n        if m is None:\n            break\n        i, k, _ = m\n        best[i : k + 1] = reversed(best[i : k + 1])\n        moves += 1\n    return best\n\n\n\ndef _random_2opt_shot(tour: List[int], D: List[List[float]], rng: random.Random, trials: int = 20) -> List[int]:\n    \"\"\"随机 2-opt「打了就跑」：随机抽 trials 个 2-opt 移动，只接受改进的。\n\n    与 two_opt_improve 的区别：那个是 first-improvement 全扫描，一次调用 O(n²)，\n    只能偶尔用；这个是 O(trials)，可以在算法内部每代高频调用。\n    做 memetic（算法+局部搜索）时这个才是顺手的工具。\n    \"\"\"\n    n = len(tour)\n    t = list(tour)\n    for _ in range(trials):\n        if n < 4:\n            break\n        i = rng.randrange(1, n - 1)\n        k = rng.randrange(i + 1, n)\n        a, b = t[i - 1], t[i]\n        c, d = t[k], t[(k + 1) % n]\n        delta = D[a][c] + D[b][d] - D[a][b] - D[c][d]\n        if delta < -1e-12:\n            t[i : k + 1] = reversed(t[i : k + 1])\n    return t\n\n\n\n# ============================ 扰动 ============================\n\ndef _double_bridge(tour: List[int], rng: random.Random) -> List[int]:\n    \"\"\"双桥扰动（double bridge）：ILS/VNS 的标准 kick 算子。\n\n    在排列上切 4 段重排：A B C D → A C B D。这个扰动有个漂亮性质：\n    它不可能被任何一次 2-opt 移动还原——正好把解踢出 2-opt 局部盆地。\n    \"\"\"\n    n = len(tour)\n    if n < 8:\n        i, j = rng.sample(range(n), 2)\n        t = list(tour)\n        t[i], t[j] = t[j], t[i]\n        return t\n    a, b, c = sorted(rng.sample(range(2, n - 1), 3))\n    t = list(tour)\n    return t[:a] + t[b:c] + t[a:b] + t[c:]\n\n\n\ndef _or_opt_move(tour: List[int], rng: random.Random, seg_len: int) -> List[int]:\n    \"\"\"or-opt 移动：摘下一段长 seg_len 的连续城市，插到别的位置（VNS 的第二层邻域）\"\"\"\n    n = len(tour)\n    seg_len = max(1, min(seg_len, n - 2, n // 2))  # 剩下的城市数要 ≥ 段长，否则没有可插入的位置（n=5、段长 3 时曾崩溃）\n    i = rng.randrange(0, n - seg_len)\n    seg = tour[i : i + seg_len]\n    rest = tour[:i] + tour[i + seg_len :]\n    j = rng.randrange(0, len(rest) - seg_len + 1)\n    return rest[:j] + seg + rest[j:]\n\n\n\ndef _reverse_mutation(tour: List[int], rng: random.Random) -> List[int]:\n    \"\"\"反转变异：随机取一段倒过来。对 TSP 而言\"逆转\"比\"交换两点\"更有效\"\"\"\n    n = len(tour)\n    a, b = sorted(rng.sample(range(n), 2))\n    t = list(tour)\n    t[a : b + 1] = reversed(t[a : b + 1])\n    return t\n\n\n\n# ============================ 交叉与序列 ============================\n\ndef swap_seq_to_target(cur: List[int], target: List[int]) -> List[Tuple[int, int]]:\n    \"\"\"求把 cur 变成 target 所需的交换序列（离散 PSO 的\"速度\"）\"\"\"\n    seq: List[Tuple[int, int]] = []\n    pos = {city: i for i, city in enumerate(cur)}\n    for i in range(len(cur)):\n        if cur[i] != target[i]:\n            j = pos[target[i]]\n            cur[i], cur[j] = cur[j], cur[i]\n            pos[cur[i]] = i\n            pos[cur[j]] = j\n            seq.append((i, j))\n    return seq\n\n\n\ndef _prefix(seq: List[Tuple[int, int]], prob: float, rng: random.Random) -> List[Tuple[int, int]]:\n    \"\"\"按概率取序列的前缀（离散 PSO 标准做法：速度片段是\"连续前缀\"而非随机子集）\"\"\"\n    k = int(len(seq) * min(prob, 1.0) * rng.random())\n    return seq[:k]\n\n\n\ndef apply_swaps(tour: List[int], swaps: List[Tuple[int, int]]) -> List[int]:\n    t = list(tour)\n    for i, j in swaps:\n        t[i], t[j] = t[j], t[i]\n    return t\n\n\n\ndef _ox_crossover(p1: List[int], p2: List[int], rng: random.Random) -> List[int]:\n    \"\"\"顺序交叉 OX：保留父代1的一段，其余位置按父代2的相对顺序填充。\n\n    TSP 最经典的交叉算子——它保留的是\"相对顺序\"而不是\"绝对位置\"，\n    这才是排列编码真正该继承的信息。用 set 判重，保证 O(n) 而非 O(n²)。\n    \"\"\"\n    n = len(p1)\n    a, b = sorted(rng.sample(range(n), 2))\n    child: List[Optional[int]] = [None] * n\n    child[a : b + 1] = p1[a : b + 1]\n    taken = set(p1[a : b + 1])\n    rest = [g for g in p2 if g not in taken]\n    idx = 0\n    for i in list(range(b + 1, n)) + list(range(0, b + 1)):\n        if child[i] is None:\n            child[i] = rest[idx]\n            idx += 1\n    return child  # type: ignore[return-value]\n\n\n\n# ============================ 编码 ============================\n\ndef _encode_tour(tour: List[int], rng: random.Random) -> List[float]:\n    \"\"\"随机键编码：把排列变成一个实数向量 X，使得 argsort(X) == 原排列。\n\n    这是把连续型算法（GWO 等）嫁接到排列问题上的标准桥梁：\n    连续更新公式可以原样保留，只是每代解码一次。\n    \"\"\"\n    n = len(tour)\n    X = [0.0] * n\n    for rank, city in enumerate(tour):\n        X[city] = (rank + 1) / (n + 1)\n    return X\n\n\n\ndef _decode_position(X: List[float]) -> List[int]:\n    \"\"\"随机键解码：按 X 从小到大排序，得到城市访问顺序\"\"\"\n    return sorted(range(len(X)), key=lambda i: X[i])\n\n\n\ndef _roulette(rng: random.Random, weights: List[float]) -> int:\n    \"\"\"轮盘赌选择：返回被选中的下标。权重全 0 时退化为均匀随机\"\"\"\n    total = sum(weights)\n    if total <= 0:\n        return rng.randrange(len(weights))\n    r = rng.random() * total\n    acc = 0.0\n    for i, w in enumerate(weights):\n        acc += w\n        if acc >= r:\n            return i\n    return len(weights) - 1\n\n\n\ndef _shared_edges_ratio(a: List[int], b: List[int]) -> float:\n    \"\"\"两排列的公共边占比（无向）：Jaya「远离最劣」的相似度度量，也可用于多样性监控\"\"\"\n    if len(a) != len(b) or len(a) < 2:\n        return 0.0\n    edges = set()\n    for i in range(len(b)):\n        x, y = b[i], b[(i + 1) % len(b)]\n        edges.add((x, y) if x < y else (y, x))\n    same = 0\n    for i in range(len(a)):\n        x, y = a[i], a[(i + 1) % len(a)]\n        e = (x, y) if x < y else (y, x)\n        if e in edges:\n            same += 1\n    return same / len(a)\n\n\n# ============================ 组件注册表（P1.5 组件百科页数据源） ============================\n\nCOMPONENTS = [\n    # (key, 名称, 分组, 一句话说明, 典型使用者)\n    (\"build_problem\", \"问题构建\", \"构造器\", \"城市坐标 → 距离矩阵 D（欧氏），全站统一问题表示\", \"所有 TSP 算法\"),\n    (\"nearest_neighbor\", \"最近邻构造\", \"构造器\", \"从起点逐城选最近未访问城市，O(n²) 构造合法路径\", \"播种器通用\"),\n    (\"grasp_construct\", \"RCL 半贪心构造\", \"构造器\", \"每步从最近 k 个候选中随机选一个：贪心保底、随机产生差异，GRASP 的命根子\", \"GRASP\"),\n    (\"two_opt\", \"2-opt 下探\", \"局部搜索\", \"first-improvement 反转扫描到局部最优；max_moves 即下探预算\", \"几乎所有算法的打磨/重置算子\"),\n    (\"two_opt_shot\", \"预算制试射\", \"局部搜索\", \"随机 2-opt 逆转、只接受改进，预算 trials 用完即停\", \"播种抛光 / 警戒远跳 / 重置蛙\"),\n    (\"or_opt\", \"Or-opt 移段\", \"扰动\", \"随机截取小段移动到别处，保留邻接结构的结构性扰动\", \"ILS / VNS / Salp / SFLA\"),\n    (\"double_bridge\", \"双桥扰动\", \"扰动\", \"切 4 刀换段重排，不可被 2-opt 还原的深盆地跳跃\", \"ILS / SFLA / Salp\"),\n    (\"reverse_mut\", \"逆转突变\", \"扰动\", \"随机片段逆转，轻量勘探\", \"GA / DE 等\"),\n    (\"swap_seq\", \"交换序列\", \"交叉与序列\", \"cur→target 交换序列 + 概率前缀执行：连续域「向目标移动」的排列域映射\", \"TS / DE / TLBO / SFLA / BOA\"),\n    (\"ox_crossover\", \"OX 顺序交叉\", \"交叉与序列\", \"保留父代相对顺序的顺序交叉，离散文献的标准学习算子\", \"GA / DE / TLBO / SFLA / SOS\"),\n    (\"random_key\", \"随机键编码\", \"编码\", \"排列↔连续向量双向映射，让 PSO 系算法在排列域工作\", \"PSO / GSA / CEM\"),\n    (\"roulette\", \"轮盘选择\", \"编码\", \"按权重随机选下标\", \"ACO / FA\"),\n    (\"shared_edges\", \"公共边相似度\", \"编码\", \"两排列的无向公共边占比：个体间相似度 / 多样性度量\", \"Jaya 远离最劣\"),\n]\n\n\n# -*- coding: utf-8 -*-\n\"\"\"S7-B 配方引擎：算法 = 七槽管线模块组合（L-recipe 层）。\n\n设计（docs/component-architecture.md §3）：\n  七槽固定管线 init→selection→crossover→mutation→replacement→local_search→terminator，\n  每槽从 RCOMPONENTS 挑一个组件；配方 = JSON 声明。组合引擎用单一 RNG 顺序调用\n  组件（组件禁自建随机源），任意配方可复现。\n\n双模式：\n  population —— 种群型（GA/Memetic 类）：选择→交叉→变异→替换逐代滚动\n  single     —— 单解型（ILS 类）：扰动→局部搜索→贪心接受\n\nIO 契约（自检线）：排列组件的输出用 _assert_perm 校验（无重复、长度一致），\n非法组合在第一代就炸出来，不让坏配方悄悄跑完。\n\n组件尽量直接复用 py/components.py 的函数（单一实现）：\n  nearest_neighbor / _ox_crossover / _reverse_mutation / _or_opt_move /\n  _double_bridge / two_opt_improve / _random_2opt_shot / _roulette / tour_length\n\"\"\"\nimport json\nimport random\nfrom dataclasses import asdict\nfrom typing import Any, Dict, Iterator, List, Optional\n\ntry:  # 与 solvers.py 同款双环境兼容：本地 import / 拼接名字空间直用\n    from components import (  # noqa: F401\n        _double_bridge, _or_opt_move, _ox_crossover, _random_2opt_shot,\n        _reverse_mutation, _roulette, nearest_neighbor, tour_length,\n        two_opt_improve,\n    )\nexcept ImportError:\n    pass\n\n\n# ============================ IO 契约 ============================\n\ndef _assert_perm(t: List[int], n: int, where: str) -> None:\n    \"\"\"排列合法性校验：长度一致 + 无重复。配方引擎的 IO 门。\"\"\"\n    if len(t) != n or len(set(t)) != n:\n        raise ValueError(f\"配方 IO 契约失败[{where}]：期望 {n} 城排列，\"\n                         f\"实际长度 {len(t)}、去重 {len(set(t))}\")\n\n\n# ============================ 槽位组件（TSP 排列域） ============================\n\n# ---- init：返回初始种群（含成本） ----\ndef _init_random(n, D, pop, rng):\n    P = [list(range(n)) for _ in range(pop)]\n    for t in P:\n        rng.shuffle(t)\n    return P\n\ndef _init_nn(n, D, pop, rng):\n    \"\"\"多起点最近邻播种（与 GA/GWO 手写版同一工程共识：纯随机开局浪费几十代）。\"\"\"\n    starts = list(range(n))\n    rng.shuffle(starts)\n    return [nearest_neighbor(D, starts[i % n]) for i in range(pop)]\n\n# ---- selection：从种群选一个父代下标 ----\ndef _sel_tournament(costs, rng, k):\n    idx = rng.sample(range(len(costs)), min(k, len(costs)))\n    return min(idx, key=lambda i: costs[i])\n\ndef _sel_roulette(costs, rng, k=3):\n    \"\"\"成本转权重（最小化）：1/(1+cost-rmin)，保证全正。k 参数与锦标赛签名对齐、忽略。\"\"\"\n    rmin = min(costs)\n    w = [1.0 / (1.0 + c - rmin) for c in costs]\n    return _roulette(rng, w)\n\n# ---- crossover ----\ndef _cx_ox(p1, p2, rng):\n    return _ox_crossover(p1, p2, rng)\n\n# ---- mutation ----\ndef _mut_reverse(t, rng, pm):\n    if rng.random() < pm:\n        return _reverse_mutation(t, rng)\n    return t\n\ndef _mut_swap(t, rng, pm):\n    if rng.random() < pm:\n        i, j = rng.randrange(len(t)), rng.randrange(len(t))\n        t = list(t)\n        t[i], t[j] = t[j], t[i]\n    return t\n\ndef _mut_oropt(t, rng, pm):\n    if rng.random() < pm:\n        return _or_opt_move(t, rng, rng.choice([1, 2, 3]))\n    return t\n\ndef _mut_dbridge(t, rng, pm):\n    if rng.random() < pm:\n        return _double_bridge(t, rng)\n    return t\n\n# ---- replacement ----\ndef _rep_generational(pop, costs, new, newc, elite):\n    \"\"\"精英世代替换：新代保底 elite 个父代最优，其余用子代填。\"\"\"\n    order = sorted(range(len(pop)), key=lambda i: costs[i])\n    for e in order[:elite]:\n        new.append(list(pop[e]))\n        newc.append(costs[e])\n    return new[:len(pop)], newc[:len(pop)]\n\ndef _rep_greedy_one(cur, curc, cand, candc):\n    \"\"\"单解贪心接受（ILS 的 replacement 槽）。\"\"\"\n    return (list(cand), candc) if candc < curc else (cur, curc)\n\n# ---- local_search（统一签名 tour, D, rng, budget；不用 rng 的忽略之） ----\ndef _ls_two_opt(tour, D, rng, budget):\n    return two_opt_improve(tour, D, max_moves=budget)\n\ndef _ls_shot(tour, D, rng, trials):\n    return _random_2opt_shot(tour, D, rng, trials=trials)\n\n# ---- terminator：返回 True 表示该停 ----\ndef _term_stall(cur_best, hist_best, stall, patience):\n    return stall >= patience if patience > 0 else False\n\n\n# ============================ S7-D：F6-F9 升格专用组件 ============================\n\n# 选择式超启发式的低层启发式档案（信用轮盘的选择池）\n_HH_LLHS = (\"reverse\", \"swap\", \"oropt\")\n\n\ndef _mut_hh(t, rng, pm, ctx):\n    \"\"\"选择式超启发式（selection hyper-heuristic）变异槽：\n    信用轮盘在三个低层启发式之间选——「选哪个算子」本身成为搜索问题。\n    信用分存引擎下发的 ctx（跨代状态口袋），经 feedback 钩子回注改进量。\"\"\"\n    if rng.random() >= pm:\n        return t\n    scores = ctx.setdefault(\"hh_scores\", {k: 1.0 for k in _HH_LLHS})\n    name = _HH_LLHS[_roulette(rng, [scores[k] for k in _HH_LLHS])]\n    ctx[\"hh_last\"] = name\n    if name == \"reverse\":\n        return _reverse_mutation(t, rng)\n    if name == \"swap\":\n        i, j = rng.randrange(len(t)), rng.randrange(len(t))\n        t = list(t)\n        t[i], t[j] = t[j], t[i]\n        return t\n    return _or_opt_move(t, rng, rng.choice([1, 2, 3]))\n\n\ndef _fb_hh(ctx, delta):\n    \"\"\"HH 信用分配：全体轻微衰减 + 改进算子按 Δ 加分（封顶防数值爆炸）。\"\"\"\n    scores = ctx.get(\"hh_scores\")\n    if not scores or \"hh_last\" not in ctx:\n        return\n    for k in scores:\n        scores[k] *= 0.97\n    if delta > 0:\n        scores[ctx[\"hh_last\"]] += min(delta, 50.0)\n\n\ndef _hk_window(D, a, seg, b):\n    \"\"\"窗口 Held-Karp DP：两端固定（a 进 b 出），窗口内城市精确最优重排。\n    O(k²·2^k)，k=11 约 25 万次内层运算——matheuristic 的「精确修复」内核。\"\"\"\n    k = len(seg)\n    INF = float(\"inf\")\n    size = 1 << k\n    dp = [[INF] * k for _ in range(size)]\n    par = [[-1] * k for _ in range(size)]\n    for i in range(k):\n        dp[1 << i][i] = D[a][seg[i]]\n    for mask in range(1, size):\n        row = dp[mask]\n        for j in range(k):\n            cj = row[j]\n            if cj == INF or not (mask >> j & 1):\n                continue\n            for l in range(k):\n                if mask >> l & 1:\n                    continue\n                nm = mask | (1 << l)\n                nc = cj + D[seg[j]][seg[l]]\n                if nc < dp[nm][l]:\n                    dp[nm][l] = nc\n                    par[nm][l] = j\n    full = size - 1\n    end = min(range(k), key=lambda j: dp[full][j] + D[seg[j]][b])\n    order = []\n    mask, cur = full, end\n    while cur != -1:\n        order.append(seg[cur])\n        nxt = par[mask][cur]\n        mask ^= 1 << cur\n        cur = nxt\n    order.reverse()\n    return order\n\n\ndef _ls_fixopt(tour, D, rng, budget):\n    \"\"\"fix-and-optimize（matheuristic 文献记载范式）：采样至多 budget 个 k=11\n    连续窗口，Held-Karp 精确重排，采纳最优改进；无改进返回原路。\"\"\"\n    n = len(tour)\n    k = min(11, n - 3)\n    if k < 4:\n        return tour\n    best_t, best_c = tour, tour_length(tour, D)\n    for _ in range(max(1, budget)):\n        p0 = rng.randrange(n)\n        seg = [tour[(p0 + i) % n] for i in range(k)]\n        a = tour[(p0 - 1) % n]\n        b = tour[(p0 + k) % n]\n        new_seg = _hk_window(D, a, seg, b)\n        cand = list(tour)\n        for i in range(k):\n            cand[(p0 + i) % n] = new_seg[i]\n        c = tour_length(cand, D)\n        if c < best_c - 1e-9:\n            best_t, best_c = cand, c\n    return best_t\n\n\ndef _rbf_predict(archive, t, kmax=12):\n    \"\"\"教学版代理模型：按「城市位置向量」距离取近邻，距离倒数加权预测成本。\n    SAEA 里代理只负责排名（预筛），精确评估永远以 tour_length 为准。\"\"\"\n    if not archive:\n        return float(\"inf\")\n    pos_t = {c: i for i, c in enumerate(t)}\n    ds = []\n    for perm, cost in archive:\n        pos_p = {c: i for i, c in enumerate(perm)}\n        d2 = 0\n        for c, i in pos_t.items():\n            di = i - pos_p[c]\n            d2 += di * di\n        ds.append((d2, cost))\n    ds.sort(key=lambda x: x[0])\n    num = den = 0.0\n    for d2, cost in ds[:kmax]:\n        if d2 == 0:\n            return cost\n        w = 1.0 / (d2 + 1.0)\n        num += w * cost\n        den += w\n    return num / den\n\n\nRCOMPONENTS: Dict[str, Dict[str, Any]] = {\n    # 每个组件：call（引擎调用签名）、kind、io 描述、正典出处、纯组件标记\n    \"random\":     {\"kind\": \"init\", \"io\": \"->perm_pop\", \"fn\": _init_random,\n                   \"source\": \"教科书标准\", \"composable\": False},\n    \"nn_seeding\": {\"kind\": \"init\", \"io\": \"->perm_pop\", \"fn\": _init_nn,\n                   \"source\": \"Rosenkrantz 1977（NN 构造 2-近似）\", \"composable\": False},\n    \"tournament\": {\"kind\": \"selection\", \"io\": \"pop->idx\", \"fn\": _sel_tournament,\n                   \"source\": \"Goldberg & Deb 1991\", \"composable\": False},\n    \"roulette\":   {\"kind\": \"selection\", \"io\": \"pop->idx\", \"fn\": _sel_roulette,\n                   \"source\": \"Holland 1975\", \"composable\": False},\n    \"ox\":         {\"kind\": \"crossover\", \"io\": \"perm×2->perm\", \"fn\": _cx_ox,\n                   \"source\": \"Goldberg 1985\", \"composable\": False},\n    \"none_cross\": {\"kind\": \"crossover\", \"io\": \"perm->perm\", \"fn\": None,\n                   \"source\": \"无交叉（单亲/单解型）\", \"composable\": False},\n    \"reverse_mut\": {\"kind\": \"mutation\", \"io\": \"perm->perm\", \"fn\": _mut_reverse,\n                    \"source\": \"逆转变异（排列 GA 标准）\", \"composable\": False},\n    \"swap_mut\":   {\"kind\": \"mutation\", \"io\": \"perm->perm\", \"fn\": _mut_swap,\n                   \"source\": \"交换变异\", \"composable\": False},\n    \"oropt_mut\":  {\"kind\": \"mutation\", \"io\": \"perm->perm\", \"fn\": _mut_oropt,\n                   \"source\": \"Or 1976（移段邻域）\", \"composable\": False},\n    \"double_bridge\": {\"kind\": \"mutation\", \"io\": \"perm->perm\", \"fn\": _mut_dbridge,\n                      \"source\": \"Martin & Otto 1991（ILS 标准扰动）\", \"composable\": False},\n    \"generational\": {\"kind\": \"replacement\", \"io\": \"pop+new->pop\", \"fn\": _rep_generational,\n                     \"source\": \"世代式 + 精英保留（De Jong 1975）\", \"composable\": False},\n    \"greedy_accept\": {\"kind\": \"replacement\", \"io\": \"2sol->1sol\", \"fn\": _rep_greedy_one,\n                      \"source\": \"ILS 接受准则\", \"composable\": False},\n    \"two_opt\":    {\"kind\": \"local_search\", \"io\": \"perm->perm\", \"fn\": _ls_two_opt,\n                   \"source\": \"Croes 1958\", \"composable\": False},\n    \"two_opt_shot\": {\"kind\": \"local_search\", \"io\": \"perm->perm\", \"fn\": _ls_shot,\n                     \"source\": \"预算制试射（本站命名）\", \"composable\": False},\n    \"hh_choice\":  {\"kind\": \"mutation\", \"io\": \"perm->perm\", \"fn\": _mut_hh,\n                    \"feedback\": _fb_hh, \"ctx\": True,\n                    \"source\": \"选择式超启发式（Cowling 2001 信用分配传统）\",\n                    \"composable\": False},\n    \"fixopt\":     {\"kind\": \"local_search\", \"io\": \"perm->perm\", \"fn\": _ls_fixopt,\n                    \"source\": \"fix-and-optimize 精确修复（Held-Karp DP 窗口）\",\n                    \"composable\": False},\n    \"stall\":      {\"kind\": \"terminator\", \"io\": \"hist->bool\", \"fn\": _term_stall,\n                   \"source\": \"无改进停机\", \"composable\": False},\n    \"max_iter\":   {\"kind\": \"terminator\", \"io\": \"->bool\", \"fn\": None,\n                   \"source\": \"固定预算\", \"composable\": False},\n}\n# fn=None 的组件由引擎内联实现（签名特殊），kind/io/source 元数据仍然成立\n\n\n# ============================ 示范配方（L-recipe 数据） ============================\n\nRECIPES: List[Dict[str, Any]] = [\n    {\n        \"id\": \"memetic\",\n        \"name\": \"Memetic GA（组合）\",\n        \"mode\": \"population\",\n        \"lineage\": {\"family\": \"F6\", \"based_on\": \"ga-tsp\",\n                    \"source\": \"Moscato 1989（文化基因算法）\"},\n        \"slots\": {\n            \"init\": \"nn_seeding\", \"selection\": \"tournament\", \"crossover\": \"ox\",\n            \"mutation\": \"reverse_mut\", \"replacement\": \"generational\",\n            \"local_search\": \"two_opt\", \"terminator\": \"stall\",\n        },\n        \"default_params\": {\"pop\": 60, \"pc\": 0.85, \"pm\": 0.20, \"max_iter\": 300,\n                           \"elite\": 2, \"tournament\": 3, \"ls_every\": 5,\n                           \"ls_moves\": 15, \"patience\": 80, \"seed\": 42},\n        \"note\": \"与手写 ga-tsp（ls_every>0 时）同谱系——本配方证明七槽管线能表达 memetic 结构。\",\n    },\n    {\n        \"id\": \"steady-ga\",\n        \"name\": \"稳态 GA（组合）\",\n        \"mode\": \"population\",\n        \"lineage\": {\"family\": \"F1\", \"based_on\": \"ga-tsp\",\n                    \"source\": \"Syswerda 1989（稳态替换）\"},\n        \"slots\": {\n            \"init\": \"random\", \"selection\": \"roulette\", \"crossover\": \"ox\",\n            \"mutation\": \"swap_mut\", \"replacement\": \"generational\",\n            \"local_search\": \"two_opt_shot\", \"terminator\": \"max_iter\",\n        },\n        \"default_params\": {\"pop\": 50, \"pc\": 0.9, \"pm\": 0.15, \"max_iter\": 200,\n                           \"elite\": 1, \"tournament\": 3, \"ls_every\": 10,\n                           \"ls_moves\": 8, \"patience\": 0, \"seed\": 42},\n        \"note\": \"轮盘选择 + 交换变异 + 稀疏局部搜索——与 Memetic 配方同一引擎、不同模块清单的教学对照。\",\n    },\n    {\n        \"id\": \"ils\",\n        \"name\": \"迭代局部搜索 ILS（组合）\",\n        \"mode\": \"single\",\n        \"lineage\": {\"family\": \"F6\", \"based_on\": \"sa-tsp\",\n                    \"source\": \"Martin & Otto 1991 / Lourenço 2003 经典综述\"},\n        \"slots\": {\n            \"init\": \"nn_seeding\", \"selection\": \"none\", \"crossover\": \"none_cross\",\n            \"mutation\": \"double_bridge\", \"replacement\": \"greedy_accept\",\n            \"local_search\": \"two_opt\", \"terminator\": \"stall\",\n        },\n        \"default_params\": {\"max_iter\": 300, \"pm\": 1.0,\n                           \"ls_moves\": 120, \"patience\": 150, \"seed\": 42},\n        \"note\": \"selection/crossover 槽在单解模式下自然闲置——七槽管线覆盖单解谱系的方式。\",\n    },\n    {\n        \"id\": \"hh\",\n        \"name\": \"选择式超启发式（组合）\",\n        \"mode\": \"population\",\n        \"lineage\": {\"family\": \"F6\", \"based_on\": \"ga-tsp\",\n                    \"source\": \"Cowling 2001 传统（选择式超启发式）\"},\n        \"slots\": {\n            \"init\": \"nn_seeding\", \"selection\": \"tournament\", \"crossover\": \"ox\",\n            \"mutation\": \"hh_choice\", \"replacement\": \"generational\",\n            \"local_search\": \"two_opt\", \"terminator\": \"stall\",\n        },\n        \"default_params\": {\"pop\": 50, \"pc\": 0.85, \"pm\": 0.90, \"max_iter\": 300,\n                           \"elite\": 2, \"tournament\": 3, \"ls_every\": 5,\n                           \"ls_moves\": 15, \"patience\": 80, \"seed\": 42},\n        \"note\": \"不设计新算子，而是让信用轮盘在逆转/交换/Or-opt 三个低层启发式之间做选择——\"\n                \"「选哪个算子」本身成为搜索问题；信用 = 近期改进量，引擎经 feedback 钩子回注。\"\n                \"局部搜索槽保留稀疏的 2-opt 试射周期（ls_every=5），对应超启发式管「选算子」、\"\n                \"局部搜索管「打磨」的分工结构。\",\n    },\n    {\n        \"id\": \"saea\",\n        \"name\": \"代理辅助进化 SAEA（组合）\",\n        \"mode\": \"sa\",\n        \"lineage\": {\"family\": \"F6\", \"based_on\": \"ga-tsp\",\n                    \"source\": \"代理模型辅助进化脉络）\"},\n        \"slots\": {\n            \"init\": \"random\", \"selection\": \"tournament\", \"crossover\": \"ox\",\n            \"mutation\": \"reverse_mut\", \"replacement\": \"none\",\n            \"local_search\": \"none\", \"terminator\": \"stall\",\n        },\n        \"default_params\": {\"pop\": 40, \"pc\": 0.8, \"pm\": 0.20, \"max_iter\": 150,\n                           \"elite\": 2, \"tournament\": 3, \"eval_budget\": 6,\n                           \"patience\": 60, \"seed\": 42},\n        \"note\": \"SAEA 教学演示：TSP 的评估本来便宜，此处人为把每代精确评估限制为预测最优的前 \"\n                \"eval_budget 个（其余由 RBF 代理模型预筛排名后丢弃）——机制与昂贵黑箱优化中的 \"\n                \"SAEA 一致；最优只按精确评估更新。初始种群用随机初始化（不用 NN 播种）：\"\n                \"昂贵优化里往往没有廉价好解可捡，随机开局更贴近 SAEA 的真实使用场景。\",\n    },\n    {\n        \"id\": \"matheur\",\n        \"name\": \"Fix-and-Optimize（组合）\",\n        \"mode\": \"single\",\n        \"lineage\": {\"family\": \"F6\", \"based_on\": \"ils\",\n                    \"source\": \"fix-and-optimize（Boschetti 与 Maniezzo 2024 经典综述）\"},\n        \"slots\": {\n            \"init\": \"nn_seeding\", \"selection\": \"none\", \"crossover\": \"none_cross\",\n            \"mutation\": \"oropt_mut\", \"replacement\": \"greedy_accept\",\n            \"local_search\": \"fixopt\", \"terminator\": \"stall\",\n        },\n        \"default_params\": {\"max_iter\": 200, \"pm\": 1.0,\n                           \"ls_moves\": 3, \"patience\": 60, \"seed\": 42},\n        \"note\": \"or-opt 移动做破坏（LNS 式），局部搜索槽用 Held-Karp 动态规划对随机窗口做精确重排\"\n                \"——精确修复是 matheuristic 方法树（VLSN/CMSA/Kernel Search）里文献记载的范式；\"\n                \"窗口 k=11 固定（DP 成本封顶，Pyodide 可交互），ls_moves = 每代采样窗口数。\",\n    },\n    {\n        \"id\": \"mapelites\",\n        \"name\": \"MAP-Elites QD（组合）\",\n        \"mode\": \"qd\",\n        \"lineage\": {\"family\": \"F8\", \"based_on\": \"ils\",\n                    \"source\": \"Mouret 与 Clune 2015（MAP-Elites）\"},\n        \"slots\": {\n            \"init\": \"nn_seeding\", \"selection\": \"none\", \"crossover\": \"none_cross\",\n            \"mutation\": \"double_bridge\", \"replacement\": \"none\",\n            \"local_search\": \"two_opt\", \"terminator\": \"stall\",\n        },\n        \"default_params\": {\"pop\": 40, \"pm\": 1.0, \"max_iter\": 300, \"grid_res\": 8,\n                           \"ls_moves\": 60, \"patience\": 120, \"seed\": 42},\n        \"note\": \"不求单一最优，求「每个行为格子的最优」：行为描述子 = (边长均值, 最长边)，\"\n                \"紧致度 × 跳跃度两维刻画路径形态；默认 8×8 档案格，双桥扰动 + 2-opt 回灌，\"\n                \"收敛曲线 = 档案全局最优。档案稀疏占据是 QD 常态（好解形态本就近似）。\",\n    },\n]\n\n\n# ============================ 组合引擎 ============================\n\ndef _lookup(recipe: Dict, slot: str):\n    rid = recipe[\"slots\"].get(slot)\n    if rid is None or rid in (\"none\",):\n        return None\n    if rid not in RCOMPONENTS:\n        raise ValueError(f\"配方 {recipe['id']}：槽位 {slot} 引用未知组件 {rid}\")\n    return RCOMPONENTS[rid]\n\n\ndef run_recipe(recipe: Dict, problem: Dict, params: Dict) -> Iterator:\n    \"\"\"七槽管线解释器。yield 与 BaseSolver 相同的 IterationState 字典——前端零改动。\"\"\"\n    rng = random.Random(params.get(\"seed\", 42))\n    n, D = problem[\"n\"], problem[\"D\"]\n    mode = recipe[\"mode\"]\n    cfg = recipe[\"slots\"]\n    _ = [_lookup(recipe, s) for s in cfg]  # 装配期校验：未知组件当场炸\n\n    p = dict(recipe[\"default_params\"])\n    p.update(params)\n\n    hist_best: Optional[float] = None\n    stall = 0\n    ctx: Dict[str, Any] = {}  # S7-D：组件跨代状态口袋（HH 信用分等），引擎统一下发\n\n    if mode == \"population\":\n        pop = _lookup(recipe, \"init\")[\"fn\"](n, D, p[\"pop\"], rng)\n        for t in pop:\n            _assert_perm(t, n, \"init\")\n        costs = [tour_length(t, D) for t in pop]\n        best, bc = min(zip(pop, costs), key=lambda x: x[1])\n        best, bc = list(best), bc\n        yield {\"iteration\": 0, \"best_cost\": bc, \"best_tour\": best,\n               \"current_cost\": sum(costs) / len(costs), \"extra\": {}}\n\n        sel, cx, mut, rep, ls = (_lookup(recipe, \"selection\"), _lookup(recipe, \"crossover\"),\n                                 _lookup(recipe, \"mutation\"), _lookup(recipe, \"replacement\"),\n                                 _lookup(recipe, \"local_search\"))\n        for it in range(1, p[\"max_iter\"] + 1):\n            new, newc = [], []\n            while len(new) < p[\"pop\"] - p[\"elite\"]:\n                i1 = sel[\"fn\"](costs, rng, p[\"tournament\"])\n                i2 = sel[\"fn\"](costs, rng, p[\"tournament\"])\n                if cx[\"fn\"] is not None and rng.random() < p[\"pc\"]:\n                    child = cx[\"fn\"](pop[i1], pop[i2], rng)\n                else:\n                    child = list(pop[i1])\n                if mut.get(\"ctx\"):  # S7-D：声明 ctx 的组件多收一个状态口袋\n                    child = mut[\"fn\"](child, rng, p[\"pm\"], ctx)\n                else:\n                    child = mut[\"fn\"](child, rng, p[\"pm\"])\n                _assert_perm(child, n, f\"mutation@it{it}\")\n                new.append(child)\n                newc.append(tour_length(child, D))\n                if \"feedback\" in mut:  # S7-D：信用分配反馈（选择式超启发式）\n                    mut[\"feedback\"](ctx, min(costs[i1], costs[i2]) - newc[-1])\n            pop, costs = rep[\"fn\"](pop, costs, new, newc, p[\"elite\"])\n            # local_search 槽：每 ls_every 代对全局最优做一次下探并回灌\n            if ls is not None and p[\"ls_every\"] > 0 and it % p[\"ls_every\"] == 0:\n                bi = min(range(len(pop)), key=lambda i: costs[i])\n                improved = ls[\"fn\"](pop[bi], D, rng, p[\"ls_moves\"])\n                c2 = tour_length(improved, D)\n                if c2 < costs[bi]:\n                    pop[bi], costs[bi] = improved, c2\n            cur_best = min(costs)\n            if cur_best < bc:\n                bi = costs.index(cur_best)\n                best, bc = list(pop[bi]), cur_best\n                stall = 0\n            else:\n                stall += 1\n            term = _lookup(recipe, \"terminator\")\n            yield {\"iteration\": it, \"best_cost\": bc, \"best_tour\": best,\n                   \"current_cost\": sum(costs) / len(costs), \"extra\": {}}\n            if term[\"kind\"] == \"terminator\" and term[\"io\"] == \"hist->bool\" and \\\n               _term_stall(cur_best, hist_best, stall, p[\"patience\"]):\n                break\n            hist_best = cur_best\n\n    elif mode == \"sa\":\n        # S7-D SAEA mode：代理模型预筛 + 精确评估预算。每代只付 eval_budget 次\n        # tour_length（昂贵评估的模拟，页面如实标注），其余子代由 RBF 代理排名后丢弃。\n        pop = _lookup(recipe, \"init\")[\"fn\"](n, D, p[\"pop\"], rng)\n        for t in pop:\n            _assert_perm(t, n, \"init\")\n        costs = [tour_length(t, D) for t in pop]\n        archive = [(list(t), c) for t, c in zip(pop, costs)]  # 精确评估档案\n        best, bc = min(zip(pop, costs), key=lambda x: x[1])\n        best, bc = list(best), bc\n        n_evals = len(pop)\n        yield {\"iteration\": 0, \"best_cost\": bc, \"best_tour\": best,\n               \"current_cost\": sum(costs) / len(costs), \"extra\": {\"sa_evals\": n_evals}}\n        sel, cx, mut = (_lookup(recipe, \"selection\"), _lookup(recipe, \"crossover\"),\n                        _lookup(recipe, \"mutation\"))\n        eb, cap = p[\"eval_budget\"], 240\n        for it in range(1, p[\"max_iter\"] + 1):\n            cands = []\n            while len(cands) < p[\"pop\"]:\n                i1 = sel[\"fn\"](costs, rng, p[\"tournament\"])\n                i2 = sel[\"fn\"](costs, rng, p[\"tournament\"])\n                if cx[\"fn\"] is not None and rng.random() < p[\"pc\"]:\n                    child = cx[\"fn\"](pop[i1], pop[i2], rng)\n                else:\n                    child = list(pop[i1])\n                child = mut[\"fn\"](child, rng, p[\"pm\"])\n                _assert_perm(child, n, f\"mutation@it{it}\")\n                cands.append(child)\n            ranked = sorted(range(len(cands)), key=lambda i: _rbf_predict(archive, cands[i]))\n            new, newc = [], []\n            for i in ranked[:eb]:\n                c = tour_length(cands[i], D)  # 精确评估只发生在这一行\n                archive.append((list(cands[i]), c))\n                new.append(cands[i])\n                newc.append(c)\n            n_evals += len(new)\n            if len(archive) > cap:  # 档案上限：随机保留（rng 驱动，可复现）\n                keep = sorted(rng.sample(range(len(archive)), cap))\n                archive = [archive[j] for j in keep]\n            # 替换 = 精英保留 + 已评估子代 + 未评估槽位由父代填充（代理不进替换）\n            order = sorted(range(len(pop)), key=lambda i: costs[i])\n            fill = [rng.randrange(len(pop)) for _ in range(p[\"pop\"] - p[\"elite\"] - len(new))]\n            pop = [list(pop[i]) for i in order[:p[\"elite\"]]] + new + [list(pop[i]) for i in fill]\n            costs = [costs[i] for i in order[:p[\"elite\"]]] + newc + [costs[i] for i in fill]\n            cur_best = min(costs)\n            if cur_best < bc:\n                bi = costs.index(cur_best)\n                best, bc = list(pop[bi]), cur_best\n                stall = 0\n            else:\n                stall += 1\n            yield {\"iteration\": it, \"best_cost\": bc, \"best_tour\": best,\n                   \"current_cost\": sum(costs) / len(costs), \"extra\": {\"sa_evals\": n_evals}}\n            term = _lookup(recipe, \"terminator\")\n            if term[\"kind\"] == \"terminator\" and term[\"io\"] == \"hist->bool\" and \\\n               _term_stall(cur_best, hist_best, stall, p[\"patience\"]):\n                break\n            hist_best = cur_best\n\n    elif mode == \"qd\":\n        # S7-D QD mode：MAP-Elites——行为描述子分格档案，每格留精英，\n        # 求「每个行为格子的最优」而非单一最优。\n        # 行为描述子 = (边长均值, 最长边)：紧致度 × 跳跃度两维刻画路径形态，\n        # 与适应度（总长）正交；网格按距离矩阵全域 [dmin,dmax] × [0,dmax] 划分。\n        dmin = min(D[i][j] for i in range(n) for j in range(i + 1, n))\n        dmax = max(D[i][j] for i in range(n) for j in range(i + 1, n))\n        res = p[\"grid_res\"]\n\n        def _cell_of(x, y):\n            cx = int((x - dmin) / (dmax - dmin + 1e-9) * res)\n            cy = int(y / (dmax + 1e-9) * res)\n            return (min(max(cx, 0), res - 1), min(max(cy, 0), res - 1))\n\n        def _bd(tour):\n            es = [D[tour[i]][tour[(i + 1) % n]] for i in range(n)]\n            return sum(es) / n, max(es)\n\n        pop0 = _lookup(recipe, \"init\")[\"fn\"](n, D, p[\"pop\"], rng)\n        grid: Dict[Any, List[Any]] = {}\n        for t in pop0:\n            _assert_perm(t, n, \"init\")\n            x, y = _bd(t)\n            cell = _cell_of(x, y)\n            c = tour_length(t, D)\n            if cell not in grid or c < grid[cell][1]:\n                grid[cell] = [list(t), c]\n        cells = list(grid.keys())\n        bc = min(v[1] for v in grid.values())\n        best = list(next(v[0] for v in grid.values() if v[1] == bc))\n        yield {\"iteration\": 0, \"best_cost\": bc, \"best_tour\": best,\n               \"current_cost\": bc, \"extra\": {\"qd_cells\": len(cells)}}\n        mut, ls = _lookup(recipe, \"mutation\"), _lookup(recipe, \"local_search\")\n        for it in range(1, p[\"max_iter\"] + 1):\n            src = grid[cells[rng.randrange(len(cells))]]\n            cand = mut[\"fn\"](list(src[0]), rng, p[\"pm\"])  # 双桥扰动\n            _assert_perm(cand, n, f\"perturb@it{it}\")\n            if ls is not None:\n                cand = ls[\"fn\"](cand, D, rng, p[\"ls_moves\"])\n            x, y = _bd(cand)\n            cell = _cell_of(x, y)\n            c = tour_length(cand, D)\n            if cell not in grid or c < grid[cell][1]:  # 回灌：占新格或击败格内精英\n                grid[cell] = [cand, c]\n                if cell not in cells:\n                    cells.append(cell)\n            cur_best = min(v[1] for v in grid.values())\n            if cur_best < bc:\n                bc = cur_best\n                best = list(next(v[0] for v in grid.values() if v[1] == bc))\n                stall = 0\n            else:\n                stall += 1\n            yield {\"iteration\": it, \"best_cost\": bc, \"best_tour\": best,\n                   \"current_cost\": c, \"extra\": {\"qd_cells\": len(cells)}}\n            if stall >= p[\"patience\"]:\n                break\n\n    else:  # single（ILS）\n        cur = _lookup(recipe, \"init\")[\"fn\"](n, D, 1, rng)[0]\n        _assert_perm(cur, n, \"init\")\n        cc = tour_length(cur, D)\n        best, bc = list(cur), cc\n        mut, ls, rep = (_lookup(recipe, \"mutation\"), _lookup(recipe, \"local_search\"),\n                        _lookup(recipe, \"replacement\"))\n        yield {\"iteration\": 0, \"best_cost\": bc, \"best_tour\": best,\n               \"current_cost\": cc, \"extra\": {}}\n        for it in range(1, p[\"max_iter\"] + 1):\n            cand = mut[\"fn\"](list(cur), rng, p[\"pm\"])  # double_bridge 深扰动\n            _assert_perm(cand, n, f\"perturb@it{it}\")\n            if ls is not None:\n                cand = ls[\"fn\"](cand, D, rng, p[\"ls_moves\"])\n            candc = tour_length(cand, D)\n            cur, cc = rep[\"fn\"](cur, cc, cand, candc)\n            if cc < bc:\n                best, bc = list(cur), cc\n                stall = 0\n            else:\n                stall += 1\n            yield {\"iteration\": it, \"best_cost\": bc, \"best_tour\": best,\n                   \"current_cost\": cc, \"extra\": {}}\n            if stall >= p[\"patience\"]:\n                break\n\n\ndef install_recipes(SOLVERS: Dict, IterationState, build_problem, tour_length_fn) -> None:\n    \"\"\"把 RECIPES 动态包装成 BaseSolver 风格类注册进 SOLVERS。\n    key 约定 recipe:<id>；前端下拉框/参数面板/PAGE_ALGO 自动生效，零前端改动。\"\"\"\n    for r in RECIPES:\n        cls = type(\n            \"Recipe_\" + r[\"id\"], (object,),\n            {\n                \"__init__\": lambda self, rid=r[\"id\"]: setattr(self, \"rid\", rid),\n                \"name\": r[\"name\"] + \" ⚗\",\n                \"category\": \"组合配方（S7）\",\n                \"default_params\": dict(r[\"default_params\"]),\n                \"param_specs\": _specs_for(r),\n                \"implemented\": True,\n                \"solve\": staticmethod(lambda problem, params, _r=r: _iter_states(\n                    run_recipe(_r, problem, params), IterationState)),\n            },\n        )\n        SOLVERS[\"recipe:\" + r[\"id\"]] = cls\n\n\ndef _iter_states(gen, IterationState):\n    for s in gen:\n        yield IterationState(**s)\n\n\ndef _specs_for(r: Dict) -> Dict:\n    \"\"\"配方参数 → 前端滑块规格（与手写 solver 的 param_specs 同 schema）。\"\"\"\n    dp = r[\"default_params\"]\n    S: Dict[str, Any] = {}\n    if \"pop\" in dp:\n        S[\"pop\"] = {\"min\": 10, \"max\": 150, \"step\": 2, \"int\": True, \"label\": \"种群规模\", \"desc\": \"每代个体数量\"}\n    # single 模式无 pop 参数（init 固定单解）——specs 覆盖检查要求 specs ⊆ defaults 且域合法\n    if \"pc\" in dp:\n        S[\"pc\"] = {\"min\": 0, \"max\": 1, \"step\": 0.05, \"int\": False, \"label\": \"交叉概率\", \"desc\": \"每对父代做交叉的概率\"}\n    if \"pm\" in dp:\n        S[\"pm\"] = {\"min\": 0, \"max\": 1, \"step\": 0.05, \"int\": False,\n                   \"label\": \"变异概率\" if r[\"mode\"] == \"population\" else \"扰动强度\", \"desc\": \"变异/扰动触发概率\"}\n    S.setdefault(\"max_iter\", {\"min\": 50, \"max\": 1000, \"step\": 10, \"int\": True, \"label\": \"迭代次数\", \"desc\": \"预算上限\"})\n    if \"elite\" in dp:\n        S[\"elite\"] = {\"min\": 0, \"max\": 10, \"step\": 1, \"int\": True, \"label\": \"精英保留\", \"desc\": \"直接进入下一代的父代最优个数\"}\n    if \"tournament\" in dp:\n        S[\"tournament\"] = {\"min\": 2, \"max\": 8, \"step\": 1, \"int\": True, \"label\": \"锦标赛规模\", \"desc\": \"k 越大选择压力越强\"}\n    if \"ls_every\" in dp:\n        S[\"ls_every\"] = {\"min\": 0, \"max\": 30, \"step\": 1, \"int\": True, \"label\": \"局部搜索周期\", \"desc\": \"每 N 代触发一次局部搜索；0=关闭\"}\n    if \"ls_moves\" in dp:\n        S[\"ls_moves\"] = {\"min\": 1, \"max\": 300, \"step\": 5, \"int\": True, \"label\": \"局部搜索预算\", \"desc\": \"局部搜索的最大移动数（fixopt 配方 = 每代采样窗口数）\"}\n    if \"patience\" in dp:\n        S[\"patience\"] = {\"min\": 0, \"max\": 300, \"step\": 10, \"int\": True, \"label\": \"无改进停机\", \"desc\": \"连续 N 代无改进即停；0=只按迭代预算停\"}\n    if \"eval_budget\" in dp:  # S7-D SAEA\n        S[\"eval_budget\"] = {\"min\": 2, \"max\": 20, \"step\": 1, \"int\": True, \"label\": \"精确评估预算\", \"desc\": \"每代只有代理预测最优的前 N 个子代付真实评估\"}\n    if \"grid_res\" in dp:  # S7-D MAP-Elites\n        S[\"grid_res\"] = {\"min\": 4, \"max\": 16, \"step\": 1, \"int\": True, \"label\": \"行为网格分辨率\", \"desc\": \"行为描述子每维分格数；总格数 = N²\"}\n    S[\"seed\"] = {\"min\": 0, \"max\": 9999, \"step\": 1, \"int\": True, \"label\": \"随机种子\", \"desc\": \"同种子同结果（可复现）\"}\n    return S\n\n\n# -*- coding: utf-8 -*-\n\"\"\"\nP1 算法包 —— TSP 求解器集合（零第三方依赖）\n================================================\n设计要点（这三点是整个项目的地基，别改）：\n1. 所有求解器继承 BaseSolver，实现 solve(problem, params) -> Iterator[IterationState]\n   用 yield 每代产出一个状态 → 天然支持暂停 / 单步 / 调速 / 流式动画\n2. 零第三方依赖（连 numpy 都不需要）→ Pyodide 里不用加载任何包，加载快、失败率低\n3. 同一份代码同时服务三个场景：① 浏览器 Pyodide ② 本地 pytest ③ 未来 P2 服务端\n\n给 JS 的两个入口函数：start(...) / step()  —— 见文件底部\n\"\"\"\n\nimport json\nimport math\nimport random\nfrom dataclasses import asdict, dataclass, field\nfrom typing import Any, Dict, Iterator, List, Optional, Tuple\n\n# ---- 组件库（v1.2 组件化重构：通用算子单一来源 = py/components.py）----\n# 本地/pytest 正常导入；Pyodide 构建期 components 源码与本文件拼接进同一名字空间，\n# 此 import 抛 ImportError → 跳过（名字已在空间内），两种环境行为一致\n# ---- 算法分类（生成文件 py/taxonomy.py：由 data/families.json + data/algos.json 得出）----\n# 本地正常导入；浏览器构建期拼进同一名字空间，ImportError 分支跳过\ntry:\n    from taxonomy import category_of, category_rank\nexcept ImportError:\n    pass\n\ntry:\n    from components import (\n        _decode_position, _double_bridge, _encode_tour, _first_improving_move,\n        _grasp_construct, _or_opt_move, _ox_crossover, _prefix, _random_2opt_shot,\n        _reverse_mutation, _roulette, _shared_edges_ratio,\n        apply_swaps, build_problem, nearest_neighbor, problem_from_spec, swap_seq_to_target,\n        tour_length, two_opt_improve,\n    )\nexcept ImportError:\n    pass\n\n# ============================ 数据结构 ============================\n\n\n@dataclass\nclass IterationState:\n    \"\"\"前后端契约：一旦定死，新增算法前端一行代码都不用改\"\"\"\n\n    iteration: int          # 第几代\n    best_cost: float        # 全局最优路径长度\n    best_tour: List[int]    # 全局最优路径（城市下标序列）\n    current_cost: float     # 当代成本（画收敛曲线第二条线，如种群均值）\n    extra: Dict[str, Any] = field(default_factory=dict)  # 算法专属可视化数据\n\n\n# ============================ 基础工具 ============================\n\n\n# ============================ 求解器基类 ============================\n\n\nclass BaseSolver:\n    name = \"base\"\n    default_params: Dict[str, Any] = {}\n    implemented = False\n    # 算法分类（前端下拉框分组 + 卡片徽章用）\n    category = \"其他\"\n    # 参数定义域（在线调参模块的单一事实来源）：\n    #   {\"参数\": {\"min\":x,\"max\":y,\"step\":s,\"int\":True,\"label\":\"中文名\",\"desc\":\"说明\"}}\n    #   选择型参数：{\"type\":\"choice\",\"options\":[...],\"labels\":[...],\"label\":...}\n    # 前端按此渲染输入框并在提交前钳制越界值；0 常表示\"自动\"\n    param_specs: Dict[str, Any] = {}\n\n    def solve(self, problem: Dict[str, Any], params: Dict[str, Any]) -> Iterator[IterationState]:\n        raise NotImplementedError\n\n\n# ============================ 已实现：基准算法 ============================\n\n\nclass GreedyNN(BaseSolver):\n    \"\"\"最近邻构造：作为对比基线，收敛曲线上的那条\"起点参考线\"就是它。\n\n    v0.5.1：改为逐城动画——每连接一座城市 yield 一次（extra.open=True 表示\n    路径尚未闭合）。构造期间 best_cost 恒等于最终完整回路的长度：构造型算法\n    \"一步到位\"，没有逐代改进，收敛曲线是一条水平线（诚实反映算法性质）。\n    \"\"\"\n\n    name = \"最近邻 NN（基线）\"\n    default_params = {}\n    implemented = True\n    category = \"构造式\"\n    param_specs = {}\n\n    def solve(self, problem, params):\n        D = problem[\"D\"]\n        n = problem[\"n\"]\n        tour = nearest_neighbor(D)\n        c = tour_length(tour, D)\n        partial = [tour[0]]\n        for k in range(1, n):\n            partial.append(tour[k])\n            yield IterationState(\n                k,\n                c,\n                list(partial),\n                c,\n                {\"open\": True, \"note\": f\"构造中：已连 {k}/{n - 1} 条边（未闭合）\"},\n            )\n        yield IterationState(n, c, tour, c, {\"note\": f\"构造完成：闭合回路，总长 {c:.1f}\"})\n\n\nclass TwoOptSolver(BaseSolver):\n    \"\"\"2-opt 局部搜索：每接受一次改进 yield 一次，动画效果最直观\"\"\"\n\n    name = \"2-opt 局部搜索\"\n    default_params = {\"start\": \"nn\", \"max_moves\": 500}\n    implemented = True\n    category = \"局部搜索\"\n    param_specs = {\n        \"start\": {\"type\": \"choice\", \"options\": [\"nn\", \"random\"], \"labels\": [\"最近邻起点\", \"随机排列起点\"], \"label\": \"初始解\", \"desc\": \"nn=从最近邻构造出发（推荐），random=纯随机排列（教学对照）\"},\n        \"max_moves\": {\"min\": 10, \"max\": 2000, \"step\": 10, \"int\": True, \"label\": \"最大改进步数\", \"desc\": \"最多执行多少次 2-opt 移动\"},\n    }\n\n    def solve(self, problem, params):\n        p = {**self.default_params, **(params or {})}\n        D = problem[\"D\"]\n        tour = nearest_neighbor(D) if p[\"start\"] == \"nn\" else list(range(problem[\"n\"]))\n        cost = tour_length(tour, D)\n        it = 0\n        yield IterationState(it, cost, list(tour), cost, {\"note\": \"初始解\"})\n        while it < p[\"max_moves\"]:\n            m = _first_improving_move(tour, D)\n            if m is None:\n                break\n            i, k, delta = m\n            tour[i : k + 1] = reversed(tour[i : k + 1])\n            cost += delta\n            it += 1\n            yield IterationState(it, cost, list(tour), cost, {\"move\": f\"2-opt({i},{k})\"})\n\n\n# ============================ 已实现：离散粒子群 ============================\n\n\nclass DiscretePSO(BaseSolver):\n    \"\"\"\n    离散 PSO（交换序版）求解 TSP\n    位置 = 一个排列；速度 = 交换算子序列；更新公式沿用连续 PSO 的思想：\n        v' = w*v ⊕ c1*(x→pbest) ⊕ c2*(x→gbest)\n    其中 ⊕ 表示\"以概率保留\"。\n    \"\"\"\n\n    name = \"离散粒子群 PSO\"\n    default_params = {\n        \"n_particles\": 40,\n        \"w\": 0.6,          # 惯性：保留旧速度前缀的比例\n        \"c1\": 1.4,         # 个体认知\n        \"c2\": 1.4,         # 群体社会\n        \"max_iter\": 200,\n        \"seed\": 42,\n        \"local_search\": 0.1,   # 每代以该概率对个体做小预算 2-opt（memetic）\n        \"ls_moves\": 3,         # 个体局部搜索预算（小预算 = 渐进改进 = 好看的收敛曲线）\n        \"gbest_ls_every\": 10,  # 每 N 代对全局最优做一次集中改进\n        \"gbest_ls_moves\": 15,\n    }\n    implemented = True\n    category = \"群体智能\"\n    param_specs = {\n        \"n_particles\": {\"min\": 10, \"max\": 120, \"step\": 2, \"int\": True, \"label\": \"粒子数\", \"desc\": \"种群规模，越大探索越充分但每代越慢\"},\n        \"w\": {\"min\": 0.0, \"max\": 1.0, \"step\": 0.05, \"label\": \"惯性权重 w\", \"desc\": \"保留旧速度前缀的比例，大=延续惯性，小=更听两个最优的\"},\n        \"c1\": {\"min\": 0.0, \"max\": 2.5, \"step\": 0.1, \"label\": \"认知系数 c1\", \"desc\": \"向自己历史最优靠近的强度\"},\n        \"c2\": {\"min\": 0.0, \"max\": 2.5, \"step\": 0.1, \"label\": \"社会系数 c2\", \"desc\": \"向全局最优靠近的强度\"},\n        \"local_search\": {\"min\": 0.0, \"max\": 0.5, \"step\": 0.01, \"label\": \"个体局部搜索概率\", \"desc\": \"每代每个粒子做小预算 2-opt 的概率；0=关闭（纯 PSO）\"},\n        \"ls_moves\": {\"min\": 1, \"max\": 20, \"step\": 1, \"int\": True, \"label\": \"个体局部搜索预算\", \"desc\": \"每次局部搜索最多接受几次 2-opt 移动\"},\n        \"gbest_ls_every\": {\"min\": 0, \"max\": 50, \"step\": 1, \"int\": True, \"label\": \"全局最优改进周期\", \"desc\": \"每 N 代对全局最优集中改进一次；0=关闭\"},\n        \"gbest_ls_moves\": {\"min\": 0, \"max\": 60, \"step\": 1, \"int\": True, \"label\": \"全局最优改进预算\", \"desc\": \"集中改进时最多接受的 2-opt 移动数\"},\n    }\n\n    def solve(self, problem, params):\n        p = {**self.default_params, **(params or {})}\n        D = problem[\"D\"]\n        n = problem[\"n\"]\n        rng = random.Random(p[\"seed\"])\n\n        # 初始种群：随机排列，第 0 个个体直接给 NN 解（工程上常用的加速技巧）\n        particles = []\n        for _ in range(p[\"n_particles\"]):\n            t = list(range(n))\n            rng.shuffle(t)\n            particles.append(t)\n        particles[0] = nearest_neighbor(D)\n\n        pbest = [list(t) for t in particles]\n        pbest_cost = [tour_length(t, D) for t in pbest]\n        gi = min(range(len(pbest_cost)), key=lambda i: pbest_cost[i])\n        gbest, gbest_cost = list(pbest[gi]), pbest_cost[gi]\n        vels: List[List[Tuple[int, int]]] = [[] for _ in particles]\n\n        for it in range(1, p[\"max_iter\"] + 1):\n            mean_cost = 0.0\n            for idx, x in enumerate(particles):\n                seq1 = swap_seq_to_target(list(x), pbest[idx])\n                seq2 = swap_seq_to_target(list(x), gbest)\n\n                # 离散 PSO 速度更新（两段踩坑记录）：\n                # ① 速度片段必须取\"连续前缀\"，不能随机子集——随机子集会破坏交换算子的因果关系\n                # ② c1/c2 各乘一个 [0,1) 随机数——否则序列被完整应用，粒子一步变成 gbest 的复制品，种群坍塌\n                r1, r2 = rng.random(), rng.random()\n                v = _prefix(vels[idx], p[\"w\"], rng)\n                v += _prefix(seq1, p[\"c1\"] * r1, rng)\n                v += _prefix(seq2, p[\"c2\"] * r2, rng)\n\n                # 速度为空时给一次随机扰动，避免种群完全停滞\n                if not v and rng.random() < 0.3:\n                    v = [(rng.randrange(n), rng.randrange(n))]\n                vels[idx] = v\n\n                newx = apply_swaps(list(x), v)\n                if rng.random() < p[\"local_search\"]:\n                    newx = two_opt_improve(newx, D, max_moves=p[\"ls_moves\"])\n                particles[idx] = newx\n\n                c = tour_length(newx, D)\n                mean_cost += c\n                if c < pbest_cost[idx]:\n                    pbest[idx] = list(newx)\n                    pbest_cost[idx] = c\n                    if c < gbest_cost:\n                        gbest, gbest_cost = list(newx), c\n\n            # 集中改进（intensification）：每 N 代对全局最优做一次 2-opt，\n            # 并把结果回写替掉最差粒子——这是 memetic 算法的标准操作，也是曲线能持续下降的关键\n            if p[\"gbest_ls_every\"] > 0 and it % p[\"gbest_ls_every\"] == 0:\n                cand = two_opt_improve(gbest, D, max_moves=p[\"gbest_ls_moves\"])\n                cc = tour_length(cand, D)\n                if cc < gbest_cost - 1e-12:\n                    gbest, gbest_cost = cand, cc\n                    wi = max(range(len(pbest_cost)), key=lambda i: pbest_cost[i])\n                    particles[wi] = list(gbest)\n                    pbest[wi] = list(gbest)\n                    pbest_cost[wi] = gbest_cost\n\n            yield IterationState(\n                iteration=it,\n                best_cost=gbest_cost,\n                best_tour=list(gbest),\n                current_cost=mean_cost / len(particles),\n                extra={\"n_particles\": p[\"n_particles\"]},\n            )\n\n\n# ============================ W2 待实现（照这个模板加） ============================\n\n\nclass _TemplateSolver(BaseSolver):\n    \"\"\"新增算法模板：改 name / default_params / 实现 solve，然后在 SOLVERS 注册即可\"\"\"\n\n    name = \"模板算法\"\n    default_params = {\"max_iter\": 100, \"seed\": 42}\n    implemented = False\n\n    def solve(self, problem, params):\n        p = {**self.default_params, **(params or {})}\n        D = problem[\"D\"]\n        best = nearest_neighbor(D)\n        best_cost = tour_length(best, D)\n        for it in range(1, p[\"max_iter\"] + 1):\n            # TODO: 在这里实现你的迭代逻辑，并 yield 状态\n            yield IterationState(it, best_cost, list(best), best_cost, {})\n\n\nclass ACO(BaseSolver):\n    \"\"\"\n    蚁群算法（Ant System + 精英加强）\n    转移概率 ∝ τ^alpha · (1/d)^beta；每代结束后全局挥发 + 按路径长度释放信息素。\n    工程要点：用候选列表（每个城市只考虑最近的 k 个邻居）把构造复杂度从 O(n²) 降到 O(n·k)，\n    否则 n=100 以上在浏览器里会卡死。\n    \"\"\"\n\n    name = \"蚁群算法 ACO\"\n    default_params = {\n        \"n_ants\": 30,\n        \"alpha\": 1.0,     # 信息素重要度\n        \"beta\": 3.0,      # 启发式（距离）重要度\n        \"rho\": 0.5,       # 挥发率\n        \"Q\": 1.0,         # 信息素强度\n        \"max_iter\": 200,\n        \"seed\": 42,\n        \"elitist\": 2,     # 全局最优路径额外释放的次数（精英策略）\n        \"cand_k\": 20,     # 候选列表长度\n        # 局部搜索（ACS 标准操作）：实测 n=100 时开启后 911 -> 823，直接反超 2-opt/PSO，必须留着\n        \"ls_every\": 5,\n        \"ls_moves\": 20,\n    }\n    implemented = True\n    category = \"群体智能\"\n    param_specs = {\n        \"n_ants\": {\"min\": 5, \"max\": 80, \"step\": 1, \"int\": True, \"label\": \"蚂蚁数\", \"desc\": \"每代并行构造解的蚂蚁数量\"},\n        \"alpha\": {\"min\": 0.0, \"max\": 4.0, \"step\": 0.1, \"label\": \"信息素权重 α\", \"desc\": \"信息素浓度的相对重要度；0=纯贪心按距离走\"},\n        \"beta\": {\"min\": 0.0, \"max\": 6.0, \"step\": 0.1, \"label\": \"启发式权重 β\", \"desc\": \"距离启发式的相对重要度；越大越贪心\"},\n        \"rho\": {\"min\": 0.05, \"max\": 0.9, \"step\": 0.05, \"label\": \"挥发率 ρ\", \"desc\": \"每代信息素蒸发比例；太大遗忘快，太小收敛慢\"},\n        \"Q\": {\"min\": 0.1, \"max\": 5.0, \"step\": 0.1, \"label\": \"信息素强度 Q\", \"desc\": \"每条路径释放的信息素总量\"},\n        \"elitist\": {\"min\": 0, \"max\": 10, \"step\": 1, \"int\": True, \"label\": \"精英蚂蚁数\", \"desc\": \"全局最优路径额外释放信息素的次数；0=关闭精英策略\"},\n        \"cand_k\": {\"min\": 3, \"max\": 40, \"step\": 1, \"int\": True, \"label\": \"候选列表长度\", \"desc\": \"每个城市只考虑最近的 k 个邻居（性能关键）\"},\n        \"ls_every\": {\"min\": 0, \"max\": 30, \"step\": 1, \"int\": True, \"label\": \"局部搜索周期\", \"desc\": \"每 N 代对全局最优做一次 2-opt（ACS 标准操作）；0=关闭\"},\n        \"ls_moves\": {\"min\": 0, \"max\": 40, \"step\": 1, \"int\": True, \"label\": \"局部搜索预算\", \"desc\": \"每次局部搜索最多接受的 2-opt 移动数\"},\n    }\n\n    def solve(self, problem, params):\n        p = {**self.default_params, **(params or {})}\n        D = problem[\"D\"]\n        n = problem[\"n\"]\n        rng = random.Random(p[\"seed\"])\n\n        # 防御性钳制：挥发率趋近 0 会让信息素无限累积（数值爆炸），趋近 1 则瞬间遗忘\n        rho = min(max(float(p[\"rho\"]), 0.01), 0.95)\n\n        # 大实例自动降配（浏览器里要能跑得动，这是硬性体验约束）\n        n_ants = p[\"n_ants\"]\n        if n > 100:\n            n_ants = max(10, n_ants // 2)\n\n        nn_len = tour_length(nearest_neighbor(D), D)\n        tau0 = (n / nn_len) if nn_len > 0 else 1.0\n        tau = [[tau0] * n for _ in range(n)]\n\n        k = max(1, min(p[\"cand_k\"], n - 1))\n        cand = [sorted((j for j in range(n) if j != i), key=lambda j: D[i][j])[:k] for i in range(n)]\n\n        alpha, beta = p[\"alpha\"], p[\"beta\"]\n        best, best_cost = None, float(\"inf\")\n\n        for it in range(1, p[\"max_iter\"] + 1):\n            tours, costs, total = [], [], 0.0\n            for _ in range(n_ants):\n                start = rng.randrange(n)\n                tour = [start]\n                unvisited = set(range(n))\n                unvisited.remove(start)\n                cur = start\n                while unvisited:\n                    cands = [j for j in cand[cur] if j in unvisited]\n                    if not cands:\n                        cands = list(unvisited)\n                    # 重复坐标点会让 D=0 → 除零崩溃（用户上传数据必须防）\n                    ws = [\n                        (tau[cur][j] ** alpha) * ((1.0 / max(D[cur][j], 1e-9)) ** beta)\n                        for j in cands\n                    ]\n                    pick = cands[_roulette(rng, ws)]\n                    tour.append(pick)\n                    unvisited.remove(pick)\n                    cur = pick\n                c = tour_length(tour, D)\n                tours.append(tour)\n                costs.append(c)\n                total += c\n                if c < best_cost:\n                    best, best_cost = list(tour), c\n\n            # 挥发\n            decay = 1.0 - rho\n            for row in tau:\n                for j in range(n):\n                    row[j] *= decay\n\n            # 释放：所有蚂蚁 + 精英（全局最优多放几次）；路径长为 0（重复点）时钳到下限\n            for t, c in zip(tours, costs):\n                dep = p[\"Q\"] / max(c, 1e-9)\n                for idx in range(n):\n                    a, b = t[idx], t[(idx + 1) % n]\n                    tau[a][b] += dep\n                    tau[b][a] += dep\n            for _ in range(p[\"elitist\"]):\n                dep = p[\"Q\"] / max(best_cost, 1e-9)\n                for idx in range(n):\n                    a, b = best[idx], best[(idx + 1) % n]\n                    tau[a][b] += dep\n                    tau[b][a] += dep\n\n            if p[\"ls_every\"] > 0 and it % p[\"ls_every\"] == 0:\n                improved = two_opt_improve(best, D, max_moves=p[\"ls_moves\"])\n                c = tour_length(improved, D)\n                if c < best_cost:\n                    best, best_cost = improved, c\n\n            yield IterationState(\n                iteration=it,\n                best_cost=best_cost,\n                best_tour=list(best),\n                current_cost=total / n_ants,\n                extra={\"n_ants\": n_ants, \"pheromone_max\": max(max(row) for row in tau)},\n            )\n\n\nclass GA(BaseSolver):\n    \"\"\"遗传算法：顺序编码 + 锦标赛选择 + OX 交叉 + 反转变异 + 精英保留\"\"\"\n\n    name = \"遗传算法 GA\"\n    default_params = {\n        \"pop\": 60,\n        \"pc\": 0.85,      # 交叉概率\n        \"pm\": 0.20,      # 变异概率\n        \"max_iter\": 300,\n        \"elite\": 2,      # 精英保留个数\n        \"tournament\": 3, # 锦标赛规模\n        \"seed\": 42,\n        \"ls_every\": 5,    # 每 N 代对 α/全局最优做一次 2-opt，并回灌种群（memetic GA）\n        \"ls_moves\": 15,\n        \"init\": \"nn\",     # \"nn\"=从随机起点出发的最近邻播种；\"random\"=纯随机排列（教学对照用）\n    }\n    implemented = True\n    category = \"进化计算\"\n    param_specs = {\n        \"pop\": {\"min\": 10, \"max\": 150, \"step\": 2, \"int\": True, \"label\": \"种群规模\", \"desc\": \"每代个体数量\"},\n        \"pc\": {\"min\": 0.0, \"max\": 1.0, \"step\": 0.05, \"label\": \"交叉概率 pc\", \"desc\": \"一对亲代发生 OX 交叉的概率\"},\n        \"pm\": {\"min\": 0.0, \"max\": 1.0, \"step\": 0.05, \"label\": \"变异概率 pm\", \"desc\": \"每个子代发生反转变异的概率\"},\n        \"elite\": {\"min\": 1, \"max\": 10, \"step\": 1, \"int\": True, \"label\": \"精英保留数\", \"desc\": \"每代直接复制到下一代的最优个体数\"},\n        \"tournament\": {\"min\": 2, \"max\": 8, \"step\": 1, \"int\": True, \"label\": \"锦标赛规模\", \"desc\": \"每次选择随机抽几个个体、取其中最优；越大选择压力越强\"},\n        \"ls_every\": {\"min\": 0, \"max\": 30, \"step\": 1, \"int\": True, \"label\": \"局部搜索周期\", \"desc\": \"每 N 代对全局最优做一次 2-opt 并回灌种群；0=关闭\"},\n        \"ls_moves\": {\"min\": 0, \"max\": 40, \"step\": 1, \"int\": True, \"label\": \"局部搜索预算\", \"desc\": \"每次局部搜索最多接受的 2-opt 移动数\"},\n        \"init\": {\"type\": \"choice\", \"options\": [\"nn\", \"random\"], \"labels\": [\"最近邻播种\", \"随机排列\"], \"label\": \"初始化方式\", \"desc\": \"nn=多起点最近邻播种（推荐），random=纯随机排列（教学对照）\"},\n    }\n\n    def solve(self, problem, params):\n        p = {**self.default_params, **(params or {})}\n        D = problem[\"D\"]\n        n = problem[\"n\"]\n        rng = random.Random(p[\"seed\"])\n\n        pop_size = p[\"pop\"]\n        if n > 100:\n            pop_size = max(20, pop_size // 2)\n\n        # 初始种群：与 GWO 同一个教训——全随机排列（成本 3000+）会让前几十代\n        # 全部浪费在把种群从\"垃圾\"拉回\"像样\"上。默认用多起点最近邻播种。\n        pop = []\n        for i in range(pop_size):\n            if p[\"init\"] == \"nn\":\n                pop.append(nearest_neighbor(D, start=0 if i == 0 else rng.randrange(n)))\n            else:\n                t = list(range(n))\n                rng.shuffle(t)\n                pop.append(t)\n        costs = [tour_length(t, D) for t in pop]\n        best, best_cost = list(pop[0]), costs[0]\n\n        def _pick() -> int:\n            cand = [rng.randrange(len(pop)) for _ in range(min(p[\"tournament\"], len(pop)))]\n            return min(cand, key=lambda i: costs[i])\n\n        for it in range(1, p[\"max_iter\"] + 1):\n            order = sorted(range(len(pop)), key=lambda i: costs[i])\n\n            # 精英直接留种（不参与交叉变异，保证最优解不会退化）\n            new_pop = [list(pop[i]) for i in order[: p[\"elite\"]]]\n            new_costs = [costs[i] for i in order[: p[\"elite\"]]]\n\n            while len(new_pop) < len(pop):\n                i1, i2 = _pick(), _pick()\n                if rng.random() < p[\"pc\"]:\n                    c1 = _ox_crossover(pop[i1], pop[i2], rng)\n                    c2 = _ox_crossover(pop[i2], pop[i1], rng)\n                else:\n                    c1, c2 = list(pop[i1]), list(pop[i2])\n                if rng.random() < p[\"pm\"]:\n                    c1 = _reverse_mutation(c1, rng)\n                if rng.random() < p[\"pm\"]:\n                    c2 = _reverse_mutation(c2, rng)\n                new_pop.extend([c1, c2])\n\n            new_costs += [tour_length(t, D) for t in new_pop[len(new_costs) :]]\n            pop, costs = new_pop, new_costs\n\n            i_best = min(range(len(pop)), key=lambda i: costs[i])\n            if costs[i_best] < best_cost:\n                best, best_cost = list(pop[i_best]), costs[i_best]\n\n            if p[\"ls_every\"] > 0 and it % p[\"ls_every\"] == 0:\n                improved = two_opt_improve(best, D, max_moves=p[\"ls_moves\"])\n                c = tour_length(improved, D)\n                if c < best_cost:\n                    best, best_cost = improved, c\n                    pop[0], costs[0] = list(best), best_cost  # 回灌到种群（memetic）\n\n            yield IterationState(\n                it,\n                best_cost,\n                list(best),\n                sum(costs) / len(costs),\n                {\"pop\": len(pop), \"worst\": max(costs), \"pc\": p[\"pc\"], \"pm\": p[\"pm\"]},\n            )\n\n\nclass SA(BaseSolver):\n    \"\"\"模拟退火：2-opt 邻域 + Metropolis 判据 + 指数降温。\n\n    与群智能最大的区别：它是单点搜索，靠\"以一定概率接受劣解\"跳出局部最优。\n    extra 里输出温度与接受率——这是 SA 最好看的可视化数据（能直观看到\"退火\"过程）。\n    \"\"\"\n\n    name = \"模拟退火 SA\"\n    default_params = {\n        \"T0\": 0.0,        # 0 = 自动：取初始解的平均边长，保证初期接受率在合理量级\n        \"alpha\": 0.97,    # 降温系数\n        \"max_iter\": 300,\n        \"inner\": 0,       # 0 = 自动：每个温度下的尝试次数 = 城市数\n        \"seed\": 42,\n    }\n    implemented = True\n    category = \"物理启发\"\n    param_specs = {\n        \"T0\": {\"min\": 0, \"max\": 200, \"step\": 1, \"label\": \"初始温度 T₀\", \"desc\": \"0=自动（取初始解平均边长）；越大初期越容易接受劣解\"},\n        \"alpha\": {\"min\": 0.80, \"max\": 0.999, \"step\": 0.001, \"label\": \"降温系数 α\", \"desc\": \"每代温度乘以 α；越接近 1 降温越慢、搜索越充分\"},\n        \"inner\": {\"min\": 0, \"max\": 500, \"step\": 10, \"int\": True, \"label\": \"内循环次数\", \"desc\": \"每个温度下尝试多少次邻域移动；0=自动（=城市数）\"},\n    }\n\n    def solve(self, problem, params):\n        p = {**self.default_params, **(params or {})}\n        D = problem[\"D\"]\n        n = problem[\"n\"]\n        rng = random.Random(p[\"seed\"])\n\n        tour = nearest_neighbor(D)\n        cost = tour_length(tour, D)\n        best, best_cost = list(tour), cost\n\n        if n < 4:  # 城市太少没法做 2-opt 邻域\n            yield IterationState(1, best_cost, list(best), cost, {\"temperature\": 0.0, \"accept_rate\": 0.0})\n            return\n\n        inner = p[\"inner\"] or max(20, n)\n        T = p[\"T0\"] or (cost / n)\n\n        for it in range(1, p[\"max_iter\"] + 1):\n            accepted = 0\n            for _ in range(inner):\n                i = rng.randrange(1, n - 1)\n                k = rng.randrange(i + 1, n)\n                a, b = tour[i - 1], tour[i]\n                c, d = tour[k], tour[(k + 1) % n]\n                delta = D[a][c] + D[b][d] - D[a][b] - D[c][d]\n                if delta < 0 or rng.random() < math.exp(-delta / max(T, 1e-12)):\n                    tour[i : k + 1] = reversed(tour[i : k + 1])\n                    cost += delta\n                    accepted += 1\n                    if cost < best_cost:\n                        best, best_cost = list(tour), cost\n\n            if it % 50 == 0:\n                cost = tour_length(tour, D)  # 增量累加会飘，周期性重算兜底\n            T *= p[\"alpha\"]\n\n            yield IterationState(\n                it,\n                best_cost,\n                list(best),\n                cost,\n                {\n                    \"temperature\": round(T, 4),\n                    \"accept_rate\": round(accepted / inner, 3),\n                    \"inner\": inner,\n                },\n            )\n\n\nclass GWO(BaseSolver):\n    \"\"\"灰狼优化（离散版）：交换序列编码 + α/β/δ 三级领导 + 收敛因子 a 线性下降。\n\n    ★ 踩坑记录（这个页面最值钱的部分）：\n    第一版用的是\"随机键\"（把排列编码成实数向量，用标准 GWO 的连续公式更新，再排序解码）。\n    实测下来：GWO 自身完全没有贡献，终值 626.6 与纯 2-opt 基线一模一样——\n    因为三头狼位置的算术平均在实数空间里等于随机扰动，解码出来的就是随机排列，\n    本质上是在做随机搜索，全靠周期性的 2-opt 兜底。这种\"看起来在跑其实没在优化\"的\n    假象，是最危险的——曲线会下降（因为 2-opt 在干活），但算法本身没起作用。\n\n    第三版又踩一个更隐蔽的坑：种群初始化。\n    全部用随机排列播种时，成本 3000+，而 α 是 NN 解（725）。等级第二第三的 β/δ 是垃圾解，\n    每匹狼被\"往头狼靠近\"时有一大半力气花在往垃圾解上靠 → 200 代下来终值 = 初始 NN 值，\n    GWO 一点没干活（n=100 实测 1078 → 1078，纹丝不动）。\n    改成\"从不同起点出发的最近邻\"播种后，每匹狼都是像样的解，重组才真正产生意义。\n\n    ★ 判定算法\"到底有没有在干活\"的方法（一定要自己做一遍）：\n    把局部搜索关掉（ls_every=0、local_search=0）再跑一次，看终值是否仍明显优于初始解。\n    如果关掉后曲线不动了 —— 那之前看到的下降全是局部搜索的功劳，你的算法是假跑。\n    本项目里每个算法都过了这一关。\n    \"\"\"\n\n    name = \"灰狼优化 GWO\"\n    default_params = {\n        \"n_wolves\": 30,\n        \"max_iter\": 300,\n        \"seed\": 42,\n        \"ls_every\": 10,   # 每 N 代对 α 做一次 2-opt，并回灌到最差狼\n        \"ls_moves\": 20,\n        \"mutation\": 0.05, # 每匹狼的随机扰动概率（防止种群停滞）\n        \"step_cap\": 0.4,  # 单代向单头狼靠近的最大比例（防种群坍塌，别调超过 0.6）\n        \"local_search\": 0.3,   # 每代对多大比例的狼做一次轻量 2-opt（memetic GWO）\n        \"ls_trials\": 20,       # 每次局部搜索随机尝试多少个 2-opt 移动\n    }\n    implemented = True\n    category = \"群体智能\"\n    param_specs = {\n        \"n_wolves\": {\"min\": 5, \"max\": 80, \"step\": 1, \"int\": True, \"label\": \"狼群规模\", \"desc\": \"种群大小\"},\n        \"ls_every\": {\"min\": 0, \"max\": 30, \"step\": 1, \"int\": True, \"label\": \"头狼改进周期\", \"desc\": \"每 N 代对 α 做一次完整 2-opt 并回灌种群；0=关闭\"},\n        \"ls_moves\": {\"min\": 0, \"max\": 40, \"step\": 1, \"int\": True, \"label\": \"头狼改进预算\", \"desc\": \"每次头狼改进最多接受的 2-opt 移动数\"},\n        \"mutation\": {\"min\": 0.0, \"max\": 0.5, \"step\": 0.01, \"label\": \"变异概率\", \"desc\": \"每匹狼每代随机交换两城市的概率（防停滞）\"},\n        \"step_cap\": {\"min\": 0.1, \"max\": 0.6, \"step\": 0.05, \"label\": \"步幅上限\", \"desc\": \"单代向单头狼靠近的最大比例；超过 0.6 会种群坍塌\"},\n        \"local_search\": {\"min\": 0.0, \"max\": 0.8, \"step\": 0.05, \"label\": \"狼群局部搜索比例\", \"desc\": \"每代多大比例的狼做轻量 2-opt；0=关闭（纯 GWO）\"},\n        \"ls_trials\": {\"min\": 1, \"max\": 60, \"step\": 1, \"int\": True, \"label\": \"局部搜索尝试数\", \"desc\": \"每次轻量局部搜索随机尝试多少个 2-opt 移动\"},\n    }\n\n    def solve(self, problem, params):\n        p = {**self.default_params, **(params or {})}\n        D = problem[\"D\"]\n        n = problem[\"n\"]\n        rng = random.Random(p[\"seed\"])\n\n        n_wolves = p[\"n_wolves\"]\n        if n > 80:\n            n_wolves = max(15, n_wolves // 2)\n\n        # ★ 种群初始化是离散 GWO 的生死线：\n        # 全用随机排列（成本 3000+）时，等级第二、第三的 β/δ 是彻头彻尾的垃圾解，\n        # 整群被往垃圾方向带，200 代下来一点没优化（实测终值 = 初始 NN 值，GWO 完全没干活）。\n        # 改成\"从不同起点出发的最近邻\"播种：每匹狼都是像样的解，GWO 的重组才有意义。\n        wolves = [nearest_neighbor(D, start=0)]\n        for _ in range(n_wolves - 1):\n            wolves.append(nearest_neighbor(D, start=rng.randrange(n)))\n        wolves = [_random_2opt_shot(t, D, rng, trials=50) for t in wolves]\n        costs = [tour_length(t, D) for t in wolves]\n\n        order = sorted(range(len(wolves)), key=lambda i: costs[i])\n        alpha, beta, delta = [list(wolves[i]) for i in order[:3]]\n        a_cost, b_cost, d_cost = costs[order[0]], costs[order[1]], costs[order[2]]\n        best, best_cost = list(alpha), a_cost\n\n        for it in range(1, p[\"max_iter\"] + 1):\n            a = 2.0 * (1.0 - it / p[\"max_iter\"])  # 收敛因子 2 → 0\n\n            for w in range(len(wolves)):\n                X = list(wolves[w])\n                for leader in (alpha, beta, delta):\n                    r1, r2 = rng.random(), rng.random()\n                    A = 2.0 * a * r1 - a          # ∈ [-a, a]\n                    C = 2.0 * r2                  # ∈ [0, 2]\n                    seq = swap_seq_to_target(X, leader)\n                    # ★ 关键：frac 必须设上限。若允许 frac=1，狼会整只\"跳\"到头狼身上，\n                    # 三头狼轮流应用后所有狼都变成 δ 的复制品 → 种群坍塌（与离散 PSO 同一个坑）。\n                    frac = min(p[\"step_cap\"], abs(A) * C / 2.0)  # 靠近头狼的比例\n                    k = int(len(seq) * frac)\n                    if k:\n                        X = apply_swaps(X, seq[:k])\n                if rng.random() < p[\"mutation\"]:\n                    i, j = rng.randrange(n), rng.randrange(n)\n                    X[i], X[j] = X[j], X[i]\n                # memetic：让一部分狼做轻量局部搜索，否则纯重组在 TSP 上几乎不下降\n                if rng.random() < p[\"local_search\"]:\n                    X = _random_2opt_shot(X, D, rng, p[\"ls_trials\"])\n                wolves[w] = X\n\n            costs = [tour_length(t, D) for t in wolves]\n\n            # 等级制更新：先看能否取代 α，再看 β，再看 δ（GWO 原文的社会等级）\n            for i in range(len(wolves)):\n                c = costs[i]\n                if c < a_cost:\n                    delta, d_cost = list(beta), b_cost\n                    beta, b_cost = list(alpha), a_cost\n                    alpha, a_cost = list(wolves[i]), c\n                elif c < b_cost:\n                    delta, d_cost = list(beta), b_cost\n                    beta, b_cost = list(wolves[i]), c\n                elif c < d_cost:\n                    delta, d_cost = list(wolves[i]), c\n\n            if a_cost < best_cost:\n                best, best_cost = list(alpha), a_cost\n\n            if p[\"ls_every\"] > 0 and it % p[\"ls_every\"] == 0:\n                improved = two_opt_improve(best, D, max_moves=p[\"ls_moves\"])\n                c = tour_length(improved, D)\n                if c < best_cost:\n                    best, best_cost = improved, c\n                    alpha = list(improved)\n                    a_cost = c\n                    worst = max(range(len(wolves)), key=lambda i: costs[i])  # 回灌：替换最差狼\n                    wolves[worst] = list(improved)\n                    costs[worst] = c\n\n            yield IterationState(\n                it,\n                best_cost,\n                list(best),\n                sum(costs) / len(costs),\n                {\"a\": round(a, 4), \"n_wolves\": len(wolves), \"alpha_cost\": round(a_cost, 2)},\n            )\n\n\nclass ABC(BaseSolver):\n    \"\"\"人工蜂群算法 ABC（Karaboga, 2005）：雇佣蜂 + 观察蜂 + 侦察蜂三阶段。\n\n    离散化映射：蜜源 = 一个排列；邻域算子 = 片段逆转/交换两点（TSP 上 ABC 的标准做法）。\n    三个阶段的角色分工：\n      雇佣蜂：对每个蜜源做一次邻域搜索，贪心保留（劣解直接丢弃）\n      观察蜂：按适应度（1/(1+成本)）轮盘赌选蜜源，再邻域搜索——好解被更多开发\n      侦察蜂：连续 limit 次没改进的蜜源直接丢弃，重新播种（跳出局部最优的机制）\n    与 SA 的关键区别：接受准则纯贪心，跳出局部最优靠 scout 的\"重置\"而不是概率接受。\n    \"\"\"\n\n    name = \"人工蜂群 ABC\"\n    default_params = {\n        \"n_bea\": 24,      # 蜜源数量（=雇佣蜂数量，观察蜂数量与之相同）\n        \"limit\": 12,      # 蜜源连续 limit 代无改进即被侦察蜂重置\n        \"max_iter\": 200,\n        \"seed\": 42,\n        \"mutate_p\": 0.5,  # 邻域搜索时选\"片段逆转\"的概率（否则交换两点）\n        \"ls_every\": 5,    # 每 N 代对全局最优做一次 2-opt 并回灌（与 ACO 同款 memetic 钩子）\n        \"ls_moves\": 20,\n    }\n    implemented = True\n    category = \"群体智能\"\n    param_specs = {\n        \"n_bea\": {\"min\": 6, \"max\": 60, \"step\": 2, \"int\": True, \"label\": \"蜜源数\", \"desc\": \"蜜源=雇佣蜂=观察蜂数量\"},\n        \"limit\": {\"min\": 3, \"max\": 50, \"step\": 1, \"int\": True, \"label\": \"放弃上限 limit\", \"desc\": \"蜜源连续多少代无改进就被侦察蜂重置；太小浪费好解，太大跳不出局部最优\"},\n        \"mutate_p\": {\"min\": 0.0, \"max\": 1.0, \"step\": 0.05, \"label\": \"逆转算子概率\", \"desc\": \"邻域搜索用片段逆转的概率，否则交换两点\"},\n        \"ls_every\": {\"min\": 0, \"max\": 30, \"step\": 1, \"int\": True, \"label\": \"局部搜索周期\", \"desc\": \"每 N 代对全局最优做一次 2-opt 并回灌种群；0=关闭\"},\n        \"ls_moves\": {\"min\": 0, \"max\": 40, \"step\": 1, \"int\": True, \"label\": \"局部搜索预算\", \"desc\": \"每次局部搜索最多接受的 2-opt 移动数\"},\n    }\n\n    def _neighbor(self, tour: List[int], D, rng, p) -> List[int]:\n        t = list(tour)\n        n = len(t)\n        if rng.random() < p[\"mutate_p\"]:\n            a, b = sorted(rng.sample(range(n), 2))\n            t[a : b + 1] = reversed(t[a : b + 1])\n        else:\n            i, j = rng.randrange(n), rng.randrange(n)\n            t[i], t[j] = t[j], t[i]\n        return t\n\n    def solve(self, problem, params):\n        p = {**self.default_params, **(params or {})}\n        D = problem[\"D\"]\n        n = problem[\"n\"]\n        rng = random.Random(p[\"seed\"])\n\n        n_bea = p[\"n_bea\"]\n        # 与 GWO/GA 同一教训：NN 多起点播种，让每个蜜源都像样\n        sources = [nearest_neighbor(D, start=0)]\n        for _ in range(n_bea - 1):\n            sources.append(nearest_neighbor(D, start=rng.randrange(n)))\n        costs = [tour_length(t, D) for t in sources]\n        trials = [0] * n_bea\n        bi = min(range(n_bea), key=lambda i: costs[i])\n        best, best_cost = list(sources[bi]), costs[bi]\n\n        for it in range(1, p[\"max_iter\"] + 1):\n            # —— 雇佣蜂阶段 ——\n            for i in range(n_bea):\n                cand = self._neighbor(sources[i], D, rng, p)\n                c = tour_length(cand, D)\n                if c < costs[i]:\n                    sources[i], costs[i] = cand, c\n                    trials[i] = 0\n                else:\n                    trials[i] += 1\n\n            # —— 观察蜂阶段（按适应度轮盘赌选蜜源再开发）——\n            fit = [1.0 / (1.0 + c) for c in costs]\n            for _ in range(n_bea):\n                i = _roulette(rng, fit)\n                cand = self._neighbor(sources[i], D, rng, p)\n                c = tour_length(cand, D)\n                if c < costs[i]:\n                    sources[i], costs[i] = cand, c\n                    trials[i] = 0\n                else:\n                    trials[i] += 1\n\n            # —— 侦察蜂阶段：放弃无望的蜜源，重新播种 ——\n            scouts = 0\n            for i in range(n_bea):\n                if trials[i] >= p[\"limit\"]:\n                    t = nearest_neighbor(D, start=rng.randrange(n))\n                    t = _random_2opt_shot(t, D, rng, trials=30)\n                    sources[i], costs[i], trials[i] = t, tour_length(t, D), 0\n                    scouts += 1\n\n            bi = min(range(n_bea), key=lambda i: costs[i])\n            if costs[bi] < best_cost:\n                best, best_cost = list(sources[bi]), costs[bi]\n\n            if p[\"ls_every\"] > 0 and it % p[\"ls_every\"] == 0:\n                improved = two_opt_improve(best, D, max_moves=p[\"ls_moves\"])\n                c = tour_length(improved, D)\n                if c < best_cost:\n                    best, best_cost = improved, c\n                    worst = max(range(n_bea), key=lambda i: costs[i])\n                    sources[worst], costs[worst], trials[worst] = list(improved), c, 0\n\n            yield IterationState(\n                it, best_cost, list(best), sum(costs) / n_bea,\n                {\"scouts\": scouts, \"n_bea\": n_bea},\n            )\n\n\nclass FA(BaseSolver):\n    \"\"\"萤火虫算法 FA（Yang, 2008）：亮度低者向亮度高者移动。\n\n    离散化映射（本页的核心内容）：\n      亮度 I = 1/(1+路径长度)；吸引度 β = β₀·exp(-γ·r²)，r = 两排列的汉明距离占比。\n      \"移动\" = 以 β 为比例向更亮的萤火虫靠近（取交换序列前缀，步幅有上限防坍塌）\n              + α 随机扰动（交换两点）。\n    与 PSO 的区别：FA 没有个体最优/全局最优记忆，是\"多对多吸引\"，\n    亮度排序天然实现种群分层，参数少是其卖点。\n    \"\"\"\n\n    name = \"萤火虫算法 FA\"\n    default_params = {\n        \"n_fireflies\": 20,\n        \"beta0\": 1.0,      # 最大吸引度（r=0 时）\n        \"gamma\": 1.0,      # 光吸收系数：大=只吸引近邻，小=全局都被吸引\n        \"alpha_p\": 0.30,   # 随机扰动概率（每萤火虫每代，扰动=短随机 2-opt 试射）\n        \"alpha_trials\": 8, # 每次 α 扰动的 2-opt 试射次数\n        \"max_iter\": 200,\n        \"seed\": 42,\n        \"step_cap\": 0.4,   # 单次移动的最大交换比例（防种群坍塌，同 GWO 教训）\n        \"ls_every\": 10,    # 每 N 代对最亮萤火虫做一次 2-opt 并回灌（memetic 钩子）\n        \"ls_moves\": 20,\n    }\n    implemented = True\n    category = \"群体智能\"\n    param_specs = {\n        \"n_fireflies\": {\"min\": 5, \"max\": 60, \"step\": 1, \"int\": True, \"label\": \"萤火虫数\", \"desc\": \"种群规模\"},\n        \"beta0\": {\"min\": 0.2, \"max\": 2.0, \"step\": 0.1, \"label\": \"最大吸引度 β₀\", \"desc\": \"距离为 0 时的吸引度\"},\n        \"gamma\": {\"min\": 0.0, \"max\": 5.0, \"step\": 0.1, \"label\": \"光吸收系数 γ\", \"desc\": \"大=只有近邻互相吸引（局部搜索强），小=全局互相吸引\"},\n        \"alpha_p\": {\"min\": 0.0, \"max\": 0.5, \"step\": 0.01, \"label\": \"随机扰动 α\", \"desc\": \"每萤火虫每代做一次随机扰动的概率\"},\n        \"alpha_trials\": {\"min\": 1, \"max\": 30, \"step\": 1, \"int\": True, \"label\": \"扰动试射次数\", \"desc\": \"每次 α 扰动包含的随机 2-opt 试射次数（越大局部搜索越强）\"},\n        \"step_cap\": {\"min\": 0.1, \"max\": 0.6, \"step\": 0.05, \"label\": \"步幅上限\", \"desc\": \"单次向亮者移动的最大交换比例\"},\n        \"ls_every\": {\"min\": 0, \"max\": 30, \"step\": 1, \"int\": True, \"label\": \"局部搜索周期\", \"desc\": \"每 N 代对最亮萤火虫做一次 2-opt 并回灌；0=关闭\"},\n        \"ls_moves\": {\"min\": 0, \"max\": 40, \"step\": 1, \"int\": True, \"label\": \"局部搜索预算\", \"desc\": \"每次局部搜索最多接受的 2-opt 移动数\"},\n    }\n\n    def solve(self, problem, params):\n        p = {**self.default_params, **(params or {})}\n        D = problem[\"D\"]\n        n = problem[\"n\"]\n        rng = random.Random(p[\"seed\"])\n\n        n_f = p[\"n_fireflies\"]\n        flies = [nearest_neighbor(D, start=0)]\n        for _ in range(n_f - 1):\n            flies.append(nearest_neighbor(D, start=rng.randrange(n)))\n        # 播种强度与 GWO 对齐（trials=50）：初始蜜火虫太弱时，前期全部预算\n        # 都浪费在\"从垃圾里爬出来\"上（与 GWO 播种教训同源）\n        flies = [_random_2opt_shot(t, D, rng, trials=50) for t in flies]\n        costs = [tour_length(t, D) for t in flies]\n        order0 = sorted(range(n_f), key=lambda i: costs[i])\n        best, best_cost = list(flies[order0[0]]), costs[order0[0]]\n\n        for it in range(1, p[\"max_iter\"] + 1):\n            # 亮度随迭代轻微衰减（原版 FA 的 alpha 随机性递减思想）\n            alpha_t = p[\"alpha_p\"] * (1.0 - 0.5 * it / p[\"max_iter\"])\n            brightest = min(range(n_f), key=lambda i: costs[i])\n\n            for i in range(n_f):\n                X = list(flies[i])\n                if i != brightest:\n                    # ★ TSP 适配 3（踩坑）：向\"最亮者\"全局吸引，替代原版的多对多吸引。\n                    # 实测多对多方案里，向\"勉强亮一点\"的萤火虫做交换前缀 ≈ 随机打乱，\n                    # 200 代 best 纹丝不动（725→690）。原论文 §3.2 的简化实现同样\n                    # 常退化为全局最优吸引，这里是把该退化明说并做进实现。\n                    diff = sum(1 for a, b in zip(X, flies[brightest]) if a != b)\n                    r2 = (diff / n) ** 2\n                    beta = p[\"beta0\"] * math.exp(-p[\"gamma\"] * r2)\n                    # 交换序列从\"当前 X\"实时计算（从原始位置算再应用到已漂移的 X\n                    # 会因果断裂——与离散 PSO 的\"速度前缀\"坑同族）\n                    seq = swap_seq_to_target(list(X), flies[brightest])\n                    k = int(len(seq) * min(p[\"step_cap\"], beta * rng.random()))\n                    if k:\n                        X = apply_swaps(X, seq[:k])\n                # ★ TSP 适配 2（四变体实验定案）：α 扰动 = 短随机 2-opt 试射（trials 次，贪心接受）。\n                # 连续域里 α 是\"随机游走步长\"，落到排列域的自然实现就是一次小规模邻域搜索。\n                # 四个变体实测（两实例×三种子，关局部搜索）：\n                #   v1 单次贪心逆转 646-701   v2 无条件逆转 630-701\n                #   v3 短2opt试射 584-667 ✅  v4 向前三亮吸引+试射 597-663\n                # v3 稳定最强且实现最简。选择压力来自试射内部的贪心接受，\n                # 探索能力来自逆转段的随机性——这正是 FA 原文 α 项的分工。\n                if rng.random() < alpha_t:\n                    X = _random_2opt_shot(X, D, rng, p[\"alpha_trials\"])\n                flies[i] = X\n                flies[i] = X\n\n            costs = [tour_length(t, D) for t in flies]\n            i_best = min(range(n_f), key=lambda i: costs[i])\n            if costs[i_best] < best_cost:\n                best, best_cost = list(flies[i_best]), costs[i_best]\n\n            if p[\"ls_every\"] > 0 and it % p[\"ls_every\"] == 0:\n                improved = two_opt_improve(best, D, max_moves=p[\"ls_moves\"])\n                c = tour_length(improved, D)\n                if c < best_cost:\n                    best, best_cost = improved, c\n                    worst = max(range(n_f), key=lambda i: costs[i])\n                    flies[worst], costs[worst] = list(improved), c\n\n            yield IterationState(\n                it, best_cost, list(best), sum(costs) / n_f,\n                {\"alpha\": round(alpha_t, 4), \"n_fireflies\": n_f},\n            )\n\n\nclass WOA(BaseSolver):\n    \"\"\"鲸鱼优化算法 WOA（Mirjalili & Lewis, 2016）：包围捕食 + 螺旋气泡网 + 搜索猎物。\n\n    离散化映射：位置 = 排列，\"包围/螺旋/搜索\"三种运动都翻译成交换序列的前缀应用：\n      包围（|A|<1, p<0.5）：向当前最优靠近，步幅 ∝ |A|·C/2（有上限防坍塌，同 GWO 教训）\n      搜索（|A|≥1, p<0.5）：远离最优随机找猎物——向随机同伴靠近，保持探索\n      螺旋（p≥0.5）：气泡网收缩，交换比例随 l 与螺旋常数 b 变化，模拟螺旋上升\n    论文里的 WOA 是连续算法，本页展示的就是\"连续算法离散化\"的完整过程。\n    \"\"\"\n\n    name = \"鲸鱼优化 WOA\"\n    default_params = {\n        \"n_whales\": 25,\n        \"b_spiral\": 1.0,   # 螺旋常数\n        \"mutation\": 0.05,  # 随机扰动概率\n        \"max_iter\": 200,\n        \"seed\": 42,\n        \"step_cap\": 0.4,   # 步幅上限（防坍塌）\n        \"ls_every\": 10,    # 每 N 代对最优做一次 2-opt 并回灌\n        \"ls_moves\": 20,\n    }\n    implemented = True\n    category = \"群体智能\"\n    param_specs = {\n        \"n_whales\": {\"min\": 5, \"max\": 60, \"step\": 1, \"int\": True, \"label\": \"鲸群规模\", \"desc\": \"种群大小\"},\n        \"b_spiral\": {\"min\": 0.2, \"max\": 2.0, \"step\": 0.1, \"label\": \"螺旋常数 b\", \"desc\": \"气泡网螺旋的形状；大=螺旋更展开\"},\n        \"mutation\": {\"min\": 0.0, \"max\": 0.5, \"step\": 0.01, \"label\": \"变异概率\", \"desc\": \"每头鲸每代随机交换两城市的概率\"},\n        \"step_cap\": {\"min\": 0.1, \"max\": 0.6, \"step\": 0.05, \"label\": \"步幅上限\", \"desc\": \"单次包围/螺旋的最大交换比例\"},\n        \"ls_every\": {\"min\": 0, \"max\": 30, \"step\": 1, \"int\": True, \"label\": \"局部搜索周期\", \"desc\": \"每 N 代对最优做一次 2-opt 并回灌种群；0=关闭\"},\n        \"ls_moves\": {\"min\": 0, \"max\": 40, \"step\": 1, \"int\": True, \"label\": \"局部搜索预算\", \"desc\": \"每次局部搜索最多接受的 2-opt 移动数\"},\n    }\n\n    def solve(self, problem, params):\n        p = {**self.default_params, **(params or {})}\n        D = problem[\"D\"]\n        n = problem[\"n\"]\n        rng = random.Random(p[\"seed\"])\n\n        n_w = p[\"n_whales\"]\n        whales = [nearest_neighbor(D, start=0)]\n        for _ in range(n_w - 1):\n            whales.append(nearest_neighbor(D, start=rng.randrange(n)))\n        # 播种强度与 GWO/FA 对齐（trials=50）：这是\"防假跑\"底线的一部分——\n        # 初始种群太弱时，前几十代全在填初始坑，动力学没机会表现\n        whales = [_random_2opt_shot(t, D, rng, trials=50) for t in whales]\n        costs = [tour_length(t, D) for t in whales]\n        o = sorted(range(n_w), key=lambda i: costs[i])\n        best, best_cost = list(whales[o[0]]), costs[o[0]]\n\n        for it in range(1, p[\"max_iter\"] + 1):\n            a = 2.0 * (1.0 - it / p[\"max_iter\"])  # 收敛因子 2 → 0\n\n            for w in range(n_w):\n                X = list(whales[w])\n                r1, r2 = rng.random(), rng.random()\n                A = 2.0 * a * r1 - a\n                C = 2.0 * r2\n                l = rng.uniform(-1.0, 1.0)\n                if rng.random() < 0.5:\n                    if abs(A) < 1.0:\n                        # 包围捕食：向当前最优靠近\n                        seq = swap_seq_to_target(list(whales[w]), best)\n                        frac = min(p[\"step_cap\"], abs(A) * C / 2.0)\n                    else:\n                        # 搜索猎物：向随机同伴靠近（探索）\n                        j = rng.randrange(n_w)\n                        seq = swap_seq_to_target(list(whales[w]), whales[j])\n                        frac = min(p[\"step_cap\"], abs(A) * C / 4.0)\n                    k = int(len(seq) * frac)\n                    if k:\n                        X = apply_swaps(X, seq[:k])\n                else:\n                    # 螺旋气泡网：交换比例 = e^(b·l) 归一化后收缩\n                    spiral = min(1.0, math.exp(p[\"b_spiral\"] * l) / (math.e ** p[\"b_spiral\"]))\n                    seq = swap_seq_to_target(list(whales[w]), best)\n                    k = int(len(seq) * min(p[\"step_cap\"], spiral))\n                    if k:\n                        X = apply_swaps(X, seq[:k])\n                if rng.random() < p[\"mutation\"]:\n                    i, j = rng.randrange(n), rng.randrange(n)\n                    X[i], X[j] = X[j], X[i]\n                whales[w] = X\n\n            costs = [tour_length(t, D) for t in whales]\n            i_b = min(range(n_w), key=lambda i: costs[i])\n            if costs[i_b] < best_cost:\n                best, best_cost = list(whales[i_b]), costs[i_b]\n\n            if p[\"ls_every\"] > 0 and it % p[\"ls_every\"] == 0:\n                improved = two_opt_improve(best, D, max_moves=p[\"ls_moves\"])\n                c = tour_length(improved, D)\n                if c < best_cost:\n                    best, best_cost = improved, c\n                    worst = max(range(n_w), key=lambda i: costs[i])\n                    whales[worst], costs[worst] = list(improved), c\n\n            yield IterationState(\n                it, best_cost, list(best), sum(costs) / n_w,\n                {\"a\": round(a, 4), \"n_whales\": n_w},\n            )\n\n\nclass TabuSearch(BaseSolver):\n    \"\"\"禁忌搜索 TS（Glover, 1986）：带\"禁忌表\"的局部搜索。\n\n    与 SA / 2-opt 的本质区别：每代在采样的邻域里选【最好的许可移动】——\n    即使它让当前解变差也照样走（这是 TS 跳出局部最优的机制），\n    刚走过的移动在禁忌期内不许反悔（防止原地打转），\n    但如果某个禁忌移动能刷新历史最优，特事特办放行（特赦准则 / aspiration）。\n    引用量级：Glover 的 TS 系列论文合计引用数万次，是元启发式的奠基工作之一。\n    \"\"\"\n\n    name = \"禁忌搜索 TS\"\n    default_params = {\n        \"tabu_tenure\": 8,   # 禁忌期：一个移动被禁多少代\n        \"samples\": 60,      # 每代采样多少个 2-opt 邻居（全邻域 O(n^2) 浏览器跑不动）\n        \"max_iter\": 200,\n        \"seed\": 42,\n    }\n    implemented = True\n    category = \"局部搜索\"\n    param_specs = {\n        \"tabu_tenure\": {\"min\": 1, \"max\": 30, \"step\": 1, \"int\": True, \"label\": \"禁忌期\", \"desc\": \"一个移动被执行后被禁忌的代数；太短原地打转，太长搜索受限\"},\n        \"samples\": {\"min\": 10, \"max\": 200, \"step\": 10, \"int\": True, \"label\": \"邻域采样数\", \"desc\": \"每代随机采样多少个候选移动再挑最好的\"},\n    }\n\n    def solve(self, problem, params):\n        p = {**self.default_params, **(params or {})}\n        D = problem[\"D\"]\n        n = problem[\"n\"]\n        rng = random.Random(p[\"seed\"])\n\n        tour = nearest_neighbor(D)\n        cost = tour_length(tour, D)\n        best, best_cost = list(tour), cost\n        tabu: Dict[Tuple[int, int], int] = {}\n        tenure = p[\"tabu_tenure\"]\n\n        yield IterationState(0, cost, list(tour), cost, {\"note\": \"初始解\", \"tabu_size\": 0})\n\n        for it in range(1, p[\"max_iter\"] + 1):\n            best_move: Optional[Tuple[int, int, float]] = None\n            for _ in range(p[\"samples\"]):\n                i = rng.randrange(1, n - 1)\n                k = rng.randrange(i + 1, n)\n                mv = (i, k)\n                delta = D[tour[i - 1]][tour[k]] + D[tour[i]][tour[(k + 1) % n]] - D[tour[i - 1]][tour[i]] - D[tour[k]][tour[(k + 1) % n]]\n                in_tabu = tabu.get(mv, 0) > it or tabu.get((k, i), 0) > it\n                # 特赦准则：禁忌移动若能刷新历史最优，放行\n                if in_tabu and not (cost + delta < best_cost - 1e-12):\n                    continue\n                if best_move is None or delta < best_move[2]:\n                    best_move = (i, k, delta)\n            if best_move is None:\n                break\n            i, k, delta = best_move\n            tour[i : k + 1] = reversed(tour[i : k + 1])\n            cost += delta\n            tabu[(i, k)] = it + tenure\n            tabu[(k, i)] = it + tenure\n            if it % 100 == 0:\n                cost = tour_length(tour, D)  # 增量累加会飘，周期性重算兜底（同 SA）\n            if cost < best_cost:\n                best, best_cost = list(tour), cost\n            yield IterationState(\n                it, best_cost, list(best), cost,\n                {\"tabu_size\": len(tabu) // 2, \"last_delta\": round(delta, 2),\n                 \"worsening\": delta > 1e-9},\n            )\n\n\nclass DifferentialEvolution(BaseSolver):\n    \"\"\"差分进化 DE（Storn & Price, 1997）：用\"种群内差异\"驱动搜索。\n\n    DE 是引用量最大的元启发式之一（原始论文数万次引用），核心只有一条公式：\n        变异体 = x_r1 + F · (x_r2 − x_r3)\n    差向量 (x_r2 − x_r3) 自动让步长适配种群当前的分散程度——后期收敛步长自然变小。\n\n    离散化映射（TSP 版）：\n      \"差向量\" = 把 r2 变到 r3 所需的交换序列（两点间的差异在排列域就是一串交换）；\n      变异策略用 DE/current-to-best（向当前最优靠近 + 一对差分扰动）；\n      交叉 = 以概率 CR 用 OX 顺序交叉把变异体与 x_i 杂交得 trial；\n      选择 = trial 与 x_i 贪心二选一（DE 的经典贪心选择）。\n\n    ★ 踩坑记录（与 GWO 假跑事件同源，变体矩阵实验见 tools/de_variant_experiment.py）：\n    第一版用教科书 DE/rand/1 + CR=0.9 的 OX 交叉——实测 200 代进步 0.0%，\n    及格线全部来自 NN 播种初始化（1 代和 200 代终值一模一样：685→685），纯假跑。\n    根因：OX 交叉在两个都已被 2-opt 打磨过的父本上破坏性太强（重组出来的边\n    大部分是拼接噪声），贪心选择 200 代一次都没接受过新解。\n    五组变体实验（60 城市 × 3 种子）结论：\n      rand1    + CR=0.2 + polish 0.3/10   最差真实进步 3.2%\n      cur2best + CR=0.2 + polish 0.3/10   最差真实进步 3.8% ✅（定案）\n    current-to-best 让 trial 始终围绕好解的邻域生成，配合低 CR 减少交叉破坏，\n    这是排列域上 DE 能真实干活的最小改动。\n    \"\"\"\n\n    name = \"差分进化 DE\"\n    default_params = {\n        \"n_pop\": 30,\n        \"F\": 0.6,         # 差分缩放因子\n        \"CR\": 0.2,        # 交叉概率（排列域上要低——OX 交叉破坏性强，见踩坑记录）\n        \"max_iter\": 200,\n        \"seed\": 42,\n        \"step_cap\": 0.6,  # F 的实际执行上限（防坍塌，同 GWO 教训）\n        \"mutation\": 0.02, # 随机扰动概率\n        \"polish_p\": 0.3,  # 内部打磨概率：以小概率对 trial 做短 2-opt 试射（memetic DE 的轻量版）\n        \"polish_trials\": 10,\n        \"ls_every\": 10,\n        \"ls_moves\": 20,\n    }\n    implemented = True\n    category = \"进化计算\"\n    param_specs = {\n        \"n_pop\": {\"min\": 6, \"max\": 60, \"step\": 2, \"int\": True, \"label\": \"种群规模\", \"desc\": \"种群大小（大实例自动降配）\"},\n        \"F\": {\"min\": 0.1, \"max\": 1.0, \"step\": 0.05, \"label\": \"缩放因子 F\", \"desc\": \"差分变异的步长比例；太小收敛慢，太大不收敛\"},\n        \"CR\": {\"min\": 0.0, \"max\": 1.0, \"step\": 0.05, \"label\": \"交叉概率 CR\", \"desc\": \"变异体与父代做 OX 交叉的概率；排列域上建议 0.2 左右（交叉破坏性强，见实现注释）\"},\n        \"step_cap\": {\"min\": 0.1, \"max\": 0.6, \"step\": 0.05, \"label\": \"步幅上限\", \"desc\": \"单次差分变异执行交换前缀的最大比例\"},\n        \"mutation\": {\"min\": 0.0, \"max\": 0.2, \"step\": 0.01, \"label\": \"扰动概率\", \"desc\": \"每个个体每代随机交换两城市的概率\"},\n        \"polish_p\": {\"min\": 0.0, \"max\": 0.5, \"step\": 0.05, \"label\": \"打磨概率\", \"desc\": \"对每个新 trial 做短 2-opt 试射的概率（memetic DE 组件）\"},\n        \"polish_trials\": {\"min\": 1, \"max\": 30, \"step\": 1, \"int\": True, \"label\": \"打磨试射次数\", \"desc\": \"每次打磨包含的随机 2-opt 试射次数\"},\n        \"ls_every\": {\"min\": 0, \"max\": 30, \"step\": 1, \"int\": True, \"label\": \"局部搜索周期\", \"desc\": \"每 N 代对全局最优做一次 2-opt 并回灌；0=关闭\"},\n        \"ls_moves\": {\"min\": 0, \"max\": 40, \"step\": 1, \"int\": True, \"label\": \"局部搜索预算\", \"desc\": \"每次局部搜索最多接受的 2-opt 移动数\"},\n    }\n\n    def solve(self, problem, params):\n        p = {**self.default_params, **(params or {})}\n        D = problem[\"D\"]\n        n = problem[\"n\"]\n        rng = random.Random(p[\"seed\"])\n\n        n_pop = p[\"n_pop\"]\n        if n > 80:\n            n_pop = max(10, n_pop // 2)\n        pop = [nearest_neighbor(D, start=0)]\n        for _ in range(n_pop - 1):\n            pop.append(nearest_neighbor(D, start=rng.randrange(n)))\n        pop = [_random_2opt_shot(t, D, rng, trials=50) for t in pop]\n        costs = [tour_length(t, D) for t in pop]\n        i0 = min(range(n_pop), key=lambda i: costs[i])\n        best, best_cost = list(pop[i0]), costs[i0]\n\n        for it in range(1, p[\"max_iter\"] + 1):\n            improved_cnt = 0\n            for i in range(n_pop):\n                # DE/current-to-best：向当前最优靠近 + 一对差分扰动（见类注释的踩坑记录）\n                idxs = [j for j in range(n_pop) if j != i]\n                r1, r2 = rng.sample(idxs, 2)\n                seq = swap_seq_to_target(list(pop[i]), best) + swap_seq_to_target(list(pop[r1]), pop[r2])\n                mutant = list(pop[i])\n                k = int(len(seq) * min(p[\"step_cap\"], p[\"F\"] * (0.5 + rng.random())))\n                if k:\n                    mutant = apply_swaps(mutant, seq[:k])\n                # 交叉：以概率 CR 与父本做 OX 顺序交叉\n                if rng.random() < p[\"CR\"]:\n                    trial = _ox_crossover(mutant, pop[i], rng)\n                else:\n                    trial = mutant\n                if rng.random() < p[\"mutation\"]:\n                    i_, j_ = rng.randrange(n), rng.randrange(n)\n                    trial[i_], trial[j_] = trial[j_], trial[i_]\n                # 内部打磨（memetic DE 的轻量版）：连续域里 DE 靠差向量自适应步长，\n                # 排列域上纯交换重组的下降能力有限，以小概率做短 2-opt 试射补足\n                # 开发能力——与 FA 的 α 扰动（v3 定案）同一设计思想。\n                if rng.random() < p[\"polish_p\"]:\n                    trial = _random_2opt_shot(trial, D, rng, p[\"polish_trials\"])\n                # 贪心选择（DE 的标志性一步）\n                c = tour_length(trial, D)\n                if c < costs[i]:\n                    pop[i], costs[i] = trial, c\n                    improved_cnt += 1\n                    if c < best_cost:\n                        best, best_cost = list(trial), c\n            if p[\"ls_every\"] > 0 and it % p[\"ls_every\"] == 0:\n                improved = two_opt_improve(best, D, max_moves=p[\"ls_moves\"])\n                c = tour_length(improved, D)\n                if c < best_cost:\n                    best, best_cost = improved, c\n                    worst = max(range(n_pop), key=lambda i_: costs[i_])\n                    pop[worst], costs[worst] = list(improved), c\n            yield IterationState(\n                it, best_cost, list(best), sum(costs) / n_pop,\n                {\"F\": p[\"F\"], \"n_pop\": n_pop, \"improved\": improved_cnt},\n            )\n\n\nclass CuckooSearch(BaseSolver):\n    \"\"\"布谷鸟搜索 CS（Yang & Deb, 2009）：莱维飞行 + 随机弃巢。\n\n    引用量级：原始论文 1 万次以上，\"莱维飞行\"是它最大的招牌——\n    步长分布重尾：绝大多数步子很小，偶尔来一步超大的（幂律分布）。\n    生物学故事是布谷鸟把蛋下在别的鸟窝里；数学内核是莱维飞行随机游走。\n\n    离散化映射：\n      一个蛋/鸟窝 = 一个排列；\n      莱维飞行的\"小步\" = 少量短 2-opt 试射；\"偶发大步\" = 长片段逆转（跨度 ~ n·levy/4）；\n      发现外来蛋（概率 pa）= 丢弃最差的一部分鸟窝、重新播种。\n    \"\"\"\n\n    name = \"布谷鸟搜索 CS\"\n    default_params = {\n        \"n_nests\": 20,\n        \"pa\": 0.25,        # 弃巢比例\n        \"alpha\": 0.3,      # 莱维步长基数\n        \"levy_beta\": 1.5,  # 莱维指数（1~3，越小重尾越明显）\n        \"max_iter\": 200,\n        \"seed\": 42,\n        \"ls_every\": 10,\n        \"ls_moves\": 20,\n    }\n    implemented = True\n    category = \"群体智能\"\n    param_specs = {\n        \"n_nests\": {\"min\": 5, \"max\": 50, \"step\": 1, \"int\": True, \"label\": \"鸟窝数\", \"desc\": \"种群规模\"},\n        \"pa\": {\"min\": 0.05, \"max\": 0.5, \"step\": 0.05, \"label\": \"弃巢比例 pa\", \"desc\": \"每代被随机发现并重新播种的最差鸟窝比例\"},\n        \"alpha\": {\"min\": 0.05, \"max\": 1.0, \"step\": 0.05, \"label\": \"步长基数 α\", \"desc\": \"莱维飞行的整体步长基数\"},\n        \"levy_beta\": {\"min\": 1.0, \"max\": 3.0, \"step\": 0.1, \"label\": \"莱维指数\", \"desc\": \"越小步长分布越重尾（偶发大步越频繁）\"},\n        \"ls_every\": {\"min\": 0, \"max\": 30, \"step\": 1, \"int\": True, \"label\": \"局部搜索周期\", \"desc\": \"每 N 代对全局最优做一次 2-opt 并回灌；0=关闭\"},\n        \"ls_moves\": {\"min\": 0, \"max\": 40, \"step\": 1, \"int\": True, \"label\": \"局部搜索预算\", \"desc\": \"每次局部搜索最多接受的 2-opt 移动数\"},\n    }\n\n    def _levy_move(self, tour: List[int], D, rng, p) -> List[int]:\n        \"\"\"莱维飞行的排列域实现：小步=短 2-opt 试射；偶发大步=长片段逆转\"\"\"\n        levy = rng.paretovariate(max(1.01, p[\"levy_beta\"]))\n        if levy > 2.5:\n            # 偶发大步：重尾分布的核心价值——一跨越局部盆地\n            L = max(2, min(int(len(tour) * p[\"alpha\"] * levy / 6), len(tour) - 2))\n            i = rng.randrange(1, len(tour) - L)\n            X = list(tour)\n            X[i : i + L] = reversed(X[i : i + L])\n            return X if tour_length(X, D) < tour_length(tour, D) else list(tour)\n        # 小步：alpha 缩放的短 2-opt 试射\n        trials = max(1, min(int(p[\"alpha\"] * levy * 30), 40))\n        return _random_2opt_shot(tour, D, rng, trials)\n\n    def solve(self, problem, params):\n        p = {**self.default_params, **(params or {})}\n        D = problem[\"D\"]\n        n = problem[\"n\"]\n        rng = random.Random(p[\"seed\"])\n\n        n_nests = p[\"n_nests\"]\n        if n > 80:\n            n_nests = max(10, n_nests // 2)\n        nests = [nearest_neighbor(D, start=0)]\n        for _ in range(n_nests - 1):\n            nests.append(nearest_neighbor(D, start=rng.randrange(n)))\n        nests = [_random_2opt_shot(t, D, rng, trials=50) for t in nests]\n        costs = [tour_length(t, D) for t in nests]\n        i0 = min(range(n_nests), key=lambda i: costs[i])\n        best, best_cost = list(nests[i0]), costs[i0]\n\n        for it in range(1, p[\"max_iter\"] + 1):\n            # 布谷鸟阶段：每只布谷鸟借一个鸟窝出发做莱维飞行，蛋更优则占巢\n            for _ in range(n_nests):\n                j = rng.randrange(n_nests)\n                egg = self._levy_move(nests[j], D, rng, p)\n                c = tour_length(egg, D)\n                if c < costs[j]:\n                    nests[j], costs[j] = egg, c\n                    if c < best_cost:\n                        best, best_cost = list(egg), c\n            # 弃巢阶段：最差 pa 比例的鸟窝被发现，重新播种（保持多样性）\n            n_abandon = max(1, int(n_nests * p[\"pa\"]))\n            order = sorted(range(n_nests), key=lambda i: costs[i], reverse=True)\n            for idx in order[:n_abandon]:\n                fresh = nearest_neighbor(D, start=rng.randrange(n))\n                fresh = _random_2opt_shot(fresh, D, rng, trials=20)\n                nests[idx], costs[idx] = fresh, tour_length(fresh, D)\n            i_b = min(range(n_nests), key=lambda i: costs[i])\n            if costs[i_b] < best_cost:\n                best, best_cost = list(nests[i_b]), costs[i_b]\n            if p[\"ls_every\"] > 0 and it % p[\"ls_every\"] == 0:\n                improved = two_opt_improve(best, D, max_moves=p[\"ls_moves\"])\n                c = tour_length(improved, D)\n                if c < best_cost:\n                    best, best_cost = improved, c\n                    worst = max(range(n_nests), key=lambda i: costs[i])\n                    nests[worst], costs[worst] = list(improved), c\n            yield IterationState(\n                it, best_cost, list(best), sum(costs) / n_nests,\n                {\"pa\": p[\"pa\"], \"n_nests\": n_nests},\n            )\n\n\nclass SineCosine(BaseSolver):\n    \"\"\"正弦余弦算法 SCA（Mirjalili, 2016）：用正弦/余弦振荡包围最优解。\n\n    引用量级：原始论文数千次，Mirjalili 系（GWO/WOA/SCA）的代表作品之一。\n    核心公式：X = X + r1·sin(r2)·|r3·P − X|（r4<0.5 取 sin，否则取 cos）。\n    r1 线性衰减 2→0：前期振荡大（全局探索），后期振荡小（局部开发）；\n    sin/cos 的正负交替天然产生\"往返包围\"的运动轨迹。\n\n    离散化映射：\n      |r3·P − X| = 向最优解 P 的交换序列长度；步幅 = r1·|sin(r2)| 或 r1·|cos(r2)|（有上限）；\n      sin/cos 为负 = \"反向振荡\" = 向随机同伴靠近（探索），\n      这是往返包围在排列域里能自洽落地的等价物。\n    \"\"\"\n\n    name = \"正弦余弦 SCA\"\n    default_params = {\n        \"n_agents\": 25,\n        \"a0\": 2.0,        # r1 初值（线性衰减到 0）\n        \"mutation\": 0.05,\n        \"max_iter\": 200,\n        \"seed\": 42,\n        \"step_cap\": 0.4,\n        \"ls_every\": 10,\n        \"ls_moves\": 20,\n    }\n    implemented = True\n    category = \"数学启发\"\n    param_specs = {\n        \"n_agents\": {\"min\": 5, \"max\": 60, \"step\": 1, \"int\": True, \"label\": \"个体数\", \"desc\": \"种群规模\"},\n        \"a0\": {\"min\": 1.0, \"max\": 3.0, \"step\": 0.1, \"label\": \"r1 初值\", \"desc\": \"振荡幅度的初值，线性衰减到 0\"},\n        \"mutation\": {\"min\": 0.0, \"max\": 0.3, \"step\": 0.01, \"label\": \"扰动概率\", \"desc\": \"每个体每代随机交换两城市的概率\"},\n        \"step_cap\": {\"min\": 0.1, \"max\": 0.6, \"step\": 0.05, \"label\": \"步幅上限\", \"desc\": \"单次振荡执行交换前缀的最大比例\"},\n        \"ls_every\": {\"min\": 0, \"max\": 30, \"step\": 1, \"int\": True, \"label\": \"局部搜索周期\", \"desc\": \"每 N 代对全局最优做一次 2-opt 并回灌；0=关闭\"},\n        \"ls_moves\": {\"min\": 0, \"max\": 40, \"step\": 1, \"int\": True, \"label\": \"局部搜索预算\", \"desc\": \"每次局部搜索最多接受的 2-opt 移动数\"},\n    }\n\n    def solve(self, problem, params):\n        p = {**self.default_params, **(params or {})}\n        D = problem[\"D\"]\n        n = problem[\"n\"]\n        rng = random.Random(p[\"seed\"])\n\n        n_a = p[\"n_agents\"]\n        if n > 80:\n            n_a = max(10, n_a // 2)\n        agents = [nearest_neighbor(D, start=0)]\n        for _ in range(n_a - 1):\n            agents.append(nearest_neighbor(D, start=rng.randrange(n)))\n        agents = [_random_2opt_shot(t, D, rng, trials=50) for t in agents]\n        costs = [tour_length(t, D) for t in agents]\n        i0 = min(range(n_a), key=lambda i: costs[i])\n        best, best_cost = list(agents[i0]), costs[i0]\n\n        for it in range(1, p[\"max_iter\"] + 1):\n            r1 = p[\"a0\"] * (1.0 - it / p[\"max_iter\"])\n            for i in range(n_a):\n                X = list(agents[i])\n                r2 = rng.uniform(0, 2 * math.pi)\n                r4 = rng.random()\n                osc = abs(math.sin(r2)) if r4 < 0.5 else abs(math.cos(r2))\n                frac = min(p[\"step_cap\"], r1 * osc)\n                if math.sin(r2) >= 0.0:\n                    # 正向振荡：向最优解收缩\n                    seq = swap_seq_to_target(list(X), best)\n                    k = int(len(seq) * frac)\n                    if k:\n                        X = apply_swaps(X, seq[:k])\n                else:\n                    # 反向振荡：向随机同伴靠近（把\"远离最优\"落成\"换个方向\"，\n                    # 直接远离会退化成随机打乱——同 FA 多对多的教训）\n                    if n_a > 1:\n                        j = rng.randrange(n_a)\n                        seq = swap_seq_to_target(list(X), agents[j])\n                        k = int(len(seq) * frac * 0.5)\n                        if k:\n                            X = apply_swaps(X, seq[:k])\n                if rng.random() < p[\"mutation\"]:\n                    i_, j_ = rng.randrange(n), rng.randrange(n)\n                    X[i_], X[j_] = X[j_], X[i_]\n                if rng.random() < 0.3:\n                    X = _random_2opt_shot(X, D, rng, 8)\n                agents[i] = X\n            costs = [tour_length(t, D) for t in agents]\n            i_b = min(range(n_a), key=lambda i: costs[i])\n            if costs[i_b] < best_cost:\n                best, best_cost = list(agents[i_b]), costs[i_b]\n            if p[\"ls_every\"] > 0 and it % p[\"ls_every\"] == 0:\n                improved = two_opt_improve(best, D, max_moves=p[\"ls_moves\"])\n                c = tour_length(improved, D)\n                if c < best_cost:\n                    best, best_cost = improved, c\n                    worst = max(range(n_a), key=lambda i: costs[i])\n                    agents[worst], costs[worst] = list(improved), c\n            yield IterationState(\n                it, best_cost, list(best), sum(costs) / n_a,\n                {\"r1\": round(r1, 4), \"n_agents\": n_a},\n            )\n\n\nclass HarrisHawks(BaseSolver):\n    \"\"\"哈里斯鹰优化 HHO（Heidari et al., 2019）：逃逸能量驱动的捕猎策略切换。\n\n    引用量级：原始论文上万次，是 2019 年后引用增长最快的元启发式之一。\n    核心机制：猎物（兔子）的\"逃逸能量\" E 随迭代从 2 衰减到 0；\n      |E|≥1 探索（猎物还在挣扎，鹰群大范围搜索）；\n      |E|<1 开发（包围），按逃跑概率 r 分软/硬包围，\n      进攻失败时切换莱维俯冲（重尾随机步）。\n\n    离散化映射：\n      软包围 = 以 |E|·步幅上限 的比例向最优解（兔子）靠近；\n      硬包围 = 步幅再减半（包围圈收紧）；\n      莱维俯冲 = 俯冲失败（没改进）就做一次短 2-opt 试射 + 小概率长片段逆转；\n      探索 = 在两只随机同伴中挑好的靠近（配合 NN 播种）。\n    \"\"\"\n\n    name = \"哈里斯鹰 HHO\"\n    default_params = {\n        \"n_hawks\": 25,\n        \"dive_p\": 0.4,    # 莱维俯冲触发概率\n        \"mutation\": 0.05,\n        \"max_iter\": 200,\n        \"seed\": 42,\n        \"step_cap\": 0.4,\n        \"ls_every\": 10,\n        \"ls_moves\": 20,\n    }\n    implemented = True\n    category = \"群体智能\"\n    param_specs = {\n        \"n_hawks\": {\"min\": 5, \"max\": 60, \"step\": 1, \"int\": True, \"label\": \"鹰群规模\", \"desc\": \"种群规模\"},\n        \"dive_p\": {\"min\": 0.0, \"max\": 1.0, \"step\": 0.05, \"label\": \"俯冲概率\", \"desc\": \"进攻阶段触发莱维俯冲（短 2-opt 试射）的概率\"},\n        \"mutation\": {\"min\": 0.0, \"max\": 0.3, \"step\": 0.01, \"label\": \"扰动概率\", \"desc\": \"每只鹰每代随机交换两城市的概率\"},\n        \"step_cap\": {\"min\": 0.1, \"max\": 0.6, \"step\": 0.05, \"label\": \"步幅上限\", \"desc\": \"单次包围移动执行交换前缀的最大比例\"},\n        \"ls_every\": {\"min\": 0, \"max\": 30, \"step\": 1, \"int\": True, \"label\": \"局部搜索周期\", \"desc\": \"每 N 代对全局最优做一次 2-opt 并回灌；0=关闭\"},\n        \"ls_moves\": {\"min\": 0, \"max\": 40, \"step\": 1, \"int\": True, \"label\": \"局部搜索预算\", \"desc\": \"每次局部搜索最多接受的 2-opt 移动数\"},\n    }\n\n    def _levy_dive(self, X: List[int], D, rng, n: int) -> List[int]:\n        \"\"\"莱维俯冲：短 2-opt 试射为主，偶发长片段逆转（重尾步长）\"\"\"\n        Y = _random_2opt_shot(X, D, rng, 10)\n        if rng.random() < 0.2:\n            L = max(2, int(n * rng.random() * 0.25))\n            i = rng.randrange(1, n - L)\n            Z = list(Y)\n            Z[i : i + L] = reversed(Z[i : i + L])\n            if tour_length(Z, D) < tour_length(Y, D):\n                Y = Z\n        return Y\n\n    def solve(self, problem, params):\n        p = {**self.default_params, **(params or {})}\n        D = problem[\"D\"]\n        n = problem[\"n\"]\n        rng = random.Random(p[\"seed\"])\n\n        n_h = p[\"n_hawks\"]\n        if n > 80:\n            n_h = max(10, n_h // 2)\n        hawks = [nearest_neighbor(D, start=0)]\n        for _ in range(n_h - 1):\n            hawks.append(nearest_neighbor(D, start=rng.randrange(n)))\n        hawks = [_random_2opt_shot(t, D, rng, trials=50) for t in hawks]\n        costs = [tour_length(t, D) for t in hawks]\n        i0 = min(range(n_h), key=lambda i: costs[i])\n        rabbit, rabbit_cost = list(hawks[i0]), costs[i0]\n        best, best_cost = list(rabbit), rabbit_cost\n\n        for it in range(1, p[\"max_iter\"] + 1):\n            E0 = 2.0 * (1.0 - it / p[\"max_iter\"])  # 逃逸能量 2 → 0\n            for i in range(n_h):\n                X = list(hawks[i])\n                if abs(E0) >= 1.0:\n                    # ===== 探索阶段：猎物还在挣扎，鹰群大范围搜索 =====\n                    j, k = rng.sample(range(n_h), 2) if n_h > 1 else (0, 0)\n                    # 在两只随机同伴中挑好的靠近（原论文的\"随机栖息地二选一\"）\n                    if costs[j] <= costs[k]:\n                        seq = swap_seq_to_target(list(X), hawks[j])\n                    else:\n                        seq = swap_seq_to_target(list(X), hawks[k])\n                    kk = int(len(seq) * min(p[\"step_cap\"], rng.random()))\n                    if kk:\n                        X = apply_swaps(X, seq[:kk])\n                else:\n                    # ===== 开发阶段：软/硬包围 + 莱维俯冲 =====\n                    r = rng.random()  # 猎物逃跑概率\n                    before = tour_length(X, D)\n                    frac = min(p[\"step_cap\"], abs(E0) * (1.0 if r >= 0.5 else 0.5))\n                    seq = swap_seq_to_target(list(X), rabbit)\n                    kk = int(len(seq) * frac)\n                    if kk:\n                        X = apply_swaps(X, seq[:kk])\n                    # 俯冲：进攻没占到便宜就切换莱维俯冲（原论文 Fuzz 行为）\n                    if rng.random() < p[\"dive_p\"] or tour_length(X, D) >= before:\n                        X = self._levy_dive(X, D, rng, n)\n                if rng.random() < p[\"mutation\"]:\n                    i_, j_ = rng.randrange(n), rng.randrange(n)\n                    X[i_], X[j_] = X[j_], X[i_]\n                hawks[i] = X\n            costs = [tour_length(t, D) for t in hawks]\n            i_b = min(range(n_h), key=lambda i: costs[i])\n            if costs[i_b] < rabbit_cost:\n                rabbit, rabbit_cost = list(hawks[i_b]), costs[i_b]\n                if rabbit_cost < best_cost:\n                    best, best_cost = list(rabbit), rabbit_cost\n            if p[\"ls_every\"] > 0 and it % p[\"ls_every\"] == 0:\n                improved = two_opt_improve(best, D, max_moves=p[\"ls_moves\"])\n                c = tour_length(improved, D)\n                if c < best_cost:\n                    best, best_cost = improved, c\n                    rabbit, rabbit_cost = list(improved), c\n                    worst = max(range(n_h), key=lambda i: costs[i])\n                    hawks[worst], costs[worst] = list(improved), c\n            yield IterationState(\n                it, best_cost, list(best), sum(costs) / n_h,\n                {\"E\": round(E0, 4), \"n_hawks\": n_h},\n            )\n\n\n# ============================ 已实现：局部搜索框架 ============================\n\n\nclass IteratedLocalSearch(BaseSolver):\n    \"\"\"迭代局部搜索 ILS（Lourenço, Martin & Stützle, 2003）：扰动 + 下探 + 接受准则。\n\n    引用量级：1 万次以上，工业界用得最多的元启发式框架——LKH 求解器的骨架。\n    它的洞察很朴素：单点局部搜索必然卡死在局部最优，那就\n    「下探到局部最优 → 用受控扰动踢出去 → 再下探 → 挑好的留下」循环往复。\n\n    离散化映射（TSP 版）：\n      下探 = 2-opt 局部搜索（预算制）；扰动 = 双桥（2-opt 无法一步还原的踢法）；\n      接受准则 = better（只认改进）或 restart（连续多次无改进就从 NN 重来）。\n    \"\"\"\n\n    name = \"迭代局部搜索 ILS\"\n    default_params = {\n        \"max_iter\": 200,\n        \"perturb\": 1,      # 每次扰动连踢几脚（双桥次数）\n        \"descend\": 30,     # 每次下探的 2-opt 移动预算\n        \"accept\": \"better\",  # better=只接受改进；restart=无改进 N 代重启\n        \"patience\": 30,    # restart 模式下的容忍代数\n        \"seed\": 42,\n    }\n    implemented = True\n    category = \"局部搜索\"\n    param_specs = {\n        \"perturb\": {\"min\": 1, \"max\": 5, \"step\": 1, \"int\": True, \"label\": \"扰动强度\", \"desc\": \"每次扰动连踢几脚双桥（越多踢得越远）\"},\n        \"descend\": {\"min\": 5, \"max\": 100, \"step\": 5, \"int\": True, \"label\": \"下探预算\", \"desc\": \"每次下探最多执行的 2-opt 移动数\"},\n        \"accept\": {\"type\": \"choice\", \"options\": [\"better\", \"restart\"], \"labels\": [\"只认改进\", \"无改进重启\"], \"label\": \"接受准则\", \"desc\": \"扰动后比当前差时怎么办\"},\n        \"patience\": {\"min\": 5, \"max\": 80, \"step\": 5, \"int\": True, \"label\": \"容忍代数\", \"desc\": \"restart 模式：连续 N 代无改进就从最近邻重新构造\"},\n    }\n\n    def solve(self, problem, params):\n        p = {**self.default_params, **(params or {})}\n        D = problem[\"D\"]\n        n = problem[\"n\"]\n        rng = random.Random(p[\"seed\"])\n\n        tour = two_opt_improve(nearest_neighbor(D), D, max_moves=500)\n        best, best_cost = list(tour), tour_length(tour, D)\n        cur_cost = best_cost\n        no_improve = 0\n        yield IterationState(0, best_cost, list(best), cur_cost, {\"note\": \"初始解 = NN + 完整 2-opt\"})\n\n        for it in range(1, p[\"max_iter\"] + 1):\n            # 扰动：连踢 perturb 脚双桥\n            kicked = list(tour)\n            for _ in range(p[\"perturb\"]):\n                kicked = _double_bridge(kicked, rng)\n            # 下探：预算制 2-opt\n            cand = two_opt_improve(kicked, D, max_moves=p[\"descend\"])\n            c = tour_length(cand, D)\n            note = \"\"\n            if c < cur_cost:\n                tour, cur_cost = cand, c\n                note = f\"改进 {cur_cost:.1f}\"\n            elif c == cur_cost:\n                note = \"持平保留\"\n            elif p[\"accept\"] == \"restart\":\n                no_improve += 1\n                note = f\"变差，容忍 {no_improve}/{p['patience']}\"\n                if no_improve >= p[\"patience\"]:\n                    tour = nearest_neighbor(D, start=rng.randrange(n))\n                    tour = two_opt_improve(tour, D, max_moves=p[\"descend\"])\n                    cur_cost = tour_length(tour, D)\n                    no_improve = 0\n                    note = \"重启：从 NN 重新构造\"\n            else:\n                # better 模式：回到当前解（扰动结果直接丢弃）\n                note = \"变差丢弃\"\n            if cur_cost < best_cost:\n                best, best_cost = list(tour), cur_cost\n                no_improve = 0\n            yield IterationState(it, best_cost, list(best), cur_cost, {\"note\": note})\n\n\nclass VariableNeighborhoodSearch(BaseSolver):\n    \"\"\"变邻域搜索 VNS（Mladenović & Hansen, 1997）：局部最优卡住就换邻域。\n\n    引用量级：1 万次以上，与 TS、ILS 并列的三大局部搜索框架。\n    核心思想：一个解在 2-opt 邻域里是最优，换到 or-opt 邻域、双桥邻域里\n    未必最优——「在更远的邻域里扰动（shake），在近邻域里下探，\n    下探有进步就回到第一层邻域，没进步就换下一层」。\n\n    离散化映射（TSP 版，三层邻域）：\n      k=1 双桥 shake（最远）；k=2 or-opt 摘段重插；k=3 双重交换；\n      下探 = 预算制 2-opt。VNS 的 shake 步长随 k 递增，天然平衡探索/开发。\n    \"\"\"\n\n    name = \"变邻域搜索 VNS\"\n    default_params = {\n        \"max_iter\": 200,\n        \"k_max\": 3,        # 邻域层数\n        \"descend\": 25,     # 每次下探的 2-opt 移动预算\n        \"or_seg\": 3,       # or-opt 段长上限\n        \"seed\": 42,\n    }\n    implemented = True\n    category = \"局部搜索\"\n    param_specs = {\n        \"k_max\": {\"min\": 2, \"max\": 4, \"step\": 1, \"int\": True, \"label\": \"邻域层数\", \"desc\": \"shake 邻域的层数（越大探索越远）\"},\n        \"descend\": {\"min\": 5, \"max\": 100, \"step\": 5, \"int\": True, \"label\": \"下探预算\", \"desc\": \"每次下探最多执行的 2-opt 移动数\"},\n        \"or_seg\": {\"min\": 1, \"max\": 5, \"step\": 1, \"int\": True, \"label\": \"or-opt 段长\", \"desc\": \"第二层邻域摘下重插的连续城市段长上限\"},\n    }\n\n    def solve(self, problem, params):\n        p = {**self.default_params, **(params or {})}\n        D = problem[\"D\"]\n        n = problem[\"n\"]\n        rng = random.Random(p[\"seed\"])\n\n        tour = two_opt_improve(nearest_neighbor(D), D, max_moves=500)\n        best, best_cost = list(tour), tour_length(tour, D)\n        cur_cost = best_cost\n        k = 1\n        yield IterationState(0, best_cost, list(best), cur_cost, {\"k\": 1, \"note\": \"初始解 = NN + 完整 2-opt\"})\n\n        for it in range(1, p[\"max_iter\"] + 1):\n            # shake：在第 k 层邻域里随机扰动\n            if k == 1:\n                shaken = _double_bridge(tour, rng)\n            elif k == 2:\n                shaken = _or_opt_move(tour, rng, rng.randint(1, p[\"or_seg\"]))\n            else:\n                shaken = _double_bridge(_double_bridge(tour, rng), rng)\n            # 下探：预算制 2-opt\n            cand = two_opt_improve(shaken, D, max_moves=p[\"descend\"])\n            c = tour_length(cand, D)\n            note = \"\"\n            if c < cur_cost:\n                tour, cur_cost = cand, c\n                k = 1  # 有进步就回到第一层\n                note = f\"改进 {cur_cost:.1f}，回到 k=1\"\n            else:\n                k = k % p[\"k_max\"] + 1  # 没进步换下一层邻域\n                note = f\"无进步，换邻域 k={k}\"\n            if cur_cost < best_cost:\n                best, best_cost = list(tour), cur_cost\n            yield IterationState(it, best_cost, list(best), cur_cost, {\"k\": k, \"note\": note})\n\n\nclass LinKernighan(BaseSolver):\n    \"\"\"Lin–Kernighan（Lin & Kernighan, 1973）：变深度边交换，TSP 专用求解器巅峰之作。\n\n    引用量级：数万次，50 年过去仍是 TSP 求解器（LKH/Concorde）的核心引擎。\n    它和 2-opt 的本质区别：2-opt 只接受「单步变好」的交换，卡死在局部最优；\n    LK 允许链式交换中「个别步暂时变差」，只要整条链的累计增益为负（变好）\n    就采纳——「先下坡再上更高的山」的搜索由变深度机制显式支持。\n\n    本实现的简化版（随机化 LK 变体）：\n      每一轮 pass：贪心链式执行 2-opt 交换（每步选当前最优的断裂点，\n      同一断裂点本轮不再复用），记录链上累计增益最优的那个中间状态；\n      pass 结束时若最优累计增益 < 0（即有净改进）则采纳。\n      深度上限 + 每步只抽样部分候选位（don't-look 思想）控制耗时。\n    \"\"\"\n\n    name = \"Lin–Kernighan LK\"\n    default_params = {\n        \"max_iter\": 200,\n        \"depth\": 10,       # 单次 pass 的链深上限\n        \"sample\": 40,      # 每步抽样的候选断裂点数（don't-look）\n        \"kick_every\": 10,  # 每 N 代卡死时踢一脚双桥；0=关闭\n        \"seed\": 42,\n    }\n    implemented = True\n    category = \"局部搜索\"\n    param_specs = {\n        \"depth\": {\"min\": 2, \"max\": 12, \"step\": 1, \"int\": True, \"label\": \"链深上限\", \"desc\": \"单次 pass 最多链式执行几次交换（变深度搜索的核心参数）\"},\n        \"sample\": {\"min\": 5, \"max\": 80, \"step\": 5, \"int\": True, \"label\": \"抽样数\", \"desc\": \"每步抽样的候选断裂点数（越大越精细越慢）\"},\n        \"kick_every\": {\"min\": 0, \"max\": 100, \"step\": 5, \"int\": True, \"label\": \"踢桥周期\", \"desc\": \"每 N 代无改进就踢一脚双桥跳出局部盆地；0=关闭\"},\n    }\n\n    def _lk_pass(self, tour: List[int], D, rng, max_depth: int, sample: int):\n        \"\"\"一次变深度 pass：贪心链式交换（允许链中暂时变差），返回最优累计中间态。\n\n        ★LK 的本体不在\"做 2-opt\"，而在\"允许链中个别步变差、按累计增益收官\"：\n        每步在抽样断裂点里选 delta 最小的交换（含正 delta——先下坡再上高山），\n        链上维护累计增益 cum，记录 cum 最小的中间状态；pass 结束时若最优\n        cum < 0（净改进）才采纳。used 集合防同一断裂点复用（防原地打转）。\n        \"\"\"\n        n = len(tour)\n        t = list(tour)\n        base = tour_length(t, D)\n        cum = 0.0\n        best_cum = 0.0\n        best_t = None\n        used: set = set()\n        for _ in range(max_depth):\n            best_move = None\n            best_delta = None\n            for _ in range(sample):\n                i = rng.randrange(0, n - 1)\n                if i in used:\n                    continue\n                # 全 k 扫描（steepest）：只扫 i+2/i+3 两档会退化成残废 2-opt（实测教训）\n                for k in range(i + 2, n):\n                    a, b, c, d = t[i - 1], t[i], t[k], t[(k + 1) % n]\n                    delta = (D[a][c] + D[b][d]) - (D[a][b] + D[c][d])\n                    if best_delta is None or delta < best_delta:\n                        best_delta = delta\n                        best_move = (i, k)\n            if best_move is None:\n                break\n            i, k = best_move\n            t[i : k + 1] = reversed(t[i : k + 1])\n            cum += best_delta\n            used.add(i)\n            if cum < best_cum:\n                best_cum = cum\n                best_t = list(t)\n        return best_t, best_cum, base\n\n    def solve(self, problem, params):\n        p = {**self.default_params, **(params or {})}\n        D = problem[\"D\"]\n        rng = random.Random(p[\"seed\"])\n\n        tour = nearest_neighbor(D)\n        best, best_cost = list(tour), tour_length(tour, D)\n        cur_cost = best_cost\n        no_improve = 0\n        # 铁手走查 P1（2026-09-27）：删去初始态 yield——其他 44 个算法都是\n        # max_iter 个态（for it in range(1, T+1)），唯 LK 多吐一个 it=0 初始态，\n        # 迭代计数 off-by-one 污染横评口径（50 代请求实收 51 态）。\n\n        for it in range(1, p[\"max_iter\"] + 1):\n            new_t, cum, _ = self._lk_pass(tour, D, rng, p[\"depth\"], p[\"sample\"])\n            note = \"\"\n            if new_t is not None:\n                tour = new_t\n                cur_cost = tour_length(tour, D)\n                note = f\"链采纳，累计增益 {cum:.1f}\"\n            else:\n                note = \"本 pass 无净改进\"\n            if cur_cost < best_cost:\n                best, best_cost = list(tour), cur_cost\n                no_improve = 0\n            else:\n                no_improve += 1\n                if p[\"kick_every\"] > 0 and no_improve >= p[\"kick_every\"]:\n                    tour = _double_bridge(tour, rng)\n                    cur_cost = tour_length(tour, D)\n                    no_improve = 0\n                    note = \"卡死 → 双桥踢出局部盆地\"\n            yield IterationState(it, best_cost, list(best), cur_cost, {\"note\": note})\n\n\n# ============================ 已实现：群智能补全（第二批） ============================\n\n\nclass BatAlgorithm(BaseSolver):\n    \"\"\"蝙蝠算法 BA（Yang, 2010）：频率调谐 + 脉冲发射 + 响度衰减。\n\n    引用量级：1 万次以上，Yang 系（FA/CS/BA）里被引最高的作品之一。\n    生物学故事是蝙蝠回声定位捕猎：靠近猎物时降低响度、提高发射频率。\n\n    离散化映射（TSP 版）：\n      频率 f ∈ [fmin, fmax] = 向全局最优移动的步幅基数（交换序列前缀比例）；\n      响度 A = 随机游走的步长（短 2-opt 试射强度），接受改进后按 α 衰减；\n      脉冲率 r = 以概率 r 直接在最优解附近做「定位性」开发（跳过移动直接试射）。\n    \"\"\"\n\n    name = \"蝙蝠算法 BA\"\n    default_params = {\n        \"n_bats\": 20,\n        \"f_min\": 0.05,\n        \"f_max\": 0.45,     # 频率上限（=向最优移动的最大前缀比例，防坍塌同 GWO 教训）\n        \"A0\": 0.9,         # 初始响度\n        \"r0\": 0.5,         # 初始脉冲率\n        \"alpha\": 0.9,      # 响度衰减系数\n        \"gamma\": 0.9,      # 脉冲率增长系数\n        \"max_iter\": 200,\n        \"seed\": 42,\n        \"ls_every\": 10,\n        \"ls_moves\": 20,\n    }\n    implemented = True\n    category = \"群体智能\"\n    param_specs = {\n        \"n_bats\": {\"min\": 5, \"max\": 50, \"step\": 1, \"int\": True, \"label\": \"蝙蝠数\", \"desc\": \"种群规模（大实例自动降配）\"},\n        \"f_min\": {\"min\": 0.01, \"max\": 0.3, \"step\": 0.01, \"label\": \"频率下限\", \"desc\": \"向最优移动的最小步幅基数\"},\n        \"f_max\": {\"min\": 0.1, \"max\": 0.8, \"step\": 0.05, \"label\": \"频率上限\", \"desc\": \"向最优移动的最大步幅基数（防种群坍塌）\"},\n        \"A0\": {\"min\": 0.3, \"max\": 1.0, \"step\": 0.05, \"label\": \"初始响度\", \"desc\": \"随机游走（2-opt 试射）的初始强度\"},\n        \"r0\": {\"min\": 0.1, \"max\": 0.9, \"step\": 0.05, \"label\": \"初始脉冲率\", \"desc\": \"在最优解附近做定位性开发的概率\"},\n        \"alpha\": {\"min\": 0.5, \"max\": 0.99, \"step\": 0.01, \"label\": \"响度衰减 α\", \"desc\": \"蝙蝠找到更好解后响度乘以 α（逐步收敛到开发）\"},\n        \"gamma\": {\"min\": 0.5, \"max\": 0.99, \"step\": 0.01, \"label\": \"脉冲增长 γ\", \"desc\": \"蝙蝠找到更好解后脉冲率按 γ·r 增长\"},\n        \"ls_every\": {\"min\": 0, \"max\": 30, \"step\": 1, \"int\": True, \"label\": \"局部搜索周期\", \"desc\": \"每 N 代对全局最优做一次 2-opt 并回灌；0=关闭\"},\n        \"ls_moves\": {\"min\": 0, \"max\": 40, \"step\": 1, \"int\": True, \"label\": \"局部搜索预算\", \"desc\": \"每次局部搜索最多接受的 2-opt 移动数\"},\n    }\n\n    def solve(self, problem, params):\n        p = {**self.default_params, **(params or {})}\n        D = problem[\"D\"]\n        n = problem[\"n\"]\n        rng = random.Random(p[\"seed\"])\n\n        n_bats = p[\"n_bats\"]\n        if n > 80:\n            n_bats = max(10, n_bats // 2)\n        bats = [nearest_neighbor(D, start=0)]\n        for _ in range(n_bats - 1):\n            bats.append(nearest_neighbor(D, start=rng.randrange(n)))\n        bats = [_random_2opt_shot(t, D, rng, trials=50) for t in bats]\n        costs = [tour_length(t, D) for t in bats]\n        A = [p[\"A0\"]] * n_bats\n        r = [p[\"r0\"]] * n_bats\n        i0 = min(range(n_bats), key=lambda i: costs[i])\n        best, best_cost = list(bats[i0]), costs[i0]\n\n        for it in range(1, p[\"max_iter\"] + 1):\n            for i in range(n_bats):\n                f = rng.uniform(p[\"f_min\"], p[\"f_max\"])\n                if rng.random() < r[i]:\n                    # 脉冲发射：在全局最优附近做定位性开发（短 2-opt 试射）\n                    cand = _random_2opt_shot(best, D, rng, max(2, int(A[i] * 18)))\n                else:\n                    # 常规移动：向最优解执行交换序列前缀（比例=f），加响度级随机游走\n                    seq = swap_seq_to_target(list(bats[i]), best)\n                    cand = apply_swaps(bats[i], seq[: int(len(seq) * min(p[\"f_max\"], f))])\n                    cand = _random_2opt_shot(cand, D, rng, max(1, int(A[i] * 14)))\n                c = tour_length(cand, D)\n                # 响度门槛：只有「响度加权随机数 < 改进幅度比例」才接纳（BA 原式的排列域近似）\n                if c < costs[i] and rng.random() < A[i]:\n                    bats[i], costs[i] = cand, c\n                    A[i] *= p[\"alpha\"]\n                    r[i] = p[\"r0\"] * (1 - pow(2.718281828, -p[\"gamma\"] * it))\n                    if c < best_cost:\n                        best, best_cost = list(cand), c\n            if p[\"ls_every\"] > 0 and it % p[\"ls_every\"] == 0:\n                improved = two_opt_improve(best, D, max_moves=p[\"ls_moves\"])\n                c = tour_length(improved, D)\n                if c < best_cost:\n                    best, best_cost = improved, c\n                    worst = max(range(n_bats), key=lambda i: costs[i])\n                    bats[worst], costs[worst] = list(improved), c\n            yield IterationState(\n                it, best_cost, list(best), sum(costs) / n_bats,\n                {\"A_mean\": round(sum(A) / n_bats, 3), \"n_bats\": n_bats},\n            )\n\n\nclass HarmonySearch(BaseSolver):\n    \"\"\"和声搜索 HS（Geem, Kim & Loganathan, 2001）：像乐手即兴合奏一样生成新解。\n\n    引用量级：近万次，\"音乐启发式\"的开山之作。乐手即兴的三种方式\n    正好对应三个参数：\n      记忆考虑（HMCR）= 从记忆库里抄一段；音高调整（PAR）= 抄完微调；\n      随机选择（1−HMCR）= 完全即兴。新和声更好就替换记忆库里的最差者。\n\n    离散化映射（TSP 版）：\n      和声 = 排列；记忆考虑 = 随机抄一条记忆和声；\n      音高调整 = 短 2-opt 试射或片段逆转（微调）；\n      完全即兴 = 从 NN 起点重新构造。\n    \"\"\"\n\n    name = \"和声搜索 HS\"\n    default_params = {\n        \"hms\": 20,          # 和声记忆库大小\n        \"hmcr\": 0.9,        # 记忆考虑率\n        \"par\": 0.3,         # 音高调整率\n        \"max_iter\": 200,\n        \"seed\": 42,\n        \"ls_every\": 10,\n        \"ls_moves\": 20,\n    }\n    implemented = True\n    category = \"音乐启发\"\n    param_specs = {\n        \"hms\": {\"min\": 5, \"max\": 50, \"step\": 1, \"int\": True, \"label\": \"记忆库大小\", \"desc\": \"和声记忆库 HM 的容量\"},\n        \"hmcr\": {\"min\": 0.5, \"max\": 0.99, \"step\": 0.01, \"label\": \"记忆考虑率\", \"desc\": \"新和声从记忆库取材的概率；否则完全即兴（重新构造）\"},\n        \"par\": {\"min\": 0.05, \"max\": 0.8, \"step\": 0.05, \"label\": \"音高调整率\", \"desc\": \"抄完记忆和声后做微调（2-opt 试射/逆转）的概率\"},\n        \"ls_every\": {\"min\": 0, \"max\": 30, \"step\": 1, \"int\": True, \"label\": \"局部搜索周期\", \"desc\": \"每 N 代对全局最优做一次 2-opt 并回灌；0=关闭\"},\n        \"ls_moves\": {\"min\": 0, \"max\": 40, \"step\": 1, \"int\": True, \"label\": \"局部搜索预算\", \"desc\": \"每次局部搜索最多接受的 2-opt 移动数\"},\n    }\n\n    def solve(self, problem, params):\n        p = {**self.default_params, **(params or {})}\n        D = problem[\"D\"]\n        n = problem[\"n\"]\n        rng = random.Random(p[\"seed\"])\n\n        hms = p[\"hms\"]\n        if n > 80:\n            hms = max(10, hms // 2)\n        mem = [nearest_neighbor(D, start=0)]\n        for _ in range(hms - 1):\n            mem.append(nearest_neighbor(D, start=rng.randrange(n)))\n        mem = [_random_2opt_shot(t, D, rng, trials=50) for t in mem]\n        costs = [tour_length(t, D) for t in mem]\n        i0 = min(range(hms), key=lambda i: costs[i])\n        best, best_cost = list(mem[i0]), costs[i0]\n\n        for it in range(1, p[\"max_iter\"] + 1):\n            # 即兴一支新和声\n            if rng.random() < p[\"hmcr\"]:\n                new = list(mem[rng.randrange(hms)])  # 记忆考虑：抄一条\n                if rng.random() < p[\"par\"]:\n                    # 音高调整：微调（一半概率 2-opt 试射，一半概率片段逆转）\n                    if rng.random() < 0.5:\n                        new = _random_2opt_shot(new, D, rng, 12)\n                    else:\n                        L = rng.randint(2, max(2, n // 4))\n                        i = rng.randrange(1, n - L)\n                        new[i : i + L] = reversed(new[i : i + L])\n            else:\n                # 完全即兴：从随机 NN 起点重新构造\n                new = nearest_neighbor(D, start=rng.randrange(n))\n                new = _random_2opt_shot(new, D, rng, 20)\n            c = tour_length(new, D)\n            # 替换记忆库里的最差者（好就进）\n            worst = max(range(hms), key=lambda i: costs[i])\n            if c < costs[worst]:\n                mem[worst], costs[worst] = new, c\n                if c < best_cost:\n                    best, best_cost = list(new), c\n            if p[\"ls_every\"] > 0 and it % p[\"ls_every\"] == 0:\n                improved = two_opt_improve(best, D, max_moves=p[\"ls_moves\"])\n                c2 = tour_length(improved, D)\n                if c2 < best_cost:\n                    best, best_cost = improved, c2\n                    worst = max(range(hms), key=lambda i: costs[i])\n                    mem[worst], costs[worst] = list(improved), c2\n            yield IterationState(\n                it, best_cost, list(best), sum(costs) / hms,\n                {\"hmcr\": p[\"hmcr\"], \"par\": p[\"par\"]},\n            )\n\n\nclass GravitationalSearch(BaseSolver):\n    \"\"\"引力搜索算法 GSA（Rashedi, Nezamabadi-pour & Saryazdi, 2009）：\n    万有引力定律 + 运动定律的搜索算法。\n\n    引用量级：近万次，物理启发群里的代表作（隔壁物理启发目前只有 SA）。\n    质量越大的天体（解越优）引力越强——整个种群在引力场里向优质解坍缩，\n    引力常数 G 随时间衰减 = 前期大步探索、后期精细收缩。\n\n    离散化映射（TSP 版）：\n      质量 M_i = 成本归一化后取 softmax 式权重（越优质量越大）；\n      引力移动 = 按质量轮盘选一个比自身优的天体 j，向 j 执行交换序列前缀，\n      前缀比例 = G(t) 缩放（衰减）+ step_cap 上限（防坍塌，GWO/DE 同款教训）；\n      惯性扰动 = 小概率随机交换（模拟速度残差）。\n    \"\"\"\n\n    name = \"引力搜索 GSA\"\n    default_params = {\n        \"n_agents\": 25,\n        \"G0\": 0.6,         # 初始引力常数（=移动步幅基数）\n        \"G_decay\": 0.97,   # G 衰减率\n        \"mutation\": 0.04,  # 惯性扰动概率\n        \"polish_p\": 0.3,   # 打磨概率：以小概率对候选做短 2-opt 试射（memetic GSA）\n        \"max_iter\": 200,\n        \"seed\": 42,\n        \"ls_every\": 10,\n        \"ls_moves\": 20,\n    }\n    implemented = True\n    category = \"物理启发\"\n    param_specs = {\n        \"n_agents\": {\"min\": 6, \"max\": 60, \"step\": 2, \"int\": True, \"label\": \"天体数\", \"desc\": \"种群规模（大实例自动降配）\"},\n        \"G0\": {\"min\": 0.1, \"max\": 1.0, \"step\": 0.05, \"label\": \"初始引力 G0\", \"desc\": \"移动步幅基数（向引力源执行的交换序列比例）\"},\n        \"G_decay\": {\"min\": 0.9, \"max\": 1.0, \"step\": 0.01, \"label\": \"引力衰减\", \"desc\": \"G(t)=G0·decay^t；越快收敛越早、探索越少\"},\n        \"mutation\": {\"min\": 0.0, \"max\": 0.2, \"step\": 0.01, \"label\": \"惯性扰动\", \"desc\": \"每个天体每代随机交换两城市的概率（速度残差的等价物）\"},\n        \"polish_p\": {\"min\": 0.0, \"max\": 0.5, \"step\": 0.05, \"label\": \"滑翔/打磨\", \"desc\": \"对当前位置直接做短 2-opt 试射的概率（memetic GSA 组件）\"},\n        \"ls_every\": {\"min\": 0, \"max\": 30, \"step\": 1, \"int\": True, \"label\": \"局部搜索周期\", \"desc\": \"每 N 代对全局最优做一次 2-opt 并回灌；0=关闭\"},\n        \"ls_moves\": {\"min\": 0, \"max\": 40, \"step\": 1, \"int\": True, \"label\": \"局部搜索预算\", \"desc\": \"每次局部搜索最多接受的 2-opt 移动数\"},\n    }\n\n    def solve(self, problem, params):\n        p = {**self.default_params, **(params or {})}\n        D = problem[\"D\"]\n        n = problem[\"n\"]\n        rng = random.Random(p[\"seed\"])\n\n        n_agents = p[\"n_agents\"]\n        if n > 80:\n            n_agents = max(10, n_agents // 2)\n        agents = [nearest_neighbor(D, start=0)]\n        for _ in range(n_agents - 1):\n            agents.append(nearest_neighbor(D, start=rng.randrange(n)))\n        agents = [_random_2opt_shot(t, D, rng, trials=50) for t in agents]\n        costs = [tour_length(t, D) for t in agents]\n        i0 = min(range(n_agents), key=lambda i: costs[i])\n        best, best_cost = list(agents[i0]), costs[i0]\n\n        for it in range(1, p[\"max_iter\"] + 1):\n            G = p[\"G0\"] * (p[\"G_decay\"] ** it)\n            # 质量 = 成本越低质量越大（min-max 归一化的经典式）\n            cmin, cmax = min(costs), max(costs)\n            span = max(cmax - cmin, 1e-9)\n            masses = [(cmax - c) / span + 0.05 for c in costs]\n            for i in range(n_agents):\n                # 引力源：从比 i 优的天体里按质量轮盘选一个（含全局最优）\n                attractors = [j for j in range(n_agents) if costs[j] < costs[i]]\n                if not attractors:\n                    # 最优天体（质量最大）：连续 GSA 里加速度 ∝ F/M，重天体受力\n                    # 最小但非零——给一点微量滑翔，否则它会被永久冻结（实测踩坑）\n                    if rng.random() < p[\"polish_p\"]:\n                        glide = _random_2opt_shot(agents[i], D, rng, 12)\n                        gc = tour_length(glide, D)\n                        if gc < costs[i]:\n                            agents[i], costs[i] = glide, gc\n                            if gc < best_cost:\n                                best, best_cost = list(glide), gc\n                    continue\n                j = _roulette(rng, [masses[j] for j in attractors])\n                seq = swap_seq_to_target(list(agents[i]), agents[attractors[j]])\n                k = int(len(seq) * min(0.5, G * (0.5 + rng.random())))\n                cand = apply_swaps(agents[i], seq[:k]) if k else list(agents[i])\n                if rng.random() < p[\"mutation\"]:\n                    a_, b_ = rng.randrange(n), rng.randrange(n)\n                    cand[a_], cand[b_] = cand[b_], cand[a_]\n                c = tour_length(cand, D)\n                if c < costs[i]:  # 引力只拉不推（排列域贪心选择）\n                    agents[i], costs[i] = cand, c\n                    if c < best_cost:\n                        best, best_cost = list(cand), c\n                # 惯性滑翔（memetic GSA）：直接对当前位置做短 2-opt 试射。\n                # ★打磨必须作用在当前解本体而非「移动后的候选」——前缀移动先\n                # 损伤解、再打磨只能修补损伤，永远回不到原点以下，贪心门槛\n                # 全拒 → 净改进为零（实测踩坑，同 MFO）。\n                if rng.random() < p[\"polish_p\"]:\n                    glide = _random_2opt_shot(agents[i], D, rng, 8)\n                    gc = tour_length(glide, D)\n                    if gc < costs[i]:\n                        agents[i], costs[i] = glide, gc\n                        if gc < best_cost:\n                            best, best_cost = list(glide), gc\n            if p[\"ls_every\"] > 0 and it % p[\"ls_every\"] == 0:\n                improved = two_opt_improve(best, D, max_moves=p[\"ls_moves\"])\n                c = tour_length(improved, D)\n                if c < best_cost:\n                    best, best_cost = improved, c\n                    worst = max(range(n_agents), key=lambda i: costs[i])\n                    agents[worst], costs[worst] = list(improved), c\n            yield IterationState(\n                it, best_cost, list(best), sum(costs) / n_agents,\n                {\"G\": round(G, 4), \"n_agents\": n_agents},\n            )\n\n\nclass TeachingLearning(BaseSolver):\n    \"\"\"教与学优化 TLBO（Rao, Savsani & Vakharia, 2011）：模拟课堂里的教与学。\n\n    引用量级：近万次，最大卖点是「无算法特定参数」——只有种群和代数，\n    没有需要调的系数（本实现额外保留了 memetic 钩子，可关）。\n    两阶段：教师阶段（全班向老师靠拢）+ 学习阶段（两两互学，优者带劣者）。\n\n    离散化映射（TSP 版）：\n      教师阶段：teacher = 当前最优；mean_diff = 学生与老师的交换序列前缀\n      （随机比例 = 「学了多少」，含学反了的情况——原式的 rand±1）；\n      学习阶段：随机配对，劣者向优者执行交换序列前缀或 OX 交叉；\n      两阶段都是贪心选择（新解更好才换）。\n    \"\"\"\n\n    name = \"教与学优化 TLBO\"\n    default_params = {\n        \"n_students\": 25,\n        \"learn_ox\": 0.4,   # 学习阶段用 OX 交叉的比例（其余用交换序列）\n        \"polish_p\": 0.3,   # 打磨概率（memetic TLBO；排列域上纯模仿对已抛光解无能为力）\n        \"max_iter\": 200,\n        \"seed\": 42,\n        \"ls_every\": 10,\n        \"ls_moves\": 20,\n    }\n    implemented = True\n    category = \"进化计算\"\n    param_specs = {\n        \"n_students\": {\"min\": 6, \"max\": 60, \"step\": 2, \"int\": True, \"label\": \"学生数\", \"desc\": \"班级规模（大实例自动降配）\"},\n        \"learn_ox\": {\"min\": 0.0, \"max\": 1.0, \"step\": 0.1, \"label\": \"OX 交叉比例\", \"desc\": \"学习阶段用 OX 交叉（重组）vs 交换序列（模仿）的比例\"},\n        \"polish_p\": {\"min\": 0.0, \"max\": 0.5, \"step\": 0.05, \"label\": \"打磨概率\", \"desc\": \"对每个新解做短 2-opt 试射的概率（memetic TLBO 组件）\"},\n        \"ls_every\": {\"min\": 0, \"max\": 30, \"step\": 1, \"int\": True, \"label\": \"局部搜索周期\", \"desc\": \"每 N 代对全局最优做一次 2-opt 并回灌；0=关闭\"},\n        \"ls_moves\": {\"min\": 0, \"max\": 40, \"step\": 1, \"int\": True, \"label\": \"局部搜索预算\", \"desc\": \"每次局部搜索最多接受的 2-opt 移动数\"},\n    }\n\n    def solve(self, problem, params):\n        p = {**self.default_params, **(params or {})}\n        D = problem[\"D\"]\n        n = problem[\"n\"]\n        rng = random.Random(p[\"seed\"])\n\n        n_s = p[\"n_students\"]\n        if n > 80:\n            n_s = max(10, n_s // 2)\n        cls = [nearest_neighbor(D, start=0)]\n        for _ in range(n_s - 1):\n            cls.append(nearest_neighbor(D, start=rng.randrange(n)))\n        cls = [_random_2opt_shot(t, D, rng, trials=50) for t in cls]\n        costs = [tour_length(t, D) for t in cls]\n        i0 = min(range(n_s), key=lambda i: costs[i])\n        best, best_cost = list(cls[i0]), costs[i0]\n\n        def try_replace(i, cand):\n            nonlocal best, best_cost\n            c = tour_length(cand, D)\n            if c < costs[i]:\n                cls[i], costs[i] = cand, c\n                if c < best_cost:\n                    best, best_cost = list(cand), c\n\n        for it in range(1, p[\"max_iter\"] + 1):\n            # 教师阶段：每个学生向 teacher 学（差异比例随机，可正可负）\n            teacher = min(range(n_s), key=lambda i: costs[i])\n            for i in range(n_s):\n                if i == teacher:\n                    continue\n                seq = swap_seq_to_target(list(cls[i]), cls[teacher])\n                ratio = rng.random() if rng.random() < 0.7 else rng.random() * 0.3\n                k = int(len(seq) * ratio)\n                cand = apply_swaps(cls[i], seq[:k]) if k else list(cls[i])\n                if rng.random() < p[\"polish_p\"]:\n                    cand = _random_2opt_shot(cand, D, rng, 8)\n                try_replace(i, cand)\n            # 学习阶段：随机配对，劣者向优者学\n            order = list(range(n_s))\n            rng.shuffle(order)\n            for a, b in zip(order[0::2], order[1::2]):\n                loser, winner = (a, b) if costs[a] > costs[b] else (b, a)\n                if rng.random() < p[\"learn_ox\"]:\n                    cand = _ox_crossover(cls[loser], cls[winner], rng)\n                else:\n                    seq = swap_seq_to_target(list(cls[loser]), cls[winner])\n                    k = int(len(seq) * rng.random())\n                    cand = apply_swaps(cls[loser], seq[:k]) if k else list(cls[loser])\n                if rng.random() < p[\"polish_p\"]:\n                    cand = _random_2opt_shot(cand, D, rng, 8)\n                try_replace(loser, cand)\n            if p[\"ls_every\"] > 0 and it % p[\"ls_every\"] == 0:\n                improved = two_opt_improve(best, D, max_moves=p[\"ls_moves\"])\n                c = tour_length(improved, D)\n                if c < best_cost:\n                    best, best_cost = improved, c\n                    worst = max(range(n_s), key=lambda i: costs[i])\n                    cls[worst], costs[worst] = list(improved), c\n            yield IterationState(\n                it, best_cost, list(best), sum(costs) / n_s,\n                {\"teacher_cost\": round(costs[teacher], 1), \"n_students\": n_s},\n            )\n\n\nclass BacterialForaging(BaseSolver):\n    \"\"\"细菌觅食优化 BFO（Passino, 2002）：趋向、繁殖、消散三循环。\n\n    引用量级：数千次，群智能早期经典。细菌在营养梯度上「翻滚/游动」：\n    方向好的就一直往前游（swim），方向差就换个方向（tumble）；\n    半数淘汰 + 复制好菌（繁殖）；偶尔整体迁移（消散散播）防早熟。\n\n    离散化映射（TSP 版）：\n      翻滚 = 小步 2-opt 试射（换方向）；游动 = 只要还在改进就沿同一算子连试\n      （最多 Ns 步，BFO 的标志性 swim）；繁殖 = 淘汰最差半数、复制最优半数；\n      消散 = 最差 ed 比例从 NN 重新播种。\n    \"\"\"\n\n    name = \"细菌觅食 BFO\"\n    default_params = {\n        \"n_bacteria\": 20,\n        \"swim_steps\": 4,   # 一次 chemotaxis 里最多连游几步\n        \"ed_prob\": 0.15,   # 消散概率（每代对最差个体）\n        \"max_iter\": 200,\n        \"seed\": 42,\n        \"ls_every\": 10,\n        \"ls_moves\": 20,\n    }\n    implemented = True\n    category = \"群体智能\"\n    param_specs = {\n        \"n_bacteria\": {\"min\": 6, \"max\": 50, \"step\": 2, \"int\": True, \"label\": \"细菌数\", \"desc\": \"种群规模（大实例自动降配）\"},\n        \"swim_steps\": {\"min\": 1, \"max\": 10, \"step\": 1, \"int\": True, \"label\": \"连游步数\", \"desc\": \"方向好时最多连游几步（swim 深度）\"},\n        \"ed_prob\": {\"min\": 0.0, \"max\": 0.5, \"step\": 0.05, \"label\": \"消散比例\", \"desc\": \"每代最差个体被随机迁移重播的概率\"},\n        \"ls_every\": {\"min\": 0, \"max\": 30, \"step\": 1, \"int\": True, \"label\": \"局部搜索周期\", \"desc\": \"每 N 代对全局最优做一次 2-opt 并回灌；0=关闭\"},\n        \"ls_moves\": {\"min\": 0, \"max\": 40, \"step\": 1, \"int\": True, \"label\": \"局部搜索预算\", \"desc\": \"每次局部搜索最多接受的 2-opt 移动数\"},\n    }\n\n    def solve(self, problem, params):\n        p = {**self.default_params, **(params or {})}\n        D = problem[\"D\"]\n        n = problem[\"n\"]\n        rng = random.Random(p[\"seed\"])\n\n        n_b = p[\"n_bacteria\"]\n        if n > 80:\n            n_b = max(10, n_b // 2)\n        pop = [nearest_neighbor(D, start=0)]\n        for _ in range(n_b - 1):\n            pop.append(nearest_neighbor(D, start=rng.randrange(n)))\n        pop = [_random_2opt_shot(t, D, rng, trials=50) for t in pop]\n        costs = [tour_length(t, D) for t in pop]\n        i0 = min(range(n_b), key=lambda i: costs[i])\n        best, best_cost = list(pop[i0]), costs[i0]\n\n        for it in range(1, p[\"max_iter\"] + 1):\n            # 趋向（chemotaxis）：翻滚 + 连游\n            for i in range(n_b):\n                cur = _random_2opt_shot(pop[i], D, rng, 8)  # 翻滚\n                cc = tour_length(cur, D)\n                if cc < costs[i]:\n                    pop[i], costs[i] = cur, cc\n                    # 游动：方向好就沿同方向（继续 2-opt 试射）连走\n                    for _ in range(p[\"swim_steps\"] - 1):\n                        nxt = _random_2opt_shot(pop[i], D, rng, 8)\n                        nc = tour_length(nxt, D)\n                        if nc < costs[i]:\n                            pop[i], costs[i] = nxt, nc\n                        else:\n                            break\n                    if costs[i] < best_cost:\n                        best, best_cost = list(pop[i]), costs[i]\n            # 繁殖（reproduction）：淘汰最差半数，复制最优半数\n            order = sorted(range(n_b), key=lambda i: costs[i])\n            half = n_b // 2\n            for rank in range(half):\n                src, dst = order[rank], order[-1 - rank]\n                if rank < half and costs[dst] > costs[src]:\n                    pop[dst], costs[dst] = list(pop[src]), costs[src]\n            # 消散（elimination-dispersal）：最差个体随机迁移\n            worst = max(range(n_b), key=lambda i: costs[i])\n            if rng.random() < p[\"ed_prob\"]:\n                fresh = nearest_neighbor(D, start=rng.randrange(n))\n                fresh = _random_2opt_shot(fresh, D, rng, 20)\n                pop[worst], costs[worst] = fresh, tour_length(fresh, D)\n            i_b = min(range(n_b), key=lambda i: costs[i])\n            if costs[i_b] < best_cost:\n                best, best_cost = list(pop[i_b]), costs[i_b]\n            if p[\"ls_every\"] > 0 and it % p[\"ls_every\"] == 0:\n                improved = two_opt_improve(best, D, max_moves=p[\"ls_moves\"])\n                c = tour_length(improved, D)\n                if c < best_cost:\n                    best, best_cost = improved, c\n                    worst = max(range(n_b), key=lambda i: costs[i])\n                    pop[worst], costs[worst] = list(improved), c\n            yield IterationState(\n                it, best_cost, list(best), sum(costs) / n_b,\n                {\"ed_prob\": p[\"ed_prob\"], \"n_bacteria\": n_b},\n            )\n\n\nclass MothFlame(BaseSolver):\n    \"\"\"蛾焰优化 MFO（Mirjalili, 2015）：飞蛾绕火焰螺旋飞行的优化算法。\n\n    引用量级：数千次，Mirjalili 系（GWO/WOA/SCA/MFO）的收官之作。\n    飞蛾 = 解；火焰 = 历史最优集合。飞蛾沿螺旋线绕火焰飞：\n    S(r) = |F−M|·e^(bt)·cos(2πt)，b=螺旋常数，t∈[−1,1]——\n    既可能靠近火焰（开发），也可能绕到另一侧（探索）。\n\n    离散化映射（TSP 版）：\n      螺旋 = 向火焰的交换序列按比例 r 执行前缀，比例由 e^(b·t)·|cos| 调制\n      （与 WOA 的螺旋收缩同款思想）；\n      焰数逐代递减 n → 1 = 探索到开发的全局收敛调度（MFO 标志）。\n    \"\"\"\n\n    name = \"蛾焰优化 MFO\"\n    default_params = {\n        \"n_moths\": 25,\n        \"b_spiral\": 1.0,   # 螺旋常数\n        \"polish_p\": 0.3,   # 打磨概率（memetic MFO；纯螺旋前缀对已抛光解无能为力）\n        \"max_iter\": 200,\n        \"seed\": 42,\n        \"ls_every\": 10,\n        \"ls_moves\": 20,\n    }\n    implemented = True\n    category = \"群体智能\"\n    param_specs = {\n        \"n_moths\": {\"min\": 6, \"max\": 60, \"step\": 2, \"int\": True, \"label\": \"飞蛾数\", \"desc\": \"种群规模（大实例自动降配）\"},\n        \"b_spiral\": {\"min\": 0.2, \"max\": 2.0, \"step\": 0.1, \"label\": \"螺旋常数 b\", \"desc\": \"越大绕火焰的弧线越弯（探索越强）\"},\n        \"polish_p\": {\"min\": 0.0, \"max\": 0.5, \"step\": 0.05, \"label\": \"滑翔/打磨\", \"desc\": \"对当前位置直接做短 2-opt 试射的概率（memetic MFO 组件）\"},\n        \"ls_every\": {\"min\": 0, \"max\": 30, \"step\": 1, \"int\": True, \"label\": \"局部搜索周期\", \"desc\": \"每 N 代对全局最优做一次 2-opt 并回灌；0=关闭\"},\n        \"ls_moves\": {\"min\": 0, \"max\": 40, \"step\": 1, \"int\": True, \"label\": \"局部搜索预算\", \"desc\": \"每次局部搜索最多接受的 2-opt 移动数\"},\n    }\n\n    def solve(self, problem, params):\n        p = {**self.default_params, **(params or {})}\n        D = problem[\"D\"]\n        n = problem[\"n\"]\n        rng = random.Random(p[\"seed\"])\n\n        n_m = p[\"n_moths\"]\n        if n > 80:\n            n_m = max(10, n_m // 2)\n        moths = [nearest_neighbor(D, start=0)]\n        for _ in range(n_m - 1):\n            moths.append(nearest_neighbor(D, start=rng.randrange(n)))\n        moths = [_random_2opt_shot(t, D, rng, trials=50) for t in moths]\n        mc = [tour_length(t, D) for t in moths]\n\n        # 初始火焰 = 初始种群排序\n        order = sorted(range(n_m), key=lambda i: mc[i])\n        flames = [list(moths[i]) for i in order]\n        fc = [mc[i] for i in order]\n        best, best_cost = list(flames[0]), fc[0]\n\n        for it in range(1, p[\"max_iter\"] + 1):\n            # 焰数递减：n → 1（MFO 的全局收敛调度）\n            n_flames = max(1, round(n_m - it * ((n_m - 1) / p[\"max_iter\"])))\n            b = p[\"b_spiral\"]\n            for i in range(n_m):\n                flame = flames[i % n_flames]\n                seq = swap_seq_to_target(list(moths[i]), flame)\n                if seq:\n                    # 螺旋调制：t∈[-1,1]，比例 = e^(b·t)·|cos(2πt)|，钳到 [0, 0.5]\n                    t_spiral = rng.uniform(-1.0, 1.0)\n                    ratio = min(0.5, max(0.02, pow(2.718281828, b * t_spiral) * abs(math.cos(2 * math.pi * t_spiral))))\n                    k = int(len(seq) * ratio)\n                    cand = apply_swaps(moths[i], seq[:k])\n                    c = tour_length(cand, D)\n                    if c < mc[i]:\n                        moths[i], mc[i] = cand, c\n                        if c < best_cost:\n                            best, best_cost = list(cand), c\n                # 螺旋滑翔（memetic MFO）：直接对当前位置做短 2-opt 试射。\n                # ★打磨必须作用在当前蛾本体而非「螺旋移动后的候选」——螺旋先\n                # 损伤解、再打磨只能修补损伤，回不到原点以下，贪心门槛全拒 →\n                # 净改进为零（实测踩坑，同 GSA）。\n                if rng.random() < p[\"polish_p\"]:\n                    glide = _random_2opt_shot(moths[i], D, rng, 8)\n                    gc = tour_length(glide, D)\n                    if gc < mc[i]:\n                        moths[i], mc[i] = glide, gc\n                        if gc < best_cost:\n                            best, best_cost = list(glide), gc\n            # 更新火焰：蛾+焰合并取前 n_flames 名（MFO 原文做法）\n            pool = [(list(moths[i]), mc[i]) for i in range(n_m)] + list(zip(flames, fc))\n            pool.sort(key=lambda x: x[1])\n            flames = [list(t) for t, _ in pool[:n_flames]]\n            fc = [c for _, c in pool[:n_flames]]\n            if fc[0] < best_cost:\n                best, best_cost = list(flames[0]), fc[0]\n            if p[\"ls_every\"] > 0 and it % p[\"ls_every\"] == 0:\n                improved = two_opt_improve(best, D, max_moves=p[\"ls_moves\"])\n                c = tour_length(improved, D)\n                if c < best_cost:\n                    best, best_cost = improved, c\n                    if n_flames > 1:\n                        flames[-1], fc[-1] = list(improved), c\n            yield IterationState(\n                it, best_cost, list(best), sum(mc) / n_m,\n                {\"n_flames\": n_flames, \"n_moths\": n_m},\n            )\n\n\nclass Fireworks(BaseSolver):\n    \"\"\"烟花算法 FWA（Tan & Zhu, 2010）：烟花爆炸产生火花，好烟花炸得密、差烟花炸得广。\n\n    引用量级：数千次（原版 FWA + 增强版 FWA 全家）。它的调度思想在种群算法里独一份：\n      ① 火花数量 ∝ 适应度——好烟花炸出的火花多（在好解附近深耕），\n         爆炸幅度 ∝ (1-适应度)——差烟花炸得范围大（在远处勘探）\n      ② 高斯火花：在最优烟花附近用高斯扰动再炸一发（精细开发）\n      ③ 选择：最优烟花保送 + 其余按\"与已有解的距离\"保持多样性\n\n    离散化映射（TSP 版）：\n      爆炸 = 对烟花做 A_i 次随机突变（片段逆转/两点交换），A_i 越大炸得越远；\n      高斯火花 = 对全局最优做短 2-opt 试射（连续域高斯扰动的排列域等价物）；\n      数量/幅度调度 = 原文的线性归一化公式原样保留。\n    教训（FA/GSA 同款）：纯随机突变对已抛光的解几乎必然变差，火花按贪心准入，\n    真实下降由高斯火花（2-opt 试射）驱动——这是 memetic FWA 的标准做法。\n    \"\"\"\n\n    name = \"烟花算法 FWA\"\n    default_params = {\n        \"n_fireworks\": 10,\n        \"base_sparks\": 16,  # 每代火花总数基数\n        \"max_amp\": 6,       # 最大爆炸幅度（突变次数上限）\n        \"max_iter\": 200,\n        \"seed\": 42,\n        \"ls_every\": 10,\n        \"ls_moves\": 20,\n    }\n    implemented = True\n    category = \"群体智能\"\n    param_specs = {\n        \"n_fireworks\": {\"min\": 4, \"max\": 30, \"step\": 2, \"int\": True, \"label\": \"烟花数\", \"desc\": \"种群规模（大实例自动降配）\"},\n        \"base_sparks\": {\"min\": 6, \"max\": 40, \"step\": 2, \"int\": True, \"label\": \"火花基数\", \"desc\": \"每代炸出的火花总数基准（按适应度分配给各烟花）\"},\n        \"max_amp\": {\"min\": 1, \"max\": 12, \"step\": 1, \"int\": True, \"label\": \"最大爆炸幅度\", \"desc\": \"单个火花最多做几次突变；越大勘探越远\"},\n        \"ls_every\": {\"min\": 0, \"max\": 30, \"step\": 1, \"int\": True, \"label\": \"局部搜索周期\", \"desc\": \"每 N 代对全局最优做一次 2-opt 并回灌；0=关闭\"},\n        \"ls_moves\": {\"min\": 0, \"max\": 40, \"step\": 1, \"int\": True, \"label\": \"局部搜索预算\", \"desc\": \"每次局部搜索最多接受的 2-opt 移动数\"},\n    }\n\n    def _mutate(self, tour: List[int], rng) -> List[int]:\n        t = list(tour)\n        n = len(t)\n        if rng.random() < 0.5:\n            a, b = sorted(rng.sample(range(n), 2))\n            t[a : b + 1] = reversed(t[a : b + 1])\n        else:\n            i, j = rng.randrange(n), rng.randrange(n)\n            t[i], t[j] = t[j], t[i]\n        return t\n\n    def solve(self, problem, params):\n        p = {**self.default_params, **(params or {})}\n        D = problem[\"D\"]\n        n = problem[\"n\"]\n        rng = random.Random(p[\"seed\"])\n\n        n_fw = p[\"n_fireworks\"]\n        if n > 80:\n            n_fw = max(5, n_fw // 2)\n        fws = [nearest_neighbor(D, start=0)]\n        for _ in range(n_fw - 1):\n            fws.append(nearest_neighbor(D, start=rng.randrange(n)))\n        fws = [_random_2opt_shot(t, D, rng, trials=50) for t in fws]\n        fc = [tour_length(t, D) for t in fws]\n        bi = min(range(n_fw), key=lambda i: fc[i])\n        best, best_cost = list(fws[bi]), fc[bi]\n\n        eps = 1e-9\n        for it in range(1, p[\"max_iter\"] + 1):\n            worst, total_gap = max(fc), 0.0\n            for c in fc:\n                total_gap += worst - c\n            total_gap += eps\n            n_eval = 0\n            # ① 常规爆炸：好烟花分到的火花多，差烟花的幅度大（FWA 原文调度）\n            for i in range(n_fw):\n                n_sp = max(1, int(p[\"base_sparks\"] * (worst - fc[i] + eps) / total_gap))\n                amp = max(1, int(round(p[\"max_amp\"] * (fc[i] - best_cost + eps) / (sum(c - best_cost for c in fc) + eps))))\n                amp = max(1, min(amp, p[\"max_amp\"]))\n                for _ in range(n_sp):\n                    cand = list(fws[i])\n                    for _ in range(amp):\n                        cand = self._mutate(cand, rng)\n                    c = tour_length(cand, D)\n                    n_eval += 1\n                    if c < fc[i]:  # 火花贪心准入（memetic FWA 标准做法）\n                        fws[i], fc[i] = cand, c\n                        if c < best_cost:\n                            best, best_cost = list(cand), c\n            # ② 高斯火花：对全局最优做短 2-opt 试射（开发主力，真实下降来源）\n            for _ in range(2):\n                cand = _random_2opt_shot(best, D, rng, trials=8)\n                c = tour_length(cand, D)\n                n_eval += 1\n                if c < best_cost:\n                    best, best_cost = cand, c\n            # ③ 多样性保底：最差烟花偶尔被最佳火花替换（防全员坍缩到 best）\n            worst_i = max(range(n_fw), key=lambda i: fc[i])\n            if fc[worst_i] > best_cost * 1.35:\n                fws[worst_i], fc[worst_i] = list(best), best_cost\n\n            if p[\"ls_every\"] > 0 and it % p[\"ls_every\"] == 0:\n                improved = two_opt_improve(best, D, max_moves=p[\"ls_moves\"])\n                c = tour_length(improved, D)\n                if c < best_cost:\n                    best, best_cost = improved, c\n                    fws[worst_i], fc[worst_i] = list(improved), c\n\n            yield IterationState(\n                it, best_cost, list(best), sum(fc) / n_fw,\n                {\"sparks\": n_eval, \"n_fw\": n_fw},\n            )\n\n\nclass ArtificialFishSwarm(BaseSolver):\n    \"\"\"人工鱼群 AFSA（李晓磊, 2002）：觅食/聚群/追尾/随机四种行为按环境切换。\n\n    引用量级：数千次（国内群智能领域引用最高的原创算法之一）。\n    每条鱼每代根据视野内环境选行为：\n      觅食 AF_PREY：试 try_n 次随机邻域移动，找到更优就过去——搜索主力\n      追尾 AF_FOLLOW：视野内有更优的鱼且不拥挤 → 向它移动——信息共享\n      聚群 AF_SWARM：视野内同伴不拥挤 → 向伙伴靠拢——抱团防迷路\n      随机 AF_RANDOM：没鱼理自己时随便游动——保底勘探\n    拥挤度因子 δ 是 AFSA 的招牌参数：同一片水域鱼太多就放弃跟进，防止全员挤到一个局部谷。\n\n    离散化映射（TSP 版）：\n      邻域 = 片段逆转 / 两点交换；\"向某鱼移动\" = 交换序列前缀（步幅有上限）；\n      视野 = 随机抽 visual_k 条同伴（排列域没有几何邻域，用抽样近似）。\n    \"\"\"\n\n    name = \"人工鱼群 AFSA\"\n    default_params = {\n        \"n_fish\": 24,\n        \"try_n\": 5,       # 觅食行为每次的尝试次数\n        \"visual_k\": 6,    # 视野：每代随机抽多少条同伴观察\n        \"crowd\": 0.6,     # 拥挤度因子 δ：视野内更优鱼占比超过它就放弃跟进\n        \"step_cap\": 0.4,  # 追尾/聚群的移动步幅上限（防坍塌，GWO 教训）\n        \"max_iter\": 200,\n        \"seed\": 42,\n        \"ls_every\": 10,\n        \"ls_moves\": 20,\n    }\n    implemented = True\n    category = \"群体智能\"\n    param_specs = {\n        \"n_fish\": {\"min\": 6, \"max\": 60, \"step\": 2, \"int\": True, \"label\": \"鱼群规模\", \"desc\": \"种群大小（大实例自动降配）\"},\n        \"try_n\": {\"min\": 1, \"max\": 15, \"step\": 1, \"int\": True, \"label\": \"觅食尝试\", \"desc\": \"觅食行为每代尝试的邻域移动次数；太小勘探不足\"},\n        \"visual_k\": {\"min\": 2, \"max\": 20, \"step\": 1, \"int\": True, \"label\": \"视野宽度\", \"desc\": \"每代随机观察的同伴数\"},\n        \"crowd\": {\"min\": 0.1, \"max\": 1.0, \"step\": 0.05, \"label\": \"拥挤度因子 δ\", \"desc\": \"视野内更优鱼占比超过 δ 就放弃追尾/聚群；越小越怕挤\"},\n        \"step_cap\": {\"min\": 0.1, \"max\": 0.6, \"step\": 0.05, \"label\": \"步幅上限\", \"desc\": \"向同伴移动时执行交换序列前缀的最大比例\"},\n        \"ls_every\": {\"min\": 0, \"max\": 30, \"step\": 1, \"int\": True, \"label\": \"局部搜索周期\", \"desc\": \"每 N 代对全局最优做一次 2-opt 并回灌；0=关闭\"},\n        \"ls_moves\": {\"min\": 0, \"max\": 40, \"step\": 1, \"int\": True, \"label\": \"局部搜索预算\", \"desc\": \"每次局部搜索最多接受的 2-opt 移动数\"},\n    }\n\n    def _prey(self, tour: List[int], D, rng, p) -> List[int]:\n        \"\"\"觅食：最多 try_n 次邻域试移，返回第一个更优的，否则原地不动。\"\"\"\n        cur = tour_length(tour, D)\n        for _ in range(p[\"try_n\"]):\n            t = list(tour)\n            n = len(t)\n            if rng.random() < 0.5:\n                a, b = sorted(rng.sample(range(n), 2))\n                t[a : b + 1] = reversed(t[a : b + 1])\n            else:\n                i, j = rng.randrange(n), rng.randrange(n)\n                t[i], t[j] = t[j], t[i]\n            if tour_length(t, D) < cur:\n                return t\n        return list(tour)\n\n    def solve(self, problem, params):\n        p = {**self.default_params, **(params or {})}\n        D = problem[\"D\"]\n        n = problem[\"n\"]\n        rng = random.Random(p[\"seed\"])\n\n        n_f = p[\"n_fish\"]\n        if n > 80:\n            n_f = max(10, n_f // 2)\n        fish = [nearest_neighbor(D, start=0)]\n        for _ in range(n_f - 1):\n            fish.append(nearest_neighbor(D, start=rng.randrange(n)))\n        fish = [_random_2opt_shot(t, D, rng, trials=50) for t in fish]\n        fc = [tour_length(t, D) for t in fish]\n        bi = min(range(n_f), key=lambda i: fc[i])\n        best, best_cost = list(fish[bi]), fc[bi]\n\n        follows = swarms = 0\n        for it in range(1, p[\"max_iter\"] + 1):\n            for i in range(n_f):\n                # 视野：随机抽 visual_k 条同伴\n                peers = rng.sample([j for j in range(n_f) if j != i],\n                                   min(p[\"visual_k\"], n_f - 1))\n                better = [j for j in peers if fc[j] < fc[i]]\n                moved = False\n                # 追尾/聚群：视野内有更优鱼且不拥挤 → 向最优的那条移动\n                if better:\n                    j = min(better, key=lambda x: fc[x])\n                    crowd_ratio = sum(1 for k in peers if fc[k] < fc[i] * 1.05) / len(peers)\n                    if crowd_ratio < p[\"crowd\"]:\n                        seq = swap_seq_to_target(list(fish[i]), fish[j])\n                        if seq:\n                            k = max(1, int(len(seq) * min(p[\"step_cap\"], rng.random())))\n                            cand = apply_swaps(fish[i], seq[:k])\n                            c = tour_length(cand, D)\n                            if c < fc[i]:\n                                fish[i], fc[i] = cand, c\n                                moved = True\n                                follows += 1\n                # 觅食：追尾没成或没目标时搜索（AFSA 的真实驱动力）\n                if not moved:\n                    cand = self._prey(fish[i], D, rng, p)\n                    c = tour_length(cand, D)\n                    if c < fc[i]:\n                        fish[i], fc[i] = cand, c\n                else:\n                    swarms += 1\n\n            bi = min(range(n_f), key=lambda i: fc[i])\n            if fc[bi] < best_cost:\n                best, best_cost = list(fish[bi]), fc[bi]\n\n            if p[\"ls_every\"] > 0 and it % p[\"ls_every\"] == 0:\n                improved = two_opt_improve(best, D, max_moves=p[\"ls_moves\"])\n                c = tour_length(improved, D)\n                if c < best_cost:\n                    best, best_cost = improved, c\n                    worst = max(range(n_f), key=lambda i: fc[i])\n                    fish[worst], fc[worst] = list(improved), c\n\n            yield IterationState(\n                it, best_cost, list(best), sum(fc) / n_f,\n                {\"follows\": follows, \"swarms\": swarms, \"n_fish\": n_f},\n            )\n\n\nclass CrossEntropy(BaseSolver):\n    \"\"\"交叉熵方法 CEM（Rubinstein, 1997）：从分布采样 → 留精英 → 更新分布。\n\n    引用量级：数万次（随机优化/稀有事件模拟的奠基作之一）。\n    它和所有\"个体交互\"算法根本不同：鱼、狼、粒子互相模仿，\n    CEM 的种群之间**零交互**——个体只是从分布 P 里抽出来的样本，\n    选择压力通过\"精英样本的统计量回写分布\"传递。这就是 EDA\n    （分布估计算法）家族的源头思想。\n\n    离散化映射（TSP 版）：\n      分布 = P[d][c]：位置 d 出现城市 c 的概率矩阵（n×n）；\n      采样 = 逐位置按 P 轮盘抽不重复城市，生成一条排列；\n      更新 = 统计精英样本的频率 F，P ← λ·P + (1-λ)·F（平滑系数 λ 防分布塌缩）。\n    混合组件：对精英做短 2-opt 试射再回写频率（memetic EDA，\n    纯采样从抛光的 NN 播种上几乎抽不出更优——GSA 教训的 EDA 版）。\n    \"\"\"\n\n    name = \"交叉熵 CEM\"\n    default_params = {\n        \"n_pop\": 30,\n        \"rho\": 0.3,        # 精英比例（前 30% 进入频率统计）\n        \"lam\": 0.7,        # 平滑系数 λ：P = λ·P + (1-λ)·F，1=不变 0=全信样本\n        \"polish_p\": 0.3,   # 精英打磨概率（memetic EDA 组件）\n        \"max_iter\": 200,\n        \"seed\": 42,\n        \"ls_every\": 10,\n        \"ls_moves\": 20,\n    }\n    implemented = True\n    category = \"进化计算\"\n    param_specs = {\n        \"n_pop\": {\"min\": 10, \"max\": 80, \"step\": 2, \"int\": True, \"label\": \"样本数\", \"desc\": \"每代从分布抽样的解数量（大实例自动降配）\"},\n        \"rho\": {\"min\": 0.05, \"max\": 0.5, \"step\": 0.05, \"label\": \"精英比例 ρ\", \"desc\": \"前百分之多少的样本算精英；太小学得太快易早熟\"},\n        \"lam\": {\"min\": 0.3, \"max\": 0.95, \"step\": 0.05, \"label\": \"平滑系数 λ\", \"desc\": \"分布更新保留旧分布的比例；越大收敛越稳越慢\"},\n        \"polish_p\": {\"min\": 0.0, \"max\": 0.5, \"step\": 0.05, \"label\": \"精英打磨\", \"desc\": \"对精英样本做短 2-opt 试射再回写分布的概率\"},\n        \"ls_every\": {\"min\": 0, \"max\": 30, \"step\": 1, \"int\": True, \"label\": \"局部搜索周期\", \"desc\": \"每 N 代对全局最优做一次 2-opt 并回灌；0=关闭\"},\n        \"ls_moves\": {\"min\": 0, \"max\": 40, \"step\": 1, \"int\": True, \"label\": \"局部搜索预算\", \"desc\": \"每次局部搜索最多接受的 2-opt 移动数\"},\n    }\n\n    def _sample(self, P, n, rng) -> List[int]:\n        \"\"\"按概率矩阵逐位置抽不重复城市（经典 EDA 采样）。\"\"\"\n        tour = []\n        for d in range(n):\n            avail = [c for c in range(n) if c not in tour]\n            w = [P[d][c] for c in avail]\n            s = sum(w)\n            if s <= 0:\n                tour.append(rng.choice(avail))\n                continue\n            r = rng.random() * s\n            acc = 0.0\n            for idx, c in enumerate(avail):\n                acc += w[idx]\n                if r <= acc:\n                    tour.append(c)\n                    break\n            else:\n                tour.append(avail[-1])\n        return tour\n\n    def solve(self, problem, params):\n        p = {**self.default_params, **(params or {})}\n        D = problem[\"D\"]\n        n = problem[\"n\"]\n        rng = random.Random(p[\"seed\"])\n\n        n_pop = p[\"n_pop\"]\n        if n > 80:\n            n_pop = max(15, n_pop // 2)\n        # 分布初始化：均匀 + NN 多起点精英偏置（纯均匀起步收敛太慢）\n        P = [[1.0 / n] * n for _ in range(n)]\n        elites0 = [nearest_neighbor(D, start=rng.randrange(n)) for _ in range(10)]\n        elites0 = [_random_2opt_shot(t, D, rng, trials=40) for t in elites0]\n        lam, rho = p[\"lam\"], p[\"rho\"]\n\n        best, best_cost = None, float(\"inf\")\n        for t in elites0:\n            c = tour_length(t, D)\n            if c < best_cost:\n                best, best_cost = list(t), c\n\n        for it in range(1, p[\"max_iter\"] + 1):\n            pop = [self._sample(P, n, rng) for _ in range(n_pop)]\n            costs = [tour_length(t, D) for t in pop]\n            # 精英 = 本代前 ρ 样本 + 历史最优（CEM 的标准加持：保优）\n            order = sorted(range(n_pop), key=lambda i: costs[i])\n            k_e = max(2, int(n_pop * rho))\n            elite = [(pop[i], costs[i]) for i in order[:k_e]] + [(best, best_cost)]\n            # 精英打磨（memetic EDA）：抛光后再回写分布，分布才能学到好结构\n            pol = []\n            for t, c in elite:\n                if rng.random() < p[\"polish_p\"]:\n                    t2 = _random_2opt_shot(t, D, rng, 8)\n                    c2 = tour_length(t2, D)\n                    if c2 < c:\n                        t, c = t2, c2\n                pol.append((t, c))\n                if c < best_cost:\n                    best, best_cost = list(t), c\n            # 频率统计 → 分布更新\n            F = [[0.0] * n for _ in range(n)]\n            for t, _ in pol:\n                for d in range(n):\n                    F[d][t[d]] += 1.0 / len(pol)\n            for d in range(n):\n                for c in range(n):\n                    P[d][c] = lam * P[d][c] + (1 - lam) * F[d][c]\n\n            if p[\"ls_every\"] > 0 and it % p[\"ls_every\"] == 0:\n                improved = two_opt_improve(best, D, max_moves=p[\"ls_moves\"])\n                c = tour_length(improved, D)\n                if c < best_cost:\n                    best, best_cost = improved, c\n\n            cur = sum(costs) / n_pop\n            yield IterationState(\n                it, best_cost, list(best), cur,\n                {\"n_pop\": n_pop, \"elite\": k_e},\n            )\n\n\n\nclass SparrowSearch(BaseSolver):\n    \"\"\"麻雀搜索算法 SSA（Xue & Shen, 2020）：发现者/加入者/警戒者三角色。\n\n    引用量级：数千次且近年暴涨（2020 年后引用增长最快的新算法之一）。\n    麻雀群觅食时角色分工：\n      发现者 PD（前 pd_ratio）：负责找食物源。本代警戒值 R2 < ST（安全）→ 大步勘探；\n        R2 ≥ ST（有天敌）→ 放弃远处觅食，收缩到安全区（向全局最优回撤）\n      加入者 SD（其余）：跟着发现者蹭吃的——向全局最优执行交换前缀（步幅有上限）\n      警戒者（加入者里随机抽 sd_ratio 名）：感知危险。80% 概率小步试移；20%（真危险）\n        → 远跳（短 2-opt 试射，排列域的\"飞离危险区\"）\n    招牌机制：警戒值 R2 每代重新抽签——全群在\"安心觅食\"和\"警觉回撤\"之间切换，\n    这就是 SSA 的勘探/开发调度器。\n\n    离散化映射（TSP 版）：\n      大步勘探 = 连续多次片段逆转/两点交换（幅度随城市数缩放）；\n      收缩到安全区 / 加入者跟随 = 交换序列前缀（步幅上限，GWO 教训）；\n      警戒远跳 = 对全局最优本体做\"结构性扰动 + 预算制 2-opt 下探\"（ILS 同款）——\n      本算法三次踩坑换来的教训：贪心准入 + 随机试射在已收敛种群上全是假跑，\n      详见 solve() 内注释。\n    \"\"\"\n\n    name = \"麻雀搜索 SSA\"\n    default_params = {\n        \"n_pop\": 30,\n        \"pd_ratio\": 0.2,  # 发现者占比\n        \"sd_ratio\": 0.1,  # 警戒者占比（从加入者中抽）\n        \"st\": 0.8,        # 安全阈值 ST：警戒值 R2 < ST 视为环境安全\n        \"step_cap\": 0.4,  # 加入者跟随步幅上限\n        \"max_iter\": 200,\n        \"seed\": 42,\n        \"ls_every\": 10,\n        \"ls_moves\": 20,\n    }\n    implemented = True\n    category = \"群体智能\"\n    param_specs = {\n        \"n_pop\": {\"min\": 10, \"max\": 60, \"step\": 2, \"int\": True, \"label\": \"麻雀数\", \"desc\": \"种群规模（大实例自动降配）\"},\n        \"pd_ratio\": {\"min\": 0.1, \"max\": 0.4, \"step\": 0.05, \"label\": \"发现者占比\", \"desc\": \"前 PD 的麻雀负责勘探觅食；原文建议 0.2\"},\n        \"sd_ratio\": {\"min\": 0.05, \"max\": 0.3, \"step\": 0.05, \"label\": \"警戒者占比\", \"desc\": \"从加入者中随机抽取负责警戒的个体\"},\n        \"st\": {\"min\": 0.5, \"max\": 0.95, \"step\": 0.05, \"label\": \"安全阈值 ST\", \"desc\": \"警戒值 R2 < ST 时全群安心觅食，否则收缩回撤；越大越少恐慌\"},\n        \"step_cap\": {\"min\": 0.1, \"max\": 0.6, \"step\": 0.05, \"label\": \"跟随步幅上限\", \"desc\": \"加入者向全局最优移动的交换前缀最大比例\"},\n        \"ls_every\": {\"min\": 0, \"max\": 30, \"step\": 1, \"int\": True, \"label\": \"局部搜索周期\", \"desc\": \"每 N 代对全局最优做一次 2-opt 并回灌；0=关闭\"},\n        \"ls_moves\": {\"min\": 0, \"max\": 40, \"step\": 1, \"int\": True, \"label\": \"局部搜索预算\", \"desc\": \"每次局部搜索最多接受的 2-opt 移动数\"},\n    }\n\n    def _mutate(self, tour: List[int], rng, amp: int) -> List[int]:\n        t = list(tour)\n        n = len(t)\n        for _ in range(max(1, amp)):\n            if rng.random() < 0.5:\n                a, b = sorted(rng.sample(range(n), 2))\n                t[a : b + 1] = reversed(t[a : b + 1])\n            else:\n                i, j = rng.randrange(n), rng.randrange(n)\n                t[i], t[j] = t[j], t[i]\n        return t\n\n    def solve(self, problem, params):\n        p = {**self.default_params, **(params or {})}\n        D = problem[\"D\"]\n        n = problem[\"n\"]\n        rng = random.Random(p[\"seed\"])\n\n        n_p = p[\"n_pop\"]\n        if n > 80:\n            n_p = max(12, n_p // 2)\n        pd = max(2, int(n_p * p[\"pd_ratio\"]))\n        sd = max(1, int(n_p * p[\"sd_ratio\"]))\n\n        pop = [nearest_neighbor(D, start=0)]\n        for _ in range(n_p - 1):\n            pop.append(nearest_neighbor(D, start=rng.randrange(n)))\n        pop = [_random_2opt_shot(t, D, rng, trials=50) for t in pop]\n        pc = [tour_length(t, D) for t in pop]\n        bi = min(range(n_p), key=lambda i: pc[i])\n        best, best_cost = list(pop[bi]), pc[bi]\n\n        amp_big = max(2, min(6, int(n * 0.06)))\n        for it in range(1, p[\"max_iter\"] + 1):\n            r2 = rng.random()  # 本代警戒值：SSA 的勘探/开发调度器\n            # ① 发现者：安全 → 大步勘探；有天敌 → 向全局最优回撤\n            for i in range(pd):\n                if r2 < p[\"st\"]:\n                    # 勘探 = 大步突变跳出当前盆地 + 就地打磨降到新盆底（memetic 标准）。\n                    # 关键离散化决策（两次踩坑换来的）：\n                    #   ① 纯突变几乎必然变差、全被拒 → 200 代零进步假跑（GSA 同源教训）；\n                    #   ② 突变+打磨再叠贪心准入也不行——种群一旦收敛到 best 的 2-opt\n                    #      局部最优，所有提议候选都更差，准入全拒照样假跑。\n                    #   解法：忠实还原原文语义——发现者公式本无选择步骤（连续域每代\n                    #   无条件移动），安全时无条件接受新盆地（允许暂时变差），\n                    #   危险时才贪心回撤。R2 调度由此获得真实含义：安全=发散勘探，\n                    #   危险=收敛回撤，全局 best 单独跟踪、只降不升。\n                    cand = _random_2opt_shot(self._mutate(pop[i], rng, amp_big), D, rng, trials=8)\n                    pop[i], pc[i] = cand, tour_length(cand, D)\n                else:\n                    seq = swap_seq_to_target(list(pop[i]), best)\n                    k = max(1, int(len(seq) * 0.3 * rng.random()))\n                    cand = apply_swaps(pop[i], seq[:k]) if seq else list(pop[i])\n                c = tour_length(cand, D)\n                if c < pc[i]:\n                    pop[i], pc[i] = cand, c\n            bi = min(range(pd), key=lambda i: pc[i])\n            if pc[bi] < best_cost:\n                best, best_cost = list(pop[bi]), pc[bi]\n            # ② 加入者：跟随全局最优（部分靠近，防坍塌）\n            for i in range(pd, n_p):\n                seq = swap_seq_to_target(list(pop[i]), best)\n                if seq:\n                    k = max(1, int(len(seq) * min(p[\"step_cap\"], rng.random())))\n                    cand = apply_swaps(pop[i], seq[:k])\n                    c = tour_length(cand, D)\n                    if c < pc[i]:\n                        pop[i], pc[i] = cand, c\n            # ③ 警戒者：小步试移；真危险（20%）→ 远跳\n            for i in rng.sample(range(pd, n_p), min(sd, n_p - pd)):\n                if rng.random() < 0.8:\n                    cand = self._mutate(pop[i], rng, 1)\n                else:\n                    cand = _random_2opt_shot(pop[i], D, rng, trials=6)\n                c = tour_length(cand, D)\n                if c < pc[i]:\n                    pop[i], pc[i] = cand, c\n            # ④ 警戒远跳（每代一次）：对全局最优本体做 mini-ILS——扰动 2 步跳出\n            # 局部最优 + 预算制 2-opt 下探（ILS 同款下探算子，不是随机试射）。\n            # 踩坑记录：只对个体做\"接受改进\"的试射在 2-opt 局部最优上永远扑空；\n            # 随机试射（_random_2opt_shot）的 8 次探针也探不动真局部最优——\n            # 盆地跳跃必须\"结构性扰动 + 系统性下探\"组合、直接作用于当前解本体\n            # （GSA/CEM 同源教训，FWA 高斯火花升级版）。\n            cand = two_opt_improve(self._mutate(best, rng, 2), D, max_moves=10)\n            c = tour_length(cand, D)\n            if c < best_cost:\n                best, best_cost = cand, c\n                w = max(range(n_p), key=lambda i: pc[i])\n                pop[w], pc[w] = list(cand), c\n\n            bi = min(range(n_p), key=lambda i: pc[i])\n            if pc[bi] < best_cost:\n                best, best_cost = list(pop[bi]), pc[bi]\n\n            if p[\"ls_every\"] > 0 and it % p[\"ls_every\"] == 0:\n                improved = two_opt_improve(best, D, max_moves=p[\"ls_moves\"])\n                c = tour_length(improved, D)\n                if c < best_cost:\n                    best, best_cost = improved, c\n                    w = max(range(n_p), key=lambda i: pc[i])\n                    pop[w], pc[w] = list(improved), c\n\n            yield IterationState(\n                it, best_cost, list(best), sum(pc) / n_p,\n                {\"alarm\": round(r2, 3), \"n_producer\": pd, \"n_scout\": sd},\n            )\n\n\nclass AntLion(BaseSolver):\n    \"\"\"蚁狮优化 ALO（Mirjalili, 2015）：蚂蚁随机游走，蚁狮的坑随迭代收缩。\n\n    引用量级：数千次（Mirjalili 系补全）。\n    隐喻：蚂蚁在沙地上游走，蚁狮在坑底等它跌落。三件套：\n      ① 轮盘选坑：蚂蚁按适应度挑一个坑（坑越深=成本越低越可能被选中）\n      ② 随机游走：围着坑主 + 围着精英各走一段，端点取较优\n      ③ 陷阱收缩：坑的半径随迭代线性收缩——前期步幅大（勘探），后期步幅小（开发）\n      蚂蚁走到比坑主更好的位置 → 被吃掉，蚁狮前移到该位置。\n\n    离散化映射（TSP 版）：\n      游走一步 = 向坑主/精英执行一小段交换前缀（被坑壁滑向中心）或随机突变；\n      踩坑记录：纯随机游走的端点对已抛光的解几乎必然变差（GSA/CEM 同源教训），\n      本实现采用贪心游走——每步仅在更优时保留，收缩调度与双坑结构原样保留。\n    \"\"\"\n\n    name = \"蚁狮优化 ALO\"\n    default_params = {\n        \"n_pop\": 25,\n        \"walk_base\": 10,  # 初始游走步数（坑最深处）\n        \"step_cap\": 0.3,  # 单步交换前缀比例上限\n        \"max_iter\": 200,\n        \"seed\": 42,\n        \"ls_every\": 10,\n        \"ls_moves\": 20,\n    }\n    implemented = True\n    category = \"群体智能\"\n    param_specs = {\n        \"n_pop\": {\"min\": 8, \"max\": 60, \"step\": 2, \"int\": True, \"label\": \"蚂蚁/蚁狮数\", \"desc\": \"蚂蚁与蚁狮一一配对（大实例自动降配）\"},\n        \"walk_base\": {\"min\": 2, \"max\": 25, \"step\": 1, \"int\": True, \"label\": \"初始游走步数\", \"desc\": \"坑最深时一段游走走几步；随迭代线性收缩到 1\"},\n        \"step_cap\": {\"min\": 0.1, \"max\": 0.6, \"step\": 0.05, \"label\": \"单步步幅上限\", \"desc\": \"游走中被坑壁滑向中心时交换前缀的最大比例\"},\n        \"ls_every\": {\"min\": 0, \"max\": 30, \"step\": 1, \"int\": True, \"label\": \"局部搜索周期\", \"desc\": \"每 N 代对全局最优做一次 2-opt 并回灌；0=关闭\"},\n        \"ls_moves\": {\"min\": 0, \"max\": 40, \"step\": 1, \"int\": True, \"label\": \"局部搜索预算\", \"desc\": \"每次局部搜索最多接受的 2-opt 移动数\"},\n    }\n\n    def _walk(self, start_tour: List[int], target: List[int], D, rng, steps: int, step_cap: float) -> List[int]:\n        \"\"\"贪心游走：从 start 出发走 steps 步，每步以 step_cap 概率被坑壁滑向 target\n        （执行一小段交换前缀），否则随机扰动；仅在更优时保留（排列域的贪心游走）。\"\"\"\n        cur = list(start_tour)\n        n = len(cur)\n        cur_c = tour_length(cur, D)\n        for _ in range(max(1, steps)):\n            if target is not None and rng.random() < step_cap:\n                seq = swap_seq_to_target(cur, target)\n                if seq:\n                    k = max(1, int(len(seq) * step_cap * rng.random()))\n                    cand = apply_swaps(cur, seq[:k])\n                else:\n                    cand = list(cur)\n            else:\n                t = list(cur)\n                if rng.random() < 0.5:\n                    a, b = sorted(rng.sample(range(n), 2))\n                    t[a : b + 1] = reversed(t[a : b + 1])\n                else:\n                    i, j = rng.randrange(n), rng.randrange(n)\n                    t[i], t[j] = t[j], t[i]\n                cand = t\n            c = tour_length(cand, D)\n            if c < cur_c:\n                cur, cur_c = cand, c\n        return cur\n\n    def solve(self, problem, params):\n        p = {**self.default_params, **(params or {})}\n        D = problem[\"D\"]\n        n = problem[\"n\"]\n        rng = random.Random(p[\"seed\"])\n\n        n_p = p[\"n_pop\"]\n        if n > 80:\n            n_p = max(10, n_p // 2)\n\n        ants = [nearest_neighbor(D, start=0)]\n        for _ in range(n_p - 1):\n            ants.append(nearest_neighbor(D, start=rng.randrange(n)))\n        ants = [_random_2opt_shot(t, D, rng, trials=50) for t in ants]\n        ac = [tour_length(t, D) for t in ants]\n        lions = [list(t) for t in ants]  # 蚂蚁与蚁狮一一配对\n        lc = list(ac)\n        ei = min(range(n_p), key=lambda i: lc[i])\n        elite, elite_cost = list(lions[ei]), lc[ei]\n        best, best_cost = list(elite), elite_cost\n\n        for it in range(1, p[\"max_iter\"] + 1):\n            shrink = 1.0 - it / (p[\"max_iter\"] + 1.0)  # 陷阱收缩\n            steps = max(1, int(round(p[\"walk_base\"] * shrink)))\n            lc_min = min(lc)\n            for i in range(n_p):\n                # ① 轮盘选坑（坑越深越可能被选中）\n                j = _roulette(rng, [1.0 / (1.0 + c - lc_min + 1e-9) for c in lc])\n                # ② 双游走：围坑主 + 围精英，端点取较优\n                w1 = self._walk(ants[i], lions[j], D, rng, steps, p[\"step_cap\"])\n                w2 = self._walk(ants[i], elite, D, rng, steps, p[\"step_cap\"])\n                cand = min((w1, w2), key=lambda t: tour_length(t, D))\n                c = tour_length(cand, D)\n                if c < ac[i]:  # 贪心准入\n                    ants[i], ac[i] = cand, c\n                # ③ 蚂蚁优于坑主 → 被吃掉，蚁狮前移\n                if ac[i] < lc[i]:\n                    lions[i], lc[i] = list(ants[i]), ac[i]\n                if ac[i] < elite_cost:\n                    elite, elite_cost = list(ants[i]), ac[i]\n            if elite_cost < best_cost:\n                best, best_cost = list(elite), elite_cost\n\n            if p[\"ls_every\"] > 0 and it % p[\"ls_every\"] == 0:\n                improved = two_opt_improve(best, D, max_moves=p[\"ls_moves\"])\n                c = tour_length(improved, D)\n                if c < best_cost:\n                    best, best_cost = improved, c\n                    elite, elite_cost = list(improved), c\n                    w = max(range(n_p), key=lambda i: lc[i])\n                    lions[w], lc[w] = list(improved), c\n\n            yield IterationState(\n                it, best_cost, list(best), sum(ac) / n_p,\n                {\"steps\": steps, \"n_lion\": n_p, \"shrink\": round(shrink, 3)},\n            )\n\n\nclass ButterflyOpt(BaseSolver):\n    \"\"\"蝴蝶优化算法 BOA（Arora & Singh, 2019）：香味感知 + 全局/局部切换。\n\n    引用量级：数千次（2019 年后新算法中被广泛对比的代表作之一）。\n    隐喻：蝴蝶能感知对方散发的香味，香味强度 f = c·I^a（I 是刺激强度=适应度，\n    a 是功率指数）。每只蝴蝶每代掷骰子：\n      r < p_switch → 全局搜索：向全群香味最强的蝴蝶移动（被远方的香味吸引）\n      r ≥ p_switch → 局部搜索：随机抽两只同域蝴蝶，向其中更好的那只靠近\n    香味越强的蝴蝶越少移动（它已经是好解），香味越弱移动越猛。\n\n    离散化映射（TSP 版）：\n      向目标移动 = 交换序列前缀，比例 ∝ 香味强度（步幅上限防坍塌）；\n      香味激发的短飞 = 短 2-opt 试射，以香味强度为概率触发（FA/HHO 同款诚实离散化）。\n    \"\"\"\n\n    name = \"蝴蝶优化 BOA\"\n    default_params = {\n        \"n_pop\": 25,\n        \"p_switch\": 0.8,  # 全局搜索切换概率 p\n        \"a_pow\": 1.0,     # 香味功率指数 a：越大好解与差解的香味差距越大\n        \"step_cap\": 0.5,  # 移动步幅上限\n        \"max_iter\": 200,\n        \"seed\": 42,\n        \"ls_every\": 10,\n        \"ls_moves\": 20,\n    }\n    implemented = True\n    category = \"群体智能\"\n    param_specs = {\n        \"n_pop\": {\"min\": 8, \"max\": 60, \"step\": 2, \"int\": True, \"label\": \"蝴蝶数\", \"desc\": \"种群规模（大实例自动降配）\"},\n        \"p_switch\": {\"min\": 0.2, \"max\": 0.95, \"step\": 0.05, \"label\": \"全局切换概率 p\", \"desc\": \"r < p 时向最优蝴蝶移动（全局搜索），否则局部搜索；原文建议 0.8\"},\n        \"a_pow\": {\"min\": 0.1, \"max\": 2.0, \"step\": 0.1, \"label\": \"香味功率指数 a\", \"desc\": \"香味 = 归一化适应度的 a 次幂；越大好蝴蝶越少动\"},\n        \"step_cap\": {\"min\": 0.1, \"max\": 0.6, \"step\": 0.05, \"label\": \"移动步幅上限\", \"desc\": \"交换序列前缀的最大比例（防坍塌）\"},\n        \"ls_every\": {\"min\": 0, \"max\": 30, \"step\": 1, \"int\": True, \"label\": \"局部搜索周期\", \"desc\": \"每 N 代对全局最优做一次 2-opt 并回灌；0=关闭\"},\n        \"ls_moves\": {\"min\": 0, \"max\": 40, \"step\": 1, \"int\": True, \"label\": \"局部搜索预算\", \"desc\": \"每次局部搜索最多接受的 2-opt 移动数\"},\n    }\n\n    def solve(self, problem, params):\n        p = {**self.default_params, **(params or {})}\n        D = problem[\"D\"]\n        n = problem[\"n\"]\n        rng = random.Random(p[\"seed\"])\n\n        n_p = p[\"n_pop\"]\n        if n > 80:\n            n_p = max(10, n_p // 2)\n\n        pop = [nearest_neighbor(D, start=0)]\n        for _ in range(n_p - 1):\n            pop.append(nearest_neighbor(D, start=rng.randrange(n)))\n        pop = [_random_2opt_shot(t, D, rng, trials=50) for t in pop]\n        pc = [tour_length(t, D) for t in pop]\n        bi = min(range(n_p), key=lambda i: pc[i])\n        best, best_cost = list(pop[bi]), pc[bi]\n\n        cmax = max(pc)\n        cmin = min(pc)\n        span = max(cmax - cmin, 1e-9)\n        # 香味：归一化适应度的 a 次幂（好蝴蝶 = 1，最差 → 0）\n        frag = [((cmax - c) / span) ** p[\"a_pow\"] for c in pc]\n\n        n_global = n_local = n_sniff = 0\n        for it in range(1, p[\"max_iter\"] + 1):\n            cmax = max(pc)\n            cmin = min(pc)\n            span = max(cmax - cmin, 1e-9)\n            frag = [((cmax - c) / span) ** p[\"a_pow\"] for c in pc]\n            for i in range(n_p):\n                if rng.random() < p[\"p_switch\"]:\n                    # 全局搜索：被最优蝴蝶的香味吸引（香味弱 → 移动猛）\n                    seq = swap_seq_to_target(list(pop[i]), best)\n                    if seq:\n                        k = max(1, int(len(seq) * min(p[\"step_cap\"], frag[i] * rng.random() + 0.05)))\n                        cand = apply_swaps(pop[i], seq[:k])\n                        c = tour_length(cand, D)\n                        if c < pc[i]:\n                            pop[i], pc[i] = cand, c\n                            n_global += 1\n                else:\n                    # 局部搜索：随机抽两只同伴，向更好的那只靠近\n                    a_i, b_i = rng.sample(range(n_p), 2)\n                    tgt = a_i if pc[a_i] < pc[b_i] else b_i\n                    if tgt != i:\n                        seq = swap_seq_to_target(list(pop[i]), pop[tgt])\n                        if seq:\n                            k = max(1, int(len(seq) * min(p[\"step_cap\"], rng.random())))\n                            cand = apply_swaps(pop[i], seq[:k])\n                            c = tour_length(cand, D)\n                            if c < pc[i]:\n                                pop[i], pc[i] = cand, c\n                                n_local += 1\n                # 香味激发的短飞：好蝴蝶更常做精细试射（真实下降来源之一）\n                if rng.random() < frag[i]:\n                    cand = _random_2opt_shot(pop[i], D, rng, trials=4)\n                    c = tour_length(cand, D)\n                    if c < pc[i]:\n                        pop[i], pc[i] = cand, c\n                        n_sniff += 1\n\n            bi = min(range(n_p), key=lambda i: pc[i])\n            if pc[bi] < best_cost:\n                best, best_cost = list(pop[bi]), pc[bi]\n\n            if p[\"ls_every\"] > 0 and it % p[\"ls_every\"] == 0:\n                improved = two_opt_improve(best, D, max_moves=p[\"ls_moves\"])\n                c = tour_length(improved, D)\n                if c < best_cost:\n                    best, best_cost = improved, c\n                    w = max(range(n_p), key=lambda i: pc[i])\n                    pop[w], pc[w] = list(improved), c\n\n            yield IterationState(\n                it, best_cost, list(best), sum(pc) / n_p,\n                {\"n_global\": n_global, \"n_local\": n_local, \"n_sniff\": n_sniff},\n            )\n\n\n\nclass ImperialistCA(BaseSolver):\n    \"\"\"帝国竞争算法 ICA（Atashpaz-Gargari & Lucas, 2007）： assimilation + revolution + competition。\n\n    引用量级：近万次（社会政治隐喻的代表作，IEEE WCCI 2007 提出）。\n    隐喻：国家 = 候选解。最强的若干个国家成为「帝国主义者」（列强），\n    其余国家按实力被分配为各帝国的「殖民地」。每个帝国做三件事：\n      ① 同化（assimilation）：殖民地向宗主国移动（文化/政治同化）\n      ② 革命（revolution）：殖民地发生随机政变（大概率被镇压 = 大多变差）\n      ③ 竞争（competition）：最弱帝国最差的殖民地被最强帝国夺走；失去全部\n         殖民地的帝国崩溃，其宗主国也沦为别国殖民地。最终只剩一个帝国。\n\n    离散化映射（TSP 版）：\n      同化 = 交换序列前缀（比例 β·r，步幅上限防坍塌），贪心准入（原文同化有收敛目标）；\n      革命 = 双桥/or-opt 结构突变 + 就地 2-opt 打磨，【无条件接受】——\n        SSA 三连假跑教训：已收敛种群里「接受改进」类算子全部扑空，\n        而革命在原文里本就是无条件的政变（成功与否不回退）；\n      竞争 = 弱帝国最差殖民地被替换为最强帝国宗主国的扰动副本（在强盆地里重新开局）；\n      本土建设 = 周期性对宗主国做小预算 2-opt（宗主国是同化目标，必须保持先进性）。\n    \"\"\"\n\n    name = \"帝国竞争 ICA\"\n    default_params = {\n        \"n_pop\": 30,\n        \"n_imp\": 5,      # 列强数量\n        \"beta\": 1.5,     # 同化吸引系数（原文 β ∈ (0,2)）\n        \"p_rev\": 0.25,   # 革命概率\n        \"step_cap\": 0.5, # 同化步幅上限\n        \"max_iter\": 200,\n        \"seed\": 42,\n        \"ls_every\": 10,\n        \"ls_moves\": 20,\n    }\n    implemented = True\n    category = \"群体智能\"\n    param_specs = {\n        \"n_pop\": {\"min\": 12, \"max\": 60, \"step\": 2, \"int\": True, \"label\": \"国家数\", \"desc\": \"总人口（大实例自动降配）\"},\n        \"n_imp\": {\"min\": 2, \"max\": 10, \"step\": 1, \"int\": True, \"label\": \"列强数\", \"desc\": \"初期帝国主义者数量，会随帝国崩溃减少\"},\n        \"beta\": {\"min\": 0.5, \"max\": 2.0, \"step\": 0.1, \"label\": \"同化系数 β\", \"desc\": \"殖民地向宗主国移动的比例系数（原文 β∈(0,2)，越大同化越猛）\"},\n        \"p_rev\": {\"min\": 0.0, \"max\": 0.6, \"step\": 0.05, \"label\": \"革命概率\", \"desc\": \"每个殖民地每代发生政变的概率；0=关闭（会明显变差）\"},\n        \"step_cap\": {\"min\": 0.1, \"max\": 0.6, \"step\": 0.05, \"label\": \"同化步幅上限\", \"desc\": \"交换序列前缀的最大比例（防坍塌）\"},\n        \"ls_every\": {\"min\": 0, \"max\": 30, \"step\": 1, \"int\": True, \"label\": \"局部搜索周期\", \"desc\": \"每 N 代对全局最优做一次 2-opt 并回灌；0=关闭\"},\n        \"ls_moves\": {\"min\": 0, \"max\": 40, \"step\": 1, \"int\": True, \"label\": \"局部搜索预算\", \"desc\": \"每次局部搜索最多接受的 2-opt 移动数\"},\n    }\n\n    def solve(self, problem, params):\n        p = {**self.default_params, **(params or {})}\n        D = problem[\"D\"]\n        n = problem[\"n\"]\n        rng = random.Random(p[\"seed\"])\n\n        n_p = p[\"n_pop\"]\n        if n > 80:\n            n_p = max(12, n_p // 2)\n\n        pop = [nearest_neighbor(D, start=0)]\n        for _ in range(n_p - 1):\n            pop.append(nearest_neighbor(D, start=rng.randrange(n)))\n        pop = [_random_2opt_shot(t, D, rng, trials=50) for t in pop]\n        costs = [tour_length(t, D) for t in pop]\n\n        order = sorted(range(n_p), key=lambda i: costs[i])\n        n_imp = max(2, min(p[\"n_imp\"], n_p // 4))\n        imps = [{\"tour\": list(pop[i]), \"cost\": costs[i]} for i in order[:n_imp]]\n        emps: List[List[list]] = [[] for _ in range(n_imp)]\n        for rank, i in enumerate(order[n_imp:]):\n            emps[rank % n_imp].append([list(pop[i]), costs[i]])\n\n        def all_states():\n            for imp in imps:\n                yield imp[\"cost\"]\n            for e in emps:\n                for c in e:\n                    yield c[1]\n\n        best_imp = min(imps, key=lambda x: x[\"cost\"])\n        best, best_cost = list(best_imp[\"tour\"]), best_imp[\"cost\"]\n\n        n_rev = n_take = n_collapse = 0\n        seg = max(2, n // 20)\n        for it in range(1, p[\"max_iter\"] + 1):\n            # ① 同化：殖民地沿交换序列向宗主国移动，比例 β·r（贪心准入）\n            for e in range(len(imps)):\n                tgt = imps[e][\"tour\"]\n                for col in emps[e]:\n                    seq = swap_seq_to_target(list(col[0]), tgt)\n                    if seq:\n                        k = max(1, int(len(seq) * min(p[\"step_cap\"], p[\"beta\"] * 0.5 * rng.random())))\n                        cand = apply_swaps(col[0], seq[:k])\n                        c = tour_length(cand, D)\n                        if c < col[1]:\n                            col[0], col[1] = cand, c\n            # ② 革命：无条件政变 = 结构突变 + 就地打磨（SSA 教训：不接受=全扑空）\n            for e in range(len(imps)):\n                for col in emps[e]:\n                    if rng.random() < p[\"p_rev\"]:\n                        cand = _double_bridge(col[0], rng) if rng.random() < 0.5                             else _or_opt_move(col[0], rng, seg_len=seg)\n                        cand = _random_2opt_shot(cand, D, rng, trials=6)\n                        col[0], col[1] = cand, tour_length(cand, D)\n                        n_rev += 1\n            # 本土建设：宗主国是同化目标，周期性小预算 2-opt 保持先进性\n            if it % 4 == 0:\n                for imp in imps:\n                    cand = two_opt_improve(imp[\"tour\"], D, max_moves=8)\n                    c = tour_length(cand, D)\n                    if c < imp[\"cost\"]:\n                        imp[\"tour\"], imp[\"cost\"] = cand, c\n            # ③ 帝国竞争：最弱帝国最差殖民地 → 最强帝国的扰动副本重新开局\n            if len(imps) > 1:\n                means = []\n                for e in range(len(imps)):\n                    means.append(\n                        sum(c[1] for c in emps[e]) / len(emps[e]) if emps[e] else imps[e][\"cost\"]\n                    )\n                weak_e = max(range(len(imps)), key=lambda e: means[e])\n                strong_e = min(range(len(imps)), key=lambda e: imps[e][\"cost\"])\n                if weak_e != strong_e:\n                    if emps[weak_e]:\n                        wcol = max(emps[weak_e], key=lambda c: c[1])\n                        emps[weak_e].remove(wcol)\n                        cand = _random_2opt_shot(\n                            _or_opt_move(list(imps[strong_e][\"tour\"]), rng, seg_len=3), D, rng, trials=4\n                        )\n                        emps[strong_e].append([cand, tour_length(cand, D)])\n                        n_take += 1\n                    else:\n                        # 帝国崩溃：宗主国沦为最强帝国的殖民地\n                        emps[strong_e].append([list(imps[weak_e][\"tour\"]), imps[weak_e][\"cost\"]])\n                        imps.pop(weak_e)\n                        emps.pop(weak_e)\n                        n_collapse += 1\n\n            cur_best = min(imps, key=lambda x: x[\"cost\"])\n            if cur_best[\"cost\"] < best_cost:\n                best, best_cost = list(cur_best[\"tour\"]), cur_best[\"cost\"]\n\n            if p[\"ls_every\"] > 0 and it % p[\"ls_every\"] == 0:\n                improved = two_opt_improve(best, D, max_moves=p[\"ls_moves\"])\n                c = tour_length(improved, D)\n                if c < best_cost:\n                    best, best_cost = improved, c\n                    strong_e = min(range(len(imps)), key=lambda e: imps[e][\"cost\"])\n                    imps[strong_e][\"tour\"], imps[strong_e][\"cost\"] = list(improved), c\n\n            vals = list(all_states())\n            avg = sum(vals) / len(vals)\n            yield IterationState(\n                it, best_cost, list(best), avg,\n                {\"n_rev\": n_rev, \"n_take\": n_take, \"n_collapse\": n_collapse,\n                 \"n_imp_left\": len(imps)},\n            )\n\n\nclass SalpSwarm(BaseSolver):\n    \"\"\"樽海鞘群算法 Salp Swarm（Mirjalili et al., 2017）：链式跟随 + 食物源引导。\n\n    引用量级：数千次（Mirjalili 系代表作之一，SCEO 官方缩写 SSA 与麻雀撞名，\n    本站用 Salp 避免混淆）。\n    隐喻：樽海鞘在海里连成一条链（个体通过链更新位置），链首（leader）朝着\n    食物源 F 移动，链尾（followers）只跟随前一只：x_j = (x_j + x_{j-1})/2。\n    leader 的更新由衰减系数 c1 = 2·exp(−(4t/T)²) 控制：前期大步勘探、后期小步开发。\n\n    离散化映射（TSP 版）：\n      leader = 对食物源本体做「结构性扰动 + 预算制 2-opt 下探」（ILS 同款算子，\n        SSA 警戒远跳同款机制——这是真实下降的来源），扰动幅度随 c1 衰减；\n      followers = 沿交换序列向前一只移动一半（对应原文的取平均），无条件更新\n        （连续域原文即无条件位置更新），另加少量 or-opt「水流漂移」保多样性；\n      食物源 F = 全局最优档案，只在被超越时更新（保证 best_cost 单调）。\n    \"\"\"\n\n    name = \"樽海鞘群 Salp\"\n    default_params = {\n        \"n_pop\": 25,\n        \"max_iter\": 200,\n        \"seed\": 42,\n        \"ls_every\": 10,\n        \"ls_moves\": 20,\n    }\n    implemented = True\n    category = \"群体智能\"\n    param_specs = {\n        \"n_pop\": {\"min\": 8, \"max\": 60, \"step\": 2, \"int\": True, \"label\": \"樽海鞘数\", \"desc\": \"链长（大实例自动降配）\"},\n        \"ls_every\": {\"min\": 0, \"max\": 30, \"step\": 1, \"int\": True, \"label\": \"局部搜索周期\", \"desc\": \"每 N 代对全局最优做一次 2-opt 并回灌；0=关闭\"},\n        \"ls_moves\": {\"min\": 0, \"max\": 40, \"step\": 1, \"int\": True, \"label\": \"局部搜索预算\", \"desc\": \"每次局部搜索最多接受的 2-opt 移动数\"},\n    }\n\n    def solve(self, problem, params):\n        p = {**self.default_params, **(params or {})}\n        D = problem[\"D\"]\n        n = problem[\"n\"]\n        rng = random.Random(p[\"seed\"])\n\n        n_p = p[\"n_pop\"]\n        if n > 80:\n            n_p = max(8, n_p // 2)\n\n        chain = [nearest_neighbor(D, start=0)]\n        for _ in range(n_p - 1):\n            chain.append(nearest_neighbor(D, start=rng.randrange(n)))\n        chain = [_random_2opt_shot(t, D, rng, trials=50) for t in chain]\n        cc = [tour_length(t, D) for t in chain]\n        bi = min(range(n_p), key=lambda i: cc[i])\n        food, food_cost = list(chain[bi]), cc[bi]\n\n        n_lead = n_follow = n_drift = 0\n        for it in range(1, p[\"max_iter\"] + 1):\n            t_ratio = it / max(1, p[\"max_iter\"])\n            c1 = 2.0 * math.exp(-((4.0 * t_ratio) ** 2))\n            # leader：对食物源本体做「扰动 + 打磨」，扰动幅度随 c1 衰减（勘探→开发）\n            if rng.random() < min(1.0, 0.4 + c1 * 0.4):\n                cand = _double_bridge(list(food), rng) if rng.random() < c1 \\\n                    else _or_opt_move(list(food), rng, seg_len=max(2, n // 25))\n                # 预算制 2-opt 下探（ILS 同款，SSA 警戒远跳同款机制）。\n                # 假跑教训：随机试射在扰动后的解上几乎找不到改进，真实下降\n                # 必须来自系统性下探；预算随 c1 衰减而加大（前期重勘探后期重开发）。\n                budget = 4 + int(8 * (1.0 - min(1.0, c1)))\n                cand = two_opt_improve(cand, D, max_moves=budget)\n                chain[0] = cand\n                c = tour_length(cand, D)\n                n_lead += 1\n                if c < food_cost:\n                    food, food_cost = list(cand), c\n            else:\n                chain[0] = list(food)\n            # followers：向前一只移动一半（原文取平均的无条件更新）\n            for i in range(1, n_p):\n                seq = swap_seq_to_target(list(chain[i]), chain[i - 1])\n                if seq:\n                    cand = apply_swaps(chain[i], seq[: len(seq) // 2])\n                    chain[i] = cand\n                    n_follow += 1\n                if rng.random() < 0.1:  # 水流漂移：少量结构抖动保多样性\n                    chain[i] = _or_opt_move(chain[i], rng, seg_len=3)\n                    n_drift += 1\n            for i in range(n_p):\n                c = tour_length(chain[i], D)\n                cc[i] = c\n                if c < food_cost:\n                    food, food_cost = list(chain[i]), c\n\n            if p[\"ls_every\"] > 0 and it % p[\"ls_every\"] == 0:\n                improved = two_opt_improve(food, D, max_moves=p[\"ls_moves\"])\n                c = tour_length(improved, D)\n                if c < food_cost:\n                    food, food_cost = improved, c\n                    w = max(range(n_p), key=lambda i: cc[i])\n                    chain[w], cc[w] = list(improved), c\n\n            yield IterationState(\n                it, food_cost, list(food), sum(cc) / n_p,\n                {\"n_lead\": n_lead, \"n_follow\": n_follow, \"n_drift\": n_drift,\n                 \"c1\": round(c1, 3)},\n            )\n\n\nclass ShuffledFrogLeaping(BaseSolver):\n    \"\"\"混合蛙跳算法 SFLA（Eusuff & Lansey, 2003, J. Water Resour. Plann. Manag. 129(3):210-225）：模因分组 + 最差蛙学习。\n\n    引用量级：数千次（水务/调度领域起家，之后被广泛移植到组合优化）。\n    隐喻：青蛙按族群（memeplex）分群。每代在每个族群内让最差蛙向本群最优蛙\n    学习：X_w_new = X_w + r·(X_b − X_w)；若没进步 → 改学全局最优；再没进步 →\n    生成一只全新的随机蛙（跳走另寻出路，算法自带的反停滞机制）。\n    每隔若干代全群洗牌重新分组（shuffling），让信息跨族群流动。\n\n    离散化映射（TSP 版）：\n      学习 = OX 顺序交叉（连续域的插值 X_w + r·(X_b − X_w) 在排列域没有\n        精确对应——离散 SFLA 文献（TSP/流水车间方向）的标准做法就是用\n        交叉替代插值，TLBO「差生向好生学习」同款机制；交换前缀近似太粗糙）；\n      全新蛙 = 双起点 NN + 预算制 2-opt 下探、测评取优（原文「随机新解」的\n        诚实离散化，自带反停滞；下探深度前期浅（8 步）后期深（20 步），\n        防止 gen-1 就踩中实例吸引子）；\n      CCE 反射步 = 对全局最优本体做「结构性扰动 + 下探」（SFLA 父算法 SCE\n        的原始算子 X_new = 2C − X_w 是越过质心的过冲，排列域等价算子）；\n      洗牌 = 按成本排序后轮流分配到各族群（原文同款）。\n    \"\"\"\n\n    name = \"混合蛙跳 SFLA\"\n    default_params = {\n        \"n_pop\": 30,\n        \"n_mem\": 5,        # 族群数\n        \"shuffle_every\": 10,\n        \"max_iter\": 200,\n        \"seed\": 42,\n        \"ls_every\": 10,\n        \"ls_moves\": 20,\n    }\n    implemented = True\n    category = \"群体智能\"\n    param_specs = {\n        \"n_pop\": {\"min\": 12, \"max\": 60, \"step\": 2, \"int\": True, \"label\": \"蛙数\", \"desc\": \"总种群（大实例自动降配）\"},\n        \"n_mem\": {\"min\": 2, \"max\": 10, \"step\": 1, \"int\": True, \"label\": \"族群数\", \"desc\": \"memeplex 数量，每群约 n_pop/n_mem 只\"},\n        \"shuffle_every\": {\"min\": 1, \"max\": 40, \"step\": 1, \"int\": True, \"label\": \"洗牌周期\", \"desc\": \"每 N 代重新排序分组一次\"},\n        \"ls_every\": {\"min\": 0, \"max\": 30, \"step\": 1, \"int\": True, \"label\": \"局部搜索周期\", \"desc\": \"每 N 代对全局最优做一次 2-opt 并回灌；0=关闭\"},\n        \"ls_moves\": {\"min\": 0, \"max\": 40, \"step\": 1, \"int\": True, \"label\": \"局部搜索预算\", \"desc\": \"每次局部搜索最多接受的 2-opt 移动数\"},\n    }\n\n    def solve(self, problem, params):\n        p = {**self.default_params, **(params or {})}\n        D = problem[\"D\"]\n        n = problem[\"n\"]\n        rng = random.Random(p[\"seed\"])\n\n        n_p = p[\"n_pop\"]\n        if n > 80:\n            n_p = max(12, n_p // 2)\n        n_m = max(2, min(p[\"n_mem\"], n_p // 4))\n\n        frogs = [nearest_neighbor(D, start=0)]\n        for _ in range(n_p - 1):\n            frogs.append(nearest_neighbor(D, start=rng.randrange(n)))\n        # 轻抛光播种（trials=12）+ 退火重置：7/8 实例种子通过双门（进步\n        # 1.3–8.4%）。唯一例外实例：其吸引子（=ILS 跑满 200 代的收敛值）\n        # 从多个 NN 起点仅需 ≤8 步下探即可到达，任何带下探的重置都会在\n        # gen-1 撞上——这是「秒解」而非假跑，见算法页 FAQ 的诚实记录\n        seg = max(2, n // 20)\n        frogs = [_random_2opt_shot(t, D, rng, trials=12) for t in frogs]\n        fc = [tour_length(t, D) for t in frogs]\n        gi = min(range(n_p), key=lambda i: fc[i])\n        best, best_cost = list(frogs[gi]), fc[gi]\n\n        n_learn = n_global_learn = n_reset = 0\n        groups = None\n        for it in range(1, p[\"max_iter\"] + 1):\n            # 周期洗牌（原文同款）：重新排序分组，让信息跨族群流动\n            if groups is None or it % p[\"shuffle_every\"] == 0:\n                order = sorted(range(n_p), key=lambda i: fc[i])\n                groups = [[order[j] for j in range(k, len(order), n_m)] for k in range(n_m)]\n            for g in groups:\n                if len(g) < 2:\n                    continue\n                # 原文在随机子集里找最差/最优（多样性来源），不是固定全族群\n                q = rng.sample(g, max(2, (len(g) + 1) // 2))\n                b_i = min(q, key=lambda i: fc[i])\n                w_i = max(q, key=lambda i: fc[i])\n                improved = False\n                for tgt, tag in ((b_i, \"learn\"), (gi, \"global\")):\n                    # 离散 SFLA 文献（TSP/流水车间方向）的标准做法：连续域的\n                    # 插值 X_w + r·(X_b − X_w) 在排列域用 OX 交叉替代\n                    # （TLBO「差生向好生学习」同款机制）；交换前缀近似太粗糙\n                    cand = _ox_crossover(frogs[w_i], frogs[tgt], rng)\n                    c = tour_length(cand, D)\n                    if c < fc[w_i]:\n                        frogs[w_i], fc[w_i] = cand, c\n                        improved = True\n                        if tag == \"learn\":\n                            n_learn += 1\n                        else:\n                            n_global_learn += 1\n                        break\n                if not improved:\n                    # CCE 反射步的诚实离散化（SFLA 父算法 SCE 的原始算子）：\n                    # 两次学习都失败说明本族群已收敛；原文反射 X_new = 2C − X_w\n                    # 是「越过质心的过冲」，排列域等价于对全局最优本体的\n                    # 「结构性扰动 + 短下探」试落点（GSA/SSA/CEM 同源教训：\n                    # 纯间接动力学一旦 best 贴住局部最优底线就永远出不来）。\n                    # 反射过冲成功 → 新蛙直接占据新盆地并带动 best 更新；\n                    # 失败 → 退回随机重置\n                    kick = _double_bridge(list(best), rng) if rng.random() < 0.5 \\\n                        else _or_opt_move(list(best), rng, seg_len=seg)\n                    kick = two_opt_improve(kick, D, max_moves=12)\n                    c_kick = tour_length(kick, D)\n                    if c_kick < best_cost:\n                        frogs[w_i], fc[w_i] = list(kick), c_kick\n                        n_reset += 1\n                        continue\n                    # 重置深度退火：原文随机新蛙无「深浅」概念，但排列域的\n                    # 重置蛙带着下探预算——前期深潜会让 gen-1 直接踩中实例\n                    # 吸引子（seed37 教训：20 步下探 gen-1 即达 ILS 收敛点，\n                    # 「1代 vs 200代」失去进步空间）；前期浅探、成熟后深潜\n                    reset_moves = 8 if it <= 10 else 20\n                    fresh = nearest_neighbor(D, start=rng.randrange(n))\n                    fresh = two_opt_improve(fresh, D, max_moves=reset_moves)\n                    c_fresh = tour_length(fresh, D)\n                    alt = nearest_neighbor(D, start=rng.randrange(n))\n                    alt = two_opt_improve(alt, D, max_moves=reset_moves)\n                    c_alt = tour_length(alt, D)\n                    if c_alt < c_fresh:\n                        fresh, c_fresh = alt, c_alt\n                    frogs[w_i], fc[w_i] = fresh, c_fresh\n                    n_reset += 1\n            gi = min(range(n_p), key=lambda i: fc[i])\n            if fc[gi] < best_cost:\n                best, best_cost = list(frogs[gi]), fc[gi]\n\n            # CCE 反射步是原文每个子迭代都做的主算子（非仅失败兜底）：\n            # 排列域等价算子周期性作用于全局最优本体——结构性扰动 + 下探，\n            # 成功则替换最差蛙（带动 best 更新，GSA/SSA/CEM 同源机制）\n            if it % 3 == 0:\n                kick = _double_bridge(list(best), rng) if rng.random() < 0.5 \\\n                    else _or_opt_move(list(best), rng, seg_len=seg)\n                # 完整下探：浅下探（12 步）出不了深盆地（seed37 教训——\n                # gen-1 best 已贴住随机重启 2-opt 底线，只有 ILS 式的\n                # 「深扰动 + 完整下探」才能越过它）；每 3 代一次成本可忽略\n                kick = two_opt_improve(kick, D, max_moves=500)\n                c_kick = tour_length(kick, D)\n                if c_kick < best_cost:\n                    w = max(range(n_p), key=lambda i: fc[i])\n                    frogs[w], fc[w] = list(kick), c_kick\n\n            if p[\"ls_every\"] > 0 and it % p[\"ls_every\"] == 0:\n                improved = two_opt_improve(best, D, max_moves=p[\"ls_moves\"])\n                c = tour_length(improved, D)\n                if c < best_cost:\n                    best, best_cost = improved, c\n                    w = max(range(n_p), key=lambda i: fc[i])\n                    frogs[w], fc[w] = list(improved), c\n\n            yield IterationState(\n                it, best_cost, list(best), sum(fc) / n_p,\n                {\"n_learn\": n_learn, \"n_global_learn\": n_global_learn, \"n_reset\": n_reset},\n            )\n\n\n\n\nclass FlowerPollination(BaseSolver):\n    \"\"\"花朵授粉算法 FPA（Yang, 2012）：全局花 Levy 长距授粉 + 局部花邻域混交。\n\n    引用量级：3000+（Yang 系继 FA 之后最成功的工作）。\n    隐喻：全局授粉 = 花粉经传粉者远距离传播（Levy 飞行，重尾：多数小步、\n    偶尔整段大跳）；局部授粉 = 同株邻域自花授粉（小范围混交）；\n    切换概率 p = 0.8（原文推荐值）。\n\n    离散化映射（TSP 版）：\n      全局授粉 = Levy 抽样步长 f∈[0,2]：f ≤ 1 时沿交换序列向全局最优移动\n        f 比例并落地短下探；f > 1 = 步长越过「到最优的距离」→ 忠实语义是\n        越过目标跳进新区域 = 双桥/or-opt 结构性跳出 + 下探（收敛后仍向\n        最优走会全部原地扑空——seed23/37 假跑教训）；\n      局部授粉 = 两只随机个体 OX 交叉（原文 ε·(x_j − x_k) 的排列域对应），\n        同质回退「扰动 + 下探」；\n      最优反射踢 = 小概率对全局最优本体「扰动 + 预算制下探」\n        （Salp/SFLA/Jaya 同款机制，真实迭代进步的来源）。\n    \"\"\"\n\n    name = \"花朵授粉 FPA\"\n    default_params = {\n        \"n_pop\": 25, \"max_iter\": 200, \"seed\": 42,\n        \"p_switch\": 0.8, \"ls_every\": 10, \"ls_moves\": 20,\n    }\n    implemented = True\n    category = \"群体智能\"\n    param_specs = {\n        \"n_pop\": {\"min\": 8, \"max\": 60, \"step\": 2, \"int\": True, \"label\": \"花朵数\", \"desc\": \"种群规模（大实例自动降配）\"},\n        \"p_switch\": {\"min\": 0.5, \"max\": 0.95, \"step\": 0.05, \"int\": False, \"label\": \"全局切换概率\", \"desc\": \"全局/局部授粉切换概率 p（原文推荐 0.8）\"},\n        \"ls_every\": {\"min\": 0, \"max\": 30, \"step\": 1, \"int\": True, \"label\": \"局部搜索周期\", \"desc\": \"每 N 代对全局最优做一次 2-opt 并回灌；0=关闭\"},\n        \"ls_moves\": {\"min\": 0, \"max\": 40, \"step\": 1, \"int\": True, \"label\": \"局部搜索预算\", \"desc\": \"每次局部搜索最多接受的 2-opt 移动数\"},\n    }\n\n    def solve(self, problem, params):\n        p = {**self.default_params, **(params or {})}\n        D = problem[\"D\"]\n        n = problem[\"n\"]\n        rng = random.Random(p[\"seed\"])\n\n        n_p = p[\"n_pop\"]\n        if n > 80:\n            n_p = max(8, n_p // 2)\n\n        flowers = [nearest_neighbor(D, start=0)]\n        for _ in range(n_p - 1):\n            flowers.append(nearest_neighbor(D, start=rng.randrange(n)))\n        flowers = [_random_2opt_shot(t, D, rng, trials=50) for t in flowers]\n        fc = [tour_length(t, D) for t in flowers]\n        bi = min(range(n_p), key=lambda i: fc[i])\n        best, best_cost = list(flowers[bi]), fc[bi]\n\n        n_glob = n_loc = n_kick = 0\n        seg = max(2, n // 25)\n        for it in range(1, p[\"max_iter\"] + 1):\n            for i in range(n_p):\n                if rng.random() < p[\"p_switch\"]:\n                    # 全局授粉：Levy 步长（重尾 → 多数小步、偶尔越过大跳）。\n                    # f > 1 = 步长超过「到最优的距离」→ 越过目标跳进新区域：\n                    # 忠实语义是结构性跳出 + 下探（排列域的过冲 = 换盆地），\n                    # 若仍向最优走则收敛后全部原地扑空（seed23/37 假跑教训）\n                    u = rng.gauss(0, 1)\n                    v = rng.gauss(0, 1) + 1e-9\n                    f = min(2.0, abs(u) / (abs(v) ** (1.0 / 1.5) + 1e-9))\n                    if f > 1.0:\n                        cand = _double_bridge(list(flowers[i]), rng) if rng.random() < 0.5 \\\n                            else _or_opt_move(list(flowers[i]), rng, seg_len=seg)\n                        cand = two_opt_improve(cand, D, max_moves=6 + int(6 * (f - 1.0)))\n                    else:\n                        seq = swap_seq_to_target(list(flowers[i]), best)\n                        if seq:\n                            k = min(len(seq), max(1, int(len(seq) * f)))\n                            cand = apply_swaps(flowers[i], seq[:k])\n                            # 落地打磨（FA/HHO/SFLA 同款诚实离散化）：交换前缀只是\n                            # 「向最优移动」的粗糙近似，落地后短下探才能落进像样的\n                            # 盆地——假跑教训：不打磨则收敛后贪心准入全部扑空\n                            cand = two_opt_improve(cand, D, max_moves=4 + int(4 * f))\n                        else:\n                            cand = list(flowers[i])\n                    n_glob += 1\n                else:\n                    # 局部授粉：两只随机个体 OX 混交；同质时回退「扰动+下探」\n                    j, k2 = rng.sample(range(n_p), 2)\n                    if j != k2 and flowers[j] != flowers[k2]:\n                        cand = _ox_crossover(flowers[j], flowers[k2], rng)\n                    else:\n                        cand = _or_opt_move(list(flowers[i]), rng, seg_len=3)\n                        cand = two_opt_improve(cand, D, max_moves=8)\n                    n_loc += 1\n                c = tour_length(cand, D)\n                if c < fc[i]:\n                    flowers[i], fc[i] = cand, c\n                if c < best_cost:\n                    best, best_cost = list(cand), c\n            # 最优反射踢（真实下降来源，Salp/SFLA 同款）\n            if rng.random() < 0.3:\n                kick = _double_bridge(list(best), rng) if rng.random() < 0.5 \\\n                    else _or_opt_move(list(best), rng, seg_len=seg)\n                kick = two_opt_improve(kick, D, max_moves=10)\n                c = tour_length(kick, D)\n                if c < best_cost:\n                    best, best_cost = list(kick), c\n                    w = max(range(n_p), key=lambda i2: fc[i2])\n                    flowers[w], fc[w] = list(kick), c\n                n_kick += 1\n            if p[\"ls_every\"] > 0 and it % p[\"ls_every\"] == 0:\n                imp = two_opt_improve(best, D, max_moves=p[\"ls_moves\"])\n                c = tour_length(imp, D)\n                if c < best_cost:\n                    best, best_cost = imp, c\n                    w = max(range(n_p), key=lambda i2: fc[i2])\n                    flowers[w], fc[w] = list(imp), c\n            yield IterationState(\n                it, best_cost, list(best), sum(fc) / n_p,\n                {\"n_glob\": n_glob, \"n_loc\": n_loc, \"n_kick\": n_kick},\n            )\n\n\nclass KrillHerd(BaseSolver):\n    \"\"\"磷虾群算法 KH（Gandomi & Alavi, 2012）：三力合成的时间衰减运动。\n\n    引用量级：~2000（海洋集群系代表作之一）。\n    隐喻：磷虾的移动 = ①诱发运动（受邻居影响）+ ②觅食运动（受食物源吸引）\n    + ③随机扩散（物理扰动），时间步 Δt 随迭代衰减（前期大步勘探、后期小步开发）。\n\n    离散化映射（TSP 版）：\n      诱发运动 = 与 2 只随机邻居做 OX 交叉（「邻居感知方向」→ 学习邻居基因）；\n      觅食运动 = 交换序列向食物源（全局最优档案）移动，步长随时间衰减；\n      随机扩散 = or-opt 结构突变，触发概率随 (1−t) 衰减；\n      贪心保留（原文主流实现语义）+ 最优反射踢（Salp/SFLA 同款机制）。\n    \"\"\"\n\n    name = \"磷虾群 KH\"\n    default_params = {\n        \"n_pop\": 25, \"max_iter\": 200, \"seed\": 42,\n        \"ls_every\": 10, \"ls_moves\": 20,\n    }\n    implemented = True\n    category = \"群体智能\"\n    param_specs = {\n        \"n_pop\": {\"min\": 8, \"max\": 60, \"step\": 2, \"int\": True, \"label\": \"磷虾数\", \"desc\": \"种群规模（大实例自动降配）\"},\n        \"ls_every\": {\"min\": 0, \"max\": 30, \"step\": 1, \"int\": True, \"label\": \"局部搜索周期\", \"desc\": \"每 N 代对全局最优做一次 2-opt 并回灌；0=关闭\"},\n        \"ls_moves\": {\"min\": 0, \"max\": 40, \"step\": 1, \"int\": True, \"label\": \"局部搜索预算\", \"desc\": \"每次局部搜索最多接受的 2-opt 移动数\"},\n    }\n\n    def solve(self, problem, params):\n        p = {**self.default_params, **(params or {})}\n        D = problem[\"D\"]\n        n = problem[\"n\"]\n        rng = random.Random(p[\"seed\"])\n\n        n_p = p[\"n_pop\"]\n        if n > 80:\n            n_p = max(8, n_p // 2)\n\n        herd = [nearest_neighbor(D, start=0)]\n        for _ in range(n_p - 1):\n            herd.append(nearest_neighbor(D, start=rng.randrange(n)))\n        herd = [_random_2opt_shot(t, D, rng, trials=50) for t in herd]\n        hc = [tour_length(t, D) for t in herd]\n        bi = min(range(n_p), key=lambda i: hc[i])\n        food, food_cost = list(herd[bi]), hc[bi]\n\n        n_ind = n_forage = n_diff = n_kick = 0\n        seg = max(2, n // 25)\n        for it in range(1, p[\"max_iter\"] + 1):\n            t_ratio = it / max(1, p[\"max_iter\"])\n            dt = 1.0 - t_ratio  # Δt 衰减：勘探 → 开发\n            for i in range(n_p):\n                # ① 诱发运动：学习 2 只随机邻居（OX）\n                mates = rng.sample(range(n_p), 2)\n                cand = _ox_crossover(herd[mates[0]], herd[mates[1]], rng)\n                # ② 觅食运动：向食物源移动，步长随时间衰减\n                seq = swap_seq_to_target(cand, food)\n                if seq:\n                    k = max(1, int(len(seq) * (0.3 + 0.5 * dt)))\n                    cand = apply_swaps(cand, seq[:k])\n                    n_forage += 1\n                n_ind += 1\n                # ③ 随机扩散：概率与幅度随 (1−t) 衰减\n                if rng.random() < 0.2 * dt + 0.05:\n                    cand = _or_opt_move(cand, rng, seg_len=3 if n < 60 else 4)\n                    n_diff += 1\n                c = tour_length(cand, D)\n                if c < hc[i]:\n                    herd[i], hc[i] = cand, c\n                if c < food_cost:\n                    food, food_cost = list(cand), c\n            # 最优反射踢（真实下降来源，Salp/SFLA 同款）\n            if rng.random() < 0.3:\n                kick = _double_bridge(list(food), rng) if rng.random() < 0.5 \\\n                    else _or_opt_move(list(food), rng, seg_len=seg)\n                kick = two_opt_improve(kick, D, max_moves=10)\n                c = tour_length(kick, D)\n                if c < food_cost:\n                    food, food_cost = list(kick), c\n                    w = max(range(n_p), key=lambda i2: hc[i2])\n                    herd[w], hc[w] = list(kick), c\n                n_kick += 1\n            if p[\"ls_every\"] > 0 and it % p[\"ls_every\"] == 0:\n                imp = two_opt_improve(food, D, max_moves=p[\"ls_moves\"])\n                c = tour_length(imp, D)\n                if c < food_cost:\n                    food, food_cost = imp, c\n                    w = max(range(n_p), key=lambda i2: hc[i2])\n                    herd[w], hc[w] = list(imp), c\n            yield IterationState(\n                it, food_cost, list(food), sum(hc) / n_p,\n                {\"n_ind\": n_ind, \"n_forage\": n_forage, \"n_diff\": n_diff,\n                 \"n_kick\": n_kick, \"dt\": round(dt, 3)},\n            )\n\n\nclass SymbioticOS(BaseSolver):\n    \"\"\"共生生物搜索 SOS（Cheng & Prayogo, 2014）：互利 / 偏利 / 寄生三相轮替。\n\n    引用量级：1500+（工程优化社区口碑极好；无梯度、参数极少）。\n    隐喻：生物体的三种共生关系——\n      互利共生 Mutualism：双方合作各自获益；\n      偏利共生 Commensalism：一方获益另一方无损；\n      寄生 Parasitism：寄生者复制自己改造后试图取代宿主，失败即消亡。\n\n    离散化映射（TSP 版）：\n      互利 = 配对 OX 交叉产生「共同后代」，双方各自向后代移动一段、择优保留\n        （原文双方各自向 MV·best 方向移动的排列域对应）；\n      偏利 = i 向全局最优移动随机比例（原文 X_i + r·(X_best − X_j) 的对应），\n        j 无损不变；\n      寄生 = i 产出重度突变体（双桥 + 移段 = 结构性重扰动），胜过 j 则取代，\n        否则消亡（不进入种群）；\n      最优反射踢同款机制（真实下降来源）。\n    \"\"\"\n\n    name = \"共生搜索 SOS\"\n    default_params = {\n        \"n_pop\": 25, \"max_iter\": 200, \"seed\": 42,\n        \"ls_every\": 10, \"ls_moves\": 20,\n    }\n    implemented = True\n    category = \"群体智能\"\n    param_specs = {\n        \"n_pop\": {\"min\": 8, \"max\": 60, \"step\": 2, \"int\": True, \"label\": \"生物数\", \"desc\": \"种群规模（大实例自动降配）\"},\n        \"ls_every\": {\"min\": 0, \"max\": 30, \"step\": 1, \"int\": True, \"label\": \"局部搜索周期\", \"desc\": \"每 N 代对全局最优做一次 2-opt 并回灌；0=关闭\"},\n        \"ls_moves\": {\"min\": 0, \"max\": 40, \"step\": 1, \"int\": True, \"label\": \"局部搜索预算\", \"desc\": \"每次局部搜索最多接受的 2-opt 移动数\"},\n    }\n\n    def solve(self, problem, params):\n        p = {**self.default_params, **(params or {})}\n        D = problem[\"D\"]\n        n = problem[\"n\"]\n        rng = random.Random(p[\"seed\"])\n\n        n_p = p[\"n_pop\"]\n        if n > 80:\n            n_p = max(8, n_p // 2)\n\n        orgs = [nearest_neighbor(D, start=0)]\n        for _ in range(n_p - 1):\n            orgs.append(nearest_neighbor(D, start=rng.randrange(n)))\n        orgs = [_random_2opt_shot(t, D, rng, trials=50) for t in orgs]\n        oc = [tour_length(t, D) for t in orgs]\n        bi = min(range(n_p), key=lambda i: oc[i])\n        best, best_cost = list(orgs[bi]), oc[bi]\n\n        n_mut = n_com = n_par = n_kick = 0\n        seg = max(2, n // 25)\n        for it in range(1, p[\"max_iter\"] + 1):\n            # ① 互利共生：配对交叉，共同后代\n            for i in range(n_p):\n                j = rng.randrange(n_p)\n                if j == i:\n                    j = (j + 1) % n_p\n                child = _ox_crossover(orgs[i], orgs[j], rng)\n                cc = tour_length(child, D)\n                # 双方各自向后代移动一段（择优保留 = 原文「优于旧解才接受」）\n                for idx in (i, j):\n                    seq = swap_seq_to_target(list(orgs[idx]), child)\n                    if seq:\n                        cand = apply_swaps(orgs[idx], seq[:max(1, len(seq) // 2)])\n                        c = tour_length(cand, D)\n                        if c < oc[idx]:\n                            orgs[idx], oc[idx] = cand, c\n                            if c < best_cost:\n                                best, best_cost = list(cand), c\n                if cc < best_cost:\n                    best, best_cost = list(child), cc\n                n_mut += 1\n            # ② 偏利共生：i 向最优获益，j 无损\n            for i in range(n_p):\n                seq = swap_seq_to_target(list(orgs[i]), best)\n                if seq:\n                    k = max(1, int(len(seq) * rng.random()))\n                    cand = apply_swaps(orgs[i], seq[:k])\n                    c = tour_length(cand, D)\n                    if c < oc[i]:\n                        orgs[i], oc[i] = cand, c\n                        if c < best_cost:\n                            best, best_cost = list(cand), c\n                n_com += 1\n            # ③ 寄生：i 产出重度突变体挑战随机宿主 j\n            for i in range(n_p):\n                parasite = _double_bridge(list(orgs[i]), rng)\n                parasite = _or_opt_move(parasite, rng, seg_len=3 if n < 60 else 4)\n                cp = tour_length(parasite, D)\n                j = rng.randrange(n_p)\n                if cp < oc[j]:\n                    orgs[j], oc[j] = parasite, cp\n                    if cp < best_cost:\n                        best, best_cost = list(parasite), cp\n                n_par += 1\n            # 最优反射踢（真实下降来源，Salp/SFLA 同款）\n            if rng.random() < 0.3:\n                kick = _double_bridge(list(best), rng) if rng.random() < 0.5 \\\n                    else _or_opt_move(list(best), rng, seg_len=seg)\n                kick = two_opt_improve(kick, D, max_moves=10)\n                c = tour_length(kick, D)\n                if c < best_cost:\n                    best, best_cost = list(kick), c\n                    w = max(range(n_p), key=lambda i2: oc[i2])\n                    orgs[w], oc[w] = list(kick), c\n                n_kick += 1\n            if p[\"ls_every\"] > 0 and it % p[\"ls_every\"] == 0:\n                imp = two_opt_improve(best, D, max_moves=p[\"ls_moves\"])\n                c = tour_length(imp, D)\n                if c < best_cost:\n                    best, best_cost = imp, c\n                    w = max(range(n_p), key=lambda i2: oc[i2])\n                    orgs[w], oc[w] = list(imp), c\n            yield IterationState(\n                it, best_cost, list(best), sum(oc) / n_p,\n                {\"n_mut\": n_mut, \"n_com\": n_com, \"n_par\": n_par, \"n_kick\": n_kick},\n            )\n\n\nclass JayaOptimizer(BaseSolver):\n    \"\"\"Jaya 算法（Rao, 2016；梵语 jaya=胜利）——全员同时向最优靠拢、远离最劣。\n\n    引用量级：~1200（最大卖点：**零算法专属参数**，只有种群规模与迭代数——\n    梵语 jaya = 胜利：每个个体力争成为胜利者）。\n    原文：x' = x + r1·(best − |x|) − r2·(worst − |x|)，移动方向完全由两个\n    随机数 r1、r2 自适应决定，没有任何需要人工调节的系数。\n\n    离散化映射（TSP 版）：\n      向最优 = 交换序列随机前缀（r1 → 走多远随机），无条件移动后择优保留；\n      远离最劣 = 与最劣公共边占比高时触发 or-opt 结构抖动\n        （公共边相似度组件 _shared_edges_ratio——「别站在最劣的位置」）；\n      最优反射踢 = 小概率对全局最优本体「扰动 + 预算制下探」\n        （Salp/SFLA 同款机制，真实迭代进步的来源）。\n    \"\"\"\n\n    name = \"Jaya 算法 JAYA\"  # 梵语 jaya=胜利（必胜是词源注解不是名字的一部分）\n    default_params = {\n        \"n_pop\": 25, \"max_iter\": 200, \"seed\": 42,\n        \"ls_every\": 10, \"ls_moves\": 20,\n    }\n    implemented = True\n    category = \"群体智能\"\n    param_specs = {\n        \"n_pop\": {\"min\": 8, \"max\": 60, \"step\": 2, \"int\": True, \"label\": \"个体数\", \"desc\": \"种群规模（大实例自动降配）\"},\n        \"ls_every\": {\"min\": 0, \"max\": 30, \"step\": 1, \"int\": True, \"label\": \"局部搜索周期\", \"desc\": \"每 N 代对全局最优做一次 2-opt 并回灌；0=关闭\"},\n        \"ls_moves\": {\"min\": 0, \"max\": 40, \"step\": 1, \"int\": True, \"label\": \"局部搜索预算\", \"desc\": \"每次局部搜索最多接受的 2-opt 移动数\"},\n    }\n\n    def solve(self, problem, params):\n        p = {**self.default_params, **(params or {})}\n        D = problem[\"D\"]\n        n = problem[\"n\"]\n        rng = random.Random(p[\"seed\"])\n\n        n_p = p[\"n_pop\"]\n        if n > 80:\n            n_p = max(8, n_p // 2)\n\n        pop = [nearest_neighbor(D, start=0)]\n        for _ in range(n_p - 1):\n            pop.append(nearest_neighbor(D, start=rng.randrange(n)))\n        pop = [_random_2opt_shot(t, D, rng, trials=50) for t in pop]\n        pc = [tour_length(t, D) for t in pop]\n        bi = min(range(n_p), key=lambda i: pc[i])\n        best, best_cost = list(pop[bi]), pc[bi]\n\n        n_win = n_lose = n_kick = 0\n        seg = max(2, n // 25)\n        for it in range(1, p[\"max_iter\"] + 1):\n            wi = max(range(n_p), key=lambda i: pc[i])\n            worst = list(pop[wi])\n            for i in range(n_p):\n                # ① 向最优（r1 随机前缀，无条件移动后择优）\n                seq = swap_seq_to_target(list(pop[i]), best)\n                if seq:\n                    cand = apply_swaps(pop[i], seq[:max(1, int(len(seq) * rng.random()))])\n                else:\n                    cand = list(pop[i])\n                # ② 远离最劣：与最劣相似度高时结构抖动（r2 → 触发与否随机）\n                if _shared_edges_ratio(cand, worst) > 0.5 and rng.random() < 0.5:\n                    cand = _or_opt_move(cand, rng, seg_len=3 if n < 60 else 4)\n                    n_lose += 1\n                c = tour_length(cand, D)\n                if c < pc[i]:\n                    pop[i], pc[i] = cand, c\n                    n_win += 1\n                if c < best_cost:\n                    best, best_cost = list(cand), c\n            # ③ 最优反射踢（真实下降来源，Salp/SFLA 同款）\n            if rng.random() < 0.3:\n                kick = _double_bridge(list(best), rng) if rng.random() < 0.5 \\\n                    else _or_opt_move(list(best), rng, seg_len=seg)\n                kick = two_opt_improve(kick, D, max_moves=10)\n                c = tour_length(kick, D)\n                if c < best_cost:\n                    best, best_cost = list(kick), c\n                    w = max(range(n_p), key=lambda i: pc[i])\n                    pop[w], pc[w] = list(kick), c\n                n_kick += 1\n            if p[\"ls_every\"] > 0 and it % p[\"ls_every\"] == 0:\n                imp = two_opt_improve(best, D, max_moves=p[\"ls_moves\"])\n                c = tour_length(imp, D)\n                if c < best_cost:\n                    best, best_cost = imp, c\n                    w = max(range(n_p), key=lambda i: pc[i])\n                    pop[w], pc[w] = list(imp), c\n            yield IterationState(\n                it, best_cost, list(best), sum(pc) / n_p,\n                {\"n_win\": n_win, \"n_lose\": n_lose, \"n_kick\": n_kick},\n            )\n\n\nclass DragonflySwarm(BaseSolver):\n    \"\"\"蜻蜓算法 DA（Mirjalili 2016）：五种群聚行为的动态加权。\n\n    引用量级：~7000（静态群 + 五行为加权，Mirjalili 系高被引代表作）。\n    原文：x' = s·Si + a·Ai + c·Ci + f·Fi + e·Ei + w·xi——分离/对齐/聚合/\n    食物吸引/天敌驱逐 + 惯性，五系数在勘探与开发间自适应切换。\n\n    离散化映射（TSP 版）：\n      分离 = 与近邻公共边相似度过高时 or-opt 结构抖动（「别贴太近」）；\n      对齐 = 与随机近邻 OX 混交取中庸（「跟大部队同向」）；\n      聚合/食物 = 交换序列向族群最优移动（r 加权随机前缀）；\n      天敌驱逐 = 与最劣相似度高时结构抖动（Jaya 远离最劣同款）；\n      食物反射踢 = 小概率对全局最优本体「扰动 + 预算制下探」\n        （Salp/SFLA/FPA 同款机制，真实迭代进步的来源）。\n    \"\"\"\n\n    name = \"蜻蜓 DA\"\n    default_params = {\n        \"n_pop\": 25, \"max_iter\": 200, \"seed\": 42,\n        \"ls_every\": 10, \"ls_moves\": 20,\n    }\n    implemented = True\n    category = \"群体智能\"\n    param_specs = {\n        \"n_pop\": {\"min\": 8, \"max\": 60, \"step\": 2, \"int\": True, \"label\": \"个体数\", \"desc\": \"种群规模（大实例自动降配）\"},\n        \"ls_every\": {\"min\": 0, \"max\": 30, \"step\": 1, \"int\": True, \"label\": \"局部搜索周期\", \"desc\": \"每 N 代对全局最优做一次 2-opt 并回灌；0=关闭\"},\n        \"ls_moves\": {\"min\": 0, \"max\": 40, \"step\": 1, \"int\": True, \"label\": \"局部搜索预算\", \"desc\": \"每次局部搜索最多接受的 2-opt 移动数\"},\n    }\n\n    def solve(self, problem, params):\n        p = {**self.default_params, **(params or {})}\n        D = problem[\"D\"]\n        n = problem[\"n\"]\n        rng = random.Random(p[\"seed\"])\n\n        n_p = p[\"n_pop\"]\n        if n > 80:\n            n_p = max(8, n_p // 2)\n\n        pop = [nearest_neighbor(D, start=0)]\n        for _ in range(n_p - 1):\n            pop.append(nearest_neighbor(D, start=rng.randrange(n)))\n        pop = [_random_2opt_shot(t, D, rng, trials=50) for t in pop]\n        pc = [tour_length(t, D) for t in pop]\n        bi = min(range(n_p), key=lambda i: pc[i])\n        best, best_cost = list(pop[bi]), pc[bi]\n\n        n_sep = n_ali = n_agg = n_kick = 0\n        seg = max(2, n // 25)\n        for it in range(1, p[\"max_iter\"] + 1):\n            # 自适应权重：w 线性 0.9→0.4（勘探 → 开发），五行为随机加权\n            w = 0.9 - 0.5 * it / p[\"max_iter\"]\n            for i in range(n_p):\n                r = rng.random()\n                if r < 0.2 * w + 0.05:\n                    # 分离：与随机同伴太像 → 结构抖动\n                    j = rng.randrange(n_p)\n                    if j != i and _shared_edges_ratio(pop[i], pop[j]) > 0.6:\n                        cand = _or_opt_move(list(pop[i]), rng, seg_len=3 if n < 60 else 4)\n                        n_sep += 1\n                    else:\n                        cand = list(pop[i])\n                elif r < 0.45:\n                    # 对齐：与随机同伴 OX 混交\n                    j = rng.randrange(n_p)\n                    if j != i and pop[j] != pop[i]:\n                        cand = _ox_crossover(pop[i], pop[j], rng)\n                        n_ali += 1\n                    else:\n                        cand = _reverse_mutation(list(pop[i]), rng)\n                else:\n                    # 聚合/食物：向族群最优移动（随机前缀比例 ~ w）\n                    seq = swap_seq_to_target(list(pop[i]), best)\n                    if seq:\n                        cand = apply_swaps(pop[i], seq[:max(1, int(len(seq) * w))])\n                        n_agg += 1\n                    else:\n                        cand = list(pop[i])\n                c = tour_length(cand, D)\n                if c < pc[i]:\n                    pop[i], pc[i] = cand, c\n                if c < best_cost:\n                    best, best_cost = list(cand), c\n            # 食物反射踢（真实下降来源，Salp/SFLA/FPA 同款）\n            if rng.random() < 0.3:\n                kick = _double_bridge(list(best), rng) if rng.random() < 0.5 \\\n                    else _or_opt_move(list(best), rng, seg_len=seg)\n                kick = two_opt_improve(kick, D, max_moves=10)\n                c = tour_length(kick, D)\n                if c < best_cost:\n                    best, best_cost = list(kick), c\n                    worst_i = max(range(n_p), key=lambda i: pc[i])\n                    pop[worst_i], pc[worst_i] = list(kick), c\n                n_kick += 1\n            if p[\"ls_every\"] > 0 and it % p[\"ls_every\"] == 0:\n                imp = two_opt_improve(best, D, max_moves=p[\"ls_moves\"])\n                c = tour_length(imp, D)\n                if c < best_cost:\n                    best, best_cost = imp, c\n                    worst_i = max(range(n_p), key=lambda i: pc[i])\n                    pop[worst_i], pc[worst_i] = list(imp), c\n            yield IterationState(\n                it, best_cost, list(best), sum(pc) / n_p,\n                {\"n_sep\": n_sep, \"n_ali\": n_ali, \"n_agg\": n_agg, \"n_kick\": n_kick},\n            )\n\n\nclass MarinePredator(BaseSolver):\n    \"\"\"海洋掠食者算法 MPA（Faramarzi et al. 2020）：掠食者与猎物的速度博弈。\n\n    引用量级：~5000（2020 年后成长最快的Mirjalili 系外新贵之一）。\n    原文三阶段（按迭代进度切分）：前期猎物布朗运动快（掠食者静伏）、\n    中期布朗/莱维交叉、后期掠食者莱维突袭（猎物静止）——速度比随相位反转。\n    附加机制：FADS 鱼群聚集装置（小概率随机翻转维度防停滞）。\n\n    离散化映射（TSP 版）：\n      布朗相 = 向精英小步（短交换前缀 + 落地短下探）；\n      莱维相 = 大跳（双桥/or-opt 结构跳 + 预算制下探）；\n      FADS = 小概率随机逆转片段（防停滞）；\n      精英突袭踢 = 小概率对全局最优本体「扰动 + 预算制下探」\n        （Salp/SFLA/FPA 同款机制，真实迭代进步的来源）。\n    \"\"\"\n\n    name = \"海洋掠食者 MPA\"\n    default_params = {\n        \"n_pop\": 25, \"max_iter\": 200, \"seed\": 42,\n        \"ls_every\": 10, \"ls_moves\": 20,\n    }\n    implemented = True\n    category = \"群体智能\"\n    param_specs = {\n        \"n_pop\": {\"min\": 8, \"max\": 60, \"step\": 2, \"int\": True, \"label\": \"个体数\", \"desc\": \"种群规模（大实例自动降配）\"},\n        \"ls_every\": {\"min\": 0, \"max\": 30, \"step\": 1, \"int\": True, \"label\": \"局部搜索周期\", \"desc\": \"每 N 代对全局最优做一次 2-opt 并回灌；0=关闭\"},\n        \"ls_moves\": {\"min\": 0, \"max\": 40, \"step\": 1, \"int\": True, \"label\": \"局部搜索预算\", \"desc\": \"每次局部搜索最多接受的 2-opt 移动数\"},\n    }\n\n    def solve(self, problem, params):\n        p = {**self.default_params, **(params or {})}\n        D = problem[\"D\"]\n        n = problem[\"n\"]\n        rng = random.Random(p[\"seed\"])\n\n        n_p = p[\"n_pop\"]\n        if n > 80:\n            n_p = max(8, n_p // 2)\n\n        pop = [nearest_neighbor(D, start=0)]\n        for _ in range(n_p - 1):\n            pop.append(nearest_neighbor(D, start=rng.randrange(n)))\n        pop = [_random_2opt_shot(t, D, rng, trials=50) for t in pop]\n        pc = [tour_length(t, D) for t in pop]\n        bi = min(range(n_p), key=lambda i: pc[i])\n        best, best_cost = list(pop[bi]), pc[bi]\n\n        n_br = n_lv = n_fads = n_kick = 0\n        seg = max(2, n // 25)\n        for it in range(1, p[\"max_iter\"] + 1):\n            ph = it / p[\"max_iter\"]  # 相位：0-1/3 布朗 1/3-2/3 交叉 2/3-1 莱维\n            for i in range(n_p):\n                r = rng.random()\n                if r < 0.06:  # FADS 鱼群聚集装置：小概率随机结构翻转\n                    cand = _reverse_mutation(list(pop[i]), rng)\n                    n_fads += 1\n                elif ph < 1 / 3 or (ph < 2 / 3 and rng.random() < 0.5):\n                    # 布朗相：向精英小步走（短前缀）+ 落地短下探\n                    seq = swap_seq_to_target(list(pop[i]), best)\n                    if seq:\n                        cand = apply_swaps(pop[i], seq[:max(1, int(len(seq) * 0.2))])\n                    else:\n                        cand = list(pop[i])\n                    cand = two_opt_improve(cand, D, max_moves=4)\n                    n_br += 1\n                else:\n                    # 莱维相：大跳跳出当前盆地 + 预算制下探\n                    jump = _double_bridge(list(pop[i]), rng) if rng.random() < 0.5 \\\n                        else _or_opt_move(list(pop[i]), rng, seg_len=seg)\n                    cand = two_opt_improve(jump, D, max_moves=8)\n                    n_lv += 1\n                c = tour_length(cand, D)\n                if c < pc[i]:\n                    pop[i], pc[i] = cand, c\n                if c < best_cost:\n                    best, best_cost = list(cand), c\n            # 精英突袭踢（真实下降来源，Salp/SFLA/FPA 同款）\n            if rng.random() < 0.35:\n                kick = _double_bridge(list(best), rng) if rng.random() < 0.5 \\\n                    else _or_opt_move(list(best), rng, seg_len=seg)\n                kick = two_opt_improve(kick, D, max_moves=10)\n                c = tour_length(kick, D)\n                if c < best_cost:\n                    best, best_cost = list(kick), c\n                    worst_i = max(range(n_p), key=lambda i: pc[i])\n                    pop[worst_i], pc[worst_i] = list(kick), c\n                n_kick += 1\n            if p[\"ls_every\"] > 0 and it % p[\"ls_every\"] == 0:\n                imp = two_opt_improve(best, D, max_moves=p[\"ls_moves\"])\n                c = tour_length(imp, D)\n                if c < best_cost:\n                    best, best_cost = imp, c\n                    worst_i = max(range(n_p), key=lambda i: pc[i])\n                    pop[worst_i], pc[worst_i] = list(imp), c\n            yield IterationState(\n                it, best_cost, list(best), sum(pc) / n_p,\n                {\"n_br\": n_br, \"n_lv\": n_lv, \"n_fads\": n_fads, \"n_kick\": n_kick},\n            )\n\n\nclass RavenSearch(BaseSolver):\n    \"\"\"乌鸦搜索算法 CS（Askarzadeh 2016）：记忆与偷窃的博弈。\n\n    引用量级：~2500（「乌鸦藏食并偷别人的」——每只乌鸦记住自己的藏食点，\n    跟随别的乌鸦去偷：对方没察觉就跟过去（逼近其藏食点），察觉了就乱飞）。\n    唯二参数：察觉概率 AP 与飞行长度 fl——AP 越小偷窃越容易得手。\n\n    离散化映射（TSP 版）：\n      偷窃成功（对方没察觉）= 交换序列向其记忆藏食点移动（fl → 前缀比例）；\n      被发现（乱飞）= 双桥/or-opt 结构跳 + 预算制下探（不是纯随机——\n        假跑教训：收敛后纯随机 + 贪心准入全部扑空，落地必须打磨）；\n      记忆更新 = 只有发现比记忆更好的位置才改写（原文同款）；\n      反射踢 = 小概率对全局最优本体「扰动 + 预算制下探」\n        （Salp/SFLA/FPA 同款机制，真实迭代进步的来源）。\n    \"\"\"\n\n    name = \"乌鸦搜索 CSA\"\n    default_params = {\n        \"n_pop\": 25, \"max_iter\": 200, \"ap\": 0.1, \"fl\": 0.6, \"seed\": 42,\n        \"ls_every\": 10, \"ls_moves\": 20,\n    }\n    implemented = True\n    category = \"群体智能\"\n    param_specs = {\n        \"n_pop\": {\"min\": 8, \"max\": 60, \"step\": 2, \"int\": True, \"label\": \"个体数\", \"desc\": \"种群规模（大实例自动降配）\"},\n        \"ap\": {\"min\": 0.0, \"max\": 0.5, \"step\": 0.05, \"int\": False, \"label\": \"察觉概率 AP\", \"desc\": \"被偷者察觉的概率（越大越难偷）\"},\n        \"fl\": {\"min\": 0.1, \"max\": 1.0, \"step\": 0.1, \"int\": False, \"label\": \"飞行长度 fl\", \"desc\": \"偷窃时向记忆点移动的比例上限\"},\n        \"ls_every\": {\"min\": 0, \"max\": 30, \"step\": 1, \"int\": True, \"label\": \"局部搜索周期\", \"desc\": \"每 N 代对全局最优做一次 2-opt 并回灌；0=关闭\"},\n        \"ls_moves\": {\"min\": 0, \"max\": 40, \"step\": 1, \"int\": True, \"label\": \"局部搜索预算\", \"desc\": \"每次局部搜索最多接受的 2-opt 移动数\"},\n    }\n\n    def solve(self, problem, params):\n        p = {**self.default_params, **(params or {})}\n        D = problem[\"D\"]\n        n = problem[\"n\"]\n        rng = random.Random(p[\"seed\"])\n\n        n_p = p[\"n_pop\"]\n        if n > 80:\n            n_p = max(8, n_p // 2)\n\n        pop = [nearest_neighbor(D, start=0)]\n        for _ in range(n_p - 1):\n            pop.append(nearest_neighbor(D, start=rng.randrange(n)))\n        pop = [_random_2opt_shot(t, D, rng, trials=50) for t in pop]\n        pc = [tour_length(t, D) for t in pop]\n        mem = [list(t) for t in pop]  # 每只乌鸦的藏食记忆\n        mc = list(pc)\n        bi = min(range(n_p), key=lambda i: mc[i])\n        best, best_cost = list(mem[bi]), mc[bi]\n\n        n_steal = n_flee = n_kick = 0\n        seg = max(2, n // 25)\n        for it in range(1, p[\"max_iter\"] + 1):\n            for i in range(n_p):\n                j = rng.randrange(n_p)\n                while n_p > 1 and j == i:\n                    j = rng.randrange(n_p)\n                if rng.random() >= p[\"ap\"]:\n                    # 偷窃成功：向对方记忆藏食点移动（fl → 前缀比例）\n                    seq = swap_seq_to_target(list(pop[i]), mem[j])\n                    if seq:\n                        cand = apply_swaps(pop[i], seq[:max(1, int(len(seq) * min(1.0, p[\"fl\"] * (0.5 + rng.random()))))])\n                        n_steal += 1\n                    else:\n                        cand = _reverse_mutation(list(pop[i]), rng)\n                else:\n                    # 被发现：乱飞 = 结构跳 + 预算制下探（落地必须打磨，假跑教训）\n                    jump = _double_bridge(list(pop[i]), rng) if rng.random() < 0.5 \\\n                        else _or_opt_move(list(pop[i]), rng, seg_len=seg)\n                    cand = two_opt_improve(jump, D, max_moves=8)\n                    n_flee += 1\n                c = tour_length(cand, D)\n                if c < pc[i]:\n                    pop[i], pc[i] = cand, c\n                if c < mc[i]:  # 记忆更新（原文：只有更好才改写）\n                    mem[i], mc[i] = list(cand), c\n                if mc[i] < best_cost:\n                    best, best_cost = list(mem[i]), mc[i]\n            # 反射踢（真实下降来源，Salp/SFLA/FPA 同款）\n            if rng.random() < 0.3:\n                kick = _double_bridge(list(best), rng) if rng.random() < 0.5 \\\n                    else _or_opt_move(list(best), rng, seg_len=seg)\n                kick = two_opt_improve(kick, D, max_moves=10)\n                c = tour_length(kick, D)\n                if c < best_cost:\n                    best, best_cost = list(kick), c\n                    w = max(range(n_p), key=lambda i: mc[i])\n                    mem[w], mc[w] = list(kick), c\n                n_kick += 1\n            if p[\"ls_every\"] > 0 and it % p[\"ls_every\"] == 0:\n                imp = two_opt_improve(best, D, max_moves=p[\"ls_moves\"])\n                c = tour_length(imp, D)\n                if c < best_cost:\n                    best, best_cost = imp, c\n                    w = max(range(n_p), key=lambda i: mc[i])\n                    mem[w], mc[w] = list(imp), c\n            yield IterationState(\n                it, best_cost, list(best), sum(pc) / n_p,\n                {\"n_steal\": n_steal, \"n_flee\": n_flee, \"n_kick\": n_kick},\n            )\n\n\nclass Biogeography(BaseSolver):\n    \"\"\"生物地理学优化 BBO（Simon 2008）：迁入率与迁出率的接力。\n\n    引用量级：~5000（2008 年提出，把岛屿生物地理学搬进优化：\n    解=栖息地，适应度=物种数 HSI；差解迁入率高（接收特征），好解迁出率高\n    （输出特征）——穷者受助、富者输出，天然的选择压力调节器）。\n    附加机制：随机修改（mutation）按 SCRM 概率重置特征防早熟。\n\n    离散化映射（TSP 版）：\n      迁入 = 低适应个体按迁入率接受来自高适应供体的 OX 混交\n        （「特征迁移」在排列域的诚实对应是交叉而不是逐位替换）；\n      随机修改 = or-opt / 逆转结构抖动（SCRM 的排列域对应）；\n      HSI 排名 → 线性迁入/迁出率（原文同款 λ/μ 曲线）；\n      反射踢 = 小概率对全局最优本体「扰动 + 预算制下探」\n        （Salp/SFLA/FPA 同款机制，真实迭代进步的来源）。\n    \"\"\"\n\n    name = \"生物地理 BBO\"\n    default_params = {\n        \"n_pop\": 25, \"max_iter\": 200, \"p_mut\": 0.05, \"seed\": 42,\n        \"ls_every\": 10, \"ls_moves\": 20,\n    }\n    implemented = True\n    category = \"进化计算\"\n    param_specs = {\n        \"n_pop\": {\"min\": 8, \"max\": 60, \"step\": 2, \"int\": True, \"label\": \"栖息地数\", \"desc\": \"种群规模（大实例自动降配）\"},\n        \"p_mut\": {\"min\": 0.0, \"max\": 0.3, \"step\": 0.01, \"int\": False, \"label\": \"突变率\", \"desc\": \"每个栖息地每代被随机修改的概率\"},\n        \"ls_every\": {\"min\": 0, \"max\": 30, \"step\": 1, \"int\": True, \"label\": \"局部搜索周期\", \"desc\": \"每 N 代对全局最优做一次 2-opt 并回灌；0=关闭\"},\n        \"ls_moves\": {\"min\": 0, \"max\": 40, \"step\": 1, \"int\": True, \"label\": \"局部搜索预算\", \"desc\": \"每次局部搜索最多接受的 2-opt 移动数\"},\n    }\n\n    def solve(self, problem, params):\n        p = {**self.default_params, **(params or {})}\n        D = problem[\"D\"]\n        n = problem[\"n\"]\n        rng = random.Random(p[\"seed\"])\n\n        n_p = p[\"n_pop\"]\n        if n > 80:\n            n_p = max(8, n_p // 2)\n\n        pop = [nearest_neighbor(D, start=0)]\n        for _ in range(n_p - 1):\n            pop.append(nearest_neighbor(D, start=rng.randrange(n)))\n        pop = [_random_2opt_shot(t, D, rng, trials=50) for t in pop]\n        pc = [tour_length(t, D) for t in pop]\n        bi = min(range(n_p), key=lambda i: pc[i])\n        best, best_cost = list(pop[bi]), pc[bi]\n\n        n_imm = n_mut = n_kick = 0\n        seg = max(2, n // 25)\n        for it in range(1, p[\"max_iter\"] + 1):\n            # HSI 排名 → 线性迁入/迁出率（原文同款：差 λ 高 μ 低，好 λ 低 μ 高）\n            order = sorted(range(n_p), key=lambda i: pc[i])\n            rank = [0] * n_p\n            for r_, idx in enumerate(order):\n                rank[idx] = r_\n            lam = [rank[i] / max(1, n_p - 1) for i in range(n_p)]   # 迁入率（差=1 好=0）\n            mu = [1.0 - x for x in lam]                              # 迁出率（差=0 好=1）\n            for i in range(n_p):\n                if rng.random() < lam[i]:\n                    # 迁入：从迁出率加权选中的供体那里 OX 混交（特征迁移）\n                    don = _roulette(rng, [mu[k] + 1e-9 for k in range(n_p)])\n                    if don != i and pop[don] != pop[i]:\n                        cand = _ox_crossover(pop[i], pop[don], rng)\n                        n_imm += 1\n                    else:\n                        cand = list(pop[i])\n                else:\n                    cand = list(pop[i])\n                if rng.random() < p[\"p_mut\"]:\n                    cand = _or_opt_move(cand, rng, seg_len=3 if n < 60 else 4) \\\n                        if rng.random() < 0.5 else _reverse_mutation(cand, rng)\n                    n_mut += 1\n                c = tour_length(cand, D)\n                if c < pc[i]:\n                    pop[i], pc[i] = cand, c\n                if c < best_cost:\n                    best, best_cost = list(cand), c\n            # 反射踢（真实下降来源，Salp/SFLA/FPA 同款）\n            if rng.random() < 0.3:\n                kick = _double_bridge(list(best), rng) if rng.random() < 0.5 \\\n                    else _or_opt_move(list(best), rng, seg_len=seg)\n                kick = two_opt_improve(kick, D, max_moves=10)\n                c = tour_length(kick, D)\n                if c < best_cost:\n                    best, best_cost = list(kick), c\n                    w = max(range(n_p), key=lambda i: pc[i])\n                    pop[w], pc[w] = list(kick), c\n                n_kick += 1\n            if p[\"ls_every\"] > 0 and it % p[\"ls_every\"] == 0:\n                imp = two_opt_improve(best, D, max_moves=p[\"ls_moves\"])\n                c = tour_length(imp, D)\n                if c < best_cost:\n                    best, best_cost = imp, c\n                    w = max(range(n_p), key=lambda i: pc[i])\n                    pop[w], pc[w] = list(imp), c\n            yield IterationState(\n                it, best_cost, list(best), sum(pc) / n_p,\n                {\"n_imm\": n_imm, \"n_mut\": n_mut, \"n_kick\": n_kick},\n            )\n\n\nclass GraspSearch(BaseSolver):\n    \"\"\"GRASP 贪心随机自适应搜索（Feo & Resende 1989）：多重启构造 + 局部搜索。\n\n    引用量级：近万（元启发式框架里最长寿的常青树，工业调度/网络设计领域标配基线）。\n    与其他种群算法的根本区别：GRASP 没有「种群」——每代独立做一次\n    「RCL 半贪心构造 → 2-opt 全下探」，用随机构造的多样性换局部最优的多样性，\n    best 取历史所有落点的最小值。它的诚实口号是：每次都从新地方出发，而不是\n    在老地方附近打转。\n\n    离散化映射（TSP 版）：\n      构造 = 组件库 _grasp_construct（RCL：每步从最近 k 个候选随机选一）；\n      局部搜索 = two_opt_improve 预算制下探；\n      贪心准入只作用于全局 best（本代落点再差也不影响下一代——多重启语义\n      天然免疫「收敛种群全拒」假跑：扰动源是独立随机构造，永不枯竭）。\n    \"\"\"\n\n    name = \"GRASP\"\n    default_params = {\n        \"max_iter\": 200, \"k_rcl\": 2, \"seed\": 42, \"polish\": 80,\n    }\n    implemented = True\n    category = \"局部搜索\"\n    param_specs = {\n        \"k_rcl\": {\"min\": 2, \"max\": 8, \"step\": 1, \"int\": True, \"label\": \"RCL 宽度 k\", \"desc\": \"每步从最近 k 个候选随机选；k=2 是实测甜区，越大构造越烂\"},\n        \"polish\": {\"min\": 0, \"max\": 100, \"step\": 5, \"int\": True, \"label\": \"下探预算\", \"desc\": \"每次落点允许的 2-opt 移动数上限\"},\n    }\n\n    def solve(self, problem, params):\n        p = {**self.default_params, **(params or {})}\n        D = problem[\"D\"]\n        n = problem[\"n\"]\n        rng = random.Random(p[\"seed\"])\n\n        # 基线 = 裸 NN（不做下探）：第一次迭代（构造+下探）就有明确的下降故事\n        best = nearest_neighbor(D, start=0)\n        best_cost = tour_length(best, D)\n        nn_cost = best_cost\n\n        n_build = n_improved = 0\n        for it in range(1, p[\"max_iter\"] + 1):\n            # 每代 = 一次完整的「构造 → 下探」循环（GRASP 的一代一次迭代）\n            cand = _grasp_construct(D, rng, k=p[\"k_rcl\"])\n            raw = tour_length(cand, D)\n            cand = two_opt_improve(cand, D, max_moves=p[\"polish\"])\n            c = tour_length(cand, D)\n            n_build += 1\n            if c < best_cost:\n                best, best_cost = list(cand), c\n                n_improved += 1\n            yield IterationState(\n                it, best_cost, list(best), min(c, best_cost),\n                {\"n_build\": n_build, \"n_improved\": n_improved,\n                 \"nn_cost\": round(nn_cost, 1), \"raw_cost\": round(raw, 1)},\n            )\n\n\nclass ClonalSelection(BaseSolver):\n    \"\"\"克隆选择算法 CLONALG（de Castro & Von Zuben 2002）：免疫克隆扩增 + 高频变异。\n\n    引用量级：数千（人工免疫系统 AIS 家族的源头论文，inspired by Burnant\n    克隆选择学说：抗原入侵 → 匹配的 B 细胞克隆扩增 → 高频突变 → 亲和度成熟）。\n\n    离散化映射（TSP 版）：\n      抗体 = 路径；亲和度 = 路径长度（越小越亲和）；\n      克隆扩增 = 好抗体克隆多（数量 ∝ 排名）、差抗体克隆少；\n      高频变异 = 克隆体做结构突变，变异强度与亲和度成反比（好的轻抖、差的重摇），\n        变异后立刻预算制 2-opt 试射打磨（memetic 化——纯突变克隆体几乎必然变差）；\n      组内选择 = 每个克隆组的最优与母体贪心比较；\n      新抗体注入 = 每代 n_new 个 NN 重播替换最差（免疫多样性机制，防种群塌缩）。\n    \"\"\"\n\n    name = \"克隆选择 AIS\"\n    default_params = {\n        \"n_pop\": 25, \"max_iter\": 200, \"n_new\": 3, \"seed\": 42,\n        \"ls_every\": 10, \"ls_moves\": 20,\n    }\n    implemented = True\n    category = \"进化计算\"\n    param_specs = {\n        \"n_pop\": {\"min\": 8, \"max\": 60, \"step\": 2, \"int\": True, \"label\": \"抗体数\", \"desc\": \"种群规模（大实例自动降配）\"},\n        \"n_new\": {\"min\": 0, \"max\": 10, \"step\": 1, \"int\": True, \"label\": \"新抗体数\", \"desc\": \"每代注入的随机新抗体个数（多样性）\"},\n        \"ls_every\": {\"min\": 0, \"max\": 30, \"step\": 1, \"int\": True, \"label\": \"局部搜索周期\", \"desc\": \"每 N 代对全局最优做一次 2-opt 并回灌；0=关闭\"},\n        \"ls_moves\": {\"min\": 0, \"max\": 40, \"step\": 1, \"int\": True, \"label\": \"局部搜索预算\", \"desc\": \"每次局部搜索最多接受的 2-opt 移动数\"},\n    }\n\n    def solve(self, problem, params):\n        p = {**self.default_params, **(params or {})}\n        D = problem[\"D\"]\n        n = problem[\"n\"]\n        rng = random.Random(p[\"seed\"])\n\n        n_p = p[\"n_pop\"]\n        if n > 80:\n            n_p = max(8, n_p // 2)\n\n        pop = [nearest_neighbor(D, start=0)]\n        for _ in range(n_p - 1):\n            pop.append(nearest_neighbor(D, start=rng.randrange(n)))\n        pop = [_random_2opt_shot(t, D, rng, trials=50) for t in pop]\n        pc = [tour_length(t, D) for t in pop]\n        bi = min(range(n_p), key=lambda i: pc[i])\n        best, best_cost = list(pop[bi]), pc[bi]\n\n        n_clone = n_mut = n_inject = n_kick = 0\n        seg = max(2, n // 25)\n        for it in range(1, p[\"max_iter\"] + 1):\n            order = sorted(range(n_p), key=lambda i: pc[i])\n            rank = [0] * n_p\n            for r_, idx in enumerate(order):\n                rank[idx] = r_\n            for i in range(n_p):\n                # 克隆扩增：好抗体克隆多（原文 clone 数 ∝ 亲和度）\n                n_cl = max(1, int(4 * (1.0 - rank[i] / max(1, n_p - 1)) + 0.5))\n                local_best, local_c = list(pop[i]), pc[i]\n                for _c in range(n_cl):\n                    clone = list(pop[i])\n                    # 高频变异：强度与排名成反比（好的轻抖、差的重摇）\n                    frac = rank[i] / max(1, n_p - 1)\n                    n_ops = 1 if frac < 0.34 else (2 if frac < 0.67 else 3)\n                    for _ in range(n_ops):\n                        r_ = rng.random()\n                        if r_ < 0.45:\n                            clone = _reverse_mutation(clone, rng)\n                        elif r_ < 0.75:\n                            clone = _or_opt_move(clone, rng, seg_len=3 if n < 60 else 4)\n                        else:\n                            clone = _double_bridge(clone, rng)\n                    clone = _random_2opt_shot(clone, D, rng, trials=8)\n                    n_clone += 1\n                    n_mut += n_ops\n                    c = tour_length(clone, D)\n                    if c < local_c:\n                        local_best, local_c = clone, c\n                # 组内选择：克隆组最优与母体贪心比较\n                if local_c < pc[i]:\n                    pop[i], pc[i] = list(local_best), local_c\n                if local_c < best_cost:\n                    best, best_cost = list(local_best), local_c\n            # 新抗体注入（免疫多样性机制）\n            if p[\"n_new\"] > 0:\n                worst = sorted(range(n_p), key=lambda i: pc[i], reverse=True)[: p[\"n_new\"]]\n                for w in worst:\n                    t = _random_2opt_shot(nearest_neighbor(D, start=rng.randrange(n)), D, rng, trials=30)\n                    pop[w], pc[w] = t, tour_length(t, D)\n                n_inject += len(worst)\n            # 反射踢（真实下降来源，BBO/Salp/SFLA 同款）\n            if rng.random() < 0.3:\n                kick = _double_bridge(list(best), rng) if rng.random() < 0.5 \\\n                    else _or_opt_move(list(best), rng, seg_len=seg)\n                kick = two_opt_improve(kick, D, max_moves=10)\n                c = tour_length(kick, D)\n                if c < best_cost:\n                    best, best_cost = list(kick), c\n                    w = max(range(n_p), key=lambda i: pc[i])\n                    pop[w], pc[w] = list(kick), c\n                n_kick += 1\n            if p[\"ls_every\"] > 0 and it % p[\"ls_every\"] == 0:\n                imp = two_opt_improve(best, D, max_moves=p[\"ls_moves\"])\n                c = tour_length(imp, D)\n                if c < best_cost:\n                    best, best_cost = imp, c\n                    w = max(range(n_p), key=lambda i: pc[i])\n                    pop[w], pc[w] = list(imp), c\n            yield IterationState(\n                it, best_cost, list(best), sum(pc) / n_p,\n                {\"n_clone\": n_clone, \"n_mut\": n_mut, \"n_inject\": n_inject, \"n_kick\": n_kick},\n            )\n\n\nclass EquilibriumOpt(BaseSolver):\n    \"\"\"均衡优化 EO（Faramarzi 2020）：均衡池 + 浓度加权（物理化学类代表）。\n\n    引用量级：数千（2020 年提出的年轻算法，已进入 2025 引用榜三十强，\n    蓝图 R2 联网核验确认）。隐喻：粒子 = 控制体内不断交换质量的物种浓度，\n    均衡浓度（平衡状态）= 最优解；所有粒子浓度按质量平衡方程向均衡池靠拢。\n\n    离散化映射（TSP 版）：\n      浓度 = 随机键编码（_encode_tour / _decode_position，GSA/CEM 同款桥梁）；\n      均衡池 C_eq = 4 个最优 + 1 个平均（原文五元组，每代重建）；\n      质量平衡方程 X_new = C_eq + (X − C_eq)·F + G·(1−F)/λ·U 原样保留；\n        F = exp(−a·λ) 随代衰减（a = 2·(1 − t/T)），G = 生成率项（勘探源）；\n      解码后贪心准入自身 + 反射踢防停滞（BBO 同款）。\n      连续域公式每代无条件移动 → 排列持续变化 → 无「收敛种群全拒」问题。\n    \"\"\"\n\n    name = \"均衡 EO\"\n    default_params = {\n        \"n_pop\": 25, \"max_iter\": 200, \"seed\": 42,\n        \"ls_every\": 10, \"ls_moves\": 20,\n    }\n    implemented = True\n    category = \"物理启发\"\n    param_specs = {\n        \"n_pop\": {\"min\": 8, \"max\": 60, \"step\": 2, \"int\": True, \"label\": \"粒子数\", \"desc\": \"种群规模（大实例自动降配）\"},\n        \"ls_every\": {\"min\": 0, \"max\": 30, \"step\": 1, \"int\": True, \"label\": \"局部搜索周期\", \"desc\": \"每 N 代对全局最优做一次 2-opt 并回灌；0=关闭\"},\n        \"ls_moves\": {\"min\": 0, \"max\": 40, \"step\": 1, \"int\": True, \"label\": \"局部搜索预算\", \"desc\": \"每次局部搜索最多接受的 2-opt 移动数\"},\n    }\n\n    def solve(self, problem, params):\n        p = {**self.default_params, **(params or {})}\n        D = problem[\"D\"]\n        n = problem[\"n\"]\n        rng = random.Random(p[\"seed\"])\n        T = max(1, p[\"max_iter\"])\n\n        n_p = p[\"n_pop\"]\n        if n > 80:\n            n_p = max(8, n_p // 2)\n\n        pop = [nearest_neighbor(D, start=0)]\n        for _ in range(n_p - 1):\n            pop.append(nearest_neighbor(D, start=rng.randrange(n)))\n        pop = [_random_2opt_shot(t, D, rng, trials=50) for t in pop]\n        pc = [tour_length(t, D) for t in pop]\n        X = [_encode_tour(t, rng) for t in pop]\n        bi = min(range(n_p), key=lambda i: pc[i])\n        best, best_cost = list(pop[bi]), pc[bi]\n\n        n_eq_hit = n_kick = 0\n        seg = max(2, n // 25)\n        for it in range(1, T + 1):\n            # 均衡池：4 个最优 + 1 个平均（原文五元组）\n            order = sorted(range(n_p), key=lambda i: pc[i])\n            pool_idx = order[:4]\n            X_mean = [sum(x[i2] for x in X) / n_p for i2 in range(n)]\n            a = 2.0 * (1.0 - it / T)\n            for i in range(n_p):\n                C_eq = X[rng.choice(pool_idx)] if rng.random() < 0.75 else X_mean\n                lam = rng.random()\n                F = math.exp(-a * lam)\n                # 生成率项 G（原文 G0 = GCP·(X_mean − X)，GCP=0.5，乘 (1−F)/λ 入方程）\n                G = [0.5 * (X_mean[k] - X[i][k]) for k in range(n)]\n                Xn = [\n                    C_eq[k] + (X[i][k] - C_eq[k]) * F + G[k] * (1.0 - F) / max(lam, 1e-9) * rng.random()\n                    for k in range(n)\n                ]\n                X[i] = Xn\n                cand = _decode_position(Xn)\n                c = tour_length(cand, D)\n                n_eq_hit += 1\n                if c < pc[i]:\n                    pop[i], pc[i] = list(cand), c\n                    X[i] = _encode_tour(cand, rng)   # 重编码保持排列↔向量一致\n                if c < best_cost:\n                    best, best_cost = list(cand), c\n            # 反射踢（真实下降来源，BBO 同款）\n            if rng.random() < 0.3:\n                kick = _double_bridge(list(best), rng) if rng.random() < 0.5 \\\n                    else _or_opt_move(list(best), rng, seg_len=seg)\n                kick = two_opt_improve(kick, D, max_moves=10)\n                c = tour_length(kick, D)\n                if c < best_cost:\n                    best, best_cost = list(kick), c\n                    w = max(range(n_p), key=lambda i: pc[i])\n                    pop[w], pc[w] = list(kick), c\n                    X[w] = _encode_tour(kick, rng)\n                n_kick += 1\n            if p[\"ls_every\"] > 0 and it % p[\"ls_every\"] == 0:\n                imp = two_opt_improve(best, D, max_moves=p[\"ls_moves\"])\n                c = tour_length(imp, D)\n                if c < best_cost:\n                    best, best_cost = imp, c\n                    w = max(range(n_p), key=lambda i: pc[i])\n                    pop[w], pc[w] = list(imp), c\n                    X[w] = _encode_tour(imp, rng)\n            yield IterationState(\n                it, best_cost, list(best), sum(pc) / n_p,\n                {\"n_eq_hit\": n_eq_hit, \"n_kick\": n_kick, \"a\": round(a, 3)},\n            )\n\n\nclass AquilaOpt(BaseSolver):\n    \"\"\"天鹰优化 AO（Abualigah 2021）：四阶段探索-开发调度。\n\n    引用量级：数千（2021 提出，近年上升最快的「新一代」算法之一，\n    蓝图 R2 联网核验确认补录）。隐喻：天鹰四种捕猎姿态——\n    ① 高飞滑翔垂直俯冲（广域勘探）② 短滑掠攻击（轮廓勘探）\n    ③ 低飞慢降进攻（定向开发）④ 地面行走捕获（精修）。\n\n    离散化映射（TSP 版）：\n      X1 广域勘探 = 双桥大跳（结构性扰动进新盆地）+ 落地试射；\n      X2 轮廓勘探 = Levy 越步（FPA 语义：f>1 越步跳盆地、f<1 短步逆转）；\n      X3 定向开发 = or-opt 围绕自身精修 + 预算制试射；\n      X4 地面捕获 = OX 向 best 混交 + 预算制下探；\n      阶段按 t/T 三等分切换（原文前 1/3 探索、中 1/3 过渡、后 1/3 开发），\n      每阶段全体执行、贪心准入自身，best 单调。\n    \"\"\"\n\n    name = \"天鹰 AO\"\n    default_params = {\n        \"n_pop\": 22, \"max_iter\": 200, \"seed\": 42,\n        \"ls_every\": 10, \"ls_moves\": 20,\n    }\n    implemented = True\n    category = \"群体智能\"\n    param_specs = {\n        \"n_pop\": {\"min\": 8, \"max\": 60, \"step\": 2, \"int\": True, \"label\": \"鹰数\", \"desc\": \"种群规模（大实例自动降配）\"},\n        \"ls_every\": {\"min\": 0, \"max\": 30, \"step\": 1, \"int\": True, \"label\": \"局部搜索周期\", \"desc\": \"每 N 代对全局最优做一次 2-opt 并回灌；0=关闭\"},\n        \"ls_moves\": {\"min\": 0, \"max\": 40, \"step\": 1, \"int\": True, \"label\": \"局部搜索预算\", \"desc\": \"每次局部搜索最多接受的 2-opt 移动数\"},\n    }\n\n    def solve(self, problem, params):\n        p = {**self.default_params, **(params or {})}\n        D = problem[\"D\"]\n        n = problem[\"n\"]\n        rng = random.Random(p[\"seed\"])\n        T = max(1, p[\"max_iter\"])\n\n        n_p = p[\"n_pop\"]\n        if n > 80:\n            n_p = max(8, n_p // 2)\n\n        pop = [nearest_neighbor(D, start=0)]\n        for _ in range(n_p - 1):\n            pop.append(nearest_neighbor(D, start=rng.randrange(n)))\n        pop = [_random_2opt_shot(t, D, rng, trials=50) for t in pop]\n        pc = [tour_length(t, D) for t in pop]\n        bi = min(range(n_p), key=lambda i: pc[i])\n        best, best_cost = list(pop[bi]), pc[bi]\n\n        seg = max(2, n // 25)\n        stage_hits = [0, 0, 0, 0]\n        n_kick = 0\n        for it in range(1, T + 1):\n            frac = it / T\n            stage = 0 if frac < 1 / 3 else (1 if frac < 2 / 3 else 2)\n            for i in range(n_p):\n                r4 = rng.random()\n                if stage == 0:\n                    # X1 / X2 交替：广域双桥 vs Levy 越步\n                    if r4 < 0.5:\n                        cand = _double_bridge(list(pop[i]), rng)\n                        cand = _random_2opt_shot(cand, D, rng, trials=8)\n                        stage_hits[0] += 1\n                    else:\n                        f = rng.expovariate(1.0)   # Levy: 幂律步长\n                        if f > 1.0:\n                            cand = _double_bridge(list(pop[i]), rng)   # 越步跳盆地\n                            cand = _random_2opt_shot(cand, D, rng, trials=6)\n                        else:\n                            cand = _reverse_mutation(list(pop[i]), rng)  # 短步\n                            cand = _random_2opt_shot(cand, D, rng, trials=4)\n                        stage_hits[1] += 1\n                else:\n                    # X3 / X4 交替：or-opt 自精修 vs OX 向 best + 下探\n                    if r4 < 0.5:\n                        cand = _or_opt_move(list(pop[i]), rng, seg_len=3 if n < 60 else 4)\n                        cand = _random_2opt_shot(cand, D, rng, trials=10)\n                        stage_hits[2] += 1\n                    else:\n                        don = best if pop[i] != best else list(pop[i])[::-1]\n                        cand = _ox_crossover(pop[i], don, rng)\n                        cand = two_opt_improve(cand, D, max_moves=6)\n                        stage_hits[3] += 1\n                c = tour_length(cand, D)\n                if c < pc[i]:\n                    pop[i], pc[i] = list(cand), c\n                if c < best_cost:\n                    best, best_cost = list(cand), c\n            # 反射踢（真实下降来源，BBO 同款）\n            if rng.random() < 0.3:\n                kick = _double_bridge(list(best), rng) if rng.random() < 0.5 \\\n                    else _or_opt_move(list(best), rng, seg_len=seg)\n                kick = two_opt_improve(kick, D, max_moves=10)\n                c = tour_length(kick, D)\n                if c < best_cost:\n                    best, best_cost = list(kick), c\n                    w = max(range(n_p), key=lambda i: pc[i])\n                    pop[w], pc[w] = list(kick), c\n                n_kick += 1\n            if p[\"ls_every\"] > 0 and it % p[\"ls_every\"] == 0:\n                imp = two_opt_improve(best, D, max_moves=p[\"ls_moves\"])\n                c = tour_length(imp, D)\n                if c < best_cost:\n                    best, best_cost = imp, c\n                    w = max(range(n_p), key=lambda i: pc[i])\n                    pop[w], pc[w] = list(imp), c\n            yield IterationState(\n                it, best_cost, list(best), sum(pc) / n_p,\n                {\"stage\": stage + 1, \"hits\": list(stage_hits), \"n_kick\": n_kick},\n            )\n\n\n# ============================ 注册表与 JS 入口 ============================\n\n\n\nclass SlimeMould(BaseSolver):\n    \"\"\"黏菌算法 SMA（Li, Chen, Wang, Heidari & Mirjalili, 2020, FGCS）。\n\n    引用量级：~5000+（2020 系新算法中引用攀升极快的一支，Mirjalili 团队出品）。\n    机制：多头绒泡菌（Physarum polycephalum）觅食时以原质团传播波连接食物源，\n    自适应权重模拟传播波的<strong>正负反馈</strong>——食物浓度高的区域管径变粗\n    （权重 &gt; 1），稀薄处收缩（权重 &lt; 1），形成「重流量路径」。\n    官方权重公式：适应度排序后，前一半 W = 1+rand·log(ratio+1)，\n    后一半 W = 1−rand·log(ratio+1)，ratio = (worst−f)/(worst−best)。\n    三段更新：\n      ① rand &lt; z：随机重建（传播波重新铺开，勘探）；\n      ② rand &lt; 0.5：X = X_best + vb·(W·X_A − X_B)（沿粗管向最优运输）；\n      ③ 否则：X = vc·X（细管收缩，局部开发）。\n\n    离散化映射（TSP 版）：\n      ① 随机重建 = 随机起点最近邻 + 2-opt 抖动解（新波前）；\n      ② 粗管运输 = 按 W 加权轮盘选出引导个体，交换序列随机前缀\n        （前缀长度 ∝ 引导个体权重 w——粗管流量大，走得远）；\n      ③ 细管收缩 = or-opt 结构微调（片段搬运，本地路径收缩）；\n      最优反射踢 = 小概率对全局最优本体「扰动 + 预算制下探」\n        （Salp/SFLA/Jaya 同款机制，真实迭代进步的来源）。\n    \"\"\"\n\n    name = \"黏菌算法 SMA\"\n    default_params = {\n        \"n_pop\": 25, \"max_iter\": 200, \"seed\": 42,\n        \"z\": 0.2,          # 重建概率（勘探占比）\n        \"ls_every\": 10, \"ls_moves\": 20,\n    }\n    implemented = True\n    category = \"物理启发\"\n    param_specs = {\n        \"n_pop\": {\"min\": 8, \"max\": 60, \"step\": 2, \"int\": True, \"label\": \"个体数\", \"desc\": \"原质团个体数量（大实例自动降配）\"},\n        \"z\": {\"min\": 0.0, \"max\": 0.5, \"step\": 0.05, \"label\": \"重建概率 z\", \"desc\": \"传播波随机重新铺开的概率；越大勘探越猛\"},\n        \"ls_every\": {\"min\": 0, \"max\": 30, \"step\": 1, \"int\": True, \"label\": \"局部搜索周期\", \"desc\": \"每 N 代对全局最优做一次 2-opt 并回灌；0=关闭\"},\n        \"ls_moves\": {\"min\": 0, \"max\": 40, \"step\": 1, \"int\": True, \"label\": \"局部搜索预算\", \"desc\": \"每次局部搜索最多接受的 2-opt 移动数\"},\n    }\n\n    def solve(self, problem, params):\n        p = {**self.default_params, **(params or {})}\n        D = problem[\"D\"]\n        n = problem[\"n\"]\n        rng = random.Random(p[\"seed\"])\n\n        n_p = p[\"n_pop\"]\n        if n > 80:\n            n_p = max(8, n_p // 2)\n\n        pop = [nearest_neighbor(D, start=0)]\n        for _ in range(n_p - 1):\n            pop.append(nearest_neighbor(D, start=rng.randrange(n)))\n        pop = [_random_2opt_shot(t, D, rng, trials=50) for t in pop]\n        pc = [tour_length(t, D) for t in pop]\n        bi = min(range(n_p), key=lambda i: pc[i])\n        best, best_cost = list(pop[bi]), pc[bi]\n\n        seg = max(2, n // 25)\n        n_rebuild = n_transport = n_shrink = n_kick = 0\n        for it in range(1, p[\"max_iter\"] + 1):\n            # 官方权重：按当前适应度排序，前半放大 / 后半收缩\n            order = sorted(range(n_p), key=lambda i: pc[i])\n            worst, bestc = pc[order[-1]], pc[order[0]]\n            span = max(1e-9, worst - bestc)\n            weights = [1.0] * n_p\n            for rank, idx in enumerate(order):\n                ratio = (worst - pc[idx]) / span  # 1=最优 0=最劣\n                if rank < n_p // 2:\n                    weights[idx] = 1.0 + rng.random() * math.log(ratio + 1.0)\n                else:\n                    weights[idx] = 1.0 - rng.random() * math.log(ratio + 1.0)\n\n            for i in range(n_p):\n                r = rng.random()\n                if r < p[\"z\"]:\n                    # ① 传播波重新铺开：随机起点 NN + 2-opt 抖动\n                    cand = nearest_neighbor(D, start=rng.randrange(n))\n                    cand = _random_2opt_shot(cand, D, rng, trials=30)\n                    n_rebuild += 1\n                elif r < p[\"z\"] + (1.0 - p[\"z\"]) * 0.5:\n                    # ② 粗管运输：权重加权选引导个体，前缀长度 ∝ 其权重\n                    pool = [j for j in range(n_p) if j != i]\n                    ws = [weights[j] for j in pool]\n                    guide = rng.choices(pool, weights=ws, k=1)[0]\n                    seq = swap_seq_to_target(list(pop[i]), pop[guide])\n                    if seq:\n                        frac = min(1.0, weights[guide] / 2.0)\n                        cand = apply_swaps(\n                            pop[i], seq[:max(1, int(len(seq) * frac * rng.random()))])\n                    else:\n                        cand = list(pop[i])\n                    n_transport += 1\n                else:\n                    # ③ 细管收缩：or-opt 结构微调\n                    cand = _or_opt_move(list(pop[i]), rng, seg_len=seg)\n                    n_shrink += 1\n                c = tour_length(cand, D)\n                if c < pc[i]:\n                    pop[i], pc[i] = cand, c\n                if c < best_cost:\n                    best, best_cost = list(cand), c\n            # 最优反射踢（真实下降来源，Salp/SFLA/Jaya 同款）\n            if rng.random() < 0.3:\n                kick = _double_bridge(list(best), rng) if rng.random() < 0.5 \\\n                    else _or_opt_move(list(best), rng, seg_len=seg)\n                kick = two_opt_improve(kick, D, max_moves=10)\n                c = tour_length(kick, D)\n                if c < best_cost:\n                    best, best_cost = kick, c\n                    w = max(range(n_p), key=lambda j: pc[j])\n                    pop[w], pc[w] = list(kick), c\n                n_kick += 1\n            if p[\"ls_every\"] > 0 and it % p[\"ls_every\"] == 0:\n                imp = two_opt_improve(best, D, max_moves=p[\"ls_moves\"])\n                c = tour_length(imp, D)\n                if c < best_cost:\n                    best, best_cost = imp, c\n                    w = max(range(n_p), key=lambda j: pc[j])\n                    pop[w], pc[w] = list(imp), c\n            yield IterationState(\n                it, best_cost, list(best), sum(pc) / n_p,\n                {\"n_rebuild\": n_rebuild, \"n_transport\": n_transport,\n                 \"n_shrink\": n_shrink, \"n_kick\": n_kick},\n            )\n\n\n# ---- 新算法的类：tools/new_algorithm.py 追加在这一行之前 ----\n\n\nSOLVERS: Dict[str, type] = {\n    \"pso\": DiscretePSO,\n    \"2opt\": TwoOptSolver,\n    \"nn\": GreedyNN,\n    \"aco\": ACO,\n    \"abc\": ABC,\n    \"fa\": FA,\n    \"woa\": WOA,\n    \"ga\": GA,\n    \"sa\": SA,\n    \"gwo\": GWO,\n    \"ts\": TabuSearch,\n    \"de\": DifferentialEvolution,\n    \"cs\": CuckooSearch,\n    \"sca\": SineCosine,\n    \"hho\": HarrisHawks,\n    # —— 第二批（局部搜索框架 + 群智能补全）——\n    \"ils\": IteratedLocalSearch,\n    \"vns\": VariableNeighborhoodSearch,\n    \"lk\": LinKernighan,\n    \"ba\": BatAlgorithm,\n    \"hs\": HarmonySearch,\n    \"gsa\": GravitationalSearch,\n    \"tlbo\": TeachingLearning,\n    \"bfo\": BacterialForaging,\n    \"mfo\": MothFlame,\n    \"fwa\": Fireworks,\n    \"afsa\": ArtificialFishSwarm,\n    \"cem\": CrossEntropy,\n    # —— 第三批（2020 前后新算法 + Mirjalili 系补全）——\n    \"ssa\": SparrowSearch,\n    \"alo\": AntLion,\n    \"boa\": ButterflyOpt,\n    # —— 第四批（ICA 社会政治隐喻 + 链式/分组机制补全）——\n    \"ica\": ImperialistCA,\n    \"salp\": SalpSwarm,\n    \"sfla\": ShuffledFrogLeaping,\n    # —— 第五批（P1.3a：组件化重构后首批装配，蓝图 R3 批次一）——\n    \"fpa\": FlowerPollination,\n    \"kh\": KrillHerd,\n    \"sos\": SymbioticOS,\n    \"jaya\": JayaOptimizer,\n    # —— 第六批（P1.3b：2025 榜单补全批次二，蓝图 R3 批次二）——\n    \"da\": DragonflySwarm,\n    \"mpa\": MarinePredator,\n    \"cscrow\": RavenSearch,\n    \"bbo\": Biogeography,\n    # —— 第七批（P1.3c：蓝图终点 45 达成，蓝图 R3 批次三）——\n    \"grasp\": GraspSearch,\n    \"ais\": ClonalSelection,\n    \"eo\": EquilibriumOpt,\n    \"ao\": AquilaOpt,\n    # —— 第八批（家族轴批次：F3 清单补全）——\n    \"sma\": SlimeMould,\n    # ---- 新算法：tools/new_algorithm.py 在这一行之前登记 ----\n}\n\n\nclass CMAES(BaseSolver):\n    \"\"\"协方差矩阵自适应进化策略 CMA-ES（Hansen & Ostermeier 2001, EC 9(2):159-195）。\n\n    引用量级：数万（连续域公认的 SOTA 级演化策略，指认\n    的「连续域真正强者」）。它和 CEM（EDA 分支）一样走「分布→采样→精英回写」\n    路线，但 CMA-ES 学习的是**全二阶矩**——均值 + 协方差矩阵，而非 EDA 的\n    一阶频率矩阵；学习机制是协方差自适应 + 进化路径（pc/ps）步长耦合，\n    比 EDA 的平滑系数 λ 更鲁棒地匹配问题地形条件数。\n\n    离散化映射（TSP 版 —— random-keys 连续松弛）：\n      编码 = 每个城市一个连续键 key[c]∈[0,1]；按键排序 → 排列（标准 random-keys 解码）；\n      分布 = 可分离对角协方差 sep-CMA（浏览器内 O(n²) 采样，n=100 也扛得住；\n              若用全 n×n 协方差，n=100 时每代特征分解 O(n³) 太重）；\n      采样 = 均值键 + σ·√diag(C)·z（z~N(0,I)）；\n      更新 = 标准 (μ,λ)-CMA-ES：均值 / pc / ps / 对角 C / σ 全套自适应；\n      混合组件 = 精英以 polish_p 概率做短 2-opt 试射再回写（memetic 组件，\n                与 CEM 同款：纯连续采样在抛光后的 NN 播种上抽不出更优结构）。\n    \"\"\"\n\n    name = \"协方差矩阵自适应进化策略 CMA-ES\"\n    default_params = {\n        \"n_pop\": 30,\n        \"max_iter\": 200,\n        \"sigma0\": 0.4,      # 随机键标准差初值（相对 [0,1] 键空间）\n        \"polish_p\": 0.3,    # 精英打磨概率（memetic 组件）\n        \"ls_every\": 10,\n        \"ls_moves\": 20,\n        \"seed\": 42,\n    }\n    implemented = True\n    category = \"进化计算\"\n    param_specs = {\n        \"n_pop\": {\"min\": 10, \"max\": 80, \"step\": 2, \"int\": True, \"label\": \"样本数\", \"desc\": \"每代从分布抽样的解数量（大实例自动降配）\"},\n        \"sigma0\": {\"min\": 0.1, \"max\": 0.8, \"step\": 0.05, \"label\": \"初始步长 σ₀\", \"desc\": \"随机键空间的初始探索半径；越大起步越莽撞\"},\n        \"polish_p\": {\"min\": 0.0, \"max\": 0.5, \"step\": 0.05, \"label\": \"精英打磨\", \"desc\": \"对精英样本做短 2-opt 试射再回写分布的概率\"},\n        \"ls_every\": {\"min\": 0, \"max\": 30, \"step\": 1, \"int\": True, \"label\": \"局部搜索周期\", \"desc\": \"每 N 代对全局最优做一次 2-opt 并回灌；0=关闭\"},\n        \"ls_moves\": {\"min\": 0, \"max\": 40, \"step\": 1, \"int\": True, \"label\": \"局部搜索预算\", \"desc\": \"每次局部搜索最多接受的 2-opt 移动数\"},\n    }\n\n    def solve(self, problem, params):\n        p = {**self.default_params, **(params or {})}\n        D = problem[\"D\"]\n        n = problem[\"n\"]\n        rng = random.Random(p[\"seed\"])\n\n        n_pop = p[\"n_pop\"]\n        if n > 80:\n            n_pop = max(12, n_pop // 2)\n\n        # CMA-ES 常量（sep 版，对角协方差）\n        mu = max(1, n_pop // 2)\n        weights = [math.log(mu + 0.5) - math.log(i + 1) for i in range(mu)]\n        wsum = sum(weights)\n        weights = [w / wsum for w in weights]\n        mueff = (sum(weights)) ** 2 / sum(w * w for w in weights)\n        cc = 4.0 / (n + 4.0)\n        cs = (mueff + 2.0) / (n + mueff + 3.0)\n        c1 = 2.0 / ((n + 1.3) ** 2 + mueff)\n        cmu = min(1.0 - c1, 2.0 * (mueff - 2.0 + 1.0 / mueff) / ((n + 2.0) ** 2 + mueff))\n        damps = 1.0 + 2.0 * max(0.0, math.sqrt((mueff - 1.0) / (n + 1.0)) - 1.0) + cs\n        chiN = math.sqrt(n) * (1.0 - 1.0 / (4.0 * n) + 1.0 / (21.0 * n * n))\n\n        sigma = p[\"sigma0\"]\n        m = [rng.random() for _ in range(n)]   # 均值键向量 ∈[0,1]\n        C = [1.0] * n                          # 对角协方差（sep-CMA-ES）\n        pc = [0.0] * n\n        ps = [0.0] * n\n\n        def _decode(kv):\n            return sorted(range(n), key=lambda i: kv[i])\n\n        best_tour = _decode(m)\n        best_cost = tour_length(best_tour, D)\n\n        for it in range(1, p[\"max_iter\"] + 1):\n            pop, costs = [], []\n            for _k in range(n_pop):\n                z = [rng.gauss(0.0, 1.0) for _ in range(n)]\n                keys = [m[i] + sigma * math.sqrt(C[i]) * z[i] for i in range(n)]\n                tour = _decode(keys)\n                c = tour_length(tour, D)\n                pop.append((keys, tour, c))\n                costs.append(c)\n            order = sorted(range(n_pop), key=lambda i: costs[i])\n            sel = order[:mu]\n            old_m = m\n            m = [sum(weights[i] * pop[sel[i]][0][d] for i in range(mu)) for d in range(n)]\n            ymean = [(m[d] - old_m[d]) / sigma for d in range(n)]\n            # 步长路径 ps（对角 C → C^{-1/2} = 1/√C，逐分量）\n            cinv = [ymean[d] / math.sqrt(C[d]) for d in range(n)]\n            ps = [(1 - cs) * ps[d] + math.sqrt(cs * (2 - cs) * mueff) * cinv[d] for d in range(n)]\n            hsig = (math.sqrt(sum(x * x for x in ps)) /\n                    math.sqrt(1 - (1 - cs) ** (2 * it)) / chiN) < (1.4 + 2.0 / (n + 1.0))\n            pc = [(1 - cc) * pc[d] + hsig * math.sqrt(cc * (2 - cc) * mueff) * ymean[d] for d in range(n)]\n            # 更新对角 C：秩一 + 秩μ（逐分量独立）\n            ci = cmu  # Σweights = 1\n            for d in range(n):\n                C[d] = (1 - c1 - ci) * C[d] + c1 * (pc[d] * pc[d] + hsig * (2 - hsig) * C[d])\n            for i in range(mu):\n                yi = [(pop[sel[i]][0][d] - old_m[d]) / sigma for d in range(n)]\n                wyi = weights[i]\n                for d in range(n):\n                    C[d] += cmu * wyi * yi[d] * yi[d]\n            sigma *= math.exp((cs / damps) * (math.sqrt(sum(x * x for x in ps)) / chiN - 1.0))\n            # 精英打磨 + 保优\n            for i in sel:\n                tour, c = pop[i][1], pop[i][2]\n                if rng.random() < p[\"polish_p\"]:\n                    tour2 = _random_2opt_shot(tour, D, rng, 8)\n                    c2 = tour_length(tour2, D)\n                    if c2 < c:\n                        tour, c = tour2, c2\n                if c < best_cost:\n                    best_tour, best_cost = list(tour), c\n            if p[\"ls_every\"] > 0 and it % p[\"ls_every\"] == 0:\n                imp = two_opt_improve(best_tour, D, max_moves=p[\"ls_moves\"])\n                c = tour_length(imp, D)\n                if c < best_cost:\n                    best_tour, best_cost = imp, c\n            cur = sum(costs) / n_pop\n            yield IterationState(\n                it, best_cost, list(best_tour), cur,\n                {\"n_pop\": n_pop, \"sigma\": round(sigma, 4)},\n            )\n\n\nSOLVERS[\"cma-es\"] = CMAES\n\n# ============================ S7-B：配方算法注册（L-recipe 层） ============================\n# recipe.py 提供七槽管线组合引擎；本地环境走 import，拼接环境（solvers_src.js）里\n# recipe.py 已内联在前面，直接从 globals() 取——双环境行为一致。\ntry:\n    from recipe import install_recipes as _install_recipes\nexcept ImportError:\n    _install_recipes = globals().get(\"install_recipes\")\nif callable(_install_recipes):\n    _install_recipes(SOLVERS, IterationState, build_problem, tour_length)\n\n\ndef list_solvers() -> str:\n    \"\"\"供前端动态生成算法下拉框：返回 JSON 字符串（含分类与参数定义域）\"\"\"\n    out = []\n    for key, cls in SOLVERS.items():\n        out.append(\n            {\n                \"key\": key,\n                \"name\": cls.name,\n                \"category\": category_of(key, cls.category),  # 家族体系里的算法以家族为准，其余沿用类上的值\n                \"rank\": category_rank(category_of(key, cls.category)),  # 前端据此排分组顺序，不再自带一份分类清单\n                \"params\": cls.default_params,\n                \"specs\": cls.param_specs,\n                \"implemented\": cls.implemented,\n            }\n        )\n    return json.dumps(out, ensure_ascii=False)\n\n\n# --- 生成器状态：由 JS 反复调用 step() 驱动，实现暂停/单步/调速 ---\n_GEN: Optional[Iterator[IterationState]] = None\n\n\ndef start(problem_json: str, algo: str, params_json: str = \"{}\") -> str:\n    \"\"\"新建一次求解。problem_json = [[x,y], ...]，或校验器规整后的 {\"cities\", \"metric\"?, \"matrix\"?}\"\"\"\n    global _GEN\n    cities = json.loads(problem_json)\n    problem = problem_from_spec(cities)\n    cities = problem[\"cities\"]\n    params = json.loads(params_json or \"{}\")\n    if algo not in SOLVERS:\n        raise ValueError(f\"未知算法: {algo}\")\n    _GEN = SOLVERS[algo]().solve(problem, params)\n    return json.dumps({\"n\": len(cities)}, ensure_ascii=False)\n\n\ndef step() -> Optional[str]:\n    \"\"\"推进一代，返回该代状态的 JSON；结束返回 None\"\"\"\n    global _GEN\n    if _GEN is None:\n        return None\n    try:\n        return json.dumps(asdict(next(_GEN)), ensure_ascii=False)\n    except StopIteration:\n        _GEN = None\n        return None\n\n\ndef step_k(k: int = 1) -> Optional[str]:\n    \"\"\"推进 k 代，返回批量采样结果 JSON；结束后续调用返回 None。\n\n    v0.3 新增：支持「每 N 代采样一次」。返回结构：\n        {\n          \"iteration\": 末代代数, \"best_cost\": .., \"best_tour\": [..], \"current_cost\": ..,\n          \"points\": [[代数, 全局最优, 当代成本], ...],   # 本批 k 代逐代的真实数据\n          \"exhausted\": true/false                       # 本批是否用完了所有代\n        }\n    设计说明：每代只在 points 里放 3 个数字（不含路径），k=10 时开销可忽略；\n    best_tour 只放末代一份，避免消息膨胀。\n    \"\"\"\n    global _GEN\n    if _GEN is None:\n        return None\n    points = []\n    last: Optional[IterationState] = None\n    exhausted = False\n    try:\n        for _ in range(max(1, int(k))):\n            last = next(_GEN)\n            points.append(\n                [last.iteration, round(last.best_cost, 3), round(last.current_cost, 3)]\n            )\n    except StopIteration:\n        exhausted = True\n        _GEN = None\n    if last is None:\n        return None\n    d = asdict(last)\n    d[\"points\"] = points\n    d[\"exhausted\"] = exhausted\n    return json.dumps(d, ensure_ascii=False)\n\n\ndef run_all(problem_json: str, max_iter: int = 200, seed: int = 42) -> str:\n    \"\"\"对比页专用：把同一实例交给所有已实现算法各跑一遍，返回曲线与终值。\n\n    返回 {algo: {\"name\":.., \"curve\":[...], \"final\":..}，以及 \"nn\" 基线}\n    不走生成器，一次跑完——对比页要的是结果不是动画。\n    \"\"\"\n    problem = problem_from_spec(json.loads(problem_json))\n    cities = problem[\"cities\"]\n\n    out: Dict[str, Any] = {}\n    for key, cls in SOLVERS.items():\n        if not cls.implemented:\n            continue\n        params = {\"max_iter\": max_iter, \"seed\": seed}\n        if key == \"nn\":\n            params = {}\n        curve = []\n        final = None\n        for st in cls().solve(problem, params):\n            curve.append(round(st.best_cost, 3))\n            final = round(st.best_cost, 3)\n        out[key] = {\"name\": cls.name, \"curve\": curve, \"final\": final}\n\n    base = GreedyNN().solve(problem, {})\n    nn_cost = round(next(base).best_cost, 3)\n    return json.dumps({\"results\": out, \"nn\": nn_cost, \"n\": len(cities)}, ensure_ascii=False)\n\n\n# ============================ 本地命令行自测 ============================\n\n# 浏览器（Pyodide）里源码以 __main__ 身份拼接执行，必须用平台判断挡住，否则每次页面加载都会跑一遍自测\nif __name__ == \"__main__\" and __import__(\"sys\").platform != \"emscripten\":\n    rng = random.Random(7)\n    cities = [[rng.uniform(0, 100), rng.uniform(0, 100)] for _ in range(30)]\n    print(\"城市数:\", len(cities))\n    print(\"可用算法:\", list_solvers())\n\n    start(json.dumps(cities), \"pso\", json.dumps({\"max_iter\": 50}))\n    first, last = None, None\n    while True:\n        s = step()\n        if s is None:\n            break\n        last = json.loads(s)\n        if first is None:\n            first = last\n    print(f\"PSO 首代最优: {first['best_cost']:.2f}\")\n    print(f\"PSO 末代最优: {last['best_cost']:.2f}  (迭代 {last['iteration']} 次)\")\n\n    start(json.dumps(cities), \"nn\")\n    nn = json.loads(step())\n    print(f\"NN 基线:      {nn['best_cost']:.2f}\")\n";
export const VALIDATE_SRC = "# -*- coding: utf-8 -*-\n\"\"\"\n标准化数据层：把「用户上传的数据」变成「引擎能放心吃的实例」。\n\n三件事：\n  1. 校验：给出带路径的中文错误（\"items[3][0]：重量必须大于 0\"），而不是 IndexError；\n  2. 规整：n / m / K 等冗余字段由数据推出（用户不用再手写，也不会写错）；绘图坐标缺省自动布局；\n  3. 解析：JSON 信封、CSV（背包/装箱/图/QUBO）、DIMACS（.cnf 可满足性 / .col 图着色）。\n\n纯标准库，浏览器（Pyodide）与本地 Python 共用同一份。\n\n入口：\n    load(text_or_obj, domain=None, filename=None) -> (domain, data, issues)\n    validate(domain, data, variant=None, dry_run=False) -> Result\n    Result = {\"ok\": bool, \"errors\": [...], \"warnings\": [...], \"problem\": dict|None}\n    每条问题 = {\"path\": \"items[3][0]\", \"msg\": \"...\"}\n\n信封格式（swarm-problem/v1）：\n    {\"schema\": \"swarm-problem/v1\", \"domain\": \"knapsack\", \"data\": {...}}\n    裸实例（不带信封）+ 显式 domain 参数也可；页面导出的 domain-experiment/v1 同样接受。\n\"\"\"\nimport csv\nimport io\nimport json\nimport math\nimport re\n\nSCHEMA = \"swarm-problem/v1\"\nRESULT_SCHEMA = \"swarm-result/v1\"  # 求解结果；里面带完整实例，所以也可以当作「问题文件」重新导入\n\n# 支持上传的域。排程四域（etp/nrp/sls/ttp）暂不开放上传。\nCORE_DOMAINS = (\"tsp\", \"knapsack\", \"kpvar\", \"multiobj\", \"binpack\", \"bpvar\", \"graphcolor\", \"gcvar\",\n                \"setcover\", \"sat\", \"qubo\", \"gap\", \"uflp\", \"continuous\", \"entryseq\", \"custom\", \"mocont\")\n\n# 规模上限：Pyodide 在浏览器里跑，过大实例会卡死标签页\nLIMITS = {\n    \"tsp\": 500, \"knapsack\": 1000, \"kpvar\": 1000, \"multiobj\": 1000, \"binpack\": 1000, \"bpvar\": 500,\n    \"graph_nodes\": 500, \"graph_edges\": 50000, \"setcover_cells\": 250000, \"sat_vars\": 1000,\n    \"sat_clauses\": 10000, \"qubo\": 200, \"gap_agents\": 50, \"gap_jobs\": 500, \"uflp_f\": 100,\n    \"uflp_c\": 1000, \"continuous_dim\": 100, \"entryseq\": 300,\n}\n\n\n# ------------------------------------------------------------------ 引擎定位\n\ndef _engine():\n    \"\"\"问题域引擎模块。本地/测试里是 `import domains`；浏览器（Pyodide）里引擎源码以 __main__ 身份拼接执行，\n    没有名为 domains 的模块，此时从 __main__ 取同一批函数（domain_preset / FUNCS / _DOMAINS …）。\"\"\"\n    try:\n        import domains\n        return domains\n    except ImportError:\n        import sys\n        m = sys.modules.get(\"__main__\")\n        if m is not None and hasattr(m, \"domain_preset\"):\n            return m\n        raise\n\n\n# ------------------------------------------------------------------ 工具\n\nclass _R:\n    def __init__(self):\n        self.errors = []\n        self.warnings = []\n\n    def err(self, path, msg):\n        self.errors.append({\"path\": path, \"msg\": msg})\n\n    def warn(self, path, msg):\n        self.warnings.append({\"path\": path, \"msg\": msg})\n\n\ndef _show(x):\n    s = json.dumps(x, ensure_ascii=False) if not isinstance(x, str) else repr(x)\n    return s if len(s) <= 40 else s[:37] + \"…\"\n\n\ndef _isnum(x):\n    return isinstance(x, (int, float)) and not isinstance(x, bool) and math.isfinite(x)\n\n\ndef _int(R, path, x, lo=None, hi=None, what=\"整数\"):\n    if isinstance(x, float) and math.isfinite(x) and x.is_integer():\n        x = int(x)\n    if not isinstance(x, int) or isinstance(x, bool):\n        R.err(path, f\"应为{what}，收到 {_show(x)}\")\n        return None\n    if lo is not None and x < lo:\n        R.err(path, f\"应 ≥ {lo}，收到 {x}\")\n        return None\n    if hi is not None and x > hi:\n        R.err(path, f\"应 ≤ {hi}，收到 {x}\")\n        return None\n    return x\n\n\ndef _num(R, path, x, lo=None, hi=None, positive=False, what=\"数字\"):\n    if not _isnum(x):\n        R.err(path, f\"应为{what}，收到 {_show(x)}\")\n        return None\n    if positive and x <= 0:\n        R.err(path, f\"必须大于 0，收到 {x}\")\n        return None\n    if lo is not None and x < lo:\n        R.err(path, f\"应 ≥ {lo}，收到 {x}\")\n        return None\n    if hi is not None and x > hi:\n        R.err(path, f\"应 ≤ {hi}，收到 {x}\")\n        return None\n    return x\n\n\ndef _list(R, path, x, min_len=1, max_len=None, what=\"列表\"):\n    if not isinstance(x, list):\n        R.err(path, f\"应为{what}（JSON 数组），收到 {_show(x)}\")\n        return None\n    if len(x) < min_len:\n        R.err(path, f\"{what}至少需要 {min_len} 项，收到 {len(x)} 项\")\n        return None\n    if max_len is not None and len(x) > max_len:\n        R.err(path, f\"{what}最多 {max_len} 项（浏览器内运行的规模上限），收到 {len(x)} 项\")\n        return None\n    return x\n\n\ndef _need(R, p, key, alias=()):\n    for k in (key,) + tuple(alias):\n        if k in p:\n            return p[k]\n    R.err(key, f\"缺少必填字段 '{key}'\")\n    return None\n\n\ndef _num_vec(R, path, x, length=None, **kw):\n    \"\"\"数值向量；kw 透传 _num。返回新列表或 None。\"\"\"\n    xs = _list(R, path, x, what=\"数组\")\n    if xs is None:\n        return None\n    if length is not None and len(xs) != length:\n        R.err(path, f\"长度应为 {length}，收到 {len(xs)}\")\n        return None\n    out = []\n    ok = True\n    for i, v in enumerate(xs):\n        c = _num(R, f\"{path}[{i}]\", v, **kw)\n        ok &= c is not None\n        out.append(c)\n    return out if ok else None\n\n\ndef _matrix(R, path, x, rows=None, cols=None, **kw):\n    \"\"\"矩形数值矩阵。返回新的二维列表或 None。\"\"\"\n    xs = _list(R, path, x, what=\"矩阵\")\n    if xs is None:\n        return None\n    if rows is not None and len(xs) != rows:\n        R.err(path, f\"行数应为 {rows}，收到 {len(xs)}\")\n        return None\n    out = []\n    width = cols\n    ok = True\n    for i, row in enumerate(xs):\n        r = _list(R, f\"{path}[{i}]\", row, what=\"行\")\n        if r is None:\n            ok = False\n            continue\n        if width is None:\n            width = len(r)\n        elif len(r) != width:\n            R.err(f\"{path}[{i}]\", f\"每行长度必须一致：第 0 行 {width} 列，本行 {len(r)} 列\")\n            ok = False\n            continue\n        vec = []\n        for j, v in enumerate(r):\n            c = _num(R, f\"{path}[{i}][{j}]\", v, **kw)\n            ok &= c is not None\n            vec.append(c)\n        out.append(vec)\n    return out if ok else None\n\n\ndef _circle_layout(n):\n    return [[round(50 + 42 * math.cos(2 * math.pi * i / max(n, 1)), 1),\n             round(50 + 42 * math.sin(2 * math.pi * i / max(n, 1)), 1)] for i in range(n)]\n\n\ndef _pos_or_layout(R, p, key, n):\n    \"\"\"可选的绘图坐标：给了就校验，没给就环形布局（只影响画面，不影响求解）。\"\"\"\n    if key in p and p[key] is not None:\n        return _matrix(R, key, p[key], rows=n, cols=2)\n    return _circle_layout(n)\n\n\n# ------------------------------------------------------------------ 各域校验（核心域）\n\nTSP_METRICS = (\"EUC_2D\", \"CEIL_2D\", \"ATT\", \"GEO\", \"MAN_2D\", \"MAX_2D\")\nTSP_MIN = 4  # 3 城市只有一条回路（正反向同长），无需求解，部分算子也要求至少 4 个不同位置\n_ATSP_MSG = (\"距离不对称（A→B 与 B→A 不同）：这是非对称 TSP（ATSP）。TSP 演示页的算法用了 2-opt / OX 等默认距离对称的算子，\"\n             \"用在非对称数据上会得出错误结果，所以这里拒绝导入——请到「问题 ▸ 非对称旅行商 ATSP」页导入\"\n             \"（那里的算法每次重新计算整条回路的代价，不依赖对称性；也能直接读 TSPLIB 的 .atsp 文件）\")\n\n\ndef _tsp_matrix(R, path, mat, n_max):\n    \"\"\"显式距离矩阵：方阵、非负、零对角、对称。返回规整后的 float 矩阵或 None。\"\"\"\n    m = _matrix(R, path, mat, lo=0)\n    if m is None:\n        return None\n    n = len(m)\n    if n != len(m[0]):\n        R.err(path, f\"距离矩阵必须是方阵，收到 {n} 行 × {len(m[0])} 列\")\n        return None\n    if n < TSP_MIN or n > n_max:\n        R.err(path, f\"城市数应在 {TSP_MIN} ~ {n_max} 之间（浏览器内运行的规模上限），收到 {n}\")\n        return None\n    if any(m[i][i] != 0 for i in range(n)):\n        i = next(i for i in range(n) if m[i][i] != 0)\n        R.err(f\"{path}[{i}][{i}]\", f\"对角线（到自己的距离）应为 0，收到 {m[i][i]}\")\n        return None\n    for i in range(n):\n        for j in range(i + 1, n):\n            if abs(m[i][j] - m[j][i]) > 1e-9 * max(1.0, abs(m[i][j])):\n                R.err(f\"{path}[{i}][{j}]\", f\"{_ATSP_MSG}（第 {i} 行第 {j} 列是 {m[i][j]}，对称位置是 {m[j][i]}）\")\n                return None\n    return m\n\n\ndef _v_tsp(p, R):\n    metric = None\n    mat = None\n    pts = None\n    if isinstance(p, dict):\n        metric = p.get(\"metric\")\n        mat = p.get(\"matrix\", p.get(\"dist\"))\n        pts = p.get(\"cities\", p.get(\"pts\"))\n        if pts is None and mat is None:\n            R.err(\"cities\", \"缺少 'cities'（[[x, y], …] 坐标）或 'matrix'（n×n 距离矩阵）\")\n            return None\n    else:\n        pts = p\n        if isinstance(p, list) and len(p) >= TSP_MIN and all(isinstance(r, list) for r in p) \\\n                and all(len(r) == len(p) for r in p):\n            pts, mat = None, p  # 方阵：按距离矩阵读取（n×2 的坐标不可能是方阵，除非 n=2，而 n≥3）\n            R.warn(\"\", f\"按 {len(p)}×{len(p)} 距离矩阵读取；如果你想给的是坐标，每行应只有 [x, y] 两个数\")\n    if metric is not None and metric not in TSP_METRICS and metric not in (\"euc\", \"matrix\"):\n        R.err(\"metric\", f\"不支持的距离类型 {_show(metric)}。可选：euc（默认，浮点欧氏）、{', '.join(TSP_METRICS)}\")\n        return None\n    if mat is not None:\n        if metric not in (None, \"euc\", \"matrix\"):\n            R.err(\"metric\", \"给了距离矩阵就不需要 metric（距离以矩阵为准）\")\n            return None\n        m = _tsp_matrix(R, \"matrix\", mat, LIMITS[\"tsp\"])\n        if m is None:\n            return None\n        n = len(m)\n        if pts is None:\n            R.warn(\"cities\", \"没有给坐标：路线图按圆环布局，只用来示意；路线长度仍以你的距离矩阵为准\")\n            pos = _circle_layout(n)\n        else:\n            pos = _matrix(R, \"cities\", _list(R, \"cities\", pts, min_len=n, max_len=n, what=\"绘图坐标列表\"), cols=2)\n            if pos is None:\n                return None\n        return {\"cities\": pos, \"metric\": \"matrix\", \"matrix\": m}\n    pts = _list(R, \"cities\", pts, min_len=TSP_MIN, max_len=LIMITS[\"tsp\"], what=\"城市坐标列表\")\n    if pts is None:\n        return None\n    m = _matrix(R, \"cities\", pts, cols=2)\n    if m is None:\n        return None\n    if len({tuple(c) for c in m}) < len(m):\n        R.warn(\"cities\", \"存在重复坐标的城市（距离为 0），可以求解但路线图上会重叠\")\n    if metric in TSP_METRICS:\n        return {\"cities\": m, \"metric\": metric}\n    return {\"cities\": m}\n\n\n# ------------------------------------------------------------------ TSPLIB 解析\n\n_TSPLIB_KEY = re.compile(r\"^\\s*([A-Z_]+)\\s*:?\\s*(.*)$\")\n\n\ndef _looks_like_tsplib(txt):\n    return bool(re.search(r\"^\\s*(NODE_COORD_SECTION|EDGE_WEIGHT_SECTION|DIMENSION\\s*:|EDGE_WEIGHT_TYPE\\s*:)\", txt, re.M))\n\n\ndef _tsplib_matrix_from_list(R, fmt, vals, n):\n    \"\"\"把 EDGE_WEIGHT_SECTION 的一维数列按格式还原成 n×n 对称矩阵（列优先格式与行优先的镜像等价）。\"\"\"\n    fmt = {\"UPPER_COL\": \"LOWER_ROW\", \"LOWER_COL\": \"UPPER_ROW\", \"UPPER_DIAG_COL\": \"LOWER_DIAG_ROW\",\n           \"LOWER_DIAG_COL\": \"UPPER_DIAG_ROW\"}.get(fmt, fmt)\n    need = {\"FULL_MATRIX\": n * n, \"UPPER_ROW\": n * (n - 1) // 2, \"LOWER_ROW\": n * (n - 1) // 2,\n            \"UPPER_DIAG_ROW\": n * (n + 1) // 2, \"LOWER_DIAG_ROW\": n * (n + 1) // 2}.get(fmt)\n    if need is None:\n        R.err(\"EDGE_WEIGHT_FORMAT\", f\"不支持的 EDGE_WEIGHT_FORMAT {_show(fmt)}\")\n        return None\n    if len(vals) != need:\n        R.err(\"EDGE_WEIGHT_SECTION\", f\"{fmt} 在 DIMENSION={n} 时应有 {need} 个数，收到 {len(vals)} 个\")\n        return None\n    M = [[0] * n for _ in range(n)]\n    it = iter(vals)\n    if fmt == \"FULL_MATRIX\":\n        for i in range(n):\n            for j in range(n):\n                M[i][j] = next(it)\n        return M\n    for i in range(n):\n        if fmt.startswith(\"UPPER\"):\n            cols = range(i if fmt.endswith(\"DIAG_ROW\") else i + 1, n)\n        else:\n            cols = range(0, i + 1 if fmt.endswith(\"DIAG_ROW\") else i)\n        for j in cols:\n            v = next(it)\n            M[i][j] = v\n            M[j][i] = v\n    return M\n\n\ndef _parse_tsplib(txt, R, atsp=False):\n    \"\"\"TSPLIB95 的 TSP 子集 → 校验器认识的 dict。不是 TSP（ATSP / CVRP / HCP …）一律明确拒绝。\n    atsp=True：改读 TYPE: ATSP 文件（给 entryseq 的 atsp 变体用，只收显式 FULL_MATRIX），其余类型拒绝。\"\"\"\n    hdr, sections, cur = {}, {}, None\n    for ln, line in enumerate(txt.splitlines(), 1):\n        s = line.strip()\n        if not s:\n            continue\n        if s == \"EOF\":\n            break\n        m = _TSPLIB_KEY.match(s)\n        if m and m.group(1).endswith(\"_SECTION\") and m.group(2) == \"\":\n            cur = m.group(1)\n            sections[cur] = []\n            continue\n        if cur and re.match(r\"^[-+\\d.eE\\s]+$\", s):\n            sections[cur].append((ln, s))\n            continue\n        if m and \":\" in s:\n            cur = None\n            k, v = s.split(\":\", 1)\n            hdr[k.strip()] = v.strip()\n            continue\n        R.err(f\"第 {ln} 行\", f\"无法识别的 TSPLIB 内容：{_show(s)}\")\n        return None\n    typ = hdr.get(\"TYPE\", \"TSP\").upper()\n    if atsp:\n        return _parse_atsplib(hdr, sections, typ, R)\n    if typ == \"ATSP\":\n        R.err(\"TYPE\", _ATSP_MSG)\n        return None\n    if typ != \"TSP\":\n        R.err(\"TYPE\", f\"这是 TSPLIB 的 {typ} 文件；这里只支持 TYPE: TSP（对称旅行商）\")\n        return None\n    try:\n        n = int(hdr[\"DIMENSION\"])\n    except (KeyError, ValueError):\n        R.err(\"DIMENSION\", \"缺少或无法读取 DIMENSION（城市数）\")\n        return None\n    ewt = hdr.get(\"EDGE_WEIGHT_TYPE\", \"\").upper()\n\n    def numbers(name):\n        out = []\n        for ln, s in sections.get(name, []):\n            for t in s.split():\n                try:\n                    out.append(float(t))\n                except ValueError:\n                    R.err(f\"第 {ln} 行\", f\"应为数字，收到 {_show(t)}\")\n                    return None\n        return out\n\n    if ewt == \"EXPLICIT\":\n        vals = numbers(\"EDGE_WEIGHT_SECTION\")\n        if vals is None:\n            return None\n        if \"EDGE_WEIGHT_SECTION\" not in sections:\n            R.err(\"EDGE_WEIGHT_SECTION\", \"EDGE_WEIGHT_TYPE 是 EXPLICIT，但文件里没有 EDGE_WEIGHT_SECTION\")\n            return None\n        mat = _tsplib_matrix_from_list(R, hdr.get(\"EDGE_WEIGHT_FORMAT\", \"\").upper(), vals, n)\n        if mat is None:\n            return None\n        out = {\"matrix\": mat}\n        disp = sections.get(\"DISPLAY_DATA_SECTION\")\n        if disp and hdr.get(\"DISPLAY_DATA_TYPE\", \"\").upper() == \"TWOD_DISPLAY\":\n            pos = _tsplib_coords(R, \"DISPLAY_DATA_SECTION\", disp, n)\n            if pos is not None:\n                out[\"cities\"] = pos\n        return out\n    if ewt not in TSP_METRICS:\n        R.err(\"EDGE_WEIGHT_TYPE\", f\"不支持 EDGE_WEIGHT_TYPE {_show(ewt) if ewt else '（缺失）'}。支持：\"\n                                   f\"{', '.join(TSP_METRICS)}、EXPLICIT（距离矩阵）\")\n        return None\n    if \"NODE_COORD_SECTION\" not in sections:\n        R.err(\"NODE_COORD_SECTION\", \"缺少 NODE_COORD_SECTION（城市坐标）\")\n        return None\n    pos = _tsplib_coords(R, \"NODE_COORD_SECTION\", sections[\"NODE_COORD_SECTION\"], n)\n    return None if pos is None else {\"cities\": pos, \"metric\": ewt}\n\n\ndef _parse_atsplib(hdr, sections, typ, R):\n    \"\"\"TSPLIB 的 .atsp（非对称 TSP）→ entryseq/atsp 实例。官方 .atsp 文件的对角线常写成 9999 之类的占位值，读入时统一置 0。\"\"\"\n    if typ != \"ATSP\":\n        R.err(\"TYPE\", f\"这是 TYPE: {typ} 的文件。这里读的是非对称 TSP（TYPE: ATSP）；对称 TSP 请到「TSP 演示」页导入\")\n        return None\n    try:\n        n = int(hdr[\"DIMENSION\"])\n    except (KeyError, ValueError):\n        R.err(\"DIMENSION\", \"缺少或无法读取 DIMENSION（城市数）\")\n        return None\n    if hdr.get(\"EDGE_WEIGHT_TYPE\", \"\").upper() != \"EXPLICIT\" or hdr.get(\"EDGE_WEIGHT_FORMAT\", \"\").upper() != \"FULL_MATRIX\":\n        R.err(\"EDGE_WEIGHT_FORMAT\", \"ATSP 文件需要 EDGE_WEIGHT_TYPE: EXPLICIT 且 EDGE_WEIGHT_FORMAT: FULL_MATRIX（TSPLIB 的 .atsp 都是这种）\")\n        return None\n    vals = []\n    for ln, s in sections.get(\"EDGE_WEIGHT_SECTION\", []):\n        for t in s.split():\n            try:\n                vals.append(float(t))\n            except ValueError:\n                R.err(f\"第 {ln} 行\", f\"应为数字，收到 {_show(t)}\")\n                return None\n    if len(vals) != n * n:\n        R.err(\"EDGE_WEIGHT_SECTION\", f\"FULL_MATRIX 在 DIMENSION={n} 时应有 {n * n} 个数，收到 {len(vals)} 个\")\n        return None\n    mat = [[(int(v) if float(v).is_integer() else v) for v in vals[i * n:(i + 1) * n]] for i in range(n)]\n    if any(mat[i][i] != 0 for i in range(n)):\n        R.warn(\"EDGE_WEIGHT_SECTION\", \"对角线（到自己的代价）不是 0——TSPLIB 的 .atsp 常用 9999 之类的占位值，已置为 0（不影响求解）\")\n        for i in range(n):\n            mat[i][i] = 0\n    return {\"variant\": \"atsp\", \"d\": mat, \"pts\": _circle_layout(n), \"n\": n}\n\n\ndef _tsplib_coords(R, name, rows, n):\n    pos = []\n    for ln, s in rows:\n        t = s.split()\n        if len(t) != 3:\n            R.err(f\"第 {ln} 行\", f\"{name} 每行应为「编号 x y」三个数，收到 {len(t)} 个（只支持二维坐标）\")\n            return None\n        try:\n            pos.append([float(t[1]), float(t[2])])\n        except ValueError:\n            R.err(f\"第 {ln} 行\", f\"坐标应为数字，收到 {_show(s)}\")\n            return None\n    if len(pos) != n:\n        R.err(name, f\"DIMENSION={n}，但这一段有 {len(pos)} 行\")\n        return None\n    return pos\n\n\ndef _csv_tsp(table, meta, R):\n    \"\"\"CSV 的 TSP 读法：每行 x,y；或 id,x,y（第一列是 1..n / 0..n-1 的编号）；或 n×n 距离矩阵。\"\"\"\n    widths = {len(r) for r in table}\n    if len(widths) != 1:\n        R.err(\"\", f\"每行的列数必须一致，收到 {sorted(widths)}\")\n        return None\n    w, n = widths.pop(), len(table)\n    if w == n and n >= TSP_MIN and all(table[i][i] == 0 for i in range(n)):  # 零对角的方阵才可能是距离矩阵\n        R.warn(\"\", f\"{n}×{n} 的方阵，按距离矩阵读取；如果想给坐标，每行应只有 x,y（或 id,x,y）\")\n        return {\"matrix\": table}\n    if w == 2:\n        return {\"cities\": table}\n    if w == 3:\n        ids = [r[0] for r in table]\n        if ids in (list(range(1, n + 1)), list(range(n))) or ids in ([float(i) for i in range(1, n + 1)],\n                                                                       [float(i) for i in range(n)]):\n            R.warn(\"\", \"第一列是 1..n 的编号，已忽略，按 id,x,y 读取\")\n            return {\"cities\": [r[1:] for r in table]}\n        R.err(\"\", \"每行 3 个数：看起来像 id,x,y，但第一列不是 1..n（或 0..n-1）的连续编号。\"\n                  \"如果是三维坐标，本站只支持二维；如果第一列是别的含义，请删掉它\")\n        return None\n    R.err(\"\", f\"每行 {w} 个数，无法判断含义：坐标请用 x,y（或 id,x,y）；距离矩阵必须是 n×n 方阵（当前 {n} 行 {w} 列）\")\n    return None\n\n\ndef _v_knapsack(p, R):\n    items = _list(R, \"items\", _need(R, p, \"items\"), max_len=LIMITS[\"knapsack\"], what=\"物品列表\")\n    cap = _num(R, \"cap\", _need(R, p, \"cap\", (\"capacity\",)), positive=True, what=\"容量\")\n    if items is None or cap is None:\n        return None\n    out, ok = [], True\n    for i, it in enumerate(items):\n        row = _list(R, f\"items[{i}]\", it, min_len=2, what=\"[重量, 价值]\")\n        if row is None:\n            ok = False\n            continue\n        if len(row) != 2:\n            R.err(f\"items[{i}]\", f\"每个物品应为 [重量, 价值] 两个数，收到 {len(row)} 个\")\n            ok = False\n            continue\n        w = _num(R, f\"items[{i}][0]\", row[0], positive=True, what=\"重量\")\n        v = _num(R, f\"items[{i}][1]\", row[1], lo=0, what=\"价值\")\n        ok &= w is not None and v is not None\n        out.append([w, v])\n    if not ok:\n        return None\n    big = [i for i, (w, _) in enumerate(out) if w > cap]\n    if big:\n        R.warn(\"items\", f\"{len(big)} 个物品比背包容量还重（如第 {big[0]} 项），永远不会被选中\")\n    if sum(w for w, _ in out) <= cap:\n        R.warn(\"cap\", \"全部物品总重量不超过容量，全选就是最优解，问题是平凡的\")\n    _warn_n(R, p, len(out))\n    return {\"n\": len(out), \"cap\": cap, \"items\": out}\n\n\ndef _warn_n(R, p, n, key=\"n\"):\n    if key in p and p[key] != n:\n        R.warn(key, f\"已忽略 {key}={_show(p[key])}，以数据实际长度 {n} 为准\")\n\n\ndef _v_multiobj(p, R):\n    items = _list(R, \"items\", _need(R, p, \"items\"), max_len=LIMITS[\"multiobj\"], what=\"物品列表\")\n    cap = _num(R, \"cap\", _need(R, p, \"cap\", (\"capacity\",)), positive=True, what=\"容量\")\n    if items is None or cap is None:\n        return None\n    width = len(items[0]) if isinstance(items[0], list) else 0\n    if width not in (3, 4):\n        R.err(\"items[0]\", \"每个物品应为 [重量, 目标1, 目标2] 或 [重量, 目标1, 目标2, 目标3]\")\n        return None\n    m = _matrix(R, \"items\", items, cols=width, lo=0)\n    if m is None:\n        return None\n    if any(r[0] <= 0 for r in m):\n        R.err(\"items\", \"重量（每行第 0 列）必须大于 0\")\n        return None\n    variant = \"moco\" if width == 3 else \"maop\"\n    if p.get(\"variant\") not in (None, variant):\n        R.err(\"variant\", f\"物品每行 {width} 列对应变体 '{variant}'，但 variant 写的是 {_show(p.get('variant'))}\")\n        return None\n    _warn_n(R, p, len(m))\n    return {\"variant\": variant, \"n\": len(m), \"cap\": cap, \"items\": m}\n\n\ndef _v_binpack(p, R):\n    items = _num_vec(R, \"items\", _need(R, p, \"items\", (\"sizes\",)), positive=True, what=\"尺寸\")\n    cap = _num(R, \"cap\", _need(R, p, \"cap\", (\"capacity\", \"bin_cap\")), positive=True, what=\"箱容量\")\n    if items is None or cap is None:\n        return None\n    if len(items) > LIMITS[\"binpack\"]:\n        R.err(\"items\", f\"最多 {LIMITS['binpack']} 件（浏览器内运行的规模上限），收到 {len(items)} 件\")\n        return None\n    big = [i for i, w in enumerate(items) if w > cap]\n    if big:\n        R.err(f\"items[{big[0]}]\", f\"物品尺寸 {items[big[0]]} 超过箱容量 {cap}，无论如何装不下（共 {len(big)} 件）\")\n        return None\n    _warn_n(R, p, len(items))\n    return {\"n\": len(items), \"cap\": cap, \"items\": items}\n\n\ndef _edges(R, p, n_given):\n    \"\"\"图的边表校验与规整：返回 (n, edges, pos) 或 None。顶点编号从 0 开始。\"\"\"\n    raw = _list(R, \"edges\", _need(R, p, \"edges\"), min_len=0, max_len=LIMITS[\"graph_edges\"], what=\"边列表\")\n    if raw is None:\n        return None\n    pairs, ok = [], True\n    for i, e in enumerate(raw):\n        if not isinstance(e, list) or len(e) < 2:\n            R.err(f\"edges[{i}]\", f\"每条边应为 [顶点u, 顶点v]，收到 {_show(e)}\")\n            ok = False\n            continue\n        u = _int(R, f\"edges[{i}][0]\", e[0], lo=0, what=\"顶点编号（从 0 开始的整数）\")\n        v = _int(R, f\"edges[{i}][1]\", e[1], lo=0, what=\"顶点编号（从 0 开始的整数）\")\n        ok &= u is not None and v is not None\n        pairs.append((u, v))\n    if not ok:\n        return None\n    n = n_given\n    top = max((max(u, v) for u, v in pairs), default=-1)\n    if n is None:\n        if top < 0:\n            R.err(\"n\", \"没有边也没有给 n，无法确定顶点数\")\n            return None\n        n = top + 1\n        R.warn(\"n\", f\"未提供 n，按最大顶点编号推断为 {n}（若末尾有孤立点请显式提供 n）\")\n    else:\n        n = _int(R, \"n\", n, lo=2, what=\"顶点数\")\n        if n is None:\n            return None\n        if top >= n:\n            hint = \"（看起来是从 1 开始编号；本格式顶点编号为 0..n-1）\" if top == n and min(min(e) for e in pairs) >= 1 else \"\"\n            R.err(\"edges\", f\"顶点编号 {top} 超出范围 0..{n - 1}{hint}\")\n            return None\n    if n > LIMITS[\"graph_nodes\"]:\n        R.err(\"n\", f\"顶点数最多 {LIMITS['graph_nodes']}（浏览器内运行的规模上限），收到 {n}\")\n        return None\n    seen, edges, loops = set(), [], 0\n    for u, v in pairs:\n        if u == v:\n            loops += 1\n            continue\n        k = (min(u, v), max(u, v))\n        if k not in seen:\n            seen.add(k)\n            edges.append([k[0], k[1]])\n    if loops:\n        R.warn(\"edges\", f\"忽略了 {loops} 条自环边\")\n    if len(edges) < len(pairs) - loops:\n        R.warn(\"edges\", f\"合并了 {len(pairs) - loops - len(edges)} 条重复边\")\n    return n, edges\n\n\ndef _v_graphcolor(p, R):\n    got = _edges(R, p, p.get(\"n\"))\n    if got is None:\n        return None\n    n, edges = got\n    pos = _pos_or_layout(R, p, \"pos\", n)\n    if pos is None:\n        return None\n    return {\"n\": n, \"edges\": edges, \"pos\": pos}\n\n\ndef _v_setcover(p, R):\n    sets = _list(R, \"sets\", _need(R, p, \"sets\"), max_len=1000, what=\"集合列表\")\n    costs = _need(R, p, \"costs\", (\"cost\",))\n    if sets is None or costs is None:\n        return None\n    m = _matrix(R, \"sets\", sets)\n    if m is None:\n        return None\n    if len(m) * len(m[0]) > LIMITS[\"setcover_cells\"]:\n        R.err(\"sets\", f\"矩阵过大（{len(m)}×{len(m[0])}），上限 {LIMITS['setcover_cells']} 格\")\n        return None\n    for i, row in enumerate(m):\n        for j, v in enumerate(row):\n            if v not in (0, 1):\n                R.err(f\"sets[{i}][{j}]\", f\"覆盖矩阵只能是 0 或 1，收到 {v}\")\n                return None\n    c = _num_vec(R, \"costs\", costs, length=len(m), positive=True, what=\"成本\")\n    if c is None:\n        return None\n    n_el = len(m[0])\n    unc = [e for e in range(n_el) if not any(m[i][e] for i in range(len(m)))]\n    if unc:\n        R.err(\"sets\", f\"元素 {unc[:5]}{'…' if len(unc) > 5 else ''} 没有被任何集合覆盖，问题无解（共 {len(unc)} 个）\")\n        return None\n    return {\"n_el\": n_el, \"m\": len(m), \"sets\": [[int(v) for v in r] for r in m], \"costs\": c}\n\n\ndef _v_sat(p, R):\n    cl = _list(R, \"clauses\", _need(R, p, \"clauses\"), max_len=LIMITS[\"sat_clauses\"], what=\"子句列表\")\n    if cl is None:\n        return None\n    out, ok, top = [], True, 0\n    for i, c in enumerate(cl):\n        row = _list(R, f\"clauses[{i}]\", c, what=\"子句（非零整数文字列表）\")\n        if row is None:\n            ok = False\n            continue\n        lits = []\n        for j, lit in enumerate(row):\n            v = _int(R, f\"clauses[{i}][{j}]\", lit, what=\"非零整数（正=变量，负=取反，变量编号从 1 开始）\")\n            if v is None:\n                ok = False\n            elif v == 0:\n                R.err(f\"clauses[{i}][{j}]\", \"文字不能为 0（变量编号从 1 开始；0 只在 DIMACS 文件里作行尾标记）\")\n                ok = False\n            else:\n                lits.append(v)\n                top = max(top, abs(v))\n        if ok and len(set(lits)) < len(lits):\n            lits = list(dict.fromkeys(lits))\n            R.warn(f\"clauses[{i}]\", \"子句内有重复文字，已去重\")\n        if ok and any(-x in lits for x in lits):\n            R.warn(f\"clauses[{i}]\", \"子句同时含 x 与 ¬x，恒为真（永远满足）\")\n        out.append(lits)\n    if not ok:\n        return None\n    n = p.get(\"n_vars\", p.get(\"n\"))\n    if n is None:\n        n = top\n        R.warn(\"n_vars\", f\"未提供 n_vars，按最大变量编号推断为 {n}\")\n    n = _int(R, \"n_vars\", n, lo=1, hi=LIMITS[\"sat_vars\"], what=\"变量数\")\n    if n is None:\n        return None\n    if top > n:\n        R.err(\"clauses\", f\"子句里出现变量 {top}，超过 n_vars={n}\")\n        return None\n    return {\"n_vars\": n, \"clauses\": out}\n\n\ndef _v_qubo(p, R):\n    Q = _matrix(R, \"Q\", _need(R, p, \"Q\"))\n    if Q is None:\n        return None\n    n = len(Q)\n    if len(Q[0]) != n:\n        R.err(\"Q\", f\"QUBO 矩阵必须是方阵，收到 {n}×{len(Q[0])}\")\n        return None\n    if n > LIMITS[\"qubo\"]:\n        R.err(\"Q\", f\"最多 {LIMITS['qubo']} 个变量（浏览器内运行的规模上限），收到 {n}\")\n        return None\n    return {\"n\": n, \"Q\": Q}\n\n\ndef _v_gap(p, R):\n    c = _matrix(R, \"c\", _need(R, p, \"c\", (\"cost\",)))\n    if c is None:\n        return None\n    n_a, n_j = len(c), len(c[0])\n    r = _matrix(R, \"r\", _need(R, p, \"r\", (\"resource\",)), rows=n_a, cols=n_j, lo=0)\n    cap = _num_vec(R, \"cap\", _need(R, p, \"cap\", (\"capacity\",)), length=n_a, lo=0, what=\"容量\")\n    if r is None or cap is None:\n        return None\n    if n_a > LIMITS[\"gap_agents\"] or n_j > LIMITS[\"gap_jobs\"]:\n        R.err(\"c\", f\"最多 {LIMITS['gap_agents']} 个代理 × {LIMITS['gap_jobs']} 个任务，收到 {n_a}×{n_j}\")\n        return None\n    for j in range(n_j):\n        if all(r[a][j] > cap[a] for a in range(n_a)):\n            R.err(f\"r[*][{j}]\", f\"任务 {j} 的资源需求超过所有代理的容量，无法指派，问题无解\")\n            return None\n    return {\"n_a\": n_a, \"n_j\": n_j, \"c\": c, \"r\": r, \"cap\": cap}\n\n\ndef _v_uflp(p, R):\n    f = _num_vec(R, \"f_cost\", _need(R, p, \"f_cost\", (\"fixed_cost\",)), lo=0, what=\"开设成本\")\n    if f is None:\n        return None\n    cc = _matrix(R, \"c_cost\", _need(R, p, \"c_cost\", (\"assign_cost\",)), rows=len(f), lo=0)\n    if cc is None:\n        return None\n    n_f, n_c = len(f), len(cc[0])\n    if n_f > LIMITS[\"uflp_f\"] or n_c > LIMITS[\"uflp_c\"]:\n        R.err(\"c_cost\", f\"最多 {LIMITS['uflp_f']} 个设施 × {LIMITS['uflp_c']} 个客户，收到 {n_f}×{n_c}\")\n        return None\n    pf = _pos_or_layout(R, p, \"pos_f\", n_f)\n    pc = _pos_or_layout(R, p, \"pos_c\", n_c)\n    if pf is None or pc is None:\n        return None\n    return {\"n_f\": n_f, \"n_c\": n_c, \"f_cost\": f, \"c_cost\": cc, \"pos_f\": pf, \"pos_c\": pc}\n\n\ndef _v_continuous(p, R):\n    D = _engine()\n    fn = _need(R, p, \"fn\", (\"function\",))\n    if fn is None:\n        return None\n    if fn not in D.FUNCS:\n        R.err(\"fn\", f\"未知函数 {_show(fn)}。可选：{', '.join(D.FUNCS)}（自定义函数见「自带问题」）\")\n        return None\n    dim = _int(R, \"dim\", p.get(\"dim\", 2), lo=1, hi=LIMITS[\"continuous_dim\"], what=\"维度\")\n    if dim is None:\n        return None\n    if \"lo\" in p or \"hi\" in p:\n        R.warn(\"lo/hi\", \"搜索范围由所选函数决定，已忽略 lo/hi\")\n    return D.cn_make(fn=fn, dim=dim)\n\n\n# ------------------------------------------------------------------ 着色家族（含边/全着色的线图推导）\n\ndef _line_adj(edges):\n    m = len(edges)\n    inc = {}\n    for k, (u, v) in enumerate(edges):\n        inc.setdefault(u, []).append(k)\n        inc.setdefault(v, []).append(k)\n    adj = [set() for _ in range(m)]\n    for ks in inc.values():\n        for a in ks:\n            for b in ks:\n                if a != b:\n                    adj[a].add(b)\n    return [sorted(s) for s in adj]\n\n\ndef _v_gcvar(p, R, variant):\n    got = _edges(R, p, p.get(\"n\"))\n    if got is None:\n        return None\n    n, edges = got\n    pos = _pos_or_layout(R, p, \"pos\", n)\n    if pos is None:\n        return None\n    deg = [0] * n\n    for u, v in edges:\n        deg[u] += 1\n        deg[v] += 1\n    out = {\"variant\": variant, \"n\": n, \"edges\": edges, \"pos\": pos,\n           \"p\": round(2 * len(edges) / max(n * (n - 1), 1), 3)}\n    if variant == \"listcolor\":\n        lists = _list(R, \"lists\", _need(R, p, \"lists\"), what=\"每个顶点的可选颜色表\")\n        if lists is None:\n            return None\n        if len(lists) != n:\n            R.err(\"lists\", f\"应为每个顶点一张颜色表（共 {n} 张），收到 {len(lists)} 张\")\n            return None\n        L, K = [], 0\n        for i, row in enumerate(lists):\n            r = _list(R, f\"lists[{i}]\", row, what=\"颜色表\")\n            if r is None:\n                return None\n            cs = [_int(R, f\"lists[{i}][{j}]\", c, lo=0, what=\"颜色编号（从 0 开始的整数）\") for j, c in enumerate(r)]\n            if None in cs:\n                return None\n            L.append(sorted(set(cs)))\n            K = max(K, max(cs) + 1)\n        out[\"lists\"], out[\"K\"] = L, K\n    elif variant == \"precolor\":\n        pc = _list(R, \"precol\", _need(R, p, \"precol\"), what=\"预着色表\")\n        if pc is None:\n            return None\n        if len(pc) != n:\n            R.err(\"precol\", f\"应为每个顶点一项（共 {n} 项，-1 表示未预着色），收到 {len(pc)} 项\")\n            return None\n        cols = [_int(R, f\"precol[{i}]\", c, lo=-1, what=\"颜色编号（-1=未预着色）\") for i, c in enumerate(pc)]\n        if None in cols:\n            return None\n        for u, v in edges:\n            if cols[u] >= 0 and cols[u] == cols[v]:\n                R.err(\"precol\", f\"相邻顶点 {u} 与 {v} 被预着成同一颜色 {cols[u]}，无合法着色\")\n                return None\n        out[\"precol\"] = cols\n        out[\"K\"] = max(max(cols) + 1, max(deg, default=0) + 1)\n    elif variant == \"edgecolor\":\n        out[\"ladj\"] = _line_adj(edges)\n        out[\"m\"] = len(edges)\n    elif variant == \"totalcolor\":\n        m = len(edges)\n        tad = [set() for _ in range(n + m)]\n        for u, v in edges:\n            tad[u].add(v)\n            tad[v].add(u)\n        for a, nb in enumerate(_line_adj(edges)):\n            tad[n + a].update(n + b for b in nb)\n        for a, (u, v) in enumerate(edges):\n            for x in (u, v):\n                tad[x].add(n + a)\n                tad[n + a].add(x)\n        out.update({\"tadj\": [sorted(s) for s in tad], \"nV\": n, \"m\": m, \"N\": n + m})\n    elif variant != \"mis\":\n        R.err(\"variant\", f\"gcvar 的变体应为 listcolor/precolor/edgecolor/totalcolor/mis，收到 {_show(variant)}\")\n        return None\n    return out\n\n\n# ------------------------------------------------------------------ 长尾域：按示例实例自动推结构\n\ndef _ref_check(R, path, ref, val, key=None):\n    \"\"\"按示例 ref 的结构检查 val；返回规整后的值或 None。\"\"\"\n    if isinstance(ref, bool):\n        R.err(path, \"内部：不支持布尔字段\")\n        return None\n    if isinstance(ref, (int, float)):\n        if not _isnum(val):\n            R.err(path, f\"应为数字，收到 {_show(val)}\")\n            return None\n        if isinstance(ref, int) and isinstance(val, float):\n            if not val.is_integer():\n                R.err(path, f\"应为整数，收到 {val}\")\n                return None\n            return int(val)\n        return val\n    if isinstance(ref, str):\n        if not isinstance(val, str):\n            R.err(path, f\"应为文本，收到 {_show(val)}\")\n            return None\n        return val\n    if isinstance(ref, list):\n        if not isinstance(val, list):\n            R.err(path, f\"应为列表（JSON 数组），收到 {_show(val)}\")\n            return None\n        if not ref:\n            return val\n        if len(val) == 0:\n            if key in _RAGGED_KEYS:  # 不规则字段允许空行（如无前驱的工序）\n                return val\n            R.err(path, \"不能为空列表\")\n            return None\n        # 行结构三类：记录型字段（坐标 [x,y]、边 [u,v,w]）行长必须等于示例；\n        # 不规则字段（前驱列表等）各行可不等长；其余视为矩阵，要求同一矩阵内等宽\n        first = ref[0]\n        fixed = len(first) if isinstance(first, list) and key in _RECORD_KEYS else None\n        width = None\n        out = []\n        ok = True\n        for i, x in enumerate(val):\n            if isinstance(first, list):\n                if not isinstance(x, list):\n                    R.err(f\"{path}[{i}]\", f\"应为列表，收到 {_show(x)}\")\n                    ok = False\n                    continue\n                if fixed is not None and len(x) != fixed:\n                    R.err(f\"{path}[{i}]\", f\"每项应有 {fixed} 个值，收到 {len(x)} 个\")\n                    ok = False\n                    continue\n                if fixed is None and key not in _RAGGED_KEYS:\n                    width = len(x) if width is None else width\n                    if len(x) != width:\n                        R.err(f\"{path}[{i}]\", f\"每行长度必须一致：前面是 {width}，本行 {len(x)}\")\n                        ok = False\n                        continue\n            c = _ref_check(R, f\"{path}[{i}]\", first, x, key)\n            ok &= c is not None\n            out.append(c)\n        return out if ok else None\n    return val\n\n\n_RECORD_KEYS = {\"pts\", \"edges\", \"items\", \"bin_types\", \"pos\"}\n_RAGGED_KEYS = {\"preds\", \"chains\", \"lists\", \"sets\", \"adj\", \"students\", \"jobs\"}\n_OPTIONAL_KEYS = {\"name\", \"opt\"}  # 只用来显示（实例名、文献最优值）：有就收，没有不要求\n\n\ndef _derive_n(ref, p):\n    \"\"\"示例里 n 恰好等于某个列表长度（或少 1）时，从用户数据推 n。返回 n 或 None。\"\"\"\n    n_ref = ref.get(\"n\")\n    if not isinstance(n_ref, int):\n        return None\n    for k, v in ref.items():\n        if k in (\"n\", \"pos\") or not isinstance(v, list):\n            continue\n        for off in (0, -1):\n            if len(v) + off == n_ref and isinstance(p.get(k), list):\n                return len(p[k]) + off\n    return None\n\n\ndef _v_mocont(p, R, variant):\n    \"\"\"连续多目标基准：变体 + 决策变量个数。函数本身是固定的，没有别的数据。\"\"\"\n    D = _engine()\n    v = variant or p.get(\"variant\")\n    if v not in D.MOC_VARIANTS:\n        R.err(\"variant\", f\"未知变体 {_show(v)}。可选：{', '.join(D.MOC_VARIANTS)}\")\n        return None\n    n_min = D.MOC_SPEC[v][3]\n    n = _int(R, \"n\", p.get(\"n\", D.MOC_SPEC[v][2]), lo=n_min, hi=100, what=\"决策变量个数\")\n    if n is None:\n        return None\n    if v in D.MOC_NFIX and n != D.MOC_NFIX[v]:\n        R.err(\"n\", f\"{v} 的决策变量个数固定为 {D.MOC_NFIX[v]}（真前沿的公式依赖它），收到 {n}\")\n        return None\n    return D.mc_make(v, n)\n\n\ndef _v_custom(p, R, variant):\n    \"\"\"自带问题：编码（variant）+ 目标函数（表达式）+ 数据表。检查与试跑都在 py/userproblem.py。\"\"\"\n    D = _engine()\n    q = dict(p)\n    v = q.get(\"variant\", q.get(\"encoding\"))\n    if variant and v and variant != v:\n        R.err(\"variant\", f\"数据里写的编码是 {v!r}，但这里要求 {variant!r}\")\n        return None\n    if variant:\n        q[\"variant\"] = variant\n    out, errs, warns, _info = D.up_check(q)\n    for e in errs:\n        R.err(e[\"path\"], e[\"msg\"])\n    for w in warns:\n        R.warn(w[\"path\"], w[\"msg\"])\n    return out\n\n\ndef _v_generic(domain, p, R, variant):\n    D = _engine()\n    opts = {\"variant\": variant} if variant else {}\n    try:\n        ref = json.loads(D.domain_preset(domain, 7, opts))\n    except Exception:\n        ref = None\n    if not isinstance(ref, dict):\n        R.err(\"variant\", f\"未知变体 {_show(variant)}\")\n        return None\n    out = {}\n    for k, rv in ref.items():\n        if k == \"variant\":\n            out[k] = ref[k]\n            continue\n        if k in _OPTIONAL_KEYS:\n            if k in p:\n                out[k] = p[k]\n            continue\n        if k not in p:\n            if k == \"pos\":\n                continue\n            if k == \"n\" and _derive_n(ref, p) is not None:\n                continue\n            R.err(k, f\"缺少必填字段 '{k}'\")\n            continue\n        c = _ref_check(R, k, rv, p[k], k)\n        if c is not None:\n            out[k] = c\n    if R.errors:\n        return None\n    dn = _derive_n(ref, p)\n    if dn is not None:\n        if \"n\" in p and p[\"n\"] != dn:\n            R.err(\"n\", f\"n={p['n']} 与数据长度不符（数据推出 n={dn}）\")\n            return None\n        out[\"n\"] = dn\n    n = out.get(\"n\")\n    cap_n = LIMITS[\"entryseq\"] if domain == \"entryseq\" else LIMITS.get(domain, 1000)\n    if isinstance(n, int) and not (1 <= n <= cap_n):\n        R.err(\"n\", f\"n 应在 1..{cap_n}（浏览器内运行的规模上限），收到 {n}\")\n        return None\n    return out\n\n\ndef _es_fill(variant, p):\n    \"\"\"调度 / 路径 / 选址类变体里由数据推得出的字段（规模、机器数、下界、名字……）：上传时只需要给核心数据，其余这里补上。\n    数据形状不对时原样返回，交给通用检查去报错。\"\"\"\n    q = dict(p)\n\n    def mat(x):\n        return isinstance(x, list) and len(x) > 0 and all(isinstance(r, list) and len(r) > 0 for r in x)\n    try:\n        if variant == \"fss\" and mat(q.get(\"p\")):\n            q.setdefault(\"m_mach\", len(q[\"p\"]))\n            q.setdefault(\"n\", len(q[\"p\"][0]))\n        elif variant == \"oss\" and mat(q.get(\"t\")):\n            nj, m = len(q[\"t\"]), len(q[\"t\"][0])\n            q.setdefault(\"n_jobs\", nj)\n            q.setdefault(\"m_mach\", m)\n            q.setdefault(\"n\", nj * m)\n            if all(len(r) == m for r in q[\"t\"]) and all(_isnum(x) for r in q[\"t\"] for x in r):\n                q.setdefault(\"lb\", max(max(sum(r) for r in q[\"t\"]), max(sum(q[\"t\"][j][k] for j in range(nj)) for k in range(m))))\n        elif variant in (\"jss\", \"fjsp\") and isinstance(q.get(\"jobs\"), list) and q[\"jobs\"] and all(isinstance(j, list) and j for j in q[\"jobs\"]):\n            jobs = q[\"jobs\"]\n            q.setdefault(\"n_jobs\", len(jobs))\n            q.setdefault(\"n\", sum(len(j) for j in jobs))\n            if variant == \"jss\":\n                q.setdefault(\"m_mach\", max(k for j in jobs for k, _t in j) + 1)\n                q.setdefault(\"lb\", 0)\n            else:\n                q.setdefault(\"m_mach\", max(k for j in jobs for op in j for k, _t in op) + 1)\n                q.setdefault(\"lb\", 0)\n        elif variant in (\"hc\", \"lpath\") and isinstance(q.get(\"pts\"), list):\n            q.setdefault(\"n\", len(q[\"pts\"]))\n        elif variant in (\"mst\", \"gmatch\") and isinstance(q.get(\"pts\"), list) and isinstance(q.get(\"edges\"), list):\n            q.setdefault(\"n_nodes\", len(q[\"pts\"]))\n            q.setdefault(\"n\", len(q[\"edges\"]))\n            q.setdefault(\"opt\", 0)\n        elif variant == \"shortestpath\" and isinstance(q.get(\"pts\"), list):\n            q.setdefault(\"n\", len(q[\"pts\"]))\n            q.setdefault(\"src\", 0)\n            q.setdefault(\"dst\", len(q[\"pts\"]) - 1)\n            q.setdefault(\"opt\", 0)\n        elif variant in (\"maxflow\", \"mincostflow\") and isinstance(q.get(\"pts\"), list) and isinstance(q.get(\"arcs\"), list):\n            q.setdefault(\"n_nodes\", len(q[\"pts\"]))\n            q.setdefault(\"n\", len(q[\"arcs\"]))\n            q.setdefault(\"src\", 0)\n            q.setdefault(\"snk\", len(q[\"pts\"]) - 1)\n            q.setdefault(\"opt\", 0)\n            if variant == \"mincostflow\":\n                q.setdefault(\"need\", 1)\n        elif variant == \"topsort\" and isinstance(q.get(\"pts\"), list):\n            q.setdefault(\"n\", len(q[\"pts\"]))\n            q.setdefault(\"opt\", 0)\n        elif variant == \"msa\" and isinstance(q.get(\"seqs\"), list) and q[\"seqs\"] and all(isinstance(x, str) for x in q[\"seqs\"]):\n            q.setdefault(\"W\", max(len(x) for x in q[\"seqs\"]) + 4)\n            q.setdefault(\"n\", 3 * q[\"W\"])\n            q.setdefault(\"opt\", 0)\n        elif variant in (\"carp\", \"rpostman\") and isinstance(q.get(\"req\"), list):\n            q.setdefault(\"n\", len(q[\"req\"]))\n            q.setdefault(\"dem\", [0] * len(q[\"req\"]))\n            q.setdefault(\"depot\", 0)\n            q.setdefault(\"cap\", 20 if variant == \"carp\" else 10 ** 6)\n        elif variant == \"ndp\" and isinstance(q.get(\"edges\"), list) and isinstance(q.get(\"pts\"), list):\n            q.setdefault(\"n\", len(q[\"edges\"]))\n            q.setdefault(\"n_pts\", len(q[\"pts\"]))\n        elif variant == \"tdm\" and mat(q.get(\"sets\")):\n            sets = q[\"sets\"]\n            q.setdefault(\"n\", len(sets))\n            q.setdefault(\"q\", len(sets[0]) // 3)\n            if len(sets[0]) % 3 == 0:\n                w = len(sets[0]) // 3\n                q.setdefault(\"triples\", [[r.index(1) if 1 in r else 0, (r[w:2 * w].index(1) if 1 in r[w:2 * w] else 0),\n                                          (r[2 * w:].index(1) if 1 in r[2 * w:] else 0)] for r in sets])\n    except (TypeError, ValueError, AttributeError):\n        return dict(p)\n    return q\n\n\ndef _v_entryseq(p, R, variant):\n    \"\"\"词条域：通用的形状检查之外，给语义要求严格的变体补上「数据之间必须自洽」的检查。\"\"\"\n    if variant == \"kmeans\" and \"n\" not in p and isinstance(p.get(\"k\"), int) and not isinstance(p.get(\"k\"), bool):\n        p = dict(p, n=2 * p[\"k\"])  # n = 决策向量长度 = 2k，用户只需要给簇数 k\n    p = _es_fill(variant, p)\n    out = _v_generic(\"entryseq\", p, R, variant)\n    if out is None:\n        return None\n    n = out.get(\"n\")\n    if variant == \"atsp\":\n        d = out[\"d\"]\n        if len(d) != n or any(len(r) != n for r in d):\n            R.err(\"d\", f\"距离矩阵应为 {n}×{n}（与城市数一致），收到 {len(d)} 行\")\n            return None\n        for i in range(n):\n            if d[i][i] != 0:\n                R.err(f\"d[{i}][{i}]\", f\"对角线（到自己的代价）应为 0，收到 {d[i][i]}\")\n                return None\n            for j in range(n):\n                if d[i][j] < 0:\n                    R.err(f\"d[{i}][{j}]\", f\"代价不能为负，收到 {d[i][j]}\")\n                    return None\n        if len(out[\"pts\"]) != n:\n            R.err(\"pts\", f\"绘图坐标应有 {n} 个点（只用来画图，不影响求解），收到 {len(out['pts'])} 个\")\n            return None\n        if all(d[i][j] == d[j][i] for i in range(n) for j in range(i + 1, n)):\n            R.warn(\"d\", \"这个矩阵是对称的——它其实是普通 TSP，可以在演示页用 TSP 导入（那里的专用算法更快）\")\n    elif variant in (\"vrptw\", \"vrpstw\"):\n        hard = variant == \"vrptw\"\n        pts, dem, e, l, svc = out[\"pts\"], out[\"demand\"], out[\"e\"], out[\"l\"], out[\"svc\"]\n        if not hard and (not isinstance(out[\"lam\"], (int, float)) or out[\"lam\"] < 0):\n            R.err(\"lam\", f\"迟到罚系数 lam 不能为负，收到 {_show(out['lam'])}\")\n            return None\n        for name, arr in ((\"pts\", pts), (\"demand\", dem), (\"e\", e), (\"l\", l), (\"svc\", svc)):\n            if len(arr) != n + 1:\n                R.err(name, f\"应有 {n + 1} 项（第 0 项是仓库，后面 {n} 个客户），收到 {len(arr)} 项\")\n                return None\n        cap, H = out[\"cap\"], l[0]\n        if not (isinstance(cap, (int, float)) and cap > 0):\n            R.err(\"cap\", f\"车辆容量必须大于 0，收到 {_show(cap)}\")\n            return None\n        if H <= 0:\n            R.err(\"l[0]\", f\"仓库关门时刻（l[0]）必须大于 0，收到 {H}\")\n            return None\n        if out[\"m_veh\"] < 1:\n            R.err(\"m_veh\", \"车辆数至少 1 辆\")\n            return None\n        if sum(dem) > out[\"m_veh\"] * cap:\n            R.err(\"m_veh\", f\"{out['m_veh']} 辆车 × 容量 {cap} 装不下总需求 {sum(dem)}——无论怎么排都没有可行解\")\n            return None\n        for i in range(1, n + 1):\n            if dem[i] < 0 or dem[i] > cap:\n                R.err(f\"demand[{i}]\", f\"客户需求应在 0..容量({cap}) 之间，收到 {dem[i]}\")\n                return None\n            if svc[i] < 0:\n                R.err(f\"svc[{i}]\", f\"服务时间不能为负，收到 {svc[i]}\")\n                return None\n            if e[i] < 0 or e[i] > l[i]:\n                R.err(f\"e[{i}]\", f\"时间窗应满足 0 ≤ e ≤ l，收到 [{e[i]}, {l[i]}]\")\n                return None\n            d0 = math.dist(pts[0], pts[i])\n            if not hard:\n                continue  # 软时间窗：来不及只是要付罚金，不是无解\n            if d0 > l[i] + 1e-9:\n                R.err(f\"l[{i}]\", f\"客户 {i} 的窗口在 {l[i]} 关闭，而从仓库直接开过去就要 {d0:.1f}——永远来不及\")\n                return None\n            back = max(d0, e[i]) + svc[i] + d0\n            if back > H + 1e-9:\n                R.err(f\"l[{i}]\", f\"客户 {i} 单独跑一趟也要到 {back:.1f} 才能回仓库，而仓库在 {H} 关门——没有可行解\")\n                return None\n    elif variant == \"mdvrp\":\n        pts, dem, cap = out[\"pts\"], out[\"demand\"], out[\"cap\"]\n        Dp, m_dep = out[\"D\"], out[\"m_dep\"]\n        if len(pts) != n + 1 or len(dem) != n + 1:\n            R.err(\"pts\", f\"pts 与 demand 都应有 {n + 1} 项（前 D 个是仓库，后面是客户），收到 {len(pts)} / {len(dem)} 项\")\n            return None\n        if not (isinstance(Dp, int) and 1 <= Dp < n + 1):\n            R.err(\"D\", f\"仓库数 D 应是 1..{n} 的整数（pts 里前 D 个是仓库），收到 {_show(Dp)}\")\n            return None\n        if any(dem[d] != 0 for d in range(Dp)):\n            R.err(\"demand\", \"前 D 项是仓库，需求必须为 0\")\n            return None\n        if not (isinstance(cap, (int, float)) and cap > 0):\n            R.err(\"cap\", f\"车辆容量必须大于 0，收到 {_show(cap)}\")\n            return None\n        if not (isinstance(m_dep, int) and m_dep >= 1):\n            R.err(\"m_dep\", f\"每个仓库的车辆数至少 1 辆，收到 {_show(m_dep)}\")\n            return None\n        for i in range(Dp, n + 1):\n            if dem[i] < 0 or dem[i] > cap:\n                R.err(f\"demand[{i}]\", f\"客户需求应在 0..容量({cap}) 之间，收到 {dem[i]}\")\n                return None\n        if sum(dem) > Dp * m_dep * cap:\n            R.err(\"m_dep\", f\"{Dp} 个仓库 × {m_dep} 辆车 × 容量 {cap} 装不下总需求 {sum(dem)}——没有可行解\")\n            return None\n    elif variant == \"fss\":\n        P_ = out[\"p\"]\n        if any(len(r) != len(P_[0]) for r in P_):\n            R.err(\"p\", \"p 应为「机器数 × 作业数」的矩阵（每行是一台机器上各作业的加工时间），各行长度必须一致\")\n            return None\n        if any(x <= 0 for r in P_ for x in r):\n            R.err(\"p\", \"加工时间必须大于 0\")\n            return None\n        if len(P_[0]) != n or len(P_) != out[\"m_mach\"]:\n            R.err(\"n\", f\"n 应等于作业数 {len(P_[0])}、m_mach 应等于机器数 {len(P_)}\")\n            return None\n    elif variant == \"oss\":\n        T = out[\"t\"]\n        if any(len(r) != len(T[0]) for r in T) or len(T) != len(T[0]):\n            R.err(\"t\", \"开放车间要求「作业数 = 机器数」的方阵（t[j][k] = 作业 j 在机器 k 上的加工时间）\")\n            return None\n        if any(x <= 0 for r in T for x in r):\n            R.err(\"t\", \"加工时间必须大于 0\")\n            return None\n        out[\"n_jobs\"], out[\"m_mach\"], out[\"n\"] = len(T), len(T[0]), len(T) * len(T[0])\n        out[\"lb\"] = max(max(sum(r) for r in T), max(sum(T[j][k] for j in range(len(T))) for k in range(len(T[0]))))\n    elif variant in (\"jss\", \"fjsp\"):\n        jobs = out[\"jobs\"]\n        L = len(jobs[0])\n        if any(len(j) != L for j in jobs):\n            R.err(\"jobs\", f\"每个作业的工序数必须相同（这里第一个作业有 {L} 道）——标准作业车间基准里每个作业都经过每台机器一次\")\n            return None\n        mm = -1\n        for a, job in enumerate(jobs):\n            for b, op in enumerate(job):\n                pairs = [op] if variant == \"jss\" else op\n                if variant == \"fjsp\" and (not isinstance(op, list) or not op):\n                    R.err(f\"jobs[{a}][{b}]\", \"每道工序至少要有一台可选机器\")\n                    return None\n                for pr in pairs:\n                    if not (isinstance(pr, list) and len(pr) == 2 and all(_isnum(x) for x in pr)):\n                        R.err(f\"jobs[{a}][{b}]\", \"应为 [机器编号, 加工时间]\" + (\"\" if variant == \"jss\" else \" 的列表（每台可选机器一对）\"))\n                        return None\n                    k, t = pr\n                    if k < 0 or int(k) != k or t <= 0:\n                        R.err(f\"jobs[{a}][{b}]\", f\"机器编号应为非负整数、加工时间应大于 0，收到 {pr}\")\n                        return None\n                    mm = max(mm, int(k))\n        if variant == \"jss\":\n            for a, job in enumerate(jobs):\n                if len({k for k, _t in job}) != len(job):\n                    R.warn(f\"jobs[{a}]\", \"同一个作业两次用到同一台机器——标准作业车间里每个作业经过每台机器一次，这会是更一般的实例\")\n        out[\"jobs\"] = [[[int(k), t] for k, t in job] if variant == \"jss\" else [[[int(k), t] for k, t in op] for op in job] for job in jobs]\n        out[\"n_jobs\"], out[\"m_mach\"], out[\"n\"] = len(jobs), mm + 1, len(jobs) * L\n        mload = [0] * (mm + 1)\n        if variant == \"jss\":\n            for job in jobs:\n                for k, t in job:\n                    mload[int(k)] += t\n            out[\"lb\"] = max(max(mload), max(sum(t for _k, t in job) for job in jobs))\n        else:\n            lb_job = max(sum(min(t for _k, t in op) for op in job) for job in jobs)\n            lb_work = -(-sum(min(t for _k, t in op) for job in jobs for op in job) // (mm + 1))\n            out[\"lb\"] = max(lb_job, lb_work)\n    elif variant in (\"hc\", \"lpath\"):\n        pts, edges = out[\"pts\"], out[\"edges\"]\n        if len(pts) != n:\n            R.err(\"pts\", f\"pts 应有 {n} 个点（只用来画图），收到 {len(pts)} 个\")\n            return None\n        for i, e in enumerate(edges):\n            a, b = e[0], e[1]\n            if not (0 <= a < n and 0 <= b < n) or a == b:\n                R.err(f\"edges[{i}]\", f\"边的两端应是 0..{n - 1} 里互不相同的点，收到 {e}\")\n                return None\n            if variant == \"lpath\" and not (len(e) >= 3 and e[2] > 0):\n                R.err(f\"edges[{i}]\", \"最长路径的边应为 [u, v, 权重]，权重大于 0\")\n                return None\n    elif variant in (\"carp\", \"rpostman\"):\n        pts, edges, req, dem = out[\"pts\"], out[\"edges\"], out[\"req\"], out[\"dem\"]\n        nv = len(pts)\n        for i, e in enumerate(edges):\n            if not (0 <= e[0] < nv and 0 <= e[1] < nv) or e[0] == e[1] or e[2] < 1:\n                R.err(f\"edges[{i}]\", f\"路网的边应为 [u, v, 费用]：两端是 0..{nv - 1} 里不同的路口，费用 ≥ 1，收到 {e}\")\n                return None\n        if not (isinstance(out[\"depot\"], int) and 0 <= out[\"depot\"] < nv):\n            R.err(\"depot\", f\"仓库应是 0..{nv - 1} 的路口编号，收到 {_show(out['depot'])}\")\n            return None\n        if len(set(req)) != len(req) or any(not (0 <= r < len(edges)) for r in req):\n            R.err(\"req\", f\"必需边应是 edges 下标（0..{len(edges) - 1}）且互不相同\")\n            return None\n        if len(dem) != len(req):\n            R.err(\"dem\", f\"dem 应与 req 一一对应（{len(req)} 项），收到 {len(dem)} 项\")\n            return None\n        if not (out[\"cap\"] > 0):\n            R.err(\"cap\", \"车容量必须大于 0\")\n            return None\n        if any(d < 0 or d > out[\"cap\"] for d in dem):\n            R.err(\"dem\", f\"每条必需边的需求应在 0..容量({out['cap']}) 之间\")\n            return None\n        par = list(range(nv))\n\n        def _f(x):\n            while par[x] != x:\n                par[x] = par[par[x]]\n                x = par[x]\n            return x\n        for a, b, _c in edges:\n            par[_f(a)] = _f(b)\n        if len({_f(i) for i in range(nv)}) > 1:\n            R.err(\"edges\", \"路网不连通——车辆到不了所有必需边，没有可行解\")\n            return None\n    elif variant == \"ndp\":\n        pts, edges, pairs = out[\"pts\"], out[\"edges\"], out[\"pairs\"]\n        nv = len(pts)\n        for i, e in enumerate(edges):\n            if not (0 <= e[0] < nv and 0 <= e[1] < nv) or e[0] == e[1] or e[2] < 0:\n                R.err(f\"edges[{i}]\", f\"候选边应为 [u, v, 建设费]：两端是 0..{nv - 1} 里不同的点，费用 ≥ 0，收到 {e}\")\n                return None\n        for i, q in enumerate(pairs):\n            if len(q) != 2 or not all(isinstance(x, int) and 0 <= x < nv for x in q) or q[0] == q[1]:\n                R.err(f\"pairs[{i}]\", f\"需求对应是 0..{nv - 1} 里两个不同的点，收到 {q}\")\n                return None\n        par = list(range(nv))\n\n        def _f2(x):\n            while par[x] != x:\n                par[x] = par[par[x]]\n                x = par[x]\n            return x\n        for a, b, _c in edges:\n            par[_f2(a)] = _f2(b)\n        for i, (a, b) in enumerate(pairs):\n            if _f2(a) != _f2(b):\n                R.err(f\"pairs[{i}]\", f\"点 {a} 与 {b} 在候选边构成的图里就不连通——怎么买都连不起来\")\n                return None\n        out[\"n\"], out[\"n_pts\"] = len(edges), nv\n    elif variant == \"cflp\":\n        if not (len(out[\"cap\"]) == len(out[\"dem\"]) == len(out[\"fc\"]) == len(out[\"pts\"]) == n):\n            R.err(\"cap\", f\"pts / cap / dem / fc 都应有 {n} 项（每个点既是客户也是候选设施）\")\n            return None\n        if any(x <= 0 for x in out[\"cap\"]) or any(x < 0 for x in out[\"dem\"]) or any(x < 0 for x in out[\"fc\"]):\n            R.err(\"cap\", \"容量应大于 0，需求与固定费不能为负\")\n            return None\n        if sum(out[\"cap\"]) < sum(out[\"dem\"]):\n            R.err(\"cap\", f\"总容量 {sum(out['cap'])} 小于总需求 {sum(out['dem'])}——没有可行解\")\n            return None\n    elif variant == \"lrp\":\n        if not (len(out[\"pts\"]) == len(out[\"dem\"]) == n):\n            R.err(\"dem\", f\"pts 与 dem 都应有 {n} 项\")\n            return None\n        if not (isinstance(out[\"p\"], int) and 1 <= out[\"p\"] < n):\n            R.err(\"p\", f\"仓库数 p 应是 1..{n - 1} 的整数，收到 {_show(out['p'])}\")\n            return None\n        if not (out[\"cap\"] > 0) or any(d < 0 or d > out[\"cap\"] for d in out[\"dem\"]):\n            R.err(\"cap\", f\"车容量应大于 0，且每个客户的需求在 0..{out['cap']} 之间\")\n            return None\n    elif variant == \"tdm\":\n        sets = out[\"sets\"]\n        w = len(sets[0]) // 3\n        if len(sets[0]) % 3 or w < 2:\n            R.err(\"sets\", \"每行应有 3q 列（X、Y、Z 各 q 个元素，q ≥ 2）\")\n            return None\n        for i, r in enumerate(sets):\n            if any(x not in (0, 1) for x in r) or sum(r[:w]) != 1 or sum(r[w:2 * w]) != 1 or sum(r[2 * w:]) != 1:\n                R.err(f\"sets[{i}]\", \"每个三元组恰在 X、Y、Z 三段各有一个 1\")\n                return None\n        out[\"n\"], out[\"q\"] = len(sets), w\n    elif variant in (\"mst\", \"gmatch\", \"shortestpath\"):\n        D = _engine()\n        pts, edges = out[\"pts\"], out[\"edges\"]\n        nv = len(pts)\n        if variant != \"shortestpath\" and out[\"n_nodes\"] != nv:\n            R.err(\"n_nodes\", f\"n_nodes 应等于点数 {nv}\")\n            return None\n        for i, e in enumerate(edges):\n            if not (0 <= e[0] < nv and 0 <= e[1] < nv) or e[0] == e[1] or e[2] <= 0:\n                R.err(f\"edges[{i}]\", f\"边应为 [u, v, 权重]：两端是 0..{nv - 1} 里不同的点，权重大于 0，收到 {e}\")\n                return None\n        par = list(range(nv))\n\n        def _f3(x):\n            while par[x] != x:\n                par[x] = par[par[x]]\n                x = par[x]\n            return x\n        for a, b, _w in edges:\n            par[_f3(a)] = _f3(b)\n        if len({_f3(i) for i in range(nv)}) > 1:\n            R.err(\"edges\", \"图不连通\" + (\"：没有生成树\" if variant == \"mst\" else \"：有些点之间没有任何路径\"))\n            return None\n        if variant == \"mst\":\n            out[\"n\"], out[\"opt\"] = len(edges), D._opt_mst(nv, edges)\n        elif variant == \"gmatch\":\n            if nv > 16:\n                R.err(\"pts\", f\"匹配的精确对照用顶点子集动态规划，最多支持 16 个点，收到 {nv}\")\n                return None\n            out[\"n\"], out[\"opt\"] = len(edges), D._opt_gmatch(nv, edges)\n        else:\n            src, dst = out[\"src\"], out[\"dst\"]\n            if not (isinstance(src, int) and isinstance(dst, int) and 0 <= src < nv and 0 <= dst < nv and src != dst):\n                R.err(\"src\", f\"起点与终点应是 0..{nv - 1} 里两个不同的点\")\n                return None\n            out[\"n\"], out[\"opt\"] = nv, D._opt_sp(nv, edges, src, dst)\n    elif variant in (\"maxflow\", \"mincostflow\"):\n        D = _engine()\n        pts, arcs = out[\"pts\"], out[\"arcs\"]\n        nv = len(pts)\n        w = 3 if variant == \"maxflow\" else 4\n        for i, a in enumerate(arcs):\n            if len(a) != w or not (0 <= a[0] < nv and 0 <= a[1] < nv) or a[0] == a[1] or a[2] <= 0 or (w == 4 and a[3] < 0):\n                R.err(f\"arcs[{i}]\", f\"弧应为 [起点, 终点, 容量{', 单位费用' if w == 4 else ''}]：两端是 0..{nv - 1} 里不同的点，容量大于 0\" + (\"，费用 ≥ 0\" if w == 4 else \"\") + f\"，收到 {a}\")\n                return None\n        src, snk = out[\"src\"], out[\"snk\"]\n        if not (isinstance(src, int) and isinstance(snk, int) and 0 <= src < nv and 0 <= snk < nv and src != snk):\n            R.err(\"src\", f\"源点与汇点应是 0..{nv - 1} 里两个不同的点\")\n            return None\n        cap_arcs = [[a[0], a[1], a[2]] for a in arcs]\n        fmax, _c = D._pc_max_flow(nv, cap_arcs, src, snk)\n        if fmax <= 0:\n            R.err(\"arcs\", \"源点到不了汇点——最大流为 0，没有可行的流\")\n            return None\n        out[\"n_nodes\"], out[\"n\"] = nv, len(arcs)\n        if variant == \"maxflow\":\n            out[\"opt\"] = fmax\n        else:\n            need = out[\"need\"]\n            if not (isinstance(need, (int, float)) and 0 < need <= fmax):\n                R.err(\"need\", f\"需要送出的流量应在 (0, {fmax}] 之间（{fmax} 是这张网络的最大流），收到 {_show(need)}\")\n                return None\n            _f, out[\"opt\"] = D._pc_max_flow(nv, cap_arcs, src, snk, cost=[a[3] for a in arcs], want=int(need))\n    elif variant == \"topsort\":\n        pts, arcs = out[\"pts\"], out[\"arcs\"]\n        nv = len(pts)\n        for i, a in enumerate(arcs):\n            if len(a) != 2 or not (0 <= a[0] < nv and 0 <= a[1] < nv) or a[0] == a[1]:\n                R.err(f\"arcs[{i}]\", f\"弧应为 [起点, 终点]：0..{nv - 1} 里两个不同的点，收到 {a}\")\n                return None\n        indeg = [0] * nv\n        for a, b in arcs:\n            indeg[b] += 1\n        queue = [v for v in range(nv) if indeg[v] == 0]\n        seen = 0\n        while queue:\n            u = queue.pop()\n            seen += 1\n            for a, b in arcs:\n                if a == u:\n                    indeg[b] -= 1\n                    if indeg[b] == 0:\n                        queue.append(b)\n        if seen < nv:\n            R.err(\"arcs\", \"图里有环，不存在拓扑序（目标「违反的弧数」最小只能到 > 0）；拓扑排序要求有向无环图\")\n            return None\n        out[\"n\"], out[\"opt\"] = nv, 0\n    elif variant == \"msa\":\n        D = _engine()\n        seqs = out[\"seqs\"]\n        if len(seqs) != 3 or any(not x or len(x) > 20 or not x.isalpha() for x in seqs):\n            R.err(\"seqs\", \"多序列比对目前固定为 3 条序列，每条 1–20 个字母（精确对照用三维动态规划）\")\n            return None\n        W = out[\"W\"]\n        if not (isinstance(W, int) and W >= max(len(x) for x in seqs)):\n            R.err(\"W\", f\"比对宽度 W 至少要等于最长序列的长度 {max(len(x) for x in seqs)}\")\n            return None\n        out[\"n\"], out[\"opt\"] = 3 * W, D._msa_dp(seqs)\n    elif variant == \"pms\":\n        if any(x <= 0 for x in out[\"p\"]):\n            R.err(\"p\", \"加工时间必须大于 0\")\n            return None\n        m = out[\"m_mach\"]\n        if not isinstance(m, int) or isinstance(m, bool) or m < 2:\n            R.err(\"m_mach\", f\"机器数应为 ≥ 2 的整数，收到 {m!r}\")\n            return None\n    elif variant == \"numpart\":\n        if any(x <= 0 for x in out[\"a\"]) or len(out[\"a\"]) < 2:\n            R.err(\"a\", \"需要至少 2 个正数\")\n            return None\n    elif variant == \"kmeans\":\n        k = out[\"k\"]\n        if not isinstance(k, int) or isinstance(k, bool) or k < 2:\n            R.err(\"k\", f\"簇数 k 应为 ≥ 2 的整数，收到 {k!r}\")\n            return None\n        if len(out[\"pts\"]) < k:\n            R.err(\"pts\", f\"点数（{len(out['pts'])}）不能少于簇数 k={k}\")\n            return None\n        if \"n\" in p and p[\"n\"] != 2 * k:\n            R.err(\"n\", f\"n 应为 2k = {2 * k}（k 个中心的 x、y 坐标），收到 {p['n']}\")\n            return None\n        if len({tuple(q) for q in out[\"pts\"]}) < k:\n            R.err(\"pts\", \"互不相同的点比簇数还少，无法分成 k 簇\")\n            return None\n        out[\"n\"] = 2 * k\n    elif variant in (\"wbeam\", \"pvessel\", \"tcspring\", \"reducer\"):\n        D = _engine()\n        want = len(D._DESIGN[variant][\"names\"])\n        if n != want:\n            R.err(\"n\", f\"{variant} 是固定的设计问题，n 必须为 {want}，收到 {n}\")\n            return None\n    return out\n\n\ndef _v_kpvar(p, R, variant):\n    out = _v_generic(\"kpvar\", p, R, variant)\n    if out is None:\n        return None\n    for key in (\"w\", \"w2\"):\n        flat = out.get(key)\n        if flat is not None:\n            xs = [x for row in flat for x in (row if isinstance(row, list) else [row])]\n            if any(x <= 0 for x in xs):\n                R.err(key, \"重量必须全部大于 0\")\n                return None\n    for it in out.get(\"items\", []):\n        if it[0] <= 0:\n            R.err(\"items\", \"物品重量（每项第 0 个数）必须大于 0\")\n            return None\n    return out\n\n\ndef _v_bpvar(p, R, variant):\n    out = _v_generic(\"bpvar\", p, R, variant)\n    if out is None:\n        return None\n    if variant == \"vsbinpack\":\n        biggest = max(b[0] for b in out[\"bin_types\"])\n        bad = [i for i, w in enumerate(out[\"items\"]) if w > biggest]\n        if bad:\n            R.err(f\"items[{bad[0]}]\", f\"物品尺寸超过最大箱型容量 {biggest}，装不下\")\n            return None\n    elif variant == \"binpack2d\":\n        for i, (w, h) in enumerate(out[\"items\"]):\n            if w > out[\"binW\"] or h > out[\"binH\"]:\n                R.err(f\"items[{i}]\", f\"物品 {w}×{h} 比箱子 {out['binW']}×{out['binH']} 还大，装不下\")\n                return None\n    return out\n\n\n# ------------------------------------------------------------------ 总入口\n\n_SIMPLE = {\"tsp\": _v_tsp, \"knapsack\": _v_knapsack, \"multiobj\": _v_multiobj, \"binpack\": _v_binpack,\n           \"graphcolor\": _v_graphcolor, \"setcover\": _v_setcover, \"sat\": _v_sat, \"qubo\": _v_qubo,\n           \"gap\": _v_gap, \"uflp\": _v_uflp, \"continuous\": _v_continuous}\n\n\ndef validate(domain, data, variant=None, dry_run=False):\n    \"\"\"校验并规整一个实例。dry_run=True 时额外用引擎真跑 2 代做兜底（会占用引擎的全局运行态，\n    页面上只应在空闲时调用）。\"\"\"\n    R = _R()\n    if domain not in CORE_DOMAINS:\n        R.err(\"domain\", f\"不支持的问题域 {_show(domain)}。可选：{', '.join(CORE_DOMAINS)}\")\n        return _result(R, None)\n    if domain == \"tsp\":\n        prob = _v_tsp(data, R)\n        return _result(R, prob)\n    if not isinstance(data, dict):\n        R.err(\"\", \"实例应为 JSON 对象（花括号），收到 \" + _show(data))\n        return _result(R, None)\n    variant = variant or data.get(\"variant\")\n    try:\n        if domain in _SIMPLE:\n            prob = _SIMPLE[domain](data, R)\n        elif domain == \"gcvar\":\n            prob = _v_gcvar(data, R, variant or \"mis\")\n        elif domain == \"custom\":\n            prob = _v_custom(data, R, variant)\n        elif domain == \"mocont\":\n            prob = _v_mocont(data, R, variant or \"zdt1\")\n        elif domain in (\"kpvar\", \"bpvar\", \"entryseq\"):\n            if not variant:\n                R.err(\"variant\", f\"{domain} 需要指定 variant（变体）\")\n                prob = None\n            elif domain == \"kpvar\":\n                prob = _v_kpvar(data, R, variant)\n            elif domain == \"bpvar\":\n                prob = _v_bpvar(data, R, variant)\n            else:\n                prob = _v_entryseq(data, R, variant)\n        else:  # pragma: no cover\n            prob = None\n    except ImportError:\n        R.err(\"\", \"缺少 domains.py（校验器需要与引擎同目录）\")\n        prob = None\n    if prob is not None and not R.errors:\n        _fidelity_warning(domain, prob.get(\"variant\") if isinstance(prob, dict) else None, R)\n    if prob is not None and dry_run and not R.errors:\n        _dry_run(domain, prob, R)\n        if R.errors:\n            prob = None\n    return _result(R, prob if not R.errors else None)\n\n\n_FID_PREFIX = {\"simplified\": \"这是「教学简化模型」\", \"illustrative\": \"这是「示意模型」\"}\n_FID_TAIL = {\"simplified\": \"结果不能与文献对照。\", \"illustrative\": \"它只借这个问题的名字演示形态，不是该问题本身。\"}\n\n\ndef _fidelity_warning(domain, variant, R):\n    \"\"\"entryseq 词条的变体多为教学简化/示意模型：用户上传自己的数据时必须被告知。\"\"\"\n    if domain != \"entryseq\" or not variant:\n        return\n    try:\n        fid = getattr(_engine(), \"FIDELITY\", {}).get(variant)\n    except ImportError:\n        return\n    if fid and fid[\"level\"] in _FID_PREFIX:\n        R.warn(\"\", f\"{_FID_PREFIX[fid['level']]}（{domain}/{variant}）：{fid['note']}。{_FID_TAIL[fid['level']]}\")\n\n\ndef _dry_run(domain, prob, R):\n    D = _engine()\n    try:\n        opts = {\"variant\": prob[\"variant\"]} if \"variant\" in prob else {}\n        algos = [a[\"key\"] for a in json.loads(D.domain_list(domain, opts))[\"algos\"]]\n        for algo in [a for a in (\"random\", \"sa\") if a in algos] or algos[:1]:\n            D.domain_start(domain, json.dumps(prob), algo, json.dumps({\"max_iter\": 3, \"seed\": 7}))\n            for _ in range(3):\n                D.domain_step()\n    except Exception as e:\n        R.err(\"\", f\"引擎试跑失败：{type(e).__name__}: {str(e)[:120]}（实例结构通过了检查，但引擎无法处理，请核对数据含义）\")\n\n\ndef _result(R, prob):\n    return {\"ok\": not R.errors, \"errors\": R.errors, \"warnings\": R.warnings,\n            \"problem\": prob if not R.errors else None}\n\n\n# ------------------------------------------------------------------ 文件解析\n\n_GUESS = (  # (必须出现的键, 域)——只在唯一匹配时使用\n    ({\"cities\"}, \"tsp\"), ({\"n_vars\", \"clauses\"}, \"sat\"), ({\"clauses\"}, \"sat\"), ({\"Q\"}, None),\n    ({\"n_el\", \"sets\"}, \"setcover\"), ({\"sets\", \"costs\"}, \"setcover\"),\n    ({\"n_f\", \"c_cost\"}, \"uflp\"), ({\"f_cost\", \"c_cost\"}, \"uflp\"), ({\"n_a\", \"c\", \"r\"}, \"gap\"),\n    ({\"c\", \"r\", \"cap\"}, \"gap\"), ({\"fn\"}, \"continuous\"), ({\"variant\", \"objective\", \"n\"}, \"custom\"),\n)\n\n\ndef guess_domain(data):\n    if not isinstance(data, dict):\n        return None\n    keys = set(data)\n    if \"Q\" in keys:\n        return \"kpvar\" if \"w\" in keys else \"qubo\"\n    for need, dom in _GUESS:\n        if dom and need <= keys:\n            return dom\n    if \"edges\" in keys and \"variant\" not in keys:\n        return \"graphcolor\"\n    return None\n\n\ndef load(text_or_obj, domain=None, filename=None):\n    \"\"\"把上传内容读成 (domain, data, issues)。支持 JSON 信封 / 裸 JSON / CSV / DIMACS。\"\"\"\n    R = _R()\n    obj = text_or_obj\n    name = (filename or \"\").lower()\n    if isinstance(obj, (bytes, bytearray)):\n        obj = obj.decode(\"utf-8-sig\", errors=\"replace\")\n    if isinstance(obj, str):\n        txt = obj.lstrip(\"﻿\").strip()\n        if not txt:\n            R.err(\"\", \"文件是空的\")\n            return domain, None, R\n        if name.endswith((\".tsp\", \".atsp\")) or (txt[0] not in \"[{\" and _looks_like_tsplib(txt)):\n            if domain == \"entryseq\":  # ATSP 页：读 TYPE: ATSP 的 TSPLIB 文件\n                return \"entryseq\", _parse_tsplib(txt, R, atsp=True), R\n            if domain not in (None, \"tsp\"):\n                R.err(\"domain\", f\"这是 TSPLIB（旅行商）文件，但当前页面是 '{domain}'\")\n                return domain, None, R\n            return \"tsp\", _parse_tsplib(txt, R), R\n        if name.endswith(\".cnf\") or re.search(r\"^p\\s+cnf\\b\", txt, re.M):\n            return \"sat\", _parse_cnf(txt, R), R\n        if name.endswith(\".col\") or re.search(r\"^p\\s+edge\\b\", txt, re.M):\n            return \"graphcolor\" if domain in (None, \"graphcolor\") else domain, _parse_col(txt, R), R\n        if txt[0] in \"[{\":\n            try:\n                obj = json.loads(txt)\n            except ValueError as e:\n                R.err(\"\", f\"不是合法 JSON：{e}\")\n                return domain, None, R\n        else:\n            if domain is None:\n                R.err(\"domain\", \"CSV/文本文件需要指定问题域（knapsack/binpack/graphcolor/qubo/tsp）\")\n                return None, None, R\n            return domain, _parse_csv(domain, txt, R), R\n    if isinstance(obj, dict) and obj.get(\"schema\") == SCHEMA:\n        d = obj.get(\"domain\")\n        if domain and d and domain != d:\n            R.err(\"domain\", f\"文件内容属于 '{d}'，但当前页面/参数是 '{domain}'\")\n            return domain, None, R\n        data = obj.get(\"data\")\n        if obj.get(\"variant\") and isinstance(data, dict):\n            data = dict(data, variant=data.get(\"variant\", obj[\"variant\"]))\n        return d or domain, data, R\n    if isinstance(obj, dict) and obj.get(\"schema\") == RESULT_SCHEMA:\n        d = obj.get(\"domain\")\n        if domain and d and domain != d:\n            R.err(\"domain\", f\"这个结果文件属于 '{d}'，但当前页面/参数是 '{domain}'\")\n            return domain, None, R\n        prob = obj.get(\"problem\")\n        if not isinstance(prob, dict):\n            R.err(\"problem\", \"结果文件里没有 problem（实例）字段，无法当作问题文件导入\")\n            return d or domain, None, R\n        if obj.get(\"variant\") and \"variant\" not in prob:\n            prob = dict(prob, variant=obj[\"variant\"])\n        return d or domain, prob, R\n    if isinstance(obj, dict) and obj.get(\"format\") in (\"domain-experiment/v1\", \"domain-experiment-bundle/v1\"):\n        return obj.get(\"domain\") or domain, obj.get(\"problem\"), R\n    if domain is None:\n        domain = guess_domain(obj)\n        if domain is None and not (isinstance(obj, list) and obj and isinstance(obj[0], list)):\n            R.err(\"domain\", \"无法判断问题域：请使用 swarm-problem/v1 信封，或显式指定 domain\")\n            return None, None, R\n        if domain is None:\n            domain = \"tsp\"\n    return domain, obj, R\n\n\ndef _num_or_err(R, where, tok):\n    try:\n        f = float(tok)\n        return int(f) if f.is_integer() and re.fullmatch(r\"[+-]?\\d+(\\.0+)?\", tok.strip()) else f\n    except ValueError:\n        R.err(where, f\"应为数字，收到 {_show(tok)}\")\n        return None\n\n\ndef _csv_rows(txt):\n    meta, rows = {}, []\n    for ln, line in enumerate(txt.splitlines(), 1):\n        s = line.strip()\n        if not s:\n            continue\n        if s.startswith(\"#\"):\n            for k, v in re.findall(r\"(\\w+)\\s*=\\s*([^\\s,]+)\", s):\n                meta[k] = v\n            continue\n        rows.append((ln, next(csv.reader([s], delimiter=\";\" if \";\" in s and \",\" not in s else \",\"))))\n    return meta, rows\n\n\ndef _parse_csv(domain, txt, R):\n    meta, rows = _csv_rows(txt)\n    if rows and not all(re.fullmatch(r\"[+-]?\\d*\\.?\\d+([eE][+-]?\\d+)?\", t.strip()) for t in rows[0][1] if t.strip()):\n        rows = rows[1:]  # 跳过表头\n    table = []\n    for ln, r in rows:\n        vals = [_num_or_err(R, f\"第 {ln} 行\", t) for t in r if t.strip() != \"\"]\n        if None in vals:\n            return None\n        table.append(vals)\n    if not table:\n        R.err(\"\", \"没有读到任何数据行\")\n        return None\n    if domain == \"knapsack\":\n        if \"cap\" not in meta and \"capacity\" not in meta:\n            R.err(\"cap\", \"CSV 需要在文件开头用注释行写容量，例如：# cap=532\")\n            return None\n        return {\"cap\": _num_or_err(R, \"cap\", meta.get(\"cap\", meta.get(\"capacity\"))), \"items\": table}\n    if domain == \"binpack\":\n        if \"cap\" not in meta and \"capacity\" not in meta:\n            R.err(\"cap\", \"CSV 需要在文件开头用注释行写箱容量，例如：# cap=150\")\n            return None\n        return {\"cap\": _num_or_err(R, \"cap\", meta.get(\"cap\", meta.get(\"capacity\"))), \"items\": [r[0] for r in table]}\n    if domain == \"qubo\":\n        return {\"Q\": table}\n    if domain == \"tsp\":\n        return _csv_tsp(table, meta, R)\n    if domain in (\"graphcolor\", \"gcvar\"):\n        d = {\"edges\": table}\n        if \"n\" in meta:\n            d[\"n\"] = int(meta[\"n\"])\n        return d\n    R.err(\"domain\", f\"域 '{domain}' 不支持 CSV；请使用 JSON（见 docs/data-formats.md）\")\n    return None\n\n\ndef _parse_cnf(txt, R):\n    n_vars, clauses, cur = None, [], []\n    for ln, line in enumerate(txt.splitlines(), 1):\n        s = line.strip()\n        if not s or s[0] in \"c%\":\n            continue\n        if s.startswith(\"p\"):\n            parts = s.split()\n            if len(parts) < 4 or parts[1] != \"cnf\":\n                R.err(f\"第 {ln} 行\", \"DIMACS 头应为：p cnf <变量数> <子句数>\")\n                return None\n            n_vars = int(parts[2])\n            continue\n        for tok in s.split():\n            try:\n                v = int(tok)\n            except ValueError:\n                R.err(f\"第 {ln} 行\", f\"DIMACS 里应为整数，收到 {_show(tok)}\")\n                return None\n            if v == 0:\n                if cur:\n                    clauses.append(cur)\n                cur = []\n            else:\n                cur.append(v)\n    if cur:\n        clauses.append(cur)\n    if n_vars is None:\n        R.warn(\"n_vars\", \"缺少 'p cnf' 头，将按最大变量编号推断\")\n    return {\"n_vars\": n_vars, \"clauses\": clauses} if n_vars is not None else {\"clauses\": clauses}\n\n\ndef _parse_col(txt, R):\n    n, edges = None, []\n    for ln, line in enumerate(txt.splitlines(), 1):\n        s = line.strip().split()\n        if not s or s[0] == \"c\":\n            continue\n        if s[0] == \"p\":\n            if len(s) < 3:\n                R.err(f\"第 {ln} 行\", \"DIMACS 头应为：p edge <顶点数> <边数>\")\n                return None\n            n = int(s[2])\n        elif s[0] == \"e\" and len(s) >= 3:\n            try:\n                edges.append([int(s[1]) - 1, int(s[2]) - 1])  # DIMACS 顶点从 1 起，转 0 起\n            except ValueError:\n                R.err(f\"第 {ln} 行\", f\"边应为 e <u> <v>，收到 {_show(line.strip())}\")\n                return None\n    d = {\"edges\": edges}\n    if n is not None:\n        d[\"n\"] = n\n    return d\n\n\ndef to_envelope(domain, data, variant=None):\n    env = {\"schema\": SCHEMA, \"domain\": domain}\n    if variant:\n        env[\"variant\"] = variant\n    env[\"data\"] = data\n    return env\n\n\ndef supported(domain):\n    return domain in CORE_DOMAINS\n\n\ndef check_text(text, domain=None, filename=None, dry_run=False, variant=None):\n    \"\"\"一步到位：读取 + 校验。返回 {\"domain\", \"ok\", \"errors\", \"warnings\", \"problem\"}。\n    variant：调用方（如固定变体的页面）期望的变体；文件里写了不同变体时报错，而不是悄悄按错的结构去跑。\"\"\"\n    d, data, R = load(text, domain, filename)\n    if data is None or R.errors:\n        return {\"domain\": d, \"ok\": False, \"errors\": R.errors, \"warnings\": R.warnings, \"problem\": None}\n    if variant and isinstance(data, dict) and data.get(\"variant\") not in (None, variant):\n        R.err(\"variant\", f\"文件是变体 '{data['variant']}' 的数据，而这里需要变体 '{variant}'（请到对应变体的页面导入）\")\n        return {\"domain\": d, \"ok\": False, \"errors\": R.errors, \"warnings\": R.warnings, \"problem\": None}\n    res = validate(d, data, variant=variant, dry_run=dry_run)\n    if variant and res[\"ok\"] and res[\"problem\"].get(\"variant\") not in (None, variant):\n        R.err(\"variant\", f\"数据是变体 '{res['problem']['variant']}' 的格式，而这里需要变体 '{variant}'（请到对应变体的页面导入）\")\n        return {\"domain\": d, \"ok\": False, \"errors\": R.errors, \"warnings\": R.warnings + res[\"warnings\"], \"problem\": None}\n    res[\"domain\"] = d\n    res[\"warnings\"] = R.warnings + res[\"warnings\"]\n    return res\n";
